using System.Collections.Immutable;
using MtgEngine.Domain.Enums;
using MtgEngine.Domain.Models;
using MtgEngine.Rules.Abilities;
using MtgEngine.Rules.Cards;
using MtgEngine.Rules.Engine;
using MtgEngine.Rules.Events;
using MtgEngine.Rules.Mana;
using MtgEngine.Rules.State;

namespace MtgEngine.Rules.Tests;

/// <summary>
/// What a compiled card actually does when it is played.
/// </summary>
/// <remarks>
/// Coverage counts cards whose every line the compiler could <em>read</em>. That is not the same
/// claim as the card being right: a template that maps "destroy target creature" to the wrong
/// target, or fires a trigger at the wrong moment, parses perfectly and plays wrongly. Nothing in
/// the coverage number would notice.
/// <para>
/// Testing all 32,765 cards one at a time is not possible, and would be the same mistake as
/// writing them one at a time. Testing each <em>template</em> is, and every card that uses a
/// template inherits its verification — so these tests are written per template, from the real
/// oracle wording, and played through a real game rather than asserted against the parse tree.
/// </para>
/// </remarks>
public sealed class CompiledCardBehaviourTests
{
    private static readonly CompiledPool Pool = new();

    /// <summary>A card built from real printed wording, so the template under test is the real one.</summary>
    private static CardDefinition Card(
        string name,
        string oracleText,
        CardType types = CardType.Instant,
        int? power = null,
        int? toughness = null,
        KeywordAbility keywords = KeywordAbility.None,
        params string[] subtypes) => new()
        {
            OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
            Name = name,
            OracleText = oracleText,
            CardTypes = types,
            Power = power,
            Toughness = toughness,
            Keywords = keywords,
            Subtypes = subtypes,
        };

    /// <summary>A vanilla creature of one colour, for the protection rules.</summary>
    private static CardDefinition Coloured(string name, ManaColor colour) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        CardTypes = CardType.Creature,
        Power = 2,
        Toughness = 2,
        ColorIdentity = [colour],
        Colors = [colour],
    };

    private static (Game Game, Guid Alice, Guid Bob) InMainPhase()
    {
        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");
        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, TestCards.Deck(40, "Alice")),
                new PlayerSetup(bob, "Bob", 20, TestCards.Deck(40, "Bob")),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);
        return (game, alice, bob);
    }

    /// <summary>
    /// Plays on until nothing is waiting.
    /// </summary>
    /// <remarks>
    /// It passes priority at least once even with an empty stack, because state-based actions
    /// run when a player would receive priority (CR 704.3) — returning early on "nothing on the
    /// stack" meant an Aura whose creature had just died was never checked, and the test read
    /// that as the rule not working.
    /// </remarks>
    private static void Settle(Game game)
    {
        Run(game);

        // The engine's founding invariant: state is a fold of the log, so a game rebuilt from its
        // events must equal the game that produced them. Checking it here is what makes each new
        // event pay for itself - an event the reducer handles differently from the emitter
        // diverges silently until something replays.
        //
        // The loop below is a separate method for one reason: this assertion used to sit after
        // it, and both of that loop's ordinary exits are `return`s, so it was reached only when
        // the guard ran out - which is to say almost never. Its own comment claimed every test
        // asserted the invariant while nearly none of them did, which is the worst state for a
        // check to be in: present, documented, and not running.
        Assert.Equal(game.State, GameReducer.Replay(game.Log));
    }

    /// <summary>Plays on until nothing is waiting, asserting nothing.</summary>
    private static void Run(Game game)
    {
        var passedOnce = false;

        for (var guard = 0; guard < 80; guard++)
        {
            if (game.State.Choice is { } choice)
            {
                game.Choose(
                    choice.PlayerId,
                    [.. choice.Options.Take(Math.Max(choice.MinPicks, 1)).Select(o => o.Id)]);
                continue;
            }

            if (passedOnce && game.State.Stack.IsEmpty && game.State.PendingTriggers.IsEmpty)
                return;

            if (game.State.Priority.Holder is not { } holder)
                return;

            game.PassPriority(holder);
            passedOnce = true;
        }
    }

    // ---- Damage --------------------------------------------------------------

    [Fact]
    public void Deals_damage_to_any_target_burns_a_player()
    {
        var bolt = Card("Bolt Test", "~ deals 3 damage to any target.");
        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, bolt);

        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void Deals_damage_to_any_target_can_kill_a_creature()
    {
        var bolt = Card("Bolt Test", "~ deals 3 damage to any target.");
        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, bolt);

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Empty(game.State.Battlefield);
    }

    // ---- Removal -------------------------------------------------------------

    [Fact]
    public void Destroy_target_creature_destroys_it()
    {
        var murder = Card("Murder Test", "Destroy target creature.");
        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Bear", 5, 5), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, murder);

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Empty(game.State.Battlefield);
        Assert.Single(game.State.GetPlayer(bob).Graveyard);
    }

    [Fact]
    public void Exile_target_creature_exiles_rather_than_destroying()
    {
        var scour = Card("Exile Test", "Exile target creature.");
        var (game, alice, bob) = InMainPhase();
        var myr = game.Create(bob, TestCards.Indestructible("Myr"), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, scour);

        game.CastSpell(alice, card, [Target.ToPermanent(myr)]);
        Settle(game);

        Assert.Empty(game.State.Battlefield);
        Assert.Single(game.State.Exile);
    }

    [Fact]
    public void Return_to_hand_bounces_to_the_owners_hand()
    {
        var unsummon = Card("Bounce Test", "Return target creature to its owner's hand.");
        var (game, alice, bob) = InMainPhase();
        var handBefore = game.State.GetPlayer(bob).Hand.Count;
        var bear = game.Create(bob, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, unsummon);

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Empty(game.State.Battlefield);
        Assert.Equal(handBefore + 1, game.State.GetPlayer(bob).Hand.Count);
    }

    // ---- Cards and life ------------------------------------------------------

    [Fact]
    public void Draw_two_cards_draws_two()
    {
        var divination = Card("Draw Test", "Draw two cards.");
        var (game, alice, _) = InMainPhase();
        var before = game.State.GetPlayer(alice).Library.Count;
        var card = TestCards.PutInHand(game, alice, divination);

        game.CastSpell(alice, card);
        Settle(game);

        Assert.Equal(before - 2, game.State.GetPlayer(alice).Library.Count);
    }

    [Fact]
    public void You_gain_life_gains_it()
    {
        var salve = Card("Life Test", "You gain 5 life.");
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, salve);

        game.CastSpell(alice, card);
        Settle(game);

        Assert.Equal(25, game.State.GetPlayer(alice).Life);
    }

    // ---- Pumps ---------------------------------------------------------------

    [Fact]
    public void Target_creature_gets_a_bonus_until_end_of_turn()
    {
        var growth = Card("Pump Test", "Target creature gets +3/+3 until end of turn.");
        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, growth);

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(5, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(bear)));
        Assert.Equal(5, Characteristics.ToughnessOf(game.State, Pool, game.State.GetObject(bear)));
    }

    [Fact]
    public void A_negative_pump_shrinks_and_can_kill()
    {
        var shrink = Card("Shrink Test", "Target creature gets -3/-3 until end of turn.");
        var (game, alice, bob) = InMainPhase();
        game.Create(bob, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        var bear = game.State.Battlefield[0];
        var card = TestCards.PutInHand(game, alice, shrink);

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Empty(game.State.Battlefield);
    }

    // ---- Mana abilities ------------------------------------------------------

    [Fact]
    public void A_tap_for_mana_line_adds_that_mana()
    {
        var forest = Card("Forest Test", "{T}: Add {G}.", CardType.Land);
        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, forest, Zone.Battlefield);

        game.ActivateAbility(alice, land, "mana");

        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Green]);
    }

    [Fact]
    public void A_land_that_pays_double_sits_out_the_next_untap_step()
    {
        var vault = Card(
            "Sitting Vault Test",
            "{T}: Add {C}{C}. This land doesn't untap during your next untap step.",
            CardType.Land);

        var compiled = CardCompiler.Compile(vault);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, vault, Zone.Battlefield);

        game.ActivateAbility(alice, land, "mana");

        // Read before anything can change step: a mana pool empties at the end of every step and
        // phase (CR 500.4), so settling first would assert against an empty one.
        Assert.Equal(2, game.State.GetPlayer(alice).ManaPool.Colorless);
        Assert.True(game.State.GetObject(land).Permanent?.SkipsNextUntap);

        // Alice's own next untap step is the one it misses, so the turn has to come back round.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.True(game.State.GetObject(land).Permanent?.IsTapped);
    }

    [Fact]
    public void A_mana_ability_whose_tail_cannot_be_read_is_not_read_at_all()
    {
        // "Dragon spells" is a subtype restriction, which the vocabulary deliberately does not
        // read. The whole line has to go unread with it: a land that taps for unrestricted mana
        // is a strictly better card than the one printed, and it would have looked complete.
        var hoard = Card(
            "Dragon Hoard Test",
            "{T}: Add {R}. Spend this mana only to cast Dragon spells.",
            CardType.Land);

        var compiled = CardCompiler.Compile(hoard);

        Assert.False(compiled.IsComplete);
        Assert.Empty(compiled.Activated);
        Assert.Contains(compiled.Unhandled, u => u.Contains("Dragon", StringComparison.Ordinal));
    }

    // ---- "That player" draws (CR 603.2) --------------------------------------

    [Fact]
    public void That_player_draws_means_the_player_the_trigger_was_about()
    {
        var font = Card(
            "Shared Font Test",
            "At the beginning of each player's draw step, that player draws an additional card.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(font);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, font, Zone.Battlefield);
        Settle(game);

        var aliceHeld = game.State.GetPlayer(alice).Hand.Count;
        var bobHeld = game.State.GetPlayer(bob).Hand.Count;

        // Bob's draw step: Bob draws his card and the extra one. Alice, who controls the
        // enchantment, draws nothing - "that player" is whoever the trigger was about.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Equal(bobHeld + 2, game.State.GetPlayer(bob).Hand.Count);
        Assert.Equal(aliceHeld, game.State.GetPlayer(alice).Hand.Count);
    }

    [Fact]
    public void That_player_on_an_opponents_step_is_the_opponent()
    {
        // The same phrase on a trigger that only fires on somebody else's step. It compiled
        // before "that player" had an answer at all, so compiling proves nothing here.
        var toll = Card(
            "Evening Toll Test",
            "At the beginning of each opponent's end step, that player loses 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(toll);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, toll, Zone.Battlefield);
        Settle(game);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.PrecombatMain);

        // Through Alice's end step, which is not an opponent's, and into Bob's turn.
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
        Assert.Equal(20, game.State.GetPlayer(bob).Life);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.PrecombatMain);

        // Bob's end step has now passed: Bob paid, not Alice.
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    // ---- A counter put on something the sentence names by role (CR 603.2) ----

    [Fact]
    public void A_counter_put_on_it_follows_the_target_the_sentence_chose()
    {
        // "It" used to mean the source unconditionally, so this card put its counter on itself
        // and left the creature it had just pumped alone.
        var graft = Card(
            "Grafting Rite Test",
            "When ~ enters, target creature you control gains flying until end of turn. "
                + "Put a +1/+1 counter on it.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(graft);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Rite Bear One Test", 2, 2), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Rite Bear Two Test", 2, 2), Zone.Battlefield);

        var source = game.Create(alice, graft, Zone.Battlefield);
        Settle(game);

        // Whichever creature the harness targeted, the counter is on that one - and not on the
        // enchantment, which is where it used to go.
        var pumped = new[] { first, second }
            .Select(game.State.GetObject)
            .Single(o => Characteristics.Of(game.State, Pool, o).Has(KeywordAbility.Flying));

        Assert.Equal(
            1, pumped.Permanent?.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        Assert.Equal(
            0,
            game.State.GetObject(source).Permanent?.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    [Fact]
    public void It_gets_a_bonus_follows_the_target_too()
    {
        // The same word in a different verb, and it had the same fault: "it" meant the source
        // whatever the sentence before it had done.
        var rite = Card(
            "Rousing Rite Test",
            "When ~ enters, untap target creature you control. It gets +2/+2 until end of turn.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(rite);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Roused Bear One Test", 2, 2), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Roused Bear Two Test", 2, 2), Zone.Battlefield);

        game.Tap(first);
        game.Tap(second);

        game.Create(alice, rite, Zone.Battlefield);
        Settle(game);

        // Whichever one was untapped is the one that grew.
        var untapped = new[] { first, second }
            .Select(game.State.GetObject)
            .Single(o => o.Permanent?.IsTapped == false);

        var other = new[] { first, second }
            .Select(game.State.GetObject)
            .Single(o => o.Id != untapped.Id);

        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, untapped));
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, other));
    }

    [Fact]
    public void A_counter_put_on_enchanted_creature_lands_on_the_host()
    {
        var graft = Card(
            "Grafting Aura Test",
            "Enchant creature\n"
                + "When ~ enters, put a +1/+1 counter on enchanted creature.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(graft);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.Creature("Grafted Bear Test", 2, 2), Zone.Battlefield);
        var mine = game.Create(alice, TestCards.Creature("Ungrafted Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, graft);
        game.CastSpell(alice, card, [Target.ToPermanent(theirs)]);
        Settle(game);

        // On what the Aura is attached to - which is the opponent's creature, not the Aura and
        // not anything of Alice's.
        Assert.Equal(
            1,
            game.State.GetObject(theirs).Permanent?.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        Assert.Equal(
            0,
            game.State.GetObject(mine).Permanent?.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    // ---- A token made under somebody else's control (CR 111.1) ---------------

    [Fact]
    public void Each_opponent_creates_a_token_gives_it_to_them_and_not_to_you()
    {
        var bribe = Card(
            "Hunted Bribe Test",
            "Each opponent creates a 1/1 white Soldier creature token.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(bribe);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, bribe);

        game.CastSpell(alice, card, []);
        Settle(game);

        var soldier = game.State.Battlefield.Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Soldier");

        // Bob's, not Alice's - a token is created under a player's control, and which player is
        // what the sentence says rather than who cast it.
        Assert.Equal(bob, soldier.ControllerId);
        Assert.Equal(bob, soldier.OwnerId);
    }

    // ---- One "for each" tail, shared by the verbs that read a number ---------

    [Theory]
    [InlineData("Draw a card for each creature you control.")]
    [InlineData("You gain 1 life for each creature you control.")]
    [InlineData("~ deals 1 damage to any target for each creature you control.")]
    [InlineData("Mill a card for each creature you control.")]
    [InlineData("Each opponent discards a card for each creature you control.")]
    [InlineData("Put a +1/+1 counter on target creature for each creature you control.")]
    [InlineData("Create a 1/1 white Soldier creature token for each creature you control.")]
    public void Every_verb_that_reads_a_number_reads_the_for_each_tail(string text)
    {
        // Each of these was added on a different day, and each time only the verb in front of a
        // developer got the tail. The tail is one shared pattern now, so this asks all of them.
        var card = Card("For Each Test", text, CardType.Sorcery);

        var compiled = CardCompiler.Compile(card);

        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
    }

    // ---- Counting a life change or a burn (CR 118.3, 119.3) ------------------

    [Fact]
    public void Damage_counted_off_the_board_scales_with_it()
    {
        var volley = Card(
            "Counted Volley Test",
            "~ deals 1 damage to any target for each creature you control.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(volley);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, TestCards.Creature("Volley Bear One Test", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Volley Bear Two Test", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Volley Bear Three Test", 2, 2), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Volley Enemy Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, volley);
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        // Three of Alice's creatures, not the four on the battlefield.
        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    // ---- Counting a life change (CR 118.3) -----------------------------------

    [Fact]
    public void Life_counted_off_the_board_is_asked_of_whoever_the_sentence_names()
    {
        var tithe = Card(
            "Blood Tithe Test",
            "Each opponent loses 1 life for each creature you control.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(tithe);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, TestCards.Creature("Tithe Bear One Test", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Tithe Bear Two Test", 2, 2), Zone.Battlefield);

        // Bob's creature is not one Alice controls, so it is not counted.
        game.Create(bob, TestCards.Creature("Tithe Enemy Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, tithe);
        game.CastSpell(alice, card, []);
        Settle(game);

        // Two, not three - and Bob pays it, not Alice.
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    // ---- Discarding a whole hand (CR 701.8a) ---------------------------------

    [Fact]
    public void Each_player_discards_their_own_hand_however_big_it_is()
    {
        var reckoning = Card(
            "Reckoning Test",
            "Each player discards their hand.",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(reckoning);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        // Different sized hands, so a single number worked out by the compiler could not be
        // right for both.
        TestCards.PutInHand(game, alice, TestCards.Creature("Reckoned One Test", 1, 1));
        TestCards.PutInHand(game, alice, TestCards.Creature("Reckoned Two Test", 1, 1));
        TestCards.PutInHand(game, bob, TestCards.Creature("Reckoned Three Test", 1, 1));

        Assert.NotEqual(
            game.State.GetPlayer(alice).Hand.Count,
            game.State.GetPlayer(bob).Hand.Count);

        var card = TestCards.PutInHand(game, alice, reckoning);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Empty(game.State.GetPlayer(alice).Hand);
        Assert.Empty(game.State.GetPlayer(bob).Hand);
    }

    // ---- An Aura on a player keeps that player's clock (CR 303.4) ------------

    [Fact]
    public void An_aura_on_a_player_fires_on_that_players_upkeep_and_not_its_controllers()
    {
        var curse = Card(
            "Player Curse Test",
            "Enchant player\n"
                + "At the beginning of enchanted player's upkeep, you gain 2 life.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(curse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var card = TestCards.PutInHand(game, alice, curse);
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        // Bob's upkeep, not Alice's: the Aura's clock runs on whoever it is on, and the two are
        // different players — which is the whole reason these cards are played.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2 && game.State.CurrentStep == TurnStep.PrecombatMain);

        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_aura_on_a_player_who_has_left_the_game_goes_to_the_graveyard()
    {
        // CR 704.5m: an Aura attached to an illegal player is put into its owner's graveyard, and
        // a player who has lost is no longer a player in the game (CR 800.4a). Only reachable at
        // three seats or more - at two, the game ends with the player, and nothing that happens
        // to the Aura afterwards can be seen.
        var curse = Card(
            "Departing Curse Test",
            "Enchant player\n"
                + "At the beginning of enchanted player's upkeep, you gain 2 life.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(curse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();

        var card = TestCards.PutInHand(game, seats[0], curse);
        game.CastSpell(seats[0], card, [Target.ToPlayer(seats[1])]);
        Settle(game);

        var aura = Assert.Single(game.State.Battlefield);

        // The enchanted seat is knocked out, and the other three play on.
        var gun = game.Create(seats[0], TestCards.Creature("Departing Gun Test", 1, 1), Zone.Battlefield);
        game.MarkDamageToPlayer(seats[1], gun, 20);
        Settle(game);

        Assert.True(game.State.GetPlayer(seats[1]).HasLost);
        Assert.False(game.State.IsOver);

        Assert.DoesNotContain(aura, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(seats[0]).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Departing Curse Test");
    }

    // ---- What kind of spell a cast trigger names (CR 603.2) ------------------

    [Fact]
    public void A_cast_trigger_naming_a_subtype_fires_only_for_that_subtype()
    {
        var chief = Card(
            "Goblin Chief Test",
            "Whenever you cast a Goblin spell, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(chief);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, chief, Zone.Battlefield);

        var goblin = Card("Cast Goblin Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Goblin");
        var elf = Card("Cast Elf Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Elf");

        var first = TestCards.PutInHand(game, alice, elf);
        game.CastSpell(alice, first, []);
        Settle(game);

        // Before this could tell a subtype from a card type, an unrecognised word meant "every
        // spell" and the Elf would have paid out too.
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        var second = TestCards.PutInHand(game, alice, goblin);
        game.CastSpell(alice, second, []);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_cast_trigger_naming_a_word_the_engine_does_not_know_is_left_unread()
    {
        // The failure this guards: an unknown word left no filter at all, and no filter means
        // every spell - a trigger that fires on everything is a strictly better card than the
        // one printed.
        var odd = Card(
            "Playtest Watcher Test",
            "Whenever you cast a playtest spell, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(odd);

        Assert.False(compiled.IsComplete);
        Assert.Contains(compiled.Unhandled, u => u.Contains("playtest", StringComparison.Ordinal));
    }

    // ---- Where a spell was cast from (CR 601.2) ------------------------------

    [Fact]
    public void A_trigger_about_where_a_spell_came_from_can_tell_the_zones_apart()
    {
        var watcher = Card(
            "Recursion Watcher Test",
            "Whenever you cast a spell from anywhere other than your hand, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // The same card, castable from the graveyard as well as from hand.
        var bolt = new CardDefinition
        {
            OracleId = "oracle-zone-bolt",
            Name = "Zone Bolt Test",
            OracleText = "~ deals 1 damage to any target.\nFlashback {R}",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{R}",
            Cmc = 1,
        };

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        var first = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        // The same definition twice: a basic land's mana ability comes from its subtype, so a
        // differently named "Mountain" would not have one.
        var second = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);

        // From hand: no trigger.
        var inHand = TestCards.PutInHand(game, alice, bolt);
        game.ActivateAbility(alice, first, "mana");
        game.CastSpell(alice, inHand, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        // The same spell, now cast from the graveyard by flashback: the trigger fires.
        var inYard = game.State.GetPlayer(alice).Graveyard
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Zone Bolt Test");

        game.ActivateAbility(alice, second, "mana");
        game.CastSpell(alice, inYard.Id, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    // ---- "Deals combat damage" with no recipient (CR 510.2) ------------------

    [Fact]
    public void Combat_damage_to_a_creature_counts_when_no_recipient_is_named()
    {
        var drum = Card(
            "War Drum Test",
            "Whenever a creature you control deals combat damage, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(drum);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, drum, Zone.Battlefield);
        var attacker = game.Create(alice, TestCards.Creature("Drum Attacker Test", 2, 2), Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Drum Blocker Test", 1, 4), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        var before = game.State.GetPlayer(alice).Life;

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Blocked, so no damage reached Bob - the whole two went to the blocker, and that is
        // still combat damage.
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);
    }

    // ---- A group trigger about blocking (CR 509.1h) --------------------------

    [Fact]
    public void A_group_becomes_blocked_trigger_needs_an_actual_blocker()
    {
        var horn = Card(
            "Warning Horn Test",
            "Whenever a creature you control becomes blocked, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(horn);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, horn, Zone.Battlefield);
        var attacker = game.Create(alice, TestCards.Creature("Horn Attacker Test", 2, 2), Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Horn Blocker Test", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        var before = game.State.GetPlayer(alice).Life;

        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        Settle(game);

        // CR 509.1h: an attacker becomes blocked when a creature is declared as blocking it.
        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);
    }

    // ---- Qualifying the subject of a trigger (CR 603.2) ----------------------

    [Fact]
    public void A_trigger_qualified_by_a_keyword_only_sees_creatures_that_have_it()
    {
        var roost = Card(
            "Skyward Roost Test",
            "Whenever a creature you control with flying enters, you gain 1 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(roost);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, roost, Zone.Battlefield);
        Settle(game);

        game.Create(alice, TestCards.Creature("Grounded Bear Test", 2, 2), Zone.Battlefield);
        Settle(game);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        game.Create(
