            Zone.Battlefield);

        Settle(game);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);
    }

    // ---- Tokens, counted and tapped (CR 111.1) -------------------------------

    [Fact]
    public void A_token_for_each_thing_makes_none_when_there_is_nothing()
    {
        var muster = Card(
            "Soldier Muster Count Test",
            "When ~ enters, create a 1/1 white Soldier creature token for each artifact you control.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(muster);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, muster, Zone.Battlefield);
        Settle(game);

        // No artifacts, so no tokens. A count that was given is used as it stands - flooring it
        // at one would be a card doing something it does not say.
        Assert.DoesNotContain(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Name == "Soldier");

        game.Create(alice, Card("Muster Rock One Test", string.Empty, CardType.Artifact), Zone.Battlefield);
        game.Create(alice, Card("Muster Rock Two Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        var again = game.Create(alice, muster, Zone.Battlefield);
        Assert.NotEqual(default, again);
        Settle(game);

        Assert.Equal(
            2,
            game.State.Battlefield.Select(game.State.GetObject)
                .Count(o => o.Card.Name == "Soldier"));
    }

    [Fact]
    public void A_tapped_token_arrives_tapped()
    {
