    // ---- Cycling -------------------------------------------------------------

    [Fact]
    public void Cycling_discards_the_card_and_draws_one()
    {
        var cycler = Card("Cycle Test", "Cycling {2}", CardType.Creature, 2, 2);
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, cycler);
        var libraryBefore = game.State.GetPlayer(alice).Library.Count;

        // Mana to pay with.
        for (var i = 0; i < 2; i++)
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.ActivateAbility(alice, card, "cycling");
        Settle(game);

        Assert.Equal(libraryBefore - 1, game.State.GetPlayer(alice).Library.Count);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Cycle Test");
    }

    // ---- Regeneration --------------------------------------------------------

    [Fact]
    public void Regeneration_saves_a_creature_from_lethal_damage()
    {
        // CR 701.15b: the destruction is replaced by tapping and clearing the damage, so the
        // creature is still there afterwards — tapped, and undamaged.
        var troll = Card(
            "Troll Test", "{G}: Regenerate ~.", CardType.Creature, 2, 2, subtypes: "Troll");

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, troll, Zone.Battlefield);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        game.ActivateAbility(alice, forest, "mana");
        game.ActivateAbility(alice, creature, "a");
        Settle(game);

        // Now something lethal.
        var bolt = Card("Bolt Test", "~ deals 3 damage to any target.");
        var card = TestCards.PutInHand(game, bob, bolt);
        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob, guard: 200);
        game.CastSpell(bob, card, [Target.ToPermanent(creature)]);
        Settle(game);

        var survivor = game.State.Battlefield
            .Select(game.State.GetObject)
            .SingleOrDefault(o => o.Card.Name == "Troll Test");

        Assert.NotNull(survivor);
        Assert.True(survivor!.Permanent!.IsTapped);
        Assert.Equal(0, survivor.Permanent.DamageMarked);
    }

    [Fact]
    public void A_regeneration_shield_is_spent_once()
    {
        var troll = Card("Troll Test", "{G}: Regenerate ~.", CardType.Creature, 2, 2);
        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, troll, Zone.Battlefield);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        game.ActivateAbility(alice, forest, "mana");
        game.ActivateAbility(alice, creature, "a");
        Settle(game);

        Assert.Equal(1, game.State.GetObject(creature).Permanent!.RegenerationShields);

        game.Move(creature, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        var after = game.State.Battlefield
            .Select(game.State.GetObject)
            .SingleOrDefault(o => o.Card.Name == "Troll Test");

        Assert.NotNull(after);
        Assert.Equal(0, after!.Permanent!.RegenerationShields);
    }

