    // ---- Basic lands ----------------------------------------------------------

    [Fact]
    public void Every_basic_land_type_taps_for_its_colour()
    {
        // Their mana ability is printed only as reminder text in brackets, which the compiler
        // strips — so it is intrinsic here (CR 305.6) or the commonest cards in Magic do nothing.
        var (game, alice, _) = InMainPhase();

        foreach (var (name, colour) in new[]
        {
            ("Plains", ManaColor.White), ("Island", ManaColor.Blue), ("Swamp", ManaColor.Black),
            ("Mountain", ManaColor.Red), ("Forest", ManaColor.Green),
        })
        {
            var land = game.Create(
                alice,
                // A distinct name from TestCards.BasicLand's: this is deliberately a
                // different card definition — one whose only text is reminder text — and
                // two definitions under one id is what the compiled pool now refuses.
                Card($"{name} Reminder Test", "({T}: Add mana.)", CardType.Land, subtypes: name),
                Zone.Battlefield);

            game.ActivateAbility(alice, land, "mana");
            Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[colour]);
            game.Move(land, Zone.Graveyard, MoveCause.Destroy);
        }
    }

    // ---- Scry and surveil -----------------------------------------------------

    [Fact]
    public void Scry_asks_which_cards_to_bottom_and_moves_them()
    {
        var seer = Card("Scry Test", "When this creature enters, scry 2.", CardType.Creature, 1, 1);
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, seer);
        var libraryBefore = game.State.GetPlayer(alice).Library.Count;
        // By name, not by id: an object gets a new identity every time it changes zone
        // (CR 400.7), so the card that was on top is not the same object once it is bottomed.
        var topBefore = game.State.GetObject(game.State.GetPlayer(alice).Library[0]).Card.Name;

        game.CastSpell(alice, card);

        // The trigger resolves, then the question is asked.
        TestCards.PassUntil(
            game, () => game.State.Choice is { Kind: ChoiceKind.Scry }, guard: 200);

        var choice = game.State.Choice!;
        Assert.Equal(alice, choice.PlayerId);
        Assert.Equal(2, choice.Options.Count);
        Assert.Equal(0, choice.MinPicks);

        // Bottom the top card.
        game.Choose(alice, [choice.Options[0].Id]);

        var library = game.State.GetPlayer(alice).Library;
        Assert.Equal(libraryBefore, library.Count);
        Assert.NotEqual(topBefore, game.State.GetObject(library[0]).Card.Name);
        Assert.Equal(topBefore, game.State.GetObject(library[^1]).Card.Name);
    }

    [Fact]
    public void Scry_may_keep_everything_on_top()
    {
        var seer = Card("Scry Test", "When this creature enters, scry 2.", CardType.Creature, 1, 1);
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, seer);
        var topBefore = game.State.GetObject(game.State.GetPlayer(alice).Library[0]).Card.Name;

        game.CastSpell(alice, card);
        TestCards.PassUntil(
            game, () => game.State.Choice is { Kind: ChoiceKind.Scry }, guard: 200);

        // Picking nothing is a legal answer, which is why MinPicks is zero.
        game.Choose(alice, []);

        Assert.Equal(
            topBefore,
            game.State.GetObject(game.State.GetPlayer(alice).Library[0]).Card.Name);
    }

    [Fact]
    public void Surveil_puts_the_chosen_cards_in_the_graveyard()
    {
        var spy = Card(
            "Surveil Test", "When this creature enters, surveil 2.", CardType.Creature, 1, 1);
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, spy);
        var graveyardBefore = game.State.GetPlayer(alice).Graveyard.Count;

        game.CastSpell(alice, card);
        TestCards.PassUntil(
            game, () => game.State.Choice is { Kind: ChoiceKind.Surveil }, guard: 200);

        game.Choose(alice, [game.State.Choice!.Options[0].Id]);

        Assert.Equal(graveyardBefore + 1, game.State.GetPlayer(alice).Graveyard.Count);
    }

    // ---- Infect ---------------------------------------------------------------

    [Fact]
    public void Infect_damages_a_player_with_poison_instead_of_life()
    {
        // CR 702.90b. The life total is untouched — that is the whole point of the mechanic,
        // and why a player can lose to infect at twenty life.
        var carrier = Card(
            "Infect Test", "Infect", CardType.Creature, 2, 2, keywords: KeywordAbility.Infect);

        var (game, alice, bob) = InMainPhase();
        var source = game.Create(alice, carrier, Zone.Battlefield);

        game.MarkDamageToPlayer(bob, source, 3, isCombat: false);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.Equal(3, game.State.GetPlayer(bob).PoisonCounters);
    }

    [Fact]
    public void Infect_damages_a_creature_with_counters_instead_of_damage()
    {
        var carrier = Card(
            "Infect Test", "Infect", CardType.Creature, 2, 2, keywords: KeywordAbility.Infect);

        var (game, alice, bob) = InMainPhase();
        var source = game.Create(alice, carrier, Zone.Battlefield);
        var victim = game.Create(bob, TestCards.Creature("Bear", 4, 4), Zone.Battlefield);

        game.MarkDamage(victim, 2, sourceId: source);
        Settle(game);

        var hit = game.State.GetObject(victim);
        Assert.Equal(0, hit.Permanent!.DamageMarked);
        Assert.Equal(2, hit.Permanent.Counters.GetValueOrDefault(CounterKinds.MinusOneMinusOne));
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, hit));
    }

