    // ---- Attack requirements ---------------------------------------------------

    [Fact]
    public void A_creature_that_must_attack_makes_leaving_it_home_illegal()
    {
        // CR 508.1d: a requirement is about the declaration as a whole, so it is only broken
        // once you know what was left out.
        var berserker = Card(
            "Berserker Test", "~ attacks each combat if able.", CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, berserker, Zone.Battlefield);

        // A turn cycle, so it has been controlled since the turn began and is therefore able
        // to attack — the requirement only binds a creature that could have attacked.
        TestCards.PassToTurn(game, game.State.TurnNumber + 2);
        TestCards.PassToStep(game, TurnStep.DeclareAttackers);

        var ex = Assert.Throws<InvalidOperationException>(() =>
            game.DeclareAttackers(alice, ImmutableDictionary<ObjectId, AttackTarget>.Empty));

        Assert.Contains("508.1d", ex.Message, StringComparison.Ordinal);
    }

    // ---- Control changes reach combat (CR 613.1b) ------------------------------

    [Fact]
    public void A_stolen_creature_can_attack_for_its_new_controller()
    {
        // CR 613.1b: control is layer 2, so the controller stored on an object is only where the
        // permanent started. Threaten takes the creature, untaps it and gives it haste - and the
        // only reason to do any of that is to attack with it the same turn.
        var threaten = Card(
            "Attack Threaten Test",
            "Gain control of target creature until end of turn. Untap that creature. "
                + "It gains haste until end of turn.");

        var compiled = CardCompiler.Compile(threaten);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Stolen Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, threaten), [Target.ToPermanent(bear)]);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [bear] = AttackTarget.Player(bob),
        });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        // Its owner takes two from his own creature, which is the whole point of the card.
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void A_stolen_creature_that_must_attack_binds_its_new_controller()
    {
        // CR 508.1d asks about creatures the attacking player controls, and after a control change
        // that is not the controller written on the object.
        var berserker = Card(
            "Stolen Berserker Test",
            "~ attacks each combat if able.",
            CardType.Creature, 2, 2);

        var threaten = Card(
            "Requirement Threaten Test",
            "Gain control of target creature until end of turn. Untap that creature. "
                + "It gains haste until end of turn.");

        var (game, alice, bob) = InMainPhase();
        var stolen = game.Create(bob, berserker, Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, threaten), [Target.ToPermanent(stolen)]);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        var ex = Assert.Throws<InvalidOperationException>(() =>
            game.DeclareAttackers(alice, ImmutableDictionary<ObjectId, AttackTarget>.Empty));

        Assert.Contains("508.1d", ex.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void A_creature_can_count_the_auras_attached_to_it()
    {
        // "for each Aura attached to it" counts a relation to this permanent, which the board-group
        // reader has nothing to say about - it reads groups on the battlefield, and "attached to
        // it" is not one. Asserted at zero, one and two, because a count that always answered one
        // would satisfy a single-Aura test on its own.
        var vine = Card(
            "Aura Counter Test", "~ gets +2/+2 for each Aura attached to it.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(vine);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, vine, Zone.Battlefield);

        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        var aura = Card(
            "Counted Aura Test", "Enchant creature", CardType.Enchantment,
            null, null, KeywordAbility.None, "Aura");

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, aura), [Target.ToPermanent(creature)]);
        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        var second = Card(
            "Second Aura Test", "Enchant creature", CardType.Enchantment,
            null, null, KeywordAbility.None, "Aura");

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, second), [Target.ToPermanent(creature)]);
        Settle(game);

        Assert.Equal(5, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);
    }

    [Fact]
    public void Delirium_counts_card_types_rather_than_cards()
    {
        // "Four or more card types among cards in your graveyard" is a different question from
        // the card count beside it, and the difference is the whole mechanic: four creatures are
        // one type and do nothing, while four cards of four types turn it on. Both are asserted,
        // because a condition that counted cards would pass the second on its own.
        var lurker = Card(
            "Delirium Lurker Test",
            "~ gets +3/+3 as long as there are four or more card types among cards in your graveyard.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(lurker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, lurker, Zone.Battlefield);

        // Four cards, all creatures: one card type, so the condition is off.
        for (var i = 0; i < 4; i++)
        {
            game.Create(
                alice, TestCards.Creature($"Delirium Body {i}", 1, 1), Zone.Graveyard);
        }

        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        // A fourth *type* is what turns it on, not a fifth card.
        game.Create(alice, Card("Delirium Bolt Test", string.Empty, CardType.Instant), Zone.Graveyard);
        game.Create(alice, Card("Delirium Ritual Test", string.Empty, CardType.Sorcery), Zone.Graveyard);
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        game.Create(alice, TestCards.BasicLand("Delirium Forest Test"), Zone.Graveyard);

        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);
    }

    /// <summary>
    /// "~ enters with a +1/+1 counter on it if a creature died this turn" (CR 614.1c).
    /// </summary>
    /// <remarks>
    /// The counters were already read; the condition on the end was not, and the line stopped at
    /// "on it". Asserted both ways on one card, because a reader that dropped the "if" would put
    /// the counter on every time and look exactly like a working implementation from the side
    /// where the condition happens to hold.
    /// </remarks>
    [Fact]
    public void A_creature_can_enter_with_counters_only_when_its_condition_holds()
    {
        var scavenger = Card(
            "Conditional Counter Test",
            "~ enters with two +1/+1 counters on it if a creature died this turn.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(scavenger);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Nothing has died, so it is the printed 1/1.
        var plain = game.Create(alice, scavenger, Zone.Battlefield);
        Settle(game);
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(plain)).Power);
        Assert.Equal(
            0,
            game.State.GetObject(plain).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        // Kill something, and the next one arrives grown.
        var victim = game.Create(alice, TestCards.Creature("Counter Victim Test", 1, 1), Zone.Battlefield);
        game.Move(victim, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        var grown = game.Create(alice, scavenger, Zone.Battlefield);
        Settle(game);

        Assert.Equal(
            2,
            game.State.GetObject(grown).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(grown)).Power);
    }

    /// <summary>
    /// "~ can't be blocked except by creatures with flying" (CR 509.1b).
    /// </summary>
    /// <remarks>
    /// The inverse of the "can't be blocked by" family and built by negating it, so the two
    /// spellings cannot come to disagree about what a filter means. Asserted in both directions:
    /// a restriction that refused every blocker would satisfy the first assertion alone, and one
    /// that allowed every blocker would satisfy the second.
    /// </remarks>
    [Fact]
    public void A_creature_blockable_only_by_fliers_refuses_everything_else()
    {
        var wisp = Card(
            "Except By Test", "~ can't be blocked except by creatures with flying.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(wisp);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, wisp, Zone.Battlefield);

        var footman = game.Create(bob, TestCards.Creature("Except Footman Test", 2, 2), Zone.Battlefield);
        var drake = game.Create(
            bob,
            Card("Except Drake Test", "Flying", CardType.Creature, 2, 2, keywords: KeywordAbility.Flying),
            Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        // A block restriction is asked of the declaration, not of one creature: `CannotBlock`
        // never sees them, so this has to go through the door the game does.
        Assert.Throws<InvalidOperationException>(
            () => game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
            {
                [attacker] = [footman],
            }));

        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
        {
            [attacker] = [drake],
        });

        Assert.Single(game.State.Combat.Blocked);
    }

    /// <summary>
    /// "~ can't be blocked except by three or more creatures" (CR 509.1b).
    /// </summary>
    /// <remarks>
    /// Menace with a number the keyword cannot say. Two blockers is the assertion that matters:
    /// a rule that only refused a lone blocker - which is what menace already does - would pass a
    /// test that checked one and three.
    /// </remarks>
    [Fact]
    public void A_creature_can_demand_more_blockers_than_menace_asks_for()
    {
        var brute = Card(
            "Three Blockers Test", "~ can't be blocked except by three or more creatures.",
            CardType.Creature, 6, 6);

        var compiled = CardCompiler.Compile(brute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, brute, Zone.Battlefield);

        var blockers = Enumerable.Range(0, 3)
            .Select(i => game.Create(
                bob, TestCards.Creature($"Gang Blocker {i}", 1, 1), Zone.Battlefield))
            .ToList();

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        foreach (var tooFew in new[] { 1, 2 })
        {
            var refused = Assert.Throws<InvalidOperationException>(
                () => game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
                {
                    [attacker] = [.. blockers.Take(tooFew)],
                }));
            Assert.Contains("509.1b", refused.Message, StringComparison.Ordinal);
        }

        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
        {
            [attacker] = blockers,
        });

        Assert.Single(game.State.Combat.Blocked);
    }

    [Fact]
    public void A_creature_that_can_neither_block_nor_be_blocked_does_both()
    {
        // Two restrictions the engine already models, printed as one sentence. Both halves are
        // asserted, because either flag alone would satisfy half of this and look right.
        var ghost = Card(
            "Neither Way Test", "~ can't block and can't be blocked.", CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(ghost);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, ghost, Zone.Battlefield);
        var theirs = game.Create(bob, ghost, Zone.Battlefield);
        var ordinary = game.Create(alice, TestCards.Creature("Neither Bear Test", 2, 2), Zone.Battlefield);

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(mine));
        Assert.True(computed.Has(KeywordAbility.CantBlock));
        Assert.True(computed.Has(KeywordAbility.CantBeBlocked));

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [mine] = AttackTarget.Player(bob),
            [ordinary] = AttackTarget.Player(bob),
        });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        // It cannot be blocked...
        Assert.NotNull(WhyNoBlock(game, theirs, mine, bob));

        // ...and it could not have blocked either, which is the other half of the sentence.
        Assert.NotNull(WhyNoBlock(game, theirs, ordinary, bob));
    }

    /// <summary>
    /// "~ gets +N/+N for each creature card in your graveyard" (CR 613.4c).
    /// </summary>
    /// <remarks>
    /// The counting static reads groups on the battlefield, and a card in a graveyard is not a
    /// permanent and has no computed characteristics to ask (CR 109.3) - so the count is taken
    /// off the printed types instead. The noun is filtered rather than ignored: a land in the
    /// same graveyard must not move the number, which is the assertion that separates this from
    /// counting the graveyard.
    /// </remarks>
    [Fact]
    public void A_creature_can_count_cards_of_a_kind_in_your_graveyard()
    {
        var lurker = Card(
            "Graveyard Count Test", "~ gets +1/+1 for each creature card in your graveyard.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(lurker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, lurker, Zone.Battlefield);

        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        game.Create(alice, TestCards.Creature("Buried Body Test", 2, 2), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Second Body Test", 2, 2), Zone.Graveyard);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        // A land in the same graveyard is not a creature card and must not count.
        game.Create(alice, TestCards.BasicLand("Buried Forest Test"), Zone.Graveyard);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        // Nor does an opponent's graveyard, because the card says "your".
        game.Create(bob, TestCards.Creature("Their Body Test", 2, 2), Zone.Graveyard);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);
    }

    [Fact]
    public void A_creature_can_count_the_cards_in_your_hand()
    {
        var scholar = Card(
            "Hand Count Test", "~ gets +1/+1 for each card in your hand.",
            CardType.Creature, 0, 1);

        var compiled = CardCompiler.Compile(scholar);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, scholar, Zone.Battlefield);

        var before = game.State.GetPlayer(alice).Hand.Count;
        Assert.Equal(
            before, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        TestCards.PutInHand(game, alice, TestCards.Creature("Held Card Test", 1, 1));

        Assert.Equal(
            before + 1,
            Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);
    }

    /// <summary>
    /// "~ enters with a +1/+1 counter on it for each color of mana spent to cast it" (CR 614.1c).
    /// </summary>
    /// <remarks>
    /// Sunburst, on the cards that spell it out instead of printing the keyword. Both spellings go
    /// through one reader: a second implementation of a rule the engine already had is how the
    /// two come to disagree, and this repository has already paid for that once with the legend
    /// rule. Two colours rather than one is the assertion that matters - a reader counting *mana*
    /// rather than *colours* would agree with a one-colour test and disagree here.
    /// </remarks>
    [Fact]
    public void A_creature_can_count_the_colours_of_mana_that_paid_for_it()
    {
        var sunburst = new CardDefinition
        {
            OracleId = "oracle-spelled-out-sunburst-test",
            Name = "Spelled Out Sunburst Test",
            OracleText = "~ enters with a +1/+1 counter on it for each color of mana spent to cast it.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}",
            Cmc = 2,
            Power = 0,
            Toughness = 1,
        };

        var compiled = CardCompiler.Compile(sunburst);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Two different colours for a generic cost, which is the whole point of the mechanic.
        game.AddMana(alice, ManaColor.White);
        game.AddMana(alice, ManaColor.Blue);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, sunburst), []);
        Settle(game);

        var arrived = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Spelled Out Sunburst Test");

        Assert.Equal(
            2, arrived.Permanent!.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    /// <summary>"Reinforce 2—{1}{G}" — discard it from hand to grow something (CR 702.76a).</summary>
    /// <remarks>
    /// Expanded into the sentence its reminder text spells out and handed to the ordinary
    /// activated-ability reader, the way outlast is. What is asserted here is the whole of what
    /// the keyword contributes: that it works from the *hand*, that discarding the card is the
    /// cost, and that the number of counters is the one printed beside the word.
    /// </remarks>
    [Fact]
    public void Reinforce_discards_the_card_from_hand_to_put_counters_on_a_creature()
    {
        var triad = Card(
            "Reinforce Test", "Reinforce 2—{1}{G}", CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(triad);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Reinforced Bear Test", 2, 2), Zone.Battlefield);
        var inHand = TestCards.PutInHand(game, alice, triad);

        game.AddMana(alice, ManaColor.Green);
        game.AddMana(alice, ManaColor.Green);

        // The generic activated-ability reader names it, because the keyword is expanded
        // into an ordinary ability rather than given a hand-written one.
        game.ActivateAbility(alice, inHand, "a", [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(
            2,
            game.State.GetObject(bear).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        // Discarding it was the cost, so the card itself is in the graveyard rather than in hand.
        Assert.DoesNotContain(inHand, game.State.GetPlayer(alice).Hand);
    }

    /// <summary>
    /// "~ enters with a +1/+1 counter on it for each creature card in your graveyard" (CR 614.1c).
    /// </summary>
    /// <remarks>
    /// The third shape of enters-with-counters: not a printed number and not a condition, but a
    /// count taken as the permanent enters. It shares its group reader with the counting statics,
    /// so "creature card in your graveyard" means the same thing in both - and the filter is
    /// asserted here too, because a group reader that counted everything would look right until
    /// something other than a creature is in the graveyard.
    /// </remarks>
    [Fact]
    public void A_creature_can_enter_with_a_counter_for_each_thing_it_counts()
    {
        var ghoul = Card(
            "Enter Per Group Test",
            "~ enters with a +1/+1 counter on it for each creature card in your graveyard.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(ghoul);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Nothing in the graveyard, so it arrives at its printed size.
        var bare = game.Create(alice, ghoul, Zone.Battlefield);
        Settle(game);
        Assert.Equal(
            0,
            game.State.GetObject(bare).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        game.Create(alice, TestCards.Creature("Entered Body One", 2, 2), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Entered Body Two", 2, 2), Zone.Graveyard);

        // A land is not a creature card and must not be counted.
        game.Create(alice, TestCards.BasicLand("Entered Forest Test"), Zone.Graveyard);

        var grown = game.Create(alice, ghoul, Zone.Battlefield);
        Settle(game);

        Assert.Equal(
            2,
            game.State.GetObject(grown).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    /// <summary>
    /// "As long as you've drawn two or more cards this turn" (CR 121.1).
    /// </summary>
    /// <remarks>
    /// The tally was in the state all along and the condition vocabulary could not ask for it, so
    /// thirteen cards were unread for want of one reader. Asserted at one card and at two, because
    /// a condition that answered "have you drawn at all" would agree with the second and not the
    /// first, and would look true for most of any real game.
    /// </remarks>
    [Fact]
    public void A_static_can_ask_how_many_cards_you_have_drawn_this_turn()
    {
        var prodigy = Card(
            "Drawn Count Test",
            "~ gets +2/+2 as long as you've drawn two or more cards this turn.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(prodigy);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, prodigy, Zone.Battlefield);

        // The starting player skips their first draw step, so the count begins at nothing.
        Assert.Equal(0, game.State.GetPlayer(alice).CardsDrawnThisTurn);
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        // One is not two, which is the assertion that separates this from "have you drawn at all".
        game.Draw(alice);
        Assert.Equal(1, game.State.GetPlayer(alice).CardsDrawnThisTurn);
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        game.Draw(alice);
        Assert.Equal(2, game.State.GetPlayer(alice).CardsDrawnThisTurn);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);
    }

    /// <summary>
    /// "As long as an opponent has three or more poison counters" (CR 122.1).
    /// </summary>
    /// <remarks>
    /// The tally has been in player state for the rule that ends the game at ten, and nothing
    /// could ask it short of that. "An opponent" is any of them, so it is a search rather than a
    /// lookup - which only shows at more than two seats, and is asserted at four here.
    /// </remarks>
    [Fact]
    public void A_static_can_ask_whether_an_opponent_is_poisoned()
    {
        var stalker = Card(
            "Poison Watcher Test",
            "~ gets +3/+3 as long as an opponent has three or more poison counters.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(stalker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();
        var creature = game.Create(seats[0], stalker, Zone.Battlefield);

        // Infect is how a player gets poison, and the counters come from damage (CR 702.90b).
        var carrier = game.Create(
            seats[0],
            Card("Poison Carrier Test", "Infect", CardType.Creature, 2, 2,
                keywords: KeywordAbility.Infect),
            Zone.Battlefield);

        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        // Two is not three, so the count is read rather than the mere presence of a counter.
        game.MarkDamageToPlayer(seats[2], carrier, 2, isCombat: false);
        Settle(game);
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        // The third seat, not the one next to us: "an opponent" is any of them.
        game.MarkDamageToPlayer(seats[2], carrier, 1, isCombat: false);
        Settle(game);
        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);
    }

    /// <summary>
    /// "As long as an opponent has eight or more cards in their graveyard."
    /// </summary>
    /// <remarks>
    /// The same count the vocabulary already took of your own graveyard, asked about somebody
    /// else. Sharing the reader is what keeps "eight or more cards" meaning one thing.
    /// </remarks>
    [Fact]
    public void A_static_can_ask_about_an_opponents_graveyard()
    {
        var ghoul = Card(
            "Their Graveyard Test",
            "~ gets +2/+2 as long as an opponent has three or more cards in their graveyard.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(ghoul);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, ghoul, Zone.Battlefield);

        // Alice's own graveyard must not answer a question about an opponent's.
        for (var i = 0; i < 4; i++)
            game.Create(alice, TestCards.Creature($"My Body {i}", 1, 1), Zone.Graveyard);

        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        for (var i = 0; i < 3; i++)
            game.Create(bob, TestCards.Creature($"Their Body {i}", 1, 1), Zone.Graveyard);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);
    }

    /// <summary>
    /// "Gain control of target creature for as long as you control this creature" (CR 611.2b).
    /// </summary>
    /// <remarks>
    /// A third clock beside "until end of turn" and "for ever", and the rule that makes it its
    /// own thing is that the effect **ends** when the condition stops holding - it does not pause
    /// and resume. Folded into the effect's own Applies it would resume, and the stolen creature
    /// would come home every time the thief did.
    /// <para>
    /// Asserted in three steps: taken, still taken while the thief is around, and given back for
    /// good once the thief has gone. The last is the one that separates an ending from a pause.
    /// </para>
    /// </remarks>
    [Fact]
    public void Control_taken_for_as_long_as_you_control_the_source_ends_when_it_goes()
    {
        var thief = Card(
            "Lasting Thief Test",
            "When ~ enters, gain control of target creature an opponent controls "
                + "for as long as you control ~.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(thief);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var prize = game.Create(bob, TestCards.Creature("Borrowed Bear Test", 2, 2), Zone.Battlefield);

        var taker = game.Create(alice, thief, Zone.Battlefield);
        Settle(game);

        // Bob's bear is the only legal target, so nothing has to be chosen.
        Assert.Equal(
            alice, Characteristics.Of(game.State, Pool, game.State.GetObject(prize)).ControllerId);

        // Still Alice's while the thief is still hers, across a turn boundary - this is not an
        // until-end-of-turn effect wearing a different name.
        TestCards.PassToTurn(game, 2);
        Assert.Equal(
            alice, Characteristics.Of(game.State, Pool, game.State.GetObject(prize)).ControllerId);

        // The thief goes, and the condition stops holding.
        game.Move(taker, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Equal(
            bob, Characteristics.Of(game.State, Pool, game.State.GetObject(prize)).ControllerId);
        Assert.Empty(game.State.FloatingEffects);
    }

    /// <summary>
    /// "Gain control of target creature for as long as ~ remains tapped" (CR 611.2b).
    /// </summary>
    /// <remarks>
    /// The second spelling of the condition duration, on the same mechanism: Vedalken Shackles'
    /// clock rather than the thief's. Untapping the source ends it for good - and the test
    /// tapping it again afterwards is what separates an ending from a pause, which is the only
    /// thing CR 611.2b actually says.
    /// </remarks>
    [Fact]
    public void Control_held_while_the_source_stays_tapped_ends_when_it_untaps()
    {
        var shackles = new CardDefinition
        {
            OracleId = "oracle-shackles-test",
            Name = "Shackles Test",
            OracleText =
                "{T}: Gain control of target creature an opponent controls "
                + "for as long as ~ remains tapped.",
            CardTypes = CardType.Artifact,
            ManaCostRaw = "{2}",
            Cmc = 2,
        };

        var compiled = CardCompiler.Compile(shackles);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var prize = game.Create(bob, TestCards.Creature("Shackled Bear Test", 2, 2), Zone.Battlefield);
        var device = game.Create(alice, shackles, Zone.Battlefield);

        game.ActivateAbility(alice, device, "a", [Target.ToPermanent(prize)]);
        Settle(game);

        Assert.Equal(
            alice, Characteristics.Of(game.State, Pool, game.State.GetObject(prize)).ControllerId);

        // It survives the opponent's whole turn, which an until-end-of-turn effect would not.
        TestCards.PassToTurn(game, 2);
        Assert.Equal(
            alice, Characteristics.Of(game.State, Pool, game.State.GetObject(prize)).ControllerId);

        // Alice's untap step is what unties it, through the ordinary rule rather than by hand.
        TestCards.PassToTurn(game, 3);
        Settle(game);
        Assert.False(game.State.GetObject(device).Permanent!.IsTapped);

        Assert.Equal(
            bob, Characteristics.Of(game.State, Pool, game.State.GetObject(prize)).ControllerId);
        Assert.Empty(game.State.FloatingEffects);

        // And it does not come back when the condition does (CR 611.2b).
        game.Tap(device);
        Settle(game);

        Assert.Equal(
            bob, Characteristics.Of(game.State, Pool, game.State.GetObject(prize)).ControllerId);
    }

    /// <summary>
    /// "Target creature you control gains protection from the color of your choice" (CR 202.2).
    /// </summary>
    /// <remarks>
    /// The colour is not known when the spell resolves, so the effect cannot finish on its own -
    /// it stops and asks, like every other question the game puts. Asserted on the colour that
    /// was *not* chosen as well: a grant that handed out protection from everything would satisfy
    /// the first half and is a different card.
    /// </remarks>
    [Fact]
    public void Protection_from_a_chosen_colour_stops_that_colour_and_no_other()
    {
        var blessing = Card(
            "Chosen Colour Test",
            "Target creature you control gains protection from the color of your choice "
                + "until end of turn.");

        var compiled = CardCompiler.Compile(blessing);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Warded Knight Test", 2, 2), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, blessing), [Target.ToPermanent(mine)]);

        // Not Settle: that helper answers any outstanding choice with its first option, so a test
        // that wants to see the question has to stop at it rather than settle past it.
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice;
        Assert.NotNull(choice);
        Assert.Equal(ChoiceKind.ChooseColor, choice.Kind);
        Assert.Equal(5, choice.Options!.Count);

        game.Choose(alice, [nameof(ManaColor.Black)]);
        Settle(game);

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(mine));
        Assert.True(computed.Has(KeywordAbility.ProtectionFromBlack));

        // And nothing else: a grant of every colour would pass the assertion above on its own.
        Assert.False(computed.Has(KeywordAbility.ProtectionFromRed));

        // It reaches the rule it exists for - a black creature cannot block it (CR 702.16e).
        var zombie = game.Create(bob, Coloured("Chosen Zombie Test", ManaColor.Black), Zone.Battlefield);
        var why = CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(zombie), game.State.GetObject(mine), bob);

        Assert.NotNull(why);
        Assert.Contains("702.16e", why, StringComparison.Ordinal);
    }

    /// <summary>
    /// "Target creature becomes the color of your choice until end of turn" (CR 202.2b).
    /// </summary>
    /// <remarks>
    /// The second use of one question. Becoming a colour *replaces* what the permanent was rather
    /// than adding to it, which is why the old colour is asserted gone: a card that adds one says
    /// "in addition to its other colors" and is a different sentence.
    /// </remarks>
    [Fact]
    public void A_creature_can_become_a_colour_its_controller_names()
    {
        var paint = Card(
            "Chosen Paint Test",
            "Target creature becomes the color of your choice until end of turn.");

        var compiled = CardCompiler.Compile(paint);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var subject = game.Create(alice, Coloured("Painted Bear Test", ManaColor.Green), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, paint), [Target.ToPermanent(subject)]);

        TestCards.PassUntil(game, () => game.State.Choice is not null);
        Assert.Equal(ChoiceKind.ChooseColor, game.State.Choice!.Kind);

        game.Choose(alice, [nameof(ManaColor.Blue)]);
        Settle(game);

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(subject));
        Assert.Contains(ManaColor.Blue, computed.Colors);

        // Replaced, not added: it was green when the spell was cast.
        Assert.DoesNotContain(ManaColor.Green, computed.Colors);
    }

    /// <summary>
    /// "Switch target creature's power and toughness until end of turn" (CR 613.4d, layer 7d).
    /// </summary>
    /// <remarks>
    /// The layer and the builder method for this were both already here and nothing produced one,
    /// so every card that says it was unread - capability present, unreachable, which has been the
    /// most productive shape to look for all session.
    /// <para>
    /// Asserted with a counter on the creature, because 7d is the *last* sublayer and that is the
    /// whole of what it means: a 2/4 with a +1/+1 counter is a 3/5 before the switch and a 5/3
    /// after, not a 4/2 with a counter added afterwards.
    /// </para>
    /// </remarks>
    [Fact]
    public void Switching_power_and_toughness_happens_after_everything_else()
    {
        var twist = Card(
            "Switch Test", "Switch target creature's power and toughness until end of turn.");

        var compiled = CardCompiler.Compile(twist);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Switched Bear Test", 2, 4), Zone.Battlefield);
        game.ChangeCounters(bear, CounterKinds.PlusOnePlusOne, 1);

        var before = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(3, before.Power);
        Assert.Equal(5, before.Toughness);

        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, twist), [Target.ToPermanent(bear)]);
        Settle(game);

        // 5/3, not 4/2: the switch swaps what the counter already produced.
        var after = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(5, after.Power);
        Assert.Equal(3, after.Toughness);
    }

    /// <summary>
    /// "All creatures able to block target creature this turn do so" (CR 509.1c).
    /// </summary>
    /// <remarks>
    /// The requirement a printed lure makes, made by a spell instead and aimed at somebody else's
    /// creature. It shares the definition with the static rather than adding a second reader, so
    /// the block check keeps answering one question - a requirement is a requirement whoever made
    /// it. What is asserted is the requirement biting: leaving a creature home is refused.
    /// </remarks>
    [Fact]
    public void A_spell_can_compel_every_creature_to_block_one_attacker()
    {
        var call = Card(
            "Target Lure Test", "All creatures able to block target creature this turn do so.");

        var compiled = CardCompiler.Compile(call);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, TestCards.Creature("Lured Attacker Test", 2, 2), Zone.Battlefield);
        var other = game.Create(alice, TestCards.Creature("Ignored Attacker Test", 3, 3), Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Compelled Blocker Test", 1, 1), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        // Cast on the turn of the attack: the lure lasts "this turn", so a spell cast two turns
        // earlier is correctly gone by the time anybody blocks - the first draft of this test
        // asserted against an expired effect and the engine was right to allow the block.
        PassTo(game, 3, TurnStep.PrecombatMain);
        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, call), [Target.ToPermanent(attacker)]);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [attacker] = AttackTarget.Player(bob),
            [other] = AttackTarget.Player(bob),
        });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        // Blocking nothing is not an option while the lure is on.
        var none = Assert.Throws<InvalidOperationException>(
            () => game.DeclareBlockers(bob, ImmutableDictionary<ObjectId, IReadOnlyList<ObjectId>>.Empty));
        Assert.Contains("509.1c", none.Message, StringComparison.Ordinal);

        // Nor is blocking the other attacker instead, which is the whole point of the card.
        var elsewhere = Assert.Throws<InvalidOperationException>(
            () => game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
            {
                [other] = [blocker],
            }));
        Assert.Contains("509.1c", elsewhere.Message, StringComparison.Ordinal);

        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
        {
            [attacker] = [blocker],
        });

        Assert.Single(game.State.Combat.Blocked);
    }

    /// <summary>
    /// "Target creature deals damage to itself equal to its power" (CR 701.12a).
    /// </summary>
    /// <remarks>
    /// A fight with one participant, built on the same effect: nothing in Fight says the dealer
    /// and the recipient have to be different objects, so the two indices are simply the same
    /// target. Asserted on a creature that survives as well as one that does not, because a
    /// reader that dealt a fixed amount rather than the creature's power would agree with a
    /// single lethal case and disagree here.
    /// </remarks>
    [Fact]
    public void A_creature_can_be_made_to_damage_itself_for_its_own_power()
    {
        var mirror = Card(
            "Self Bite Test", "Target creature deals damage to itself equal to its power.");

        var compiled = CardCompiler.Compile(mirror);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        // A 2/5 takes two and lives; the damage is its power, not a fixed number.
        var tough = game.Create(bob, TestCards.Creature("Tough Self Test", 2, 5), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, mirror), [Target.ToPermanent(tough)]);
        Settle(game);

        Assert.Contains(tough, game.State.Battlefield);
        Assert.Equal(2, game.State.GetObject(tough).Permanent!.DamageMarked);

        // A 4/4 kills itself, which a fixed-damage reader would only manage by luck.
        var brute = game.Create(bob, TestCards.Creature("Brute Self Test", 4, 4), Zone.Battlefield);
        var second = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, second, "mana");

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, mirror), [Target.ToPermanent(brute)]);
        Settle(game);

        Assert.DoesNotContain(brute, game.State.Battlefield);
    }

    /// <summary>
    /// "Untap up to two lands" — the controller chooses, as it resolves (CR 701.21a).
    /// </summary>
    /// <remarks>
    /// No target is named, so the candidates are whatever is tapped when the effect resolves, and
    /// the limit is a ceiling rather than a demand: "up to" means none is a legal answer. Both
    /// halves are asserted - that the cap binds, and that untapped lands are not offered - because
    /// an effect that untapped everything tapped would satisfy neither and look generous.
    /// </remarks>
    [Fact]
    public void Untapping_up_to_a_number_of_lands_offers_only_the_tapped_ones()
    {
        var surge = Card("Untap Lands Test", "Untap up to two lands.");

        var compiled = CardCompiler.Compile(surge);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var tapped = Enumerable.Range(0, 3)
            .Select(i => game.Create(alice, TestCards.BasicLand($"Tapped Land {i}"), Zone.Battlefield))
            .ToList();

        foreach (var land in tapped)
            game.Tap(land);

        var free = game.Create(alice, TestCards.BasicLand("Free Land Test"), Zone.Battlefield);

        // A real basic, because the fixture keys its mana ability to the land's own name.
        var payment = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, payment, "mana");

        game.CastSpell(alice, TestCards.PutInHand(game, alice, surge), []);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice!;
        Assert.Equal(ChoiceKind.ChooseUntaps, choice.Kind);

        // Two is the ceiling, and the untapped land is not among the candidates. The land tapped
        // for mana is, which is correct - it is tapped like any other.
        Assert.Equal(2, choice.MaxPicks);
        Assert.DoesNotContain(choice.Options!, o => o.Id == free.Value.ToString("N"));

        game.Choose(alice, [.. choice.Options!.Take(2).Select(o => o.Id)]);
        Settle(game);

        Assert.Equal(2, tapped.Concat([payment])
            .Count(id => game.State.GetObject(id).Permanent!.IsTapped == false));
    }

    /// <summary>"Bolster 2" — counters on the smallest creature you control (CR 701.36a).</summary>
    /// <remarks>
    /// The candidate set is the whole keyword, and toughness is the *computed* one: a 1/1 under
    /// an anthem is not the smallest creature on a board with a printed 2/2. That is what the
    /// anthem in this test is for - without it a reader using printed toughness would agree.
    /// </remarks>
    [Fact]
    public void Bolster_finds_the_smallest_creature_after_the_layers()
    {
        var rally = Card("Bolster Test", "Bolster 2.");

        var compiled = CardCompiler.Compile(rally);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // The fixture anthem is +0/+2, so the 1/1 is a 1/3 and the 2/4 a 2/6: the toughnesses
        // the condition compares are the computed ones, not the printed 1 and 4. The smallest is
        // the same creature either way here - what the anthem changes is the numbers being
        // compared, which is what makes this a test of computed toughness rather than printed.
        var small = game.Create(alice, TestCards.Creature("Bolster Small Test", 1, 1), Zone.Battlefield);
        var large = game.Create(alice, TestCards.Creature("Bolster Large Test", 2, 4), Zone.Battlefield);
        game.Create(alice, TestCards.Anthem("Bolster Anthem Test"), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, TestCards.PutInHand(game, alice, rally), []);
        Settle(game);

        // One candidate is not a choice, so the counters land without the game stopping.
        Assert.Equal(
            2,
            game.State.GetObject(small).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
        Assert.Equal(
            0,
            game.State.GetObject(large).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    /// <summary>"Amass Orcs 2" — grow an Army, making one first if you have none (CR 701.44a).</summary>
    /// <remarks>
    /// The order is the whole of it: the token is a 0/0, so it only survives because the counters
    /// arrive in the same resolution, before state-based actions run. A test that only checked the
    /// second amass would miss that entirely - the first is where it can go wrong.
    /// </remarks>
    [Fact]
    public void Amass_makes_an_army_before_it_grows_one()
    {
        var muster = Card("Amass Test", "Amass Orcs 2.");

        var compiled = CardCompiler.Compile(muster);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, TestCards.PutInHand(game, alice, muster), []);
        Settle(game);

        // A 0/0 with two counters, still alive: the counters came with it, not after it.
        var army = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Subtypes.Contains("Army", StringComparer.OrdinalIgnoreCase));

        Assert.Equal(
            2, army.Permanent!.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        var computed = Characteristics.Of(game.State, Pool, army);
        Assert.Equal(2, computed.Power);
        Assert.Equal(2, computed.Toughness);

        // The second amass grows the Army that is already there rather than making another.
        var second = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        game.ActivateAbility(alice, second, "mana");
        game.CastSpell(alice, TestCards.PutInHand(game, alice, muster), []);
        Settle(game);

        Assert.Single(
            game.State.Battlefield.Select(game.State.GetObject),
            o => o.Card.Subtypes.Contains("Army", StringComparer.OrdinalIgnoreCase));

        Assert.Equal(
            4,
            game.State.Battlefield.Select(game.State.GetObject)
                .Single(o => o.Card.Subtypes.Contains("Army", StringComparer.OrdinalIgnoreCase))
                .Permanent!.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    /// <summary>
    /// "~ doesn't untap during your untap step if it has a depletion counter on it" (CR 502.3).
    /// </summary>
    /// <remarks>
    /// A static with a question in front of it, and a static re-asks its question continuously -
    /// so this belongs in the effect's Applies, where it stops applying and starts again as the
    /// counters come and go. That is the opposite of a "for as long as" duration, which ends for
    /// good, and getting the two the wrong way round is the whole difficulty of both.
    /// <para>
    /// Asserted in both states on one permanent: with a counter it stays tapped, and once the
    /// counter is gone it untaps again. A reader that ignored the condition would pass the first.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_permanent_stays_tapped_only_while_its_condition_holds()
    {
        var mine = Card(
            "Depletion Test",
            "~ doesn't untap during your untap step if it has a depletion counter on it.",
            CardType.Land);

        var compiled = CardCompiler.Compile(mine);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, mine, Zone.Battlefield);

        game.Tap(land);
        game.ChangeCounters(land, "depletion", 1);

        // With a counter on it, Alice's untap step leaves it alone.
        TestCards.PassToTurn(game, 3);
        Settle(game);
        Assert.True(game.State.GetObject(land).Permanent!.IsTapped);

        // Take the counter off and the same untap step frees it: the condition is asked each
        // time, not once when the permanent arrived.
        game.ChangeCounters(land, "depletion", -1);
        TestCards.PassToTurn(game, 5);
        Settle(game);

        Assert.False(game.State.GetObject(land).Permanent!.IsTapped);
    }

    /// <summary>
    /// "~ deals 4 damage divided as you choose among any number of targets" (CR 601.2d).
    /// </summary>
    /// <remarks>
    /// "Any number" names no ceiling and the damage is the ceiling: every target in a division
    /// must be assigned at least one, so four damage cannot reach a fifth target however many are
    /// on the board. Sharing the reader with the counted forms is what keeps that arithmetic in
    /// one place rather than in two that can disagree.
    /// </remarks>
    [Fact]
    public void Damage_divided_among_any_number_of_targets_is_capped_by_the_damage()
    {
        var salvo = Card(
            "Any Number Test", "~ deals 3 damage divided as you choose among any number of targets.");

        var compiled = CardCompiler.Compile(salvo);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // Three damage, so three targets: the first required and the other two optional.
        Assert.Equal(3, compiled.Spell!.Targets.Count);

        var (game, alice, bob) = InMainPhase();
        var first = game.Create(bob, TestCards.Creature("Split One Test", 1, 1), Zone.Battlefield);
        var second = game.Create(bob, TestCards.Creature("Split Two Test", 1, 1), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, salvo),
            [Target.ToPermanent(first), Target.ToPermanent(second)],
            damageDivision: [2, 1]);
        Settle(game);

        Assert.DoesNotContain(first, game.State.Battlefield);
        Assert.DoesNotContain(second, game.State.Battlefield);
    }

    /// <summary>
    /// "Power-up — {2}{R}: …" — an ability word with a hyphen in it (CR 207.2c).
    /// </summary>
    /// <remarks>
    /// An ability word is flavour with no rules meaning, so the compiler strips it and reads what
    /// follows. The stripper's character class allowed letters, apostrophes and spaces, which
    /// silently excluded the one ability word that has a hyphen - and the thirty-seven cards
    /// carrying it were unread for a punctuation mark.
    /// </remarks>
    [Fact]
    public void An_ability_word_with_a_hyphen_is_stripped_like_any_other()
    {
        var machine = new CardDefinition
        {
            OracleId = "oracle-power-up-test",
            Name = "Power Up Test",
            OracleText = "Power-up \u2014 {1}: Put a +1/+1 counter on ~.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}",
            Cmc = 2,
            Power = 1,
            Toughness = 1,
        };

        var compiled = CardCompiler.Compile(machine);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, machine, Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.ActivateAbility(alice, creature, "a");
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(creature).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    /// <summary>"Descend 4 \u2014 …" — an ability word with a number in it (CR 207.2c).</summary>
    /// <remarks>
    /// The same miss as the hyphen, one character along: the stripper's class had no digits, so
    /// "Descend 4" read as two words rather than as one ability word and the line went unread.
    /// </remarks>
    [Fact]
    public void An_ability_word_with_a_number_is_stripped_like_any_other()
    {
        var crypt = Card(
            "Descend Test",
            "Descend 4 \u2014 ~ gets +2/+2 as long as there are four or more cards in your graveyard.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(crypt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, crypt, Zone.Battlefield);

        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);

        for (var i = 0; i < 4; i++)
            game.Create(alice, TestCards.Creature($"Descend Body {i}", 1, 1), Zone.Graveyard);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(creature)).Power);
    }

    /// <summary>
    /// "~ deals damage to target creature equal to the number of lands you control" (CR 107.3).
    /// </summary>
    /// <remarks>
    /// The engine already read this sentence with the clauses the other way round - "deals damage
    /// equal to the number of Elves you control to target creature" - and could not take this
    /// order, because each reader has to know where the target phrase stops. Two orders, one
    /// effect: the count goes through the same counting the other verbs use.
    /// </remarks>
    [Fact]
    public void Damage_can_be_counted_off_the_board_with_the_target_named_first()
    {
        var bolt = Card(
            "Counted Damage Test",
            "~ deals damage to target creature equal to the number of lands you control.");

        var compiled = CardCompiler.Compile(bolt);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var victim = game.Create(bob, TestCards.Creature("Counted Victim Test", 4, 4), Zone.Battlefield);

        // Three lands, so three damage: the 4/4 lives with three marked on it.
        var lands = Enumerable.Range(0, 3)
            .Select(i => game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield))
            .ToList();

        game.ActivateAbility(alice, lands[0], "mana");

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, bolt), [Target.ToPermanent(victim)]);
        Settle(game);

        Assert.Contains(victim, game.State.Battlefield);
        Assert.Equal(3, game.State.GetObject(victim).Permanent!.DamageMarked);
    }

    /// <summary>
    /// "~ enters tapped unless your opponents control three or more lands."
    /// </summary>
    /// <remarks>
    /// The conditional entry was already read; the condition was not. "Your opponents control N"
    /// counts across all of them together, which is what the plural says - and is a different
    /// question from "an opponent has N", which asks about each in turn. The two read alike and
    /// diverge at more than two seats, which is why this is tested at four.
    /// </remarks>
    [Fact]
    public void A_land_can_enter_untapped_once_the_opponents_between_them_have_enough()
    {
        var slow = Card(
            "Opponent Count Land Test",
            "~ enters tapped unless your opponents control three or more lands.",
            CardType.Land);

        var compiled = CardCompiler.Compile(slow);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, seats) = FourPlayers();

        // Two lands between two opponents is not three: it enters tapped.
        game.Create(seats[1], TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.Create(seats[2], TestCards.BasicLand("Island"), Zone.Battlefield);

        var first = game.Create(seats[0], slow, Zone.Battlefield);
        Settle(game);
        Assert.True(game.State.GetObject(first).Permanent!.IsTapped);

        // A third, on a third opponent: the count is across all of them, not any one of them.
        game.Create(seats[3], TestCards.BasicLand("Mountain"), Zone.Battlefield);

        var second = game.Create(seats[0], slow, Zone.Battlefield);
        Settle(game);
        Assert.False(game.State.GetObject(second).Permanent!.IsTapped);

        // And the caster's own lands are not counted: they are not their own opponent.
        Assert.Equal(3, game.State.Battlefield
            .Select(game.State.GetObject)
            .Count(o => o.Card.CardTypes.HasFlag(CardType.Land)
                && Characteristics.Of(game.State, Pool, o).ControllerId != seats[0]));
    }

    /// <summary>
    /// "~ costs {1} less to cast for each creature in your party" (CR 700.9, 601.2f).
    /// </summary>
    /// <remarks>
    /// A party is not a count of creatures: it is at most one Cleric, one Rogue, one Warrior and
    /// one Wizard, so three Clerics are a party of one. That is the whole of the rule and the only
    /// thing that can go wrong, so it is what the test asserts - the discount does not grow with
    /// the second and third Cleric, and does grow when a Rogue joins them.
    /// </remarks>
    [Fact]
    public void A_party_counts_classes_rather_than_creatures()
    {
        var costed = new CardDefinition
        {
            OracleId = "oracle-party-cost-test",
            Name = "Party Cost Test",
            OracleText = "~ costs {1} less to cast for each creature in your party.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{4}",
            Cmc = 4,
            Power = 2,
            Toughness = 2,
        };

        var compiled = CardCompiler.Compile(costed);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        CardDefinition Member(string name, string cls) =>
            Card(name, string.Empty, CardType.Creature, 1, 1, KeywordAbility.None, cls);

        // Three Clerics are a party of one, so {4} becomes {3} - and with no mana at all that
        // cannot be cast. Nothing is tapped for mana anywhere in this test, so the only thing
        // that can make the spell castable is the discount reaching {0}.
        game.Create(alice, Member("Party Cleric One", "Cleric"), Zone.Battlefield);
        game.Create(alice, Member("Party Cleric Two", "Cleric"), Zone.Battlefield);
        game.Create(alice, Member("Party Cleric Three", "Cleric"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, costed);
        Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, card, []));

        // One of each of the other three classes fills the party, and {4} less four is nothing.
        game.Create(alice, Member("Party Rogue", "Rogue"), Zone.Battlefield);
        game.Create(alice, Member("Party Warrior", "Warrior"), Zone.Battlefield);
        game.Create(alice, Member("Party Wizard", "Wizard"), Zone.Battlefield);

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Party Cost Test");
    }

    /// <summary>
    /// "~ gets +2/+2 as long as it's attacking alone" (CR 506.5).
    /// </summary>
    /// <remarks>
    /// The engine reads "~ attacks alone" as a trigger already, which fires once when attackers
    /// are declared. This is the same fact asked *continuously*, so it cannot reuse that: the
    /// bonus has to be there while the creature is attacking alone and gone when it is not.
    /// <para>
    /// Both declarations are tested on one board, because a condition that ignored the "alone"
    /// would pass the first and a condition that never held would pass the second.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_static_can_ask_whether_its_creature_attacks_alone()
    {
        var duellist = Card(
            "Attacks Alone Test", "~ gets +2/+2 as long as it's attacking alone.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(duellist);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var hero = game.Create(alice, duellist, Zone.Battlefield);
        var friend = game.Create(alice, TestCards.Creature("Alone Friend Test", 1, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);

        // Attacking with company: the printed size.
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [hero] = AttackTarget.Player(bob),
            [friend] = AttackTarget.Player(bob),
        });

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(hero)).Power);

        // A fresh turn, attacking by itself: the bonus is on.
        PassTo(game, 5, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [hero] = AttackTarget.Player(bob) });

        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(hero)).Power);
    }

    /// <summary>
    /// "Look at the top three cards of your library, then put them back in any order" (CR 701.19a).
    /// </summary>
    /// <remarks>
    /// Nothing moves: the cards stay in the library, so nothing changes identity and the order is
    /// stated once rather than performed as a sequence of moves - which would mint a new id per
    /// card (CR 400.7) and invalidate the ones still to be placed, half way through.
    /// <para>
    /// The test reverses the top three and asserts the *whole* library: what is underneath has to
    /// be untouched, which is the half an arrangement gets wrong by rewriting too much.
    /// </para>
    /// </remarks>
    [Fact]
    public void Cards_looked_at_can_be_put_back_in_a_chosen_order()
    {
        var seer = Card(
            "Arrange Test",
            "When ~ enters, look at the top three cards of your library, then put them back in any order.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(seer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var before = game.State.GetPlayer(alice).Library;
        var topThree = before.Take(3).ToList();
        var beneath = before.Skip(3).ToList();

        game.Create(alice, seer, Zone.Battlefield);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice!;
        Assert.Equal(ChoiceKind.OrderLibraryTop, choice.Kind);
        Assert.Equal(3, choice.MinPicks);
        Assert.Equal(3, choice.MaxPicks);

        // Reversed, so the answer cannot be mistaken for the order they were already in.
        game.Choose(alice, [.. choice.Options!.Reverse().Select(o => o.Id)]);
        Settle(game);

        var after = game.State.GetPlayer(alice).Library;
        Assert.Equal(topThree.AsEnumerable().Reverse(), after.Take(3));
        Assert.Equal(beneath, after.Skip(3));
    }

    /// <summary>
    /// "Escape—{1}{B}, Exile two other cards from your graveyard" (CR 702.139a).
    /// </summary>
    /// <remarks>
    /// Flashback's shape with two differences, and the test is about both. The additional cost
    /// takes *other* cards from the same graveyard - a cost that could take the escaping card
    /// would eat the spell being cast - and the card is **not** exiled on resolution, which is the
    /// whole mechanic: it goes back to the graveyard and can escape again.
    /// </remarks>
    [Fact]
    public void An_escaped_spell_pays_with_other_cards_and_can_escape_again()
    {
        var revenant = new CardDefinition
        {
            OracleId = "oracle-escape-test",
            Name = "Escape Test",
            OracleText = "Escape\u2014{1}{B}, Exile two other cards from your graveyard.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{3}{B}",
            Cmc = 4,
            Power = 3,
            Toughness = 3,
        };

        var compiled = CardCompiler.Compile(revenant);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = game.Create(alice, revenant, Zone.Graveyard);

        var fodder = Enumerable.Range(0, 2)
            .Select(i => game.Create(alice, TestCards.Creature($"Escape Fuel {i}", 1, 1), Zone.Graveyard))
            .ToList();

        var lands = Enumerable.Range(0, 2)
            .Select(i => game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield))
            .ToList();

        foreach (var land in lands)
            game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, [], costPayment: fodder);
        Settle(game);

        // It is on the battlefield, and the two other cards paid for it.
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Escape Test");

        foreach (var spent in fodder)
            Assert.DoesNotContain(spent, game.State.GetPlayer(alice).Graveyard);
    }

    /// <summary>
    /// "Activate no more than twice each turn" is the same limit as "only twice" (CR 602.5b).
    /// </summary>
    /// <remarks>
    /// The pattern required the word "only", so a card spelling the restriction the other way had
    /// its limit dropped - which is worse than leaving the line unread, because an ability with no
    /// limit where the card prints one is strictly better than the card. The third activation is
    /// what this asserts: two are allowed and the third is refused.
    /// </remarks>
    [Fact]
    public void An_activation_limit_reads_either_wording()
    {
        var engine = new CardDefinition
        {
            OracleId = "oracle-twice-limit-test",
            Name = "Twice Limit Test",
            OracleText = "{T}: ~ gets +1/+1 until end of turn. Activate no more than twice each turn.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}",
            Cmc = 2,
            Power = 1,
            Toughness = 1,
        };

        var compiled = CardCompiler.Compile(engine);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Activated.Single().MaxActivationsPerTurn);
    }

    /// <summary>
    /// The self forms of two effects that already worked on a target.
    /// </summary>
    /// <remarks>
    /// Found by comparing unread lines against lines the compiler does read: both of these sit
    /// one word away from a sentence it understood, and both were readers written earlier in this
    /// same session that took "target permanent" and not "~". The gap is invisible from the queue,
    /// because the symptom is a line that will not read and not a rule that is missing.
    /// </remarks>
    [Fact]
    public void A_permanent_can_aim_a_colour_choice_and_a_switch_at_itself()
    {
        var shifter = new CardDefinition
        {
            OracleId = "oracle-self-shift-test",
            Name = "Self Shift Test",
            OracleText = "{T}: ~ becomes the color of your choice until end of turn.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}",
            Cmc = 2,
            Power = 2,
            Toughness = 3,
        };

        var twister = new CardDefinition
        {
            OracleId = "oracle-self-switch-test",
            Name = "Self Switch Test",
            OracleText = "{T}: Switch ~'s power and toughness until end of turn.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}",
            Cmc = 2,
            Power = 2,
            Toughness = 5,
        };

        Assert.True(CardCompiler.Compile(shifter).IsComplete);
        Assert.True(CardCompiler.Compile(twister).IsComplete);

        var (game, alice, _) = InMainPhase();
        var flipper = game.Create(alice, twister, Zone.Battlefield);

        PassTo(game, 3, TurnStep.PrecombatMain);
        game.ActivateAbility(alice, flipper, "a");
        Settle(game);

        // 2/5 becomes 5/2 - aimed at itself, with no target named anywhere.
        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(flipper));
        Assert.Equal(5, computed.Power);
        Assert.Equal(2, computed.Toughness);
    }

    /// <summary>
    /// "When ~ enters, exile another target nonland permanent" and its return half (CR 400.7).
    /// </summary>
    /// <remarks>
    /// The two lines are read as a pair on purpose - an exile with no way back is a strictly
    /// better card - and the pattern for the *enters* half required the phrase to start with
    /// "target". Oblivion Ring's family says "another target", so the enters half went unread and
    /// took the return half with it, which is why the near-miss sweep reported the return line as
    /// the problem when the cause was the line above it.
    /// <para>
    /// The card that comes back is a new object (CR 400.7), which is why the counter put on it
    /// beforehand is gone when it returns - asserted here, because a return that preserved the
    /// permanent would look identical on the board.
    /// </para>
    /// </remarks>
    [Fact]
    public void Exiling_another_target_returns_it_as_a_new_object()
    {
        var ring = Card(
            "Another Ring Test",
            "When ~ enters, exile another target nonland permanent.\n"
                + "When ~ leaves the battlefield, return the exiled card to the battlefield "
                + "under its owner's control.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(ring);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var prize = game.Create(bob, TestCards.Creature("Ringed Bear Test", 2, 2), Zone.Battlefield);
        game.ChangeCounters(prize, CounterKinds.PlusOnePlusOne, 1);

        var oblivion = game.Create(alice, ring, Zone.Battlefield);
        Settle(game);

        Assert.DoesNotContain(prize, game.State.Battlefield);

        game.Move(oblivion, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        // Back under its owner's control, and bare: a new object keeps nothing it had.
        var returned = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Ringed Bear Test");

        Assert.Equal(bob, returned.ControllerId);
        Assert.Equal(
            0, returned.Permanent!.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    /// <summary>
    /// "Return up to one other target creature to its owner's hand" (CR 115.1).
    /// </summary>
    /// <remarks>
    /// "Another target creature" was read; "other target creature" was not - and a card only says
    /// the second once a count is in front of it, so the "up to one" was stripped and the grammar
    /// was handed a phrase it did not know. Both spellings mean the same thing.
    /// <para>
    /// What "other" contributes is that the source cannot be chosen, which is what is asserted:
    /// aiming the trigger at the permanent that made it is refused.
    /// </para>
    /// </remarks>
    [Fact]
    public void Up_to_one_other_target_excludes_the_source()
    {
        var mage = Card(
            "Other Bounce Test",
            "When ~ enters, return up to one other target creature to its owner's hand.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(mage);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.Creature("Bounced Bear Test", 2, 2), Zone.Battlefield);

        var self = game.Create(alice, mage, Zone.Battlefield);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice!;

        // The source is not among the options: "other" is what says so. Options for a permanent
        // carry an "object:" prefix, so the ids are matched on the suffix rather than whole.
        Assert.DoesNotContain(
            choice.Options!, o => o.Id.EndsWith(self.Value.ToString("N"), StringComparison.Ordinal));

        var offered = Assert.Single(choice.Options!);
        Assert.EndsWith(theirs.Value.ToString("N"), offered.Id, StringComparison.Ordinal);

        game.Choose(alice, [offered.Id]);
        Settle(game);

        Assert.DoesNotContain(theirs, game.State.Battlefield);
        Assert.Contains(self, game.State.Battlefield);
    }

    // ---- Can't attack or block alone -------------------------------------------

    /// <summary>
    /// "~ can't attack or block alone" (CR 506.3c, 509.1b), on the card that prints it.
    /// </summary>
    /// <remarks>
    /// A restriction on the *declaration*, which is why it is not answered by `CannotAttack`:
    /// that is handed one creature and has no way to know how many others are coming with it.
    /// Both halves are asked in the set checks instead, and both are asserted in both directions
    /// here - refused alone, allowed with company - because a check that refused everything would
    /// pass the first assertion on its own.
    /// </remarks>
    [Fact]
    public void A_creature_that_cannot_act_alone_needs_company_to_attack()
    {
        var flunkies = Card(
            "Flunkies Test", "~ can't attack or block alone.", CardType.Creature, 3, 3);

        var compiled = CardCompiler.Compile(flunkies);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var loner = game.Create(alice, flunkies, Zone.Battlefield);
        var friend = game.Create(alice, TestCards.Creature("Flunkies Friend Test", 1, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);

        var refused = Assert.Throws<InvalidOperationException>(
            () => game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
            {
                [loner] = AttackTarget.Player(bob),
            }));
        Assert.Contains("alone", refused.Message, StringComparison.Ordinal);

        // With company the same declaration is legal.
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [loner] = AttackTarget.Player(bob),
            [friend] = AttackTarget.Player(bob),
        });

        Assert.Equal(2, game.State.Combat.Attackers.Count);
    }

    [Fact]
    public void A_creature_that_cannot_act_alone_needs_company_to_block()
    {
        var flunkies = Card(
            "Blocking Flunkies Test", "~ can't attack or block alone.", CardType.Creature, 3, 3);

        var (game, alice, bob) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Alone Attacker One", 2, 2), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Alone Attacker Two", 2, 2), Zone.Battlefield);
        var loner = game.Create(bob, flunkies, Zone.Battlefield);
        var friend = game.Create(bob, TestCards.Creature("Blocking Friend Test", 1, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [first] = AttackTarget.Player(bob),
            [second] = AttackTarget.Player(bob),
        });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        var refused = Assert.Throws<InvalidOperationException>(
            () => game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
            {
                [first] = [loner],
            }));
        Assert.Contains("alone", refused.Message, StringComparison.Ordinal);

        // Company on a *different* attacker is still company: the count is of blockers, not of
        // blocks on one attacker.
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
        {
            [first] = [loner],
            [second] = [friend],
        });

        Assert.Equal(2, game.State.Combat.Blocked.Count);
    }

    // ---- Protection ------------------------------------------------------------

    [Fact]
    public void Protection_from_a_colour_stops_a_creature_of_that_colour_blocking()
    {
        // CR 702.16e, the "B" of DEBT. Protection reads as evasion from the attacker's side.
        var knight = Card(
            "Knight Test", "Protection from black", CardType.Creature, 2, 2,
            keywords: KeywordAbility.ProtectionFromBlack);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, knight, Zone.Battlefield);

        var blocker = game.Create(bob, Coloured("Zombie Test", ManaColor.Black), Zone.Battlefield);

        var why = CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(blocker), game.State.GetObject(attacker), bob);

        Assert.NotNull(why);
        Assert.Contains("702.16e", why, StringComparison.Ordinal);
    }

    /// <summary>Protection from every colour, not just the one somebody wrote a test for.</summary>
    /// <remarks>
    /// The colour table has five entries and the tests reached black and green. Swapping white or
    /// blue for a keyword nothing has changed no result - the same shape as the landwalks and as
    /// reach against flying, and by now the most reliable place in this engine to find a gap: a
    /// list of parallel alternatives where one entry is taken to stand for the rest.
    /// </remarks>
    [Theory]
    [InlineData(KeywordAbility.ProtectionFromWhite, ManaColor.White)]
    [InlineData(KeywordAbility.ProtectionFromBlue, ManaColor.Blue)]
    [InlineData(KeywordAbility.ProtectionFromBlack, ManaColor.Black)]
    [InlineData(KeywordAbility.ProtectionFromRed, ManaColor.Red)]
    [InlineData(KeywordAbility.ProtectionFromGreen, ManaColor.Green)]
    public void Protection_from_each_colour_stops_that_colour_blocking(
        KeywordAbility protection, ManaColor colour)
    {
        var knight = Card(
            $"{colour} Ward Test", protection.ToString(), CardType.Creature, 2, 2,
            keywords: protection);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, knight, Zone.Battlefield);
        var matching = game.Create(bob, Coloured($"{colour} Blocker Test", colour), Zone.Battlefield);

        var why = CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(matching), game.State.GetObject(attacker), bob);

        Assert.NotNull(why);
        Assert.Contains("702.16e", why, StringComparison.Ordinal);

        // And a creature of some other colour is still allowed through, so the assertion above is
        // about this colour rather than about protection refusing everything.
        var other = colour == ManaColor.White ? ManaColor.Black : ManaColor.White;
        var unmatched = game.Create(bob, Coloured($"{other} Bystander Test", other), Zone.Battlefield);

        Assert.Null(CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(unmatched), game.State.GetObject(attacker), bob));
    }

    [Fact]
    public void Protection_does_not_stop_another_colour()
    {
        var knight = Card(
            "Knight Test", "Protection from black", CardType.Creature, 2, 2,
            keywords: KeywordAbility.ProtectionFromBlack);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, knight, Zone.Battlefield);

        var blocker = game.Create(bob, Coloured("Elf Test", ManaColor.Green), Zone.Battlefield);

        Assert.Null(CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(blocker), game.State.GetObject(attacker), bob));
    }

    // ---- Activation limits ------------------------------------------------------

    [Fact]
    public void An_ability_limited_to_once_a_turn_refuses_a_second_activation()
    {
        // CR 602.5b. Checked before any cost is paid, so a refused second try costs nothing.
        var pump = Card(
            "Limited Test",
            "{G}: ~ gets +1/+1 until end of turn. Activate only once each turn.",
            CardType.Creature, 1, 1);

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, pump, Zone.Battlefield);

        for (var i = 0; i < 2; i++)
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.ActivateAbility(alice, creature, "a");
        Settle(game);

        var ex = Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, creature, "a"));

        Assert.Contains("602.5b", ex.Message, StringComparison.Ordinal);

        // The mana was not spent on the refused attempt.
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool[ManaColor.Green]);
    }

    // ---- Renown ------------------------------------------------------------------

    [Fact]
    public void Renown_puts_counters_on_after_combat_damage()
    {
        var hero = Card("Renown Test", "Renown 2", CardType.Creature, 2, 2);
        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, hero, Zone.Battlefield);

        game.MarkDamageToPlayer(bob, creature, 2);
        Settle(game);

        Assert.Equal(
            2,
            game.State.GetObject(creature).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    // ---- Undying -----------------------------------------------------------------

    [Fact]
    public void Undying_returns_the_creature_with_a_counter()
    {
        var ghoul = Card("Undying Test", "Undying", CardType.Creature, 2, 2);
        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, ghoul, Zone.Battlefield);

        game.Move(creature, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        var back = game.State.Battlefield
            .Select(game.State.GetObject)
            .SingleOrDefault(o => o.Card.Name == "Undying Test");

