    [Fact]
    public void Assigning_as_though_unblocked_sends_it_all_past_the_blocker()
    {
        var thorn = Card(
            "Thorn Elemental Test",
            "You may have ~ assign its combat damage as though it weren't blocked.",
            CardType.Creature,
            power: 7,
            toughness: 7);

        var compiled = CardCompiler.Compile(thorn);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, thorn, Zone.Battlefield);
        var wall = game.Create(bob, TestCards.Creature("Thorn Wall Test", 0, 8), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [wall] });

        TestCards.PassUntil(
            game, () => game.State.Choice is { Kind: ChoiceKind.AssignAsThoughUnblocked });

        var before = game.State.GetPlayer(bob).Life;
        game.Choose(alice, ["yes"]);
        Settle(game);

        // All seven past the wall, and the wall takes none - it is still blocking, so this is not
        // the same as being unblocked, but the damage goes where the permission says.
        Assert.Equal(before - 7, game.State.GetPlayer(bob).Life);
        Assert.Equal(0, game.State.GetObject(wall).Permanent!.DamageMarked);
    }

