    [Fact]
    public void Learn_is_the_discard_to_draw_half_and_compiles_to_the_same_thing_as_the_words()
    {
        var lesson = Card("Learn Test", "Learn.", CardType.Sorcery);
        var spelled = Card(
            "Learn Spelled Test",
            "You may discard a card. If you do, draw a card.",
            CardType.Sorcery);

        var keyword = CardCompiler.Compile(lesson);
        Assert.True(keyword.IsComplete, string.Join(" | ", keyword.Unhandled));

        // The keyword and the sentence fifteen cards print in full have to mean the same thing,
        // which is why one is parsed as the other rather than built beside it.
        Assert.Equal(
            CardCompiler.Compile(spelled).Spell!.Effects.Count,
            keyword.Spell!.Effects.Count);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, lesson);
        var land = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var spare = TestCards.PutInHand(game, alice, TestCards.Creature("Learn Spare Test", 1, 1));
        var handBefore = game.State.GetPlayer(alice).Hand.Count;

        game.CastSpell(alice, card, targets: null);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.OptionalPayment });
        game.Choose(alice, ["yes"]);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.DiscardToEffect });
        game.Choose(alice, [spare.Value.ToString("N")]);
        Settle(game);

        // The spell left the hand, one card was discarded and one drawn: net one fewer.
        Assert.Equal(handBefore - 1, game.State.GetPlayer(alice).Hand.Count);

        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Learn Spare Test");
    }

    [Fact]
    public void A_ciphered_spell_stays_in_exile_and_pays_out_every_time_it_connects()
    {
        var whisper = Card(
            "Cipher Whisper Test",
            "Target player loses 1 life.\nCipher",
            CardType.Sorcery);

        var compiled = CardCompiler.Compile(whisper);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var carrier = game.Create(
            alice, TestCards.Creature("Cipher Carrier Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, whisper);
        var land = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.EncodeOnCreature });
        game.Choose(alice, [carrier.Value.ToString("N")]);
        Settle(game);

        // In exile encoded on the creature, not in the graveyard.
        var encoded = game.State.Exile
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Cipher Whisper Test");

        Assert.Equal(carrier, encoded.EncodedOn);
        Assert.Equal(19, game.State.GetPlayer(bob).Life);

        // Connect: a copy is offered for free, and the encoded card stays put.
        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [carrier] = AttackTarget.Player(bob) });

        // The offer is a window that closes when its player passes priority (CR 601.2b), so the
        // loop stops the moment it appears rather than settling past it.
        for (var guard = 0; guard < 60; guard++)
        {
            if (game.State.Exile.Any(id => game.State.GetObject(id).MayCastFree))
                break;

            if (game.State.Priority.Holder is not { } holder)
                break;

            game.PassPriority(holder);
        }

        var copy = game.State.Exile
            .Select(game.State.GetObject)
            .FirstOrDefault(o => o.Card.Name == "Cipher Whisper Test" && o.MayCastFree);

        Assert.NotNull(copy);
        Assert.NotEqual(encoded.Id, copy!.Id);

        // The original is still encoded, which is the whole point - it pays out again next time.
        Assert.Equal(carrier, game.State.GetObject(encoded.Id).EncodedOn);
    }

    [Fact]
    public void A_granted_quoted_ability_can_actually_be_activated()
    {
        var gift = Card(
            "Ability Gift Test",
            "Until end of turn, target creature gains \"{T}: Add {G}\".",
            CardType.Instant);

        var compiled = CardCompiler.Compile(gift);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Gift Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, gift);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        // Granted, not merely recorded: the ability has to be there to be used, which is the
        // whole point of parsing the quoted text rather than storing it as a label.
        var now = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        var mana = Assert.Single(now.GrantedActivated);

        Assert.NotEmpty(mana.Produces);
    }

