    [Fact]
    public void Redirected_damage_is_still_dealt_just_somewhere_else()
    {
        var wall = Card(
            "Redirect Wall Test",
            "{T}: The next 2 damage that would be dealt to ~ this turn is dealt to target"
                + " creature you control instead.",
            CardType.Creature,
            power: 0,
            toughness: 6);

        var compiled = CardCompiler.Compile(wall);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var shielded = game.Create(alice, wall, Zone.Battlefield);
        var scapegoat = game.Create(
            alice, TestCards.Creature("Redirect Goat Test", 1, 5), Zone.Battlefield);

        PassTo(game, 3, TurnStep.PrecombatMain);
        game.ActivateAbility(alice, shielded, "a", [Target.ToPermanent(scapegoat)]);
        Settle(game);

        var bolt = Card("Redirect Bolt Test", "~ deals 3 damage to any target.", CardType.Instant);
        var mountain = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, mountain, "mana");

        var shot = TestCards.PutInHand(game, alice, bolt);
        game.CastSpell(alice, shot, [Target.ToPermanent(shielded)]);
        Settle(game);

        // Two of the three moved across; the third still lands where it was aimed. A prevention
        // shield would have made those two vanish instead, which is a different card.
        Assert.Equal(2, game.State.GetObject(scapegoat).Permanent!.DamageMarked);
        Assert.Equal(1, game.State.GetObject(shielded).Permanent!.DamageMarked);
    }

    [Fact]
    public void A_bounce_cost_returns_the_land_rather_than_killing_it()
    {
        var lair = Card(
            "Lair Test",
            "When ~ enters, sacrifice it unless you return a land you control to its owner's hand.",
            CardType.Land);

        var compiled = CardCompiler.Compile(lair);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var arriving = game.Create(alice, lair, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.PayOrSacrifice });
        game.Choose(alice, [forest.Value.ToString("N")]);
        Settle(game);

        // The lair stays, and the Forest goes to hand rather than to the graveyard - which is the
        // whole difference between this cost and a sacrifice.
        Assert.Contains(arriving, game.State.Battlefield);
        Assert.DoesNotContain(forest, game.State.Battlefield);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Forest");

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Forest");
    }

    [Fact]
    public void A_protection_aura_survives_the_protection_it_grants()
    {
        var ward = Card(
            "Protection Aura Test",
            "Enchant creature" + "\n" + "Enchanted creature has protection from red."
                + "\n" + "This effect doesn't remove ~.",
            CardType.Enchantment,
            subtypes: "Aura");

