        PassTo(game, 2, TurnStep.Draw);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        PassTo(game, 3, TurnStep.Draw);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_end_step_trigger_fires_in_the_ending_phase_not_the_upkeep()
    {
        var oracle = Card(
            "End Step Test",
