        var bear = game.Create(bob, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        game.MarkDamage(bear, 2);
        Settle(game);

        Assert.Equal(21, game.State.GetPlayer(alice).Life);
    }

    // ---- Triggers off combat and targeting -----------------------------------

    [Fact]
    public void Becoming_blocked_triggers_only_when_a_blocker_is_actually_declared()
    {
        var menacer = Card(
            "Becomes Blocked Test",
            "Whenever ~ becomes blocked, you gain 4 life.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, menacer, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Blocker", 1, 4), Zone.Battlefield);

        // CR 302.6: it cannot attack the turn it arrived, so the test waits for its controller's
        // next turn rather than reaching into the permanent's status.
        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void Becoming_the_target_of_a_spell_triggers_as_the_spell_is_cast()
    {
        var wary = Card(
            "Targeted Test",
            "Whenever ~ becomes the target of a spell or ability, you gain 5 life.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, wary, Zone.Battlefield);

        var bolt = TestCards.PutInHand(
            game, alice, Card("Pinprick Test", "~ deals 1 damage to target creature."));

        game.CastSpell(alice, bolt, [Target.ToPermanent(creature)]);
        Settle(game);

        Assert.Equal(25, game.State.GetPlayer(alice).Life);
        Assert.NotEqual(bob, alice);
    }

