            CardType.Creature, 1, 1);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, mage, Zone.Battlefield);

        var instant = TestCards.PutInHand(
            game, alice, Card("Cantrip Test", "Draw a card."));
        game.CastSpell(alice, instant, []);
