        Assert.Equal(21, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void Gaining_life_triggers_on_the_controllers_own_gain_only()
    {
        var angel = Card(
            "Life Watch Test",
            "Whenever you gain life, put a +1/+1 counter on it.",
            CardType.Creature, 1, 1);

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, angel, Zone.Battlefield);

        var salve = TestCards.PutInHand(game, alice, Card("Salve Test", "You gain 2 life."));
        game.CastSpell(alice, salve, []);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(creature).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        // The opponent gaining life is not "you gain life". The card is dealt after the turn
        // passes, not before: cleanup discards down to hand size (CR 514.1), and a spare card
        // handed over early is exactly the one that gets pitched.
        TestCards.PassUntil(game, () => game.State.ActivePlayerId == bob
            && game.State.CurrentStep == TurnStep.PrecombatMain);
        var theirs = TestCards.PutInHand(game, bob, Card("Their Salve Test", "You gain 2 life."));
        game.CastSpell(bob, theirs, []);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(creature).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    // ---- Keyword abilities that expand to something else ---------------------

    [Fact]
    public void Flanking_weakens_the_blocker_but_spares_another_flanker()
    {
        var knight = Card(
            "Flanking Test", "Flanking", CardType.Creature, 2, 2,
            keywords: KeywordAbility.Flanking);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, knight, Zone.Battlefield);
        var plain = game.Create(bob, TestCards.Creature("Plain", 1, 2), Zone.Battlefield);
        var flanker = game.Create(
            bob,
            Card("Other Flanker Test", "Flanking", CardType.Creature, 1, 2,
                keywords: KeywordAbility.Flanking),
            Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [plain, flanker] });

        TestCards.PassUntil(game, () => game.State.PendingTriggers.IsEmpty && game.State.Stack.IsEmpty);

        Assert.Equal(0, Characteristics.Of(game.State, Pool, game.State.GetObject(plain)).Power);

        // CR 702.25a spares a blocker that has flanking itself.
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(flanker)).Power);
    }

    [Fact]
    public void Devoid_makes_the_permanent_colourless()
