    [Fact]
    public void Damage_an_ability_deals_is_dealt_by_the_permanent_and_not_by_the_ability()
    {
        // The bug this covers: what resolves is the *ability*, which is its own object on the
        // stack, and the damage was being attributed to it. Every question about the source then
        // missed — lifelink on the creature, deathtouch on the creature, and this trigger.
        var pinger = Card(
            "Pinger Test",
            "{T}: ~ deals 1 damage to target player.\n"
                + "Whenever ~ deals damage to an opponent, you gain 2 life.",
            CardType.Creature, 1, 1);

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, pinger, Zone.Battlefield);

        // CR 302.6: it needs to have been under its controller's control since the turn began.
        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PrecombatMain);

        game.ActivateAbility(alice, creature, "a", [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(19, game.State.GetPlayer(bob).Life);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

