    [Fact]
    public void A_mana_value_trigger_measures_the_printed_cost()
    {
        var watcher = Card(
            "Mana Value Watch Test",
            "Whenever another creature you control with mana value three or greater enters, "
                + "you gain 3 life.",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        Settle(game);

        game.Create(
            alice,
            new CardDefinition
            {
                OracleId = "oracle-costly-test",
                Name = "Costly Test",
                CardTypes = CardType.Creature,
                Cmc = 4,
                Power = 1,
                Toughness = 1,
            },
            Zone.Battlefield);
        Settle(game);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);

        // Under the bar, and a big body does not raise it - this slot asks about the cost.
        game.Create(
            alice,
            new CardDefinition
            {
                OracleId = "oracle-cheap-test",
                Name = "Cheap Test",
                CardTypes = CardType.Creature,
                Cmc = 1,
                Power = 6,
                Toughness = 6,
            },
            Zone.Battlefield);
        Settle(game);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void Entering_under_your_control_is_the_same_trigger_written_backwards()
    {
        var watcher = Card(
            "Under Your Control Test",
            "Whenever another creature enters the battlefield under your control, you gain 1 life.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        Settle(game);

        game.Create(alice, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        Settle(game);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        // "Under your control" is whose it is, so an opponent's creature is not one of them.
        game.Create(bob, TestCards.Creature("Their Bear", 2, 2), Zone.Battlefield);
        Settle(game);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void The_long_form_of_dies_is_read_as_the_same_trigger()
    {
        // CR 700.4. The cards that spell it out are mostly watching permanents that are not
        // creatures, where "dies" would be the wrong word for what happened.
        var watcher = Card(
            "Artifact Mourner Test",
            "Whenever another artifact you control is put into a graveyard from the battlefield, "
                + "you gain 2 life.",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        var relic = game.Create(
            alice,
            Card("Relic Test", string.Empty, CardType.Artifact),
            Zone.Battlefield);
        Settle(game);

        game.Move(relic, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void From_anywhere_counts_a_graveyard_arrival_that_never_saw_the_battlefield()
    {
        var watcher = Card(
            "Anywhere Watch Test",
            "Whenever another creature you control is put into a graveyard from anywhere, "
                + "you gain 1 life.",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        Settle(game);

        // Discarded from hand: never on the battlefield, so it did not die - and this trigger
        // asks the wider question, which is the whole reason the longer phrase exists.
        var discarded = TestCards.PutInHand(game, alice, TestCards.Creature("Bear", 2, 2));
        game.Move(discarded, Zone.Graveyard, MoveCause.Discard);
        Settle(game);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_becomes_tapped_trigger_fires_when_a_creature_attacks()
    {
        var watcher = Card(
            "Tap Watch Test",
            "Whenever another creature you control becomes tapped, you gain 1 life.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        var attacker = game.Create(
            alice, TestCards.Creature("Tapping Attacker Test", 2, 2), Zone.Battlefield);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });
        Settle(game);

        // Attacking taps it (CR 508.1f), and tapping is tapping however it came about.
        Assert.Equal(before + 1, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_intervening_if_about_the_source_reads_the_sources_own_state()
    {
        // Two cards with the same trigger and opposite clauses, in one game, at one upkeep -
        // so whichever fires, the other one proves the clause was actually read.
        var whenTapped = Card(
            "Tapped Clause Test",
            "At the beginning of your upkeep, if this creature is tapped, you gain 5 life.",
            CardType.Creature, 2, 2);

        var whenUntapped = Card(
            "Untapped Clause Test",
            "At the beginning of your upkeep, if this creature is untapped, you gain 3 life.",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, whenTapped, Zone.Battlefield);
        game.Create(alice, whenUntapped, Zone.Battlefield);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        // Alice's next turn: both untapped after the untap step, so only the second one pays.
        PassTo(game, 3, TurnStep.Upkeep);
        Settle(game);

        Assert.Equal(before + 3, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_intervening_if_about_the_sources_type_reads_what_it_is()
    {
        var text = "At the beginning of your upkeep, if this permanent is an enchantment, "
            + "you gain 2 life.";

        var (game, alice, _) = InMainPhase();
        game.Create(alice, Card("Enchantment Clause Test", text, CardType.Enchantment), Zone.Battlefield);
        game.Create(
            alice,
            Card("Creature Clause Test", text, CardType.Creature, 2, 2),
            Zone.Battlefield);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        PassTo(game, 3, TurnStep.Upkeep);
        Settle(game);

        // Same sentence on both, and only the one that is an enchantment pays.
        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData(1, 0)]
    [InlineData(2, 1)]
    public void A_life_gain_clause_counts_what_was_gained_and_not_the_current_total(
        int gains, int expectedDraws)
    {
        // Two life a spell: one cast is under the bar and two clears it. Run as two separate
        // games so neither half can be reading life the other half gained.
        var watcher = Card(
            "Threshold Gain Test",
            "At the beginning of your end step, if you gained 3 or more life this turn, "
                + "draw a card.",
            CardType.Enchantment);

        var gain = Card("Small Gain Test", "You gain 2 life.");

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, gains))
        {
            var card = TestCards.PutInHand(game, alice, gain);
            game.CastSpell(alice, card, []);
        }

        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        Settle(game);

        Assert.Equal(gains * 2, game.State.GetPlayer(alice).LifeGainedThisTurn);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);
        Settle(game);

        // The life is gained either way; the clause is what decides whether the card is drawn.
        Assert.Equal(handBefore + expectedDraws, game.State.GetPlayer(alice).Hand.Count);
    }

    [Theory]
    [InlineData(3, 2)]
    [InlineData(1, 0)]
    public void A_clause_comparing_two_boards_counts_both_of_them(int theirLands, int gain)
    {
        var watcher = Card(
            "Land Envy Test",
            "At the beginning of your upkeep, if an opponent controls more lands than you, "
                + "you gain 2 life.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, theirLands))
            game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);

        var before = game.State.GetPlayer(alice).Life;

        PassTo(game, 3, TurnStep.Upkeep);
        Settle(game);

        // Three of theirs against one of Alice's beats it; one against one does not, because
        // "more" is strict.
        Assert.Equal(before + gain, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData(2, 2)]
    [InlineData(1, 0)]
    public void A_count_can_name_a_permanent_by_more_than_its_type(int attackers, int gain)
    {
        var watcher = Card(
            "Tapped Count Test",
            "At the beginning of your end step, if you control two or more tapped creatures, "
                + "you gain 2 life.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        var army = Enumerable.Range(0, 2)
            .Select(i => game.Create(
                alice, TestCards.Creature("Tapped Count Soldier " + i, 1, 1), Zone.Battlefield))
            .ToList();

        var before = game.State.GetPlayer(alice).Life;

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            army.Take(attackers).ToDictionary(id => id, _ => AttackTarget.Player(bob)));

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);
        Settle(game);

        // Attacking taps them (CR 508.1f), so the end step finds as many tapped creatures as
        // Alice sent - which is what makes "tapped creatures" a different count from "creatures".
        Assert.Equal(before + gain, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData(true, 2)]
    [InlineData(false, 0)]
    public void A_spell_count_clause_tells_the_two_kinds_apart(bool noncreature, int gain)
    {
        // The clause names noncreature spells, so a creature spell must not satisfy it. Counting
        // every spell would answer a narrower question with a wider number - the failure mode
        // this reader is shaped to avoid.
        var watcher = Card(
            "Spell Count Test",
            "At the beginning of your end step, if you've cast a noncreature spell this turn, "
                + "you gain 2 life.",
            CardType.Enchantment);

        var spell = noncreature
            ? Card("Counted Instant Test", "You gain 0 life.")
            : new CardDefinition
            {
                OracleId = "oracle-counted-creature-test",
                Name = "Counted Creature Test",
                OracleText = string.Empty,
                CardTypes = CardType.Creature,
                ManaCostRaw = "{1}",
                Cmc = 1,
                Power = 1,
                Toughness = 1,
            };

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        var card = TestCards.PutInHand(game, alice, spell);
        game.CastSpell(alice, card, []);

        var before = game.State.GetPlayer(alice).Life;
        Settle(game);

        Assert.Equal(1, game.State.GetPlayer(alice).SpellsCastThisTurn);
        Assert.Equal(
            noncreature ? 1 : 0, game.State.GetPlayer(alice).NoncreatureSpellsCastThisTurn);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);
        Settle(game);

        Assert.Equal(before + gain, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData(1)]
    [InlineData(3)]
    public void A_plural_combat_trigger_fires_once_however_many_connected(int attackers)
    {
        // CR 603.2 with CR 510.2: the damage is dealt simultaneously, so "one or more" is one
        // trigger. Reusing the singular reader would have fired it once per creature, and the
        // card would have paid three times for a sentence that says once.
        var watcher = Card(
            "Plural Damage Test",
            "Whenever one or more creatures you control deal combat damage to a player, "
                + "you gain 1 life.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        var army = Enumerable.Range(0, 3)
            .Select(i => game.Create(
                alice, TestCards.Creature("Plural Soldier " + i, 1, 1), Zone.Battlefield))
            .ToList();

        var before = game.State.GetPlayer(alice).Life;

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            army.Take(attackers).ToDictionary(id => id, _ => AttackTarget.Player(bob)));

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(20 - attackers, game.State.GetPlayer(bob).Life);
        Assert.Equal(before + 1, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_plural_combat_trigger_stays_silent_when_nothing_it_names_connected()
    {
        var watcher = Card(
            "Plural Flier Test",
            "Whenever one or more creatures you control with flying deal combat damage to a "
                + "player, you gain 4 life.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        var grounded = game.Create(
            alice, TestCards.Creature("Grounded Test", 2, 2), Zone.Battlefield);

        var before = game.State.GetPlayer(alice).Life;

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [grounded] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // It connected, so the batch event fired - and the description in the sentence is what
        // decides, which is the half a plural reader could most easily drop.
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(before, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData("+1/+1", 2)]
    [InlineData("-1/-1", 0)]
    public void A_counter_trigger_reads_which_kind_of_counter_arrived(string kind, int gain)
    {
        // The sentence names +1/+1 counters, so any counter at all is the wrong answer - the
        // same mistake as counting every spell for a clause about noncreature ones.
        var watcher = Card(
            "Counter Watch Test",
            "Whenever one or more +1/+1 counters are put on ~, you gain 2 life.",
            CardType.Creature, 2, 2);

        // Named for the counter it puts: the two theory cases are two different cards, and the
        // compiled pool refuses to serve one card's behaviour under another's id.
        var putter = Card(
            "Counter Putter " + kind + " Test",
            "Put a " + kind + " counter on target creature.");

        var (game, alice, _) = InMainPhase();
        var watched = game.Create(alice, watcher, Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, putter);
        game.CastSpell(alice, card, [Target.ToPermanent(watched)]);

        var before = game.State.GetPlayer(alice).Life;
        Settle(game);

        // The counter went on either way; only one of them is the one the card watches for.
        Assert.Equal(
            1,
            game.State.GetObject(watched).Permanent?.Counters.GetValueOrDefault(kind) ?? 0);

        Assert.Equal(before + gain, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void It_means_the_creature_the_trigger_was_about_and_not_the_card_that_said_it()
    {
        // CR 603.1. Only one event reported what it was about, so every other trigger reported
        // nothing and "it" fell through to meaning the permanent with the ability: this card put
        // the counter on itself, every time, and nothing failed. The two creatures are told
        // apart by which one ends up bigger.
        var shepherd = Card(
            "Counter Shepherd Test",
            "Whenever another creature you control enters, put a +1/+1 counter on it.",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        var source = game.Create(alice, shepherd, Zone.Battlefield);
        Settle(game);

        var arrival = game.Create(
            alice, TestCards.Creature("Counter Arrival Test", 1, 1), Zone.Battlefield);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(arrival).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);

        Assert.Equal(
            0,
            game.State.GetObject(source).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);
    }

    [Fact]
    public void A_pronoun_the_reader_cannot_resolve_still_leaves_the_card_unread()
    {
        // Destroy, exile and tap take a pronoun now, and the rule about what a pronoun may mean
        // did not move with them: with nothing targeted there is no referent this reader can
        // see, and the fallback would be the permanent with the ability. "Whenever ~ blocks a
        // creature, destroy that creature" would have destroyed the blocker.
        Assert.False(CardCompiler.Compile(
            Card("Dangling Destroy Test", "Destroy it.")).IsComplete);

        Assert.False(CardCompiler.Compile(
            Card("Dangling Exile Test", "Exile that creature.")).IsComplete);

        // With a target in the same sentence there is a referent, and it is used.
        Assert.True(CardCompiler.Compile(
            Card("Chained Exile Test", "Tap target creature. Exile it.")).IsComplete);
    }

    [Fact]
    public void That_player_means_the_one_who_drew_and_not_the_cards_controller()
    {
        // A draw is a zone change, and nothing told the trigger which player it was about - so
        // "that player" resolved to nobody and the effect emitted no events at all. The card
        // compiled, the trigger fired, and the game was simply not played: a failure with no
        // symptom, which is why it is asserted on the opponent's life rather than on the log.
        var watcher = Card(
            "Draw Punish Test",
            "Whenever an opponent draws a card, that player loses 2 life.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        Settle(game);

        TestCards.PassToTurn(game, 2);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PrecombatMain);
        Settle(game);

        // Bob drew for his turn and paid for it; Alice, who controls the enchantment, did not.
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void That_player_means_the_one_whose_creature_died()
    {
        // Massacre Wurm's shape. A dying creature's controller is a battlefield fact, and the
        // card is its owner's the moment it is in the graveyard (CR 108.4, CR 109.5) - so the
        // object as it last was is the one that knows whose it was.
        var wurm = Card(
            "Death Toll Test",
            "Whenever a creature an opponent controls dies, that player loses 2 life.",
            CardType.Creature, 6, 5);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, wurm, Zone.Battlefield);

        var theirs = game.Create(bob, TestCards.Creature("Doomed Test", 1, 1), Zone.Battlefield);
        Settle(game);

        game.Move(theirs, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void It_means_the_creature_that_connected_and_not_the_one_watching()
    {
        // "It" after "deals combat damage to a player" can only be the creature that dealt it -
        // the other participant is a player, not an object.
        var regent = Card(
            "Connect Counter Test",
            "Whenever another creature you control deals combat damage to a player, "
                + "put a +1/+1 counter on it.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var watcher = game.Create(alice, regent, Zone.Battlefield);
        var attacker = game.Create(
            alice, TestCards.Creature("Connecting Test", 2, 2), Zone.Battlefield);
        Settle(game);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(attacker).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);

        Assert.Equal(
            0,
            game.State.GetObject(watcher).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);
    }

    [Fact]
    public void That_player_means_the_one_whose_land_arrived()
    {
        // Polluted Bonds' shape. An object created rather than moved carries its controller on
        // the event, and nothing was reading it - so "that player" meant nobody and neither half
        // of the sentence happened.
        var bonds = Card(
            "Land Toll Test",
            "Whenever a land enters under an opponent's control, that player loses 2 life "
                + "and you gain 2 life.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, bonds, Zone.Battlefield);
        Settle(game);

        game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);

        // Alice's own land is not an opponent's, so nothing moves.
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_auras_it_means_the_creature_it_is_on_and_not_the_aura()
    {
        // Unstable Mutation's shape. The trigger fires on a step, which is about no object at
        // all, so "it" fell back to the permanent with the ability: the Aura put the counter on
        // itself, shrinking nothing, and the creature it was written to wear down was untouched.
        var mutation = Card(
            "Wasting Aura Test",
            "Enchant creature" + (char)10
                + "At the beginning of the upkeep of enchanted creature's controller, "
                + "put a -1/-1 counter on it.",
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Wasting Host Test", 3, 3), Zone.Battlefield);
        var aura = game.Create(alice, mutation, Zone.Battlefield);
        game.Attach(aura, bear);
        Settle(game);

        PassTo(game, 3, TurnStep.Upkeep);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(bear).Permanent?.Counters.GetValueOrDefault("-1/-1") ?? 0);

        Assert.Equal(
            0,
            game.State.GetObject(aura).Permanent?.Counters.GetValueOrDefault("-1/-1") ?? 0);
    }

    [Fact]
    public void That_much_life_means_what_the_sentence_before_it_just_took()
    {
        // A drain is two clauses and one number, and the number belongs to the first: "that
        // much" is not the triggering event's amount, because a spell has no triggering event.
        // The gain resolved to nothing, so every drain in the game took life and gave none -
        // and the card compiled, cast and resolved without complaint.
        var drain = Card(
            "That Much Drain Test", "Each opponent loses 2 life and you gain that much life.");

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, drain);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_gain_that_reads_its_own_clause_is_not_fed_by_the_gain_itself()
    {
        // The running amount counts life lost and damage dealt and deliberately not life
        // gained: the gain is usually the clause doing the asking, and counting it would make
        // the number grow down the card. Two drains in one spell each take their own amount.
        var twice = Card(
            "Double Drain Test",
            "Each opponent loses 1 life and you gain that much life. "
                + "Each opponent loses 3 life and you gain that much life.");

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, twice);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(16, game.State.GetPlayer(bob).Life);
        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_mass_effect_naming_a_tribe_or_a_land_type_finds_them()
    {
        // The group grammar folded plurals for the six card types and nothing else, so a tribe
        // or a land type stayed plural and the filter went looking for a subtype called
        // "Islands" - which no card has. Boil destroyed no Islands, and compiled, cast and
        // resolved without complaint.
        var boil = Card("Boil Test", "Destroy all Islands.");

        var (game, alice, bob) = InMainPhase();
        var island = game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);
        var forest = game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, boil);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.DoesNotContain(island, game.State.Battlefield);
        Assert.Contains(forest, game.State.Battlefield);
    }

    [Fact]
    public void A_mass_effect_naming_a_creature_tribe_finds_only_that_tribe()
    {
        var crusade = Card("Tribe Sweep Test", "Destroy all Goblins.");

        var (game, alice, bob) = InMainPhase();
        var goblin = game.Create(
