        Settle(game);

        Assert.DoesNotContain(goblin, game.State.Battlefield);
        Assert.Contains(bear, game.State.Battlefield);
    }

    [Fact]
    public void A_mass_pump_naming_a_colour_finds_that_colour()
    {
        // The adjective vocabulary had every colour's negation and none of the colours: there
        // was a reading for "nonwhite creature" and none at all for "white creature". The
        // sentence still compiled, because a capitalised word with no other reading is taken for
        // a creature type - so "White creatures get +2/+0" looked for a tribe called White and
        // pumped nothing.
        var charge = Card("Colour Pump Test", "White creatures get +2/+0 until end of turn.");

        var (game, alice, _) = InMainPhase();
        var soldier = game.Create(alice, Coloured("Pump White Bear", ManaColor.White), Zone.Battlefield);
        var other = game.Create(alice, Coloured("Pump Blue Bear", ManaColor.Blue), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, charge);
        game.CastSpell(alice, card, []);
        Settle(game);

        var pool = new CompiledPool();

        Assert.Equal(4, Characteristics.PowerOf(game.State, pool, game.State.GetObject(soldier)));
        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(other)));
    }

    [Fact]
    public void A_mass_pump_naming_the_attackers_finds_them()
    {
        // Same defect, different word: "Attacking" at the start of a sentence is capitalised by
        // position, and the adjective slot was matched case-sensitively - so it fell through to
        // the tribe reading, like the colours did.
        var blast = Card("Blast Pump Test", "Attacking creatures get +2/+0 until end of turn.");

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, TestCards.Creature("Blast Attacker", 2, 2), Zone.Battlefield);
        var home = game.Create(alice, TestCards.Creature("Blast Homebody", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        var card = TestCards.PutInHand(game, alice, blast);
        game.CastSpell(alice, card, []);
        Settle(game);

        var pool = new CompiledPool();

        Assert.Equal(4, Characteristics.PowerOf(game.State, pool, game.State.GetObject(attacker)));
        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(home)));
    }

    [Fact]
    public void A_mass_effect_naming_basic_lands_spares_the_others()
    {
        // "Nonbasic" had a reading and "basic" had none, the same gap the colours were in.
        var wave = Card("Basic Sweep Test", "Destroy all basic lands.");

        var (game, alice, bob) = InMainPhase();
        var island = game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);
