    [Fact]
    public void Modified_means_a_counter_or_something_attached()
    {
        // CR 701.48a: three unrelated things under one word, like historic. A counter is enough
        // on its own, and a creature with neither is not modified however large it is.
        var purge = Card("Modified Sweep Test", "Destroy all modified creatures.");

        var (game, alice, bob) = InMainPhase();
        // Counters put on by the creature's own arrival, since nothing else in the harness
        // places one directly.
        var counted = game.Create(
            bob,
            Card("Counted Test", "When ~ enters, put a +1/+1 counter on it.",
                CardType.Creature, 1, 1),
            Zone.Battlefield);
        var plain = game.Create(bob, TestCards.Creature("Plain Test", 5, 5), Zone.Battlefield);
        var worn = game.Create(bob, TestCards.Creature("Worn Test", 2, 2), Zone.Battlefield);

        var aura = game.Create(
            bob,
            Card("Sweep Aura Test", "Enchant creature", CardType.Enchantment,
                null, null, KeywordAbility.None, "Aura"),
            Zone.Battlefield);

        game.Attach(aura, worn);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(counted).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);

        var card = TestCards.PutInHand(game, alice, purge);
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.DoesNotContain(counted, game.State.Battlefield);
        Assert.DoesNotContain(worn, game.State.Battlefield);
        Assert.Contains(plain, game.State.Battlefield);
    }

    [Fact]
    public void A_granted_evasion_keyword_is_enforced_in_combat()
    {
        // The blocking rules have played fear since combat was built; the word for granting it
        // was never written into the table the compiler reads, so a card that hands it out
        // compiled to a grant of nothing. Found by diffing that table against the enum.
        var scare = Card("Fear Grant Test", "Target creature gains fear until end of turn.");

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, TestCards.Creature("Feared Test", 2, 2), Zone.Battlefield);
        var greenBlocker = game.Create(bob, Coloured("Green Blocker Test", ManaColor.Green), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        var card = TestCards.PutInHand(game, alice, scare);
        game.CastSpell(alice, card, [Target.ToPermanent(attacker)]);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        // CR 702.36b: a green creature is neither an artifact nor black, so it may not block.
        var refused = Assert.Throws<InvalidOperationException>(() =>
            game.DeclareBlockers(
                bob,
                new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
                {
                    [attacker] = [greenBlocker],
                }));

        Assert.Contains("fear", refused.Message, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public void Counting_instant_and_sorcery_cards_counts_either_of_them()
    {
        // "And" joining two card types means a card answering to either: nothing is an instant
        // and a sorcery at once, so reading it as a conjunction counts zero every time.
        var tarmo = Card(
            "Graveyard Sage Test",
            "~'s power is equal to the number of instant and sorcery cards in your graveyard.",
            CardType.Creature, 0, 4);

        var (game, alice, _) = InMainPhase();
        var sage = game.Create(alice, tarmo, Zone.Battlefield);

        game.Create(alice, Card("Yard Instant Test", string.Empty), Zone.Graveyard);
        game.Create(alice, Card("Yard Sorcery Test", string.Empty, CardType.Sorcery), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Yard Bear Test", 2, 2), Zone.Graveyard);
        Settle(game);

        var pool = new CompiledPool();
        var obj = game.State.GetObject(sage);

        // The instant and the sorcery, and not the creature.
        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, obj));
        Assert.Equal(4, Characteristics.ToughnessOf(game.State, pool, obj));
    }

    [Fact]
    public void Counting_creatures_on_the_battlefield_counts_everyones()
    {
        var mirror = Card(
            "Mirror Totem Test",
            "~'s power and toughness are each equal to the number of creatures on the battlefield.",
            CardType.Creature, 0, 0);

        var (game, alice, bob) = InMainPhase();
        var totem = game.Create(alice, mirror, Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Mirror Mine Test", 1, 1), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Mirror Theirs Test", 1, 1), Zone.Battlefield);
        Settle(game);

        var pool = new CompiledPool();

        // Both players' creatures and itself: the phrase names no owner, so neither does the count.
        Assert.Equal(3, Characteristics.PowerOf(game.State, pool, game.State.GetObject(totem)));
    }

    [Fact]
    public void A_defining_ability_may_set_one_stat_and_leave_the_other_printed()
    {
        // CR 604.3. "Power and toughness are each equal to" was read and "power is equal to" was
        // not - the same sentence with one stat in it. The half the sentence does not mention
        // keeps its printed value, which is the part a pair-only reader had nowhere to put.
        var totem = Card(
            "Defined Power Test",
            "~'s power is equal to the number of creatures you control.",
            CardType.Creature, 0, 3);

        var (game, alice, _) = InMainPhase();
        var totemId = game.Create(alice, totem, Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Defined Friend One", 1, 1), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Defined Friend Two", 1, 1), Zone.Battlefield);
        Settle(game);

        var pool = new CompiledPool();
        var obj = game.State.GetObject(totemId);

        // Three creatures: the two friends and the totem itself.
        Assert.Equal(3, Characteristics.PowerOf(game.State, pool, obj));
        Assert.Equal(3, Characteristics.ToughnessOf(game.State, pool, obj));

        // And the toughness is the printed 3 rather than a copy of the count: with one friend
        // gone the power moves and the toughness does not.
        var friend = game.State.Battlefield
            .Select(game.State.GetObject)
            .First(o => o.Card.Name == "Defined Friend One");

        game.Move(friend.Id, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        var after = game.State.GetObject(totemId);
        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, after));
        Assert.Equal(3, Characteristics.ToughnessOf(game.State, pool, after));
    }

    [Fact]
    public void Monstrosity_puts_the_counters_on_once_and_triggers_on_the_designation()
    {
        // CR 701.32a and 701.32b. The designation is what makes this different from adapt: a
        // creature that picked up +1/+1 counters some other way can still become monstrous, and
        // one that already is gets nothing however many counters it has lost since.
        var hydra = new CardDefinition
        {
            OracleId = "oracle-monstrosity-test",
            Name = "Monstrosity Test",
            OracleText = "{G}: Monstrosity 2." + (char)10
                + "When ~ becomes monstrous, you gain 3 life.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{G}",
            Cmc = 1,
            Power = 1,
            Toughness = 1,
        };

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, hydra, Zone.Battlefield);

        var before = game.State.GetPlayer(alice).Life;

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.ActivateAbility(alice, id, "a");
        Settle(game);

        Assert.Equal(
            2,
            game.State.GetObject(id).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);

        Assert.True(game.State.GetObject(id).Permanent?.IsMonstrous);
        Assert.Equal(before + 3, game.State.GetPlayer(alice).Life);

        // Already monstrous: no more counters, and the trigger does not fire a second time.
        var second = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, second, "mana");
        game.ActivateAbility(alice, id, "a");
        Settle(game);

        Assert.Equal(
            2,
            game.State.GetObject(id).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);

        Assert.Equal(before + 3, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_permanent_created_on_the_battlefield_still_enters_with_its_counters()
    {
        // CR 111.1: a token is created there and was never anywhere else, so it is not among the
        // objects the replacement pipeline walks when its own arrival is being replaced - and its
        // own replacements are exactly the ones that decide how it arrives. Every entry
        // replacement was written against the move, so this arrived bare.
        var phantom = Card(
            "Created Counters Test",
            "~ enters with two +1/+1 counters on it.",
            CardType.Creature, 1, 1);

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, phantom, Zone.Battlefield);
        Settle(game);

        Assert.Equal(
            2, game.State.GetObject(id).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);
    }

    [Fact]
    public void A_land_created_on_the_battlefield_still_enters_tapped()
    {
        // The same gap in the other entry replacement, and the reason the reader is shared: all
        // five were the same cast to ObjectMoved and wrong in the same way.
        var land = Card("Created Tapped Test", "~ enters tapped.", CardType.Land);

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, land, Zone.Battlefield);
        Settle(game);

        Assert.True(game.State.GetObject(id).Permanent?.IsTapped);
    }

    [Theory]
    [InlineData("Forest", "Island", 2)]
    [InlineData("Forest", "Forest", 1)]
    public void Sunburst_counts_the_colours_that_were_spent(
        string first, string second, int counters)
    {
        // CR 702.43a. The colours spent, not the colours in the cost: this costs {2}, names no
        // colour at all, and what it enters with depends entirely on which lands paid for it.
        var golem = new CardDefinition
        {
            OracleId = "oracle-sunburst-test",
            Name = "Sunburst Test",
            OracleText = "Sunburst",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}",
            Cmc = 2,
            Power = 0,
            Toughness = 4,
        };

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, golem);

        foreach (var basic in new[] { first, second })
        {
            var land = game.Create(alice, TestCards.BasicLand(basic), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(alice, card, []);
        Settle(game);

        var id = game.State.Battlefield
            .Select(game.State.GetObject)
            .First(o => o.Card.Name == "Sunburst Test")
            .Id;

