    [Theory]
    [InlineData("if {U} was spent to cast this spell", "Island", "Island", true)]
    [InlineData("if {U} was spent to cast this spell", "Forest", "Forest", false)]
    [InlineData("if {U}{U} was spent to cast it", "Island", "Island", true)]
    [InlineData("if {U}{U} was spent to cast it", "Island", "Forest", false)]
    [InlineData("if at least two mana was spent to cast it", "Forest", "Island", true)]
    public void A_clause_about_the_mana_spent_reads_what_actually_paid(
        string clause, string first, string second, bool fires)
    {
        // CR 202.2. The mana that paid, not the mana the cost named: this costs {2} and names no
        // colour, so the answer depends entirely on which lands were tapped. The record is kept
        // on the object from the moment it is cast, because the pool has moved on by the time
        // anything asks.
        var spell = new CardDefinition
        {
            OracleId = "oracle-spent-" + clause.GetHashCode(StringComparison.Ordinal),
            Name = "Spent Test " + clause.GetHashCode(StringComparison.Ordinal),
            OracleText = "When ~ enters, " + clause + ", you gain 4 life.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}",
            Cmc = 2,
            Power = 1,
            Toughness = 1,
        };

        Assert.True(CardCompiler.Compile(spell).IsComplete);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, spell);

        foreach (var basic in new[] { first, second })
        {
            var land = game.Create(alice, TestCards.BasicLand(basic), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        var before = game.State.GetPlayer(alice).Life;
        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(before + (fires ? 4 : 0), game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_oblivion_ring_printed_as_two_lines_gives_the_card_back()
    {
        // The pair has to be read together: an exile compiled without its return is removal that
        // never gives the card back, which is a strictly better card than the one printed.
        var ring = Card(
            "Two Line Ring Test",
            "When ~ enters, exile target creature an opponent controls." + (char)10
                + "When ~ leaves the battlefield, return the exiled card to the battlefield "
                + "under its owner's control.",
            CardType.Enchantment);

        Assert.True(CardCompiler.Compile(ring).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var victim = game.Create(bob, TestCards.Creature("Ringed Bear Test", 2, 2), Zone.Battlefield);
        var ringId = game.Create(alice, ring, Zone.Battlefield);
        Settle(game);

        Assert.DoesNotContain(victim, game.State.Battlefield);

        // And it comes back when the ring goes, under its owner's control rather than the
        // exiler's (CR 400.7 makes it a new object either way).
        game.Move(ringId, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        var returned = game.State.Battlefield
            .Select(game.State.GetObject)
            .SingleOrDefault(o => o.Card.Name == "Ringed Bear Test");

        Assert.NotNull(returned);
        Assert.Equal(bob, returned.ControllerId);
    }

