    [Fact]
    public void A_filtered_dig_takes_only_a_card_the_sentence_allows()
    {
        // "You may reveal a creature card from among them and put that card into your hand" -
        // the same dig as "put one of them into your hand" with a filter on what may be taken.
        // The take was already optional (the choice allows none), so "you may" adds nothing the
        // mechanism did not already do; what the filter adds is a rule about which card.
        var dig = Card(
            "Revealing Dig Test",
            "Look at the top five cards of your library. You may reveal a creature card from "
                + "among them and put that card into your hand. Put the rest on the bottom of "
                + "your library in a random order.");

        Assert.True(CardCompiler.Compile(dig).IsComplete);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, dig);
        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        var libraryBefore = game.State.GetPlayer(alice).Library.Count;

        game.CastSpell(alice, card, []);
        Settle(game);

        // Settle answers the choice with the first option, so one card was taken and the rest
        // went back: the library is one shorter, not five, and the hand is the size it was -
        // the dig itself left it and the taken card replaced it.
        Assert.Equal(libraryBefore - 1, game.State.GetPlayer(alice).Library.Count);
        Assert.Equal(handBefore, game.State.GetPlayer(alice).Hand.Count);
        Assert.Single(game.State.GetPlayer(alice).Graveyard);
    }

    [Theory]
    [InlineData("~ deals damage", 1)]
    [InlineData("~ deals combat damage", 1)]
    [InlineData("~ deals noncombat damage", 0)]
    public void A_damage_trigger_with_no_named_recipient_reads_the_kind_of_damage(
        string condition, int gain)
    {
        // The recipient was mandatory, so the bare forms went unread. A sentence that names no
        // recipient means any of them - and whether the damage has to be combat damage is a
        // separate question, which is why the two are read as two groups.
        var watcher = Card(
            "Damage Watch " + condition.GetHashCode(StringComparison.Ordinal),
            "Whenever " + condition + ", you gain 1 life.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, watcher, Zone.Battlefield);

        var before = game.State.GetPlayer(alice).Life;

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Combat damage: the first two fire, and the one that asks for noncombat damage does not.
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(before + gain, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData("scry", "Scry 2.", 1)]
    [InlineData("scry", "Surveil 2.", 0)]
    [InlineData("surveil", "Surveil 2.", 1)]
    [InlineData("surveil", "Scry 2.", 0)]
    public void A_scry_trigger_tells_scrying_and_surveilling_apart(
        string watched, string doing, int gain)
    {
        // CR 701.42a: surveil is the same look with a different destination, so the two are told
        // apart by that flag rather than by two readers - and a card that watches one must not
        // fire on the other.
        var watcher = Card(
            "Look Watcher " + watched,
            "Whenever you " + watched + ", you gain 1 life.",
            CardType.Enchantment);

        var spell = Card("Look Doer " + doing.GetHashCode(StringComparison.Ordinal), doing);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, spell);
        var before = game.State.GetPlayer(alice).Life;

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(before + gain, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData("you tap a land for mana", "Forest", 1)]
    [InlineData("you tap a Swamp for mana", "Forest", 0)]
    [InlineData("you tap a Swamp for mana", "Swamp", 1)]
    public void A_tapped_for_mana_trigger_reads_which_permanent_made_it(
        string condition, string basic, int gain)
    {
        // The event is the mana, not the tap: a land tapped to pay a cost never reaches this,
        // and the permanent that made it is now on the event because the pool does not remember
        // where mana came from (CR 106.1) and does not need to.
        var watcher = Card(
            "Mana Watch " + condition.GetHashCode(StringComparison.Ordinal),
            "Whenever " + condition + ", you gain 1 life.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand(basic), Zone.Battlefield);
        var before = game.State.GetPlayer(alice).Life;

        game.ActivateAbility(alice, land, "mana");
        Settle(game);

        Assert.Equal(before + gain, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_aura_watching_its_land_reads_the_land_it_is_on()
    {
        var toll = Card(
            "Mana Toll Test",
            "Enchant land" + (char)10
                + "Whenever enchanted land is tapped for mana, you gain 2 life.",
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);
        var other = game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);

        var aura = game.Create(alice, toll, Zone.Battlefield);
        game.Attach(aura, theirs);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        // The land it is on pays; the one beside it does not.
        game.ActivateAbility(bob, other, "mana");
        Settle(game);
        Assert.Equal(before, game.State.GetPlayer(alice).Life);

        game.ActivateAbility(bob, theirs, "mana");
        Settle(game);
        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_creature_this_one_damaged_pays_when_it_dies()
    {
        // The damage total cannot answer this: how much is on a creature says nothing about who
        // put it there. The dying creature is read from the state before the move, which is the
        // only state that still has it - a zone change makes a new object (CR 400.7) and the new
        // one is a card in a graveyard with no damage on it at all.
        var avenger = Card(
            "Avenger Test",
            "Whenever a creature dealt damage by ~ this turn dies, you gain 3 life.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var source = game.Create(alice, avenger, Zone.Battlefield);
        var bitten = game.Create(bob, TestCards.Creature("Bitten Test", 4, 4), Zone.Battlefield);
        var bystander = game.Create(bob, TestCards.Creature("Bystander Test", 4, 4), Zone.Battlefield);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        // A creature this one never touched dies: nothing happens.
        game.Move(bystander, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);
        Assert.Equal(before, game.State.GetPlayer(alice).Life);

        // One it damaged this turn does pay, even though the damage did not kill it.
        game.MarkDamage(bitten, 1, sourceId: source);
        Settle(game);

        game.Move(bitten, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);
        Assert.Equal(before + 3, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void The_memory_of_who_dealt_damage_is_cleared_with_the_damage()
    {
        // Cleared alongside the damage at cleanup (CR 514.2), which is the same "this turn" the
        // cards mean: a creature damaged last turn and killed this one pays nobody.
        var avenger = Card(
            "Forgetful Avenger Test",
            "Whenever a creature dealt damage by ~ this turn dies, you gain 3 life.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var source = game.Create(alice, avenger, Zone.Battlefield);
        var bitten = game.Create(bob, TestCards.Creature("Forgotten Test", 4, 4), Zone.Battlefield);
        Settle(game);

        game.MarkDamage(bitten, 1, sourceId: source);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        // Past the cleanup step, where damage and the memory of it both go.
        PassTo(game, 3, TurnStep.PrecombatMain);
        Settle(game);

        Assert.Equal(0, game.State.GetObject(bitten).Permanent?.DamageMarked ?? -1);

        game.Move(bitten, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Equal(before, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_static_that_asks_whether_it_is_attacking_turns_on_in_combat()
    {
        var berserker = Card(
            "Attacking Static Test",
            "As long as ~ is attacking, ~ gets +2/+0.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var id = game.Create(alice, berserker, Zone.Battlefield);
        Settle(game);

        var pool = new CompiledPool();

        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(id)));

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [id] = AttackTarget.Player(bob) });

        Assert.Equal(4, Characteristics.PowerOf(game.State, pool, game.State.GetObject(id)));
    }

    [Fact]
    public void A_static_that_asks_whether_it_is_equipped_reads_what_is_attached()
    {
        // CR 301.5c: equipped is a fact about the Equipment rather than about the creature, so
        // it is asked of the battlefield - and an Aura attached to the same creature is not
        // Equipment, which is the distinction the second half checks.
        var soldier = Card(
            "Equipped Static Test",
            "As long as ~ is equipped, ~ gets +1/+1.",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, soldier, Zone.Battlefield);

        var aura = game.Create(
            alice,
            Card("Static Aura Test", "Enchant creature", CardType.Enchantment,
                null, null, KeywordAbility.None, "Aura"),
            Zone.Battlefield);

        game.Attach(aura, id);
        Settle(game);

        var pool = new CompiledPool();

        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(id)));

        var sword = game.Create(
            alice,
            Card("Static Sword Test", "Equip {2}", CardType.Artifact,
                null, null, KeywordAbility.None, "Equipment"),
            Zone.Battlefield);

        game.Attach(sword, id);
        Settle(game);

        Assert.Equal(3, Characteristics.PowerOf(game.State, pool, game.State.GetObject(id)));
    }

    [Fact]
    public void Another_in_a_presence_check_excludes_the_permanent_asking()
    {
        // CR 109.5. Every adjective in this slot already worked and this one word did not, which
        // is the difference between a card that turns itself on and one that needs a friend -
        // and a creature counting itself would be permanently switched on.
        var loner = Card(
            "Another Check Test",
            "As long as you control another creature, ~ gets +2/+2.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var id = game.Create(alice, loner, Zone.Battlefield);
        Settle(game);

        var pool = new CompiledPool();

        // Alone: it does not count itself.
        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(id)));

        // An opponent's creature is not one you control either.
        game.Create(bob, TestCards.Creature("Another Theirs Test", 1, 1), Zone.Battlefield);
        Settle(game);
        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(id)));

        game.Create(alice, TestCards.Creature("Another Friend Test", 1, 1), Zone.Battlefield);
        Settle(game);
        Assert.Equal(4, Characteristics.PowerOf(game.State, pool, game.State.GetObject(id)));
    }

    [Fact]
    public void An_auras_conditional_static_asks_about_its_host_and_buffs_its_host()
    {
        // Both halves are about the enchanted permanent and neither is about the Aura: the Aura
        // is not a creature, so a reading that asked about itself would never turn on, and one
        // that buffed itself would put the bonus somewhere it cannot be used.
        var aura = Card(
            "Host Condition Test",
            "Enchant permanent" + (char)10
                + "As long as enchanted permanent is a creature, it gets +2/+2.",
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Host Bear Test", 2, 2), Zone.Battlefield);
        var rock = game.Create(
            alice, Card("Host Rock Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        var onRock = game.Create(alice, aura, Zone.Battlefield);
        game.Attach(onRock, rock);
        Settle(game);

        var pool = new CompiledPool();

        // On an artifact the condition is false, and the bear beside it is untouched either way.
        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(bear)));

        // Moved onto the creature, the condition holds and the creature is what grows.
        game.Attach(onRock, bear);
        Settle(game);

        Assert.Equal(4, Characteristics.PowerOf(game.State, pool, game.State.GetObject(bear)));
    }

    [Theory]
    [InlineData("As long as you control a Swamp, enchanted creature gets +2/+2.")]
    [InlineData("Enchanted creature gets +2/+2 as long as you control a Swamp.")]
    public void An_aura_naming_its_host_buffs_the_host_whichever_way_round_it_reads(string line)
    {
        // "Enchanted creature" is the host named directly, the same thing "it" means. The two
        // word orders are one card printed two ways, and only "~" means the Aura itself.
        var aura = Card(
            "Named Host Test " + line.GetHashCode(StringComparison.Ordinal),
            "Enchant creature" + (char)10 + line,
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Named Host Bear", 2, 2), Zone.Battlefield);
        var worn = game.Create(alice, aura, Zone.Battlefield);
        game.Attach(worn, bear);
        Settle(game);

        var pool = new CompiledPool();

        // No Swamp yet: the condition is false and the creature is its printed size.
        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(bear)));

        game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        Settle(game);

        Assert.Equal(4, Characteristics.PowerOf(game.State, pool, game.State.GetObject(bear)));
    }

    [Fact]
    public void An_auras_condition_about_it_is_about_the_creature_it_is_on()
    {
        // "Enchanted creature gets +2/+2 as long as it's attacking" is about the creature, not
        // the Aura: an Aura is not a creature and never attacks, so a reading that asked about
        // itself would never be true and the card would do nothing at all.
        var aura = Card(
            "Attacking Host Test",
            "Enchant creature" + (char)10
                + "Enchanted creature gets +2/+2 as long as it's attacking.",
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Attacking Host Bear", 2, 2), Zone.Battlefield);
        var worn = game.Create(alice, aura, Zone.Battlefield);
        game.Attach(worn, bear);
        Settle(game);

        var pool = new CompiledPool();

        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(bear)));

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [bear] = AttackTarget.Player(bob) });

