    [Fact]
    public void A_permanent_asking_about_itself_by_name_is_not_redirected()
    {
        // Only the pronoun redirects. "~ is untapped" on an Equipment is about the Equipment,
        // which can perfectly well be tapped while the creature holding it is not.
        var blade = Card(
            "Self Named Equipment Test",
            "Equip {2}" + (char)10 + "As long as ~ is untapped, equipped creature gets +2/+2.",
            CardType.Artifact, null, null, KeywordAbility.None, "Equipment");

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Blade Bearer Test", 2, 2), Zone.Battlefield);
        var sword = game.Create(alice, blade, Zone.Battlefield);
        game.Attach(sword, bear);
        Settle(game);

        var pool = new CompiledPool();

        Assert.Equal(4, Characteristics.PowerOf(game.State, pool, game.State.GetObject(bear)));

        // Tapping the Equipment turns it off, which it could not do if the question had been
        // redirected to the creature.
        game.Tap(sword);
        Settle(game);

        Assert.Equal(2, Characteristics.PowerOf(game.State, pool, game.State.GetObject(bear)));
    }

    [Theory]
    [InlineData("deals damage", 1)]
    [InlineData("deals combat damage", 1)]
    [InlineData("deals damage to an opponent", 1)]
    [InlineData("becomes blocked", 0)]
    public void An_auras_damage_trigger_watches_the_creature_it_is_on(string verb, int gain)
    {
        // The host is who deals the damage, and the Aura is who gains the life. "To an opponent"
        // is asked of the ability's controller, because "opponent" is said from the point of
        // view of whoever controls the Aura and not of the creature wearing it.
        var aura = Card(
            "Aura Damage Watch " + verb.GetHashCode(StringComparison.Ordinal),
            "Enchant creature" + (char)10
                + "Whenever enchanted creature " + verb + ", you gain 1 life.",
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, TestCards.Creature("Aura Damage Bear", 2, 2), Zone.Battlefield);
        var worn = game.Create(alice, aura, Zone.Battlefield);
        game.Attach(worn, attacker);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // Unblocked combat damage to the opponent: the three damage verbs fire and the blocking
        // one does not.
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(before + gain, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_aura_on_a_land_watches_the_land_it_is_on()
    {
        // The noun is not always "creature": a land can be enchanted and become tapped just as a
        // creature can, and the reader only knew the one word.
        var aura = Card(
            "Land Tap Watch Test",
            "Enchant land" + (char)10
                + "Whenever enchanted land becomes tapped, you gain 2 life.",
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);
        var other = game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);

        var worn = game.Create(alice, aura, Zone.Battlefield);
        game.Attach(worn, theirs);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        // The land beside it does not pay.
        game.Tap(other);
        Settle(game);
        Assert.Equal(before, game.State.GetPlayer(alice).Life);

        game.Tap(theirs);
        Settle(game);
        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData("Exile a card from your graveyard", 1)]
    [InlineData("Exile two cards from your graveyard", 2)]
    public void A_graveyard_cost_charges_the_number_the_card_names(string cost, int exiled)
    {
        // The filter was mandatory and the count was not read at all, so the plain form went
        // unread and a counted one would have charged for a single card. They vary
        // independently, and the number is what the player actually pays.
        var engine = Card(
            "Graveyard Cost Test " + exiled,
            cost + ": You gain 1 life.",
            CardType.Creature, 2, 2);

        Assert.True(CardCompiler.Compile(engine).IsComplete);

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, engine, Zone.Battlefield);

        foreach (var i in Enumerable.Range(0, 4))
        {
            game.Create(
                alice, TestCards.Creature("Graveyard Fuel " + i, 1, 1), Zone.Graveyard);
        }

        var before = game.State.GetPlayer(alice).Graveyard.Count;

        // The cards are offered with the activation rather than asked for during it: the pick
        // belongs to the player, and a cost paid mid-action would be a continuation a log cannot
        // rebuild.
        var fuel = game.State.GetPlayer(alice).Graveyard.Take(exiled).ToList();

        game.ActivateAbility(alice, id, "a", targets: null, costPayment: fuel);
        Settle(game);

        Assert.Equal(before - exiled, game.State.GetPlayer(alice).Graveyard.Count);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_counterspell_naming_two_types_takes_either_of_them()
    {
        // "Instant or sorcery" is two types the spell answers to *either* of: no card is both,
        // so a conjunction would counter nothing. Neither type could be named at all before —
        // the only type table was the one built for permanents, and a spell on the stack is a
        // card of any type (CR 205.2a).
        var counter = Card(
            "Two Type Counter Test", "Counter target instant or sorcery spell.");

        Assert.True(CardCompiler.Compile(counter).IsComplete);

        var (game, alice, _) = InMainPhase();

        var sorcery = TestCards.PutInHand(
            game, alice, Card("Countered Sorcery Test", "You gain 2 life.", CardType.Sorcery));

        var card = TestCards.PutInHand(game, alice, counter);

        // Cast on her own turn and answered while it is still on the stack: the point is which
        // spells the target grammar will accept, not who cast them.
        game.CastSpell(alice, sorcery, []);
        game.CastSpell(alice, card, [Target.ToSpell(game.State.Stack[0])]);
        Settle(game);

        // Countered, so the life was never gained and the card is in the graveyard.
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Countered Sorcery Test");

        // And a creature spell is neither an instant nor a sorcery, so it is refused.
        var bear = TestCards.PutInHand(game, alice, TestCards.Creature("Uncounterable Bear", 2, 2));
        var second = TestCards.PutInHand(game, alice, Card("Two Type Counter Encore Test",
            "Counter target instant or sorcery spell."));

        game.CastSpell(alice, bear, []);

        Assert.Throws<InvalidOperationException>(() =>
            game.CastSpell(alice, second, [Target.ToSpell(game.State.Stack[0])]));
    }

    [Theory]
    [InlineData("one", 1)]
    [InlineData("two", 2)]
    [InlineData("three", 3)]
    public void Mana_of_any_one_colour_pays_out_the_number_the_card_names(string word, int many)
    {
        // "One mana of any color" is one ability per colour and the player picks by choosing
        // which to activate. The count was not read at all, so "two" made one and "three" made
        // one: every rock of this shape paid out a fraction of what it prints, and nothing
        // failed - the ability worked, it was just poorer than the card.
        var rock = Card(
            "Any Colour Rock " + word,
            "{T}: Add " + word + " mana of any one color.",
            CardType.Artifact);

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, rock, Zone.Battlefield);

        game.ActivateAbility(alice, id, "mana");

        var pool = game.State.GetPlayer(alice).ManaPool;

        Assert.Equal(many, pool.Colored.Sum(each => each.Value));
        Assert.Equal(0, pool.Colorless);
    }

    [Fact]
    public void Mana_in_any_combination_offers_every_pair_of_colours()
    {
        // Each mana is its own colour, so the payout is a multiset rather than one choice. The
        // model already works this way — the player picks a payout by picking which ability to
        // activate — so the combinations are written out: fifteen pairs of five colours.
        var rock = Card(
            "Combination Rock Test",
            "{T}: Add two mana in any combination of colors.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(rock);

        Assert.True(compiled.Unhandled.IsEmpty);
        Assert.Equal(15, compiled.Activated.Count);

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, rock, Zone.Battlefield);

        game.ActivateAbility(alice, id, compiled.Activated[0].Id);

        var pool = game.State.GetPlayer(alice).ManaPool;

        // Whichever pair was taken, it is two mana and both of them coloured.
        Assert.Equal(2, pool.Colored.Sum(each => each.Value));
        Assert.Equal(0, pool.Colorless);
    }

    [Fact]
    public void A_combination_too_large_to_choose_from_is_left_unread()
    {
        // Three colours would be thirty-five alternatives and five would be a hundred and
        // twenty-six. Those are not menus anybody can use, so they stay unread rather than
        // being made unusable.
        Assert.False(CardCompiler.Compile(
            Card("Big Combination Test", "{T}: Add five mana in any combination of colors.",
                CardType.Artifact)).IsComplete);
    }

    [Fact]
    public void A_spell_cast_only_during_combat_is_refused_outside_it()
    {
        // CR 601.3e: a restriction on top of the type's own timing. The card is an instant, so
        // nothing else stops it being cast in a main phase - only this line does.
        var ambush = Card(
            "Combat Only Test",
            "~ deals 2 damage to any target." + (char)10 + "Cast ~ only during combat.");

        Assert.True(CardCompiler.Compile(ambush).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, ambush);

        var refused = Assert.Throws<InvalidOperationException>(() =>
            game.CastSpell(alice, card, [Target.ToPlayer(bob)]));

        Assert.Contains("cannot be cast now", refused.Message, StringComparison.OrdinalIgnoreCase);

        // In combat it is allowed and resolves. The card is put in hand again because a turn
        // passed on the way here and the cleanup step takes what is over the limit.
        PassTo(game, 3, TurnStep.BeginningOfCombat);

        var second = TestCards.PutInHand(game, alice, ambush);
        game.CastSpell(alice, second, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void An_ambush_needs_the_attack_it_names_before_it_may_be_cast()
    {
        // "You've been attacked this step" is read from the combat state rather than a tally: an
        // attacker whose target is this player *is* the fact, and the declaration recorded it.
        //
        // The negative half is the attacking player trying to use it. Nobody can cast anything
        // in this step before attackers are declared (CR 508.2 gives priority afterwards), so
        // "declared, but not at me" is the only reachable way to be refused.
        var ambush = Card(
            "Ambush Only Test",
            "~ deals 2 damage to any target." + (char)10
                + "Cast ~ only during the declare attackers step and only if you've been "
                + "attacked this step.");

        Assert.True(CardCompiler.Compile(ambush).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, TestCards.Creature("Ambushed Attacker", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        // Alice declared the attack, so Alice was not attacked: refused.
        var hers = TestCards.PutInHand(game, alice, ambush);
        Assert.Throws<InvalidOperationException>(() =>
            game.CastSpell(alice, hers, [Target.ToPlayer(bob)]));

        // Bob was attacked, so Bob may cast it once priority reaches him.
        var his = TestCards.PutInHand(game, bob, ambush);
        game.PassPriority(alice);

        game.CastSpell(bob, his, [Target.ToPlayer(alice)]);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(alice).Life);
    }

    [Theory]
    [InlineData(1)]
    [InlineData(3)]
    public void A_storage_land_pays_out_the_number_of_counters_the_player_names(int spend)
    {
        // "Remove any number of storage counters" is a number chosen as the ability is
        // activated (CR 601.2b), the way X is, and the mana that comes back is the same number.
        // The count is read once so the charge and the payout cannot disagree.
        var land = Card(
            "Storage Land Test",
            "{T}, Remove any number of storage counters from ~: "
                + "Add {C} for each storage counter removed this way.",
            CardType.Land);

        var compiled = CardCompiler.Compile(land);
        Assert.True(compiled.IsComplete);

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, land, Zone.Battlefield);

        // Counters put on directly, since the point here is what the activation charges.
        game.AddCounters(id, "storage", 4);

        game.ActivateAbility(
            alice,
            id,
            compiled.Activated.Single().Id,
            targets: null,
            costPayment: null,
            variableValue: spend);

        var pool = game.State.GetPlayer(alice).ManaPool;

        Assert.Equal(spend, pool.Colorless);
        Assert.Equal(4 - spend, game.State.GetObject(id).Permanent?.Counters.GetValueOrDefault("storage") ?? 0);
    }

    [Fact]
    public void A_phantom_loses_a_counter_instead_of_taking_damage()
    {
        // The Phantom cycle, whole: printed 0/0, enters with counters, and damage removes one
        // instead of being marked. The prevention is unconditional - what kills it is running
        // out of counters and being a 0/0 (CR 704.5f), not the damage that never landed. The
        // two lines have to be read together, because a 0/0 with no counters is dead the moment
        // it arrives.
        var phantom = new CardDefinition
        {
            OracleId = "oracle-phantom-test",
            Name = "Phantom Test",
            OracleText = "~ enters with two +1/+1 counters on it." + (char)10
                + "If damage would be dealt to ~, prevent that damage. "
                + "Remove a +1/+1 counter from ~.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{G}",
            Cmc = 1,
            Power = 0,
            Toughness = 0,
        };

        Assert.True(CardCompiler.Compile(phantom).IsComplete);

        // Cast from hand rather than created directly: an entry replacement watches the move
        // onto the battlefield, and a permanent conjured straight there never made one.
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, phantom);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.CastSpell(alice, card, []);
        Settle(game);

        var pool = new CompiledPool();

        var id = game.State.Battlefield
            .Select(game.State.GetObject)
            .First(o => o.Card.Name == "Phantom Test")
            .Id;

        Assert.Equal(
            2, game.State.GetObject(id).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);

        // Three damage takes one counter, not three, and marks nothing.
        game.MarkDamage(id, 3);
        Settle(game);

        var hit = game.State.GetObject(id);
        Assert.Equal(1, hit.Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);
        Assert.Equal(0, hit.Permanent?.DamageMarked ?? 0);
        Assert.Equal(1, Characteristics.ToughnessOf(game.State, pool, hit));

        // The last counter goes, and a 0/0 dies to a state-based action.
        game.MarkDamage(id, 1);
        Settle(game);

        Assert.DoesNotContain(id, game.State.Battlefield);
    }

    [Fact]
    public void Adapt_does_nothing_to_a_creature_that_already_has_a_counter()
    {
        // CR 702.131a. The condition is the whole keyword: adapt is a way of growing a creature
        // once, and a second activation has to be a legal thing to do that achieves nothing.
        var beast = new CardDefinition
        {
            OracleId = "oracle-adapt-test",
            Name = "Adapt Test",
            OracleText = "{G}: Adapt 2.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{G}",
            Cmc = 1,
            Power = 1,
            Toughness = 1,
        };

        var (game, alice, _) = InMainPhase();
        var id = game.Create(alice, beast, Zone.Battlefield);

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.ActivateAbility(alice, id, "a");
        Settle(game);

        Assert.Equal(
            2,
            game.State.GetObject(id).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);

        // Adapting again is legal and does nothing, because it already has counters on it.
        var second = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, second, "mana");
        game.ActivateAbility(alice, id, "a");
        Settle(game);

        Assert.Equal(
            2,
            game.State.GetObject(id).Permanent?.Counters.GetValueOrDefault("+1/+1") ?? 0);
    }

    [Fact]
    public void That_player_means_the_one_who_discarded()
    {
