        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        var card = TestCards.PutInHand(game, bob, TestCards.Creature("Discarded Test", 1, 1));
        game.Move(card, Zone.Graveyard, MoveCause.Discard);
