    [Fact]
    public void A_tribal_enters_trigger_counts_only_its_tribe_and_any_changeling()
    {
        var chief = Card(
            "Ally Test",
            "Whenever ~ or another Ally you control enters, you gain 1 life.",
            CardType.Creature, 2, 2, subtypes: "Ally");

        var (game, alice, _) = InMainPhase();
        game.Create(alice, chief, Zone.Battlefield);
        Settle(game);

        // "~ or another" includes the source's own arrival, unlike "another" on its own.
        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        game.Create(
            alice,
            Card("Other Ally Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Ally"),
            Zone.Battlefield);
        Settle(game);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);

        // A creature of another tribe does not count.
        game.Create(alice, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        Settle(game);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);

        // CR 702.73a: a changeling is every creature type, so it is an Ally too.
        game.Create(
            alice,
            Card("Shapeshifter Test", "Changeling", CardType.Creature, 1, 1,
                keywords: KeywordAbility.Changeling),
            Zone.Battlefield);
        Settle(game);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void Being_targeted_by_your_own_spell_triggers_the_cast_watcher()
