    [Fact]
    public void An_equipment_trigger_watches_the_creature_it_is_attached_to()
    {
        var blade = Card(
            "Equip Trigger Test",
            "Whenever equipped creature deals combat damage to a player, you gain 3 life.\n"
                + "Equip {2}",
            CardType.Artifact, subtypes: "Equipment");

        var (game, alice, bob) = InMainPhase();
        var equipment = game.Create(alice, blade, Zone.Battlefield);
        var bearer = game.Create(alice, TestCards.Creature("Bearer", 2, 2), Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        game.ActivateAbility(alice, equipment, "equip", [Target.ToPermanent(bearer)]);
        Settle(game);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [bearer] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());
        TestCards.PassUntil(
            game, () => game.State.CurrentStep >= TurnStep.EndOfCombat);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    // ---- Combat tricks that grant a restriction ------------------------------

    [Fact]
    public void Making_a_creature_unable_to_block_is_a_keyword_the_engine_already_enforces()
    {
        var trick = Card("Cant Block Test", "Target creature can't block this turn.");
        var (game, alice, bob) = InMainPhase();

        var attacker = game.Create(alice, TestCards.Creature("Attacker", 2, 2), Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Blocker", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, trick);

        Assert.Null(WhyNoBlock(game, blocker, attacker, bob));

        game.CastSpell(alice, card, [Target.ToPermanent(blocker)]);
        Settle(game);

        Assert.NotNull(WhyNoBlock(game, blocker, attacker, bob));
    }

    [Fact]
    public void Making_a_creature_unblockable_stops_every_block()
    {
        var trick = Card("Unblockable Test", "Target creature can't be blocked this turn.");
        var (game, alice, bob) = InMainPhase();

        var attacker = game.Create(alice, TestCards.Creature("Attacker", 2, 2), Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Blocker", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, trick);

        game.CastSpell(alice, card, [Target.ToPermanent(attacker)]);
        Settle(game);

        Assert.NotNull(WhyNoBlock(game, blocker, attacker, bob));
    }

    // ---- Combat keywords, played (CR 509-510) --------------------------------
    //
    // The most-used rules in the game: every turn of every match goes through them. They are
    // tested here through the compiler rather than through hand-written fixtures, because that is
    // how a real card reaches them — a keyword printed on a card, read into a flag, honoured by
    // the combat rules.

    /// <summary>Runs one combat with the given attackers and blockers and settles it.</summary>
    private static void Fight(
        Game game,
        Guid attackerId,
        Guid defenderId,
        IReadOnlyDictionary<ObjectId, IReadOnlyList<ObjectId>> blocks,
        params ObjectId[] attackers)
    {
        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(
            attackerId,
            attackers.ToDictionary(id => id, _ => AttackTarget.Player(defenderId)));

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(defenderId, blocks);

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.EndOfCombat);
    }

    [Fact]
    public void Trample_pushes_the_excess_through_to_the_player()
    {
        var giant = Card(
            "Trampler Test", "Trample", CardType.Creature, 5, 5,
            keywords: KeywordAbility.Trample);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, giant, Zone.Battlefield);
        var chump = game.Create(bob, TestCards.Creature("Chump", 1, 2), Zone.Battlefield);

        Fight(
            game, alice, bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [chump] },
            attacker);

        // CR 702.19b: lethal to the blocker, the rest to the player — 2 and 3.
        Assert.DoesNotContain(chump, game.State.Battlefield);
        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void A_blocked_creature_without_trample_pushes_nothing_through()
    {
        var giant = Card("Blocked Test", string.Empty, CardType.Creature, 5, 5);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, giant, Zone.Battlefield);
        var chump = game.Create(bob, TestCards.Creature("Chump", 1, 2), Zone.Battlefield);

        Fight(
            game, alice, bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [chump] },
            attacker);

        Assert.DoesNotContain(chump, game.State.Battlefield);
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void First_strike_kills_before_the_blocker_can_answer()
    {
        var duellist = Card(
            "First Strike Test", "First strike", CardType.Creature, 2, 2,
            keywords: KeywordAbility.FirstStrike);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, duellist, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Blocker", 2, 2), Zone.Battlefield);

        Fight(
            game, alice, bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] },
            attacker);

        // CR 510.4: the first-striker deals its damage in a step of its own, and a blocker that
        // dies there never deals any back.
        Assert.DoesNotContain(blocker, game.State.Battlefield);
        Assert.Contains(attacker, game.State.Battlefield);
        Assert.Equal(0, game.State.GetObject(attacker).Permanent!.DamageMarked);
    }

    [Fact]
    public void Deathtouch_kills_whatever_it_touches()
    {
        var assassin = Card(
            "Deathtouch Test", "Deathtouch", CardType.Creature, 1, 1,
            keywords: KeywordAbility.Deathtouch);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, assassin, Zone.Battlefield);
        var giant = game.Create(bob, TestCards.Creature("Giant", 6, 6), Zone.Battlefield);

        Fight(
            game, alice, bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [giant] },
            attacker);

        // CR 702.2b: any nonzero damage from a deathtouch source is lethal.
        Assert.DoesNotContain(giant, game.State.Battlefield);
    }

    [Fact]
    public void Wither_damages_a_creature_as_counters_rather_than_as_damage()
    {
        // CR 702.90a. Infect is wither plus poison, and only infect had a test - so the half they
        // share was covered through the card that does more, and wither itself never ran. The
        // difference from marked damage is that counters do not wear off at cleanup.
        var blight = Card(
            "Wither Creature Test", "Wither", CardType.Creature, 2, 2,
            keywords: KeywordAbility.Wither);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, blight, Zone.Battlefield);
        var wall = game.Create(bob, TestCards.Creature("Withered Wall Test", 0, 5), Zone.Battlefield);

        Fight(
            game, alice, bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [wall] },
            attacker);

        var hit = game.State.GetObject(wall);
        Assert.Equal(2, hit.Permanent!.Counters.GetValueOrDefault(CounterKinds.MinusOneMinusOne));
        Assert.Equal(0, hit.Permanent.DamageMarked);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, hit).Toughness);

        // Wither is not infect: the player half is ordinary damage, so no poison anywhere.
        Assert.Equal(0, game.State.GetPlayer(bob).PoisonCounters);
    }

    [Fact]
    public void Infect_damages_a_creature_as_counters_rather_than_as_damage()
    {
        // CR 702.90b has two halves and they are different mechanisms: to a player it is poison,
        // to a creature it is -1/-1 counters. Only the player half was covered, and counters are
        // the half that persists past cleanup — marked damage would wear off at end of turn.
        var blight = Card(
            "Infect Creature Test", "Infect", CardType.Creature, 2, 2,
            keywords: KeywordAbility.Infect);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, blight, Zone.Battlefield);
        var wall = game.Create(bob, TestCards.Creature("Wall", 0, 5), Zone.Battlefield);

        Fight(
            game, alice, bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [wall] },
            attacker);

        var hit = game.State.GetObject(wall);
        Assert.Equal(2, hit.Permanent!.Counters.GetValueOrDefault(CounterKinds.MinusOneMinusOne));
        Assert.Equal(0, hit.Permanent.DamageMarked);

        // 0/5 minus two counters is 0/3, and it survives — but the counters stay for good.
        Assert.Equal(3, Characteristics.Of(game.State, Pool, hit).Toughness);
    }

    [Fact]
    public void Regeneration_saves_a_creature_from_deathtouch()
    {
        // Deathtouch destroys (CR 702.2b) and regeneration replaces destruction (CR 701.19a), so
        // the shield answers it — which it would not if deathtouch were modelled as "put it in
        // the graveyard" rather than as lethal damage.
        var tough = Card(
            "Regenerating Blocker Test",
            "{G}: Regenerate ~.",
            CardType.Creature, 2, 3);

        var (game, alice, bob) = InMainPhase();
        var assassin = Card(
            "Deathtouch Attacker Test", "Deathtouch", CardType.Creature, 1, 1,
            keywords: KeywordAbility.Deathtouch);

        var attacker = game.Create(alice, assassin, Zone.Battlefield);
        var blocker = game.Create(bob, tough, Zone.Battlefield);
        var forest = game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        // Put the shield up before damage.
        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        game.ActivateAbility(bob, forest, "mana");
        game.ActivateAbility(bob, blocker, "a");

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.EndOfCombat);

        Assert.Contains(blocker, game.State.Battlefield);
    }

    [Fact]
    public void Haste_from_a_lord_lets_a_creature_attack_the_turn_it_arrives()
    {
        // Summoning sickness asks whether the creature *has* haste (CR 302.6), which is a
        // computed question — layer 6 grants it, so a lord's haste counts exactly as a printed
        // one would.
        var (game, alice, bob) = InMainPhase();

        game.Create(
            alice,
            Card("Haste Lord Test", "Other creatures you control have haste.", CardType.Enchantment),
            Zone.Battlefield);

        var fresh = game.Create(alice, TestCards.Creature("Fresh", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.True(game.State.GetObject(fresh).Permanent!.HasSummoningSickness);
        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(fresh))
            .Has(KeywordAbility.Haste));

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        // It arrived this turn and is still summoning sick, but haste lets it attack anyway.
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [fresh] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.EndOfCombat);
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void Deathtouch_and_trample_together_need_only_one_damage_each()
    {
        // CR 702.2c: with deathtouch, one damage counts as lethal for the purpose of assigning
        // trample damage — so a 5/5 facing a 1/4 assigns 1 and tramples 4 over. Reading "lethal"
        // as toughness-minus-damage instead would let only one through, and neither keyword on
        // its own shows the difference.
        var beast = Card(
            "Deathtrample Test", "Deathtouch, trample", CardType.Creature, 5, 5,
            keywords: KeywordAbility.Deathtouch | KeywordAbility.Trample);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, beast, Zone.Battlefield);
        var wall = game.Create(bob, TestCards.Creature("Wall", 0, 4), Zone.Battlefield);

        Fight(
            game, alice, bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [wall] },
            attacker);

        Assert.DoesNotContain(wall, game.State.Battlefield);
        Assert.Equal(16, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void Double_strike_deals_its_damage_in_both_steps()
    {
        var duellist = Card(
            "Double Strike Test", "Double strike", CardType.Creature, 2, 2,
            keywords: KeywordAbility.DoubleStrike);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, duellist, Zone.Battlefield);

        Fight(game, alice, bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>(), attacker);

        // CR 702.4b: once in the first-strike step and once in the normal one.
        Assert.Equal(16, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void An_aura_follows_the_creature_when_its_creature_is_stolen()
    {
        // CR 613.1b changes who controls the creature, not what is attached to it — the Aura
        // stays where it is and keeps buffing the same permanent, now under new management.
        var aura = Card(
            "Following Aura Test",
            "Enchant creature\nEnchanted creature gets +2/+2.",
            CardType.Enchantment, subtypes: "Aura");

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);

        // Bob enchants his own creature — an enchantment is sorcery-speed (CR 505.6a), so it has
        // to be his turn and his main phase, not merely his priority.
        TestCards.PassUntil(game, () => game.State.ActivePlayerId == bob
            && game.State.CurrentStep == TurnStep.PrecombatMain
            && game.State.Priority.Holder == bob);

        var card = TestCards.PutInHand(game, bob, aura);
        game.CastSpell(bob, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);

        // Alice takes the creature on her own turn. The Aura is still Bob's and still attached.
        TestCards.PassUntil(game, () => game.State.ActivePlayerId == alice
            && game.State.CurrentStep == TurnStep.PrecombatMain
            && game.State.Priority.Holder == alice);
        var steal = TestCards.PutInHand(
            game, alice, Card("Aura Grab Test", "Gain control of target creature until end of turn."));

        game.CastSpell(alice, steal, [Target.ToPermanent(bear)]);
        Settle(game);

        var stolen = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(alice, stolen.ControllerId);
        Assert.Equal(4, stolen.Power);
    }

    [Fact]
    public void Menace_needs_two_blockers_or_none()
    {
        var brute = Card(
            "Menace Test", "Menace", CardType.Creature, 3, 3,
            keywords: KeywordAbility.Menace);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, brute, Zone.Battlefield);
        var one = game.Create(bob, TestCards.Creature("One", 1, 1), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Two", 1, 1), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        // CR 702.110b: it cannot be blocked except by two or more creatures.
        Assert.Throws<InvalidOperationException>(
            () => game.DeclareBlockers(
                bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [one] }));
    }

    [Fact]
    public void Vigilance_leaves_the_attacker_untapped()
    {
        var sentinel = Card(
            "Vigilance Test", "Vigilance", CardType.Creature, 2, 2,
            keywords: KeywordAbility.Vigilance);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, sentinel, Zone.Battlefield);

        Fight(
            game, alice, bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>(), attacker);

        // CR 702.20b: attacking does not cause it to tap.
        Assert.False(game.State.GetObject(attacker).Permanent!.IsTapped);
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void Lifelink_gains_life_from_combat_damage()
    {
        var cleric = Card(
            "Lifelink Combat Test", "Lifelink", CardType.Creature, 3, 3,
            keywords: KeywordAbility.Lifelink);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, cleric, Zone.Battlefield);

        Fight(
            game, alice, bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>(), attacker);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_attacker_blocked_by_two_creatures_divides_its_damage()
    {
        // CR 510.1c: the attacker's controller divides the damage, and it is a division rather
        // than a selection — two damage to each of two three-toughness blockers, killing neither,
        // is a legal answer that no ordering could express.
        var giant = Card("Divider Test", string.Empty, CardType.Creature, 4, 4);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, giant, Zone.Battlefield);
        var first = game.Create(bob, TestCards.Creature("First", 1, 3), Zone.Battlefield);
        var second = game.Create(bob, TestCards.Creature("Second", 1, 3), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [first, second] });

        TestCards.PassUntil(
            game, () => game.State.Choice is { Kind: ChoiceKind.DivideCombatDamage });

        var choice = game.State.Choice!;
        Assert.True(choice.IsDivision);
        Assert.Equal(4, choice.TotalToDivide);
        Assert.Equal(alice, choice.PlayerId);

        // Three to the first, one to the second — killing exactly one of them.
        var toFirst = choice.Options!.Single(o => o.Id.Contains(first.Value.ToString("N"), StringComparison.Ordinal));
        var toSecond = choice.Options!.Single(o => o.Id.Contains(second.Value.ToString("N"), StringComparison.Ordinal));

        game.Choose(alice, [toFirst.Id, toFirst.Id, toFirst.Id, toSecond.Id]);
        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.EndOfCombat);

        Assert.DoesNotContain(first, game.State.Battlefield);
        Assert.Contains(second, game.State.Battlefield);
        Assert.Equal(1, game.State.GetObject(second).Permanent!.DamageMarked);
    }

    [Fact]
    public void Infect_deals_its_damage_as_poison_and_ten_of_them_is_a_loss()
    {
        // CR 702.90b: damage to a player from an infect source is poison counters instead, and
        // CR 704.5c is what makes them a way to lose rather than a curiosity.
        var blight = Card(
            "Infect Test", "Infect", CardType.Creature, 5, 5, keywords: KeywordAbility.Infect);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, blight, Zone.Battlefield);

        Fight(game, alice, bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>(), attacker);

        // The life total is untouched; the poison is what moved.
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.Equal(5, game.State.GetPlayer(bob).PoisonCounters);

        TestCards.PassToTurn(game, 5);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(
            game, () => game.State.IsOver || game.State.CurrentStep >= TurnStep.EndOfCombat);

        Assert.Equal(10, game.State.GetPlayer(bob).PoisonCounters);
        Assert.True(game.State.GetPlayer(bob).HasLost);
    }

    // ---- Threaten: control, untap, haste (CR 613.1b) -------------------------

    [Fact]
    public void Threaten_takes_the_creature_untaps_it_and_gives_it_haste()
    {
        var threaten = Card(
            "Threaten Test",
            "Gain control of target creature until end of turn. Untap that creature. "
                + "It gains haste until end of turn.");

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, threaten);

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        var stolen = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));

        // Layer 2 settles control before anything else asks whose creature it is.
        Assert.Equal(alice, stolen.ControllerId);
        Assert.True(stolen.Has(KeywordAbility.Haste));
        Assert.False(game.State.GetObject(bear).Permanent!.IsTapped);
    }

    [Fact]
    public void A_stolen_creature_is_pumped_by_its_new_controllers_lord()
    {
        // Control is layer 2 and a lord is layer 6, so by the time the lord asks whose creatures
        // it sees, the theft has already happened. Getting the order wrong here is invisible on
        // either card alone.
        var threaten = Card(
            "Steal And Pump Test", "Gain control of target creature until end of turn.");

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);

        game.Create(
            alice,
            Card("Thief Lord Test", "Other creatures you control get +2/+2.", CardType.Enchantment),
            Zone.Battlefield);

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);

        var card = TestCards.PutInHand(game, alice, threaten);
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }

    [Fact]
    public void Landwalk_asks_who_controls_the_land_now()
    {
        // Landwalk is about what the defending player controls *now* (CR 702.14b), and control is
        // layer 2 (CR 613.1b). Stealing their only Swamp turns swampwalk off, because they no
        // longer control one — which the check could not see while it read the controller stored
        // on the land.
        //
        // The other half of the same fix — computed land *types*, for effects that make every
        // land a Swamp — has no template to exercise it yet, so it is not claimed here.
        var walker = Card(
            "Swampwalker Test", "Swampwalk", CardType.Creature, 2, 2,
            keywords: KeywordAbility.Swampwalk);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, walker, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Blocker", 2, 2), Zone.Battlefield);
        var swamp = game.Create(bob, TestCards.BasicLand("Swamp"), Zone.Battlefield);

        // They control a Swamp, so the walk is on and the block is refused.
        Assert.NotNull(WhyNoBlock(game, blocker, attacker, bob));

        var steal = TestCards.PutInHand(
            game,
            alice,
            Card("Land Grab Test", "Gain control of target land until end of turn."));

        game.CastSpell(alice, steal, [Target.ToPermanent(swamp)]);
        Settle(game);

        // The Swamp is still on the battlefield, but not theirs — so the walk is off.
        Assert.Contains(swamp, game.State.Battlefield);
        Assert.Null(WhyNoBlock(game, blocker, attacker, bob));
    }

    [Fact]
    public void You_may_use_the_abilities_of_a_creature_you_have_taken()
    {
        // CR 613.1b again, reached through activation rather than through a static. Taking a
        // creature means taking what it can do — a stolen pinger pings for its new controller.
        var pinger = Card(
            "Stolen Pinger Test",
            "{T}: ~ deals 1 damage to any target.",
            CardType.Creature, 1, 1);

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(bob, pinger, Zone.Battlefield);

        // It has been under Bob's control since the turn began, so it is not summoning sick;
        // stealing it does not reset that for this test's purposes because Alice takes it on a
        // later turn.
        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PrecombatMain);

        var steal = TestCards.PutInHand(
            game,
            alice,
            Card("Take Test", "Gain control of target creature until end of turn."));

        game.CastSpell(alice, steal, [Target.ToPermanent(creature)]);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);

        // Before the fix this threw: the check read the controller stored on the object, which
        // was still Bob.
        game.ActivateAbility(alice, creature, "a", [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(19, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void A_stolen_creature_counts_as_yours_for_targeting_and_for_sweepers()
    {
        // The same layer-2 rule as the lord, reached through the target grammar instead. "You
        // control" and "your opponents control" are questions about the *computed* controller,
        // so a creature you have taken is yours for both — and a sweeper aimed at theirs must
        // now miss it.
        var threaten = Card(
            "Steal For Sweep Test", "Gain control of target creature until end of turn.");

        var (game, alice, bob) = InMainPhase();
        var stolen = game.Create(bob, TestCards.Creature("Stolen", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Theirs", 2, 2), Zone.Battlefield);

        var steal = TestCards.PutInHand(game, alice, threaten);
        game.CastSpell(alice, steal, [Target.ToPermanent(stolen)]);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);

        var sweep = TestCards.PutInHand(
            game,
            alice,
            Card("Their Sweep Test", "Creatures your opponents control get -2/-2 until end of turn."));

        game.CastSpell(alice, sweep, []);
        Settle(game);

        // The one still theirs died; the one now mine did not.
        Assert.DoesNotContain(theirs, game.State.Battlefield);
        Assert.Contains(stolen, game.State.Battlefield);
    }

    // ---- Choosing your own permanent on resolution (CR 609.4) ----------------

    [Fact]
    public void A_karoo_land_bounces_a_land_its_controller_picks()
    {
        var karoo = new CardDefinition
        {
            OracleId = "oracle-karoo-test",
            Name = "Karoo Test",
            CardTypes = CardType.Land,
            Subtypes = ["Forest"],
            OracleText = "~ enters tapped.\n"
                + "When ~ enters, return a land you control to its owner's hand.",
        };

        var (game, alice, _) = InMainPhase();
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, karoo);

        game.PlayLand(alice, card);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.ChoosePermanent });

        // The karoo itself is a land it controls, so it is on offer too — that is the real card.
        var choice = game.State.Choice!;
        Assert.Equal(alice, choice.PlayerId);
        Assert.Contains(choice.Options!, o => o.Label == "Forest");

        game.Choose(alice, [choice.Options!.Single(o => o.Label == "Forest").Id]);
        Settle(game);

        Assert.DoesNotContain(forest, game.State.Battlefield);
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Forest");
    }

    [Fact]
    public void A_sorcery_can_ask_you_to_choose_even_though_it_has_already_gone()
    {
        // The same rule that broke the counterspell tax: a spell goes to the graveyard and
        // becomes a new object as it resolves (CR 400.7), so a question asked *after* the
        // resolution cannot find the spell that asked it. Every deferred question with a locator
        // has to capture what it needs while the source is still there.
        var edict = Card("Sorcery Edict Test", "Sacrifice a creature you control.", CardType.Sorcery);

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, edict);

        game.CastSpell(alice, card, []);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.ChoosePermanent });

        var choice = game.State.Choice!;
        game.Choose(alice, [choice.Options!.Single(o => o.Label == "Bear").Id]);
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);
    }

    [Fact]
    public void Nothing_to_choose_is_not_a_failure()
    {
        // CR 608.2b is about *targets*. A choice made on resolution simply does as much as it
        // can, so an effect with nothing to pick must not stall the game on a question with no
        // answers.
        var altar = Card(
            "Empty Choice Test",
            "When ~ enters, sacrifice a creature you control.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, altar, Zone.Battlefield);
        Settle(game);

        Assert.Null(game.State.Choice);
        Assert.Single(game.State.Battlefield);
    }

    // ---- Proliferate (CR 701.34) ---------------------------------------------

    [Fact]
    public void Proliferate_adds_one_of_every_kind_already_there_and_only_where_chosen()
    {
        var spell = Card("Proliferate Test", "Proliferate.");

        var (game, alice, _) = InMainPhase();

        // Set up through real cards rather than through a back door, so the counters arrive the
        // way they would in a game. The grower carries two kinds; the other carries one.
        // Cast rather than conjured onto the battlefield: "enters with counters" is a
        // replacement on the *move* (CR 614.1c), so a permanent placed there directly never
        // meets it.
        var growerCard = TestCards.PutInHand(
            game,
            alice,
            Card(
                "Charge Grower Test",
                "~ enters with two charge counters on it.",
                CardType.Creature,
                1,
                1));

        game.CastSpell(alice, growerCard, []);
        Settle(game);

        var grower = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Charge Grower Test")
            .Id;

        var other = game.Create(alice, TestCards.Creature("Other", 1, 1), Zone.Battlefield);
        Settle(game);

        foreach (var target in new[] { grower, other })
        {
            // Settling hands priority on, so it has to come back before the next cast.
            TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);

            var pump = TestCards.PutInHand(
                game, alice, Card("Counter Spell Test", "Put a +1/+1 counter on target creature."));

            game.CastSpell(alice, pump, [Target.ToPermanent(target)]);
            Settle(game);
        }

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        var card = TestCards.PutInHand(game, alice, spell);
        game.CastSpell(alice, card, []);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Proliferate });

        var choice = game.State.Choice!;
        Assert.Equal(0, choice.MinPicks);

        // Take the grower; leave the other alone.
        game.Choose(alice, [choice.Options!.Single(o => o.Label == "Charge Grower Test").Id]);
        Settle(game);

        // "Another counter of each kind already there" — every kind, not one of them.
        var counters = game.State.GetObject(grower).Permanent!.Counters;
        Assert.Equal(2, counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));
        Assert.Equal(3, counters.GetValueOrDefault("charge"));

        // The one not chosen is untouched.
        Assert.Equal(
            1,
            game.State.GetObject(other).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    [Fact]
    public void Proliferating_nothing_is_a_legal_answer()
    {
        var spell = Card("Empty Proliferate Test", "Proliferate.");

        var (game, alice, _) = InMainPhase();
        var grower = game.Create(
            alice, TestCards.Creature("Proliferate Grower Test", 1, 1), Zone.Battlefield);

        var pump = TestCards.PutInHand(
            game, alice, Card("Lone Counter Test", "Put a +1/+1 counter on target creature."));

        game.CastSpell(alice, pump, [Target.ToPermanent(grower)]);
        Settle(game);

        var card = TestCards.PutInHand(game, alice, spell);
        game.CastSpell(alice, card, []);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Proliferate });

        // CR 701.34a: "any number", which includes none.
        game.Choose(alice, []);
        Settle(game);

        Assert.Equal(
            1,
            game.State.GetObject(grower).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    // ---- Explore (CR 701.44) -------------------------------------------------

    [Fact]
    public void Exploring_into_a_land_puts_it_in_hand_and_leaves_no_counter()
    {
        var scout = Card(
            "Explorer Test", "When ~ enters, it explores.", CardType.Creature, 1, 1);

        var (game, alice, _) = InMainPhase();
        var handBefore = game.State.GetPlayer(alice).Hand.Count;

        // Put a land on top, so the land branch is the one that runs.
        game.Create(alice, TestCards.BasicLand("Forest"), Zone.Library);

        var creature = game.Create(alice, scout, Zone.Battlefield);
        Settle(game);

        Assert.Equal(handBefore + 1, game.State.GetPlayer(alice).Hand.Count);
        Assert.Equal(
            0,
            game.State.GetObject(creature).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    [Fact]
    public void Exploring_into_a_nonland_grows_the_creature_and_offers_the_card()
    {
        var scout = Card(
            "Second Explorer Test", "When ~ enters, it explores.", CardType.Creature, 1, 1);

        var (game, alice, _) = InMainPhase();

        // A creature on top, so the other branch runs.
        game.Create(alice, TestCards.Creature("On Top", 2, 2), Zone.Library);

        var creature = game.Create(alice, scout, Zone.Battlefield);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.Surveil });

        Assert.Equal(
            1,
            game.State.GetObject(creature).Permanent!.Counters
                .GetValueOrDefault(CounterKinds.PlusOnePlusOne));

        // CR 701.44a: the controller *may* bin it. Choosing nothing leaves it on top, which is
        // the same question surveil asks — so it reuses that machinery rather than adding a kind.
        var choice = game.State.Choice!;
        Assert.Single(choice.Options!);
        Assert.Equal("On Top", choice.Options![0].Label);

        game.Choose(alice, [choice.Options![0].Id]);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "On Top");
    }

    // ---- Animating a land (CR 613.1d, 613.4b) --------------------------------

    [Fact]
    public void An_animated_land_becomes_a_creature_and_stays_a_land()
    {
        var awaken = Card(
            "Animate Test",
            "Until end of turn, target land you control becomes a 3/3 Elemental creature "
                + "with haste. It's still a land.");

        var (game, alice, _) = InMainPhase();
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, awaken);

        game.CastSpell(alice, card, [Target.ToPermanent(forest)]);
        Settle(game);

        var animated = Characteristics.Of(game.State, Pool, game.State.GetObject(forest));

        Assert.True(animated.IsCreature);
        Assert.Equal(3, animated.Power);
        Assert.True(animated.Has(KeywordAbility.Haste));

        // The rider is true because the type was *added*, not swapped — so it can still be
        // tapped for mana.
        Assert.True(animated.CardTypes.HasFlag(CardType.Land));
        Assert.NotEmpty(Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(forest)));
    }

    [Fact]
    public void Setting_power_happens_before_a_counter_modifies_it()
    {
        // CR 613.4b before 613.4c. A land that becomes a 3/3 and then takes a +1/+1 counter is a
        // 4/4 — setting first, then modifying what setting produced. A pump would have been
        // nothing at all on a land with no printed power.
        var awaken = Card(
            "Layer Order Test",
            "Until end of turn, target land you control becomes a 2/2 Elemental creature.");

        var (game, alice, _) = InMainPhase();
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, awaken);

        game.CastSpell(alice, card, [Target.ToPermanent(forest)]);
        Settle(game);

        var counters = TestCards.PutInHand(
            game, alice, Card("Counter Test", "Put a +1/+1 counter on target creature."));

        game.CastSpell(alice, counters, [Target.ToPermanent(forest)]);
        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(forest)).Power);
    }

    // ---- Restrictions printed as their own sentence --------------------------

    [Fact]
    public void An_ability_anyone_may_activate_can_be_used_by_the_opponent()
    {
        // CR 602.1a: only the controller may activate, unless the card says otherwise. A public
        // machine anyone can use is not the same object as one only you can.
        var machine = Card(
            "Public Machine Test",
            "{T}: You gain 1 life. Any player may activate this ability.",
            CardType.Artifact);

        var (game, alice, bob) = InMainPhase();
        var permanent = game.Create(alice, machine, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        game.ActivateAbility(bob, permanent, "a");
        Settle(game);

        // Bob activated it, so Bob gains the life — "you" is the ability's controller (CR 608.2).
        Assert.Equal(21, game.State.GetPlayer(bob).Life);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void An_ability_without_that_sentence_still_belongs_to_its_controller()
    {
        var machine = Card(
            "Private Machine Test", "{T}: You gain 1 life.", CardType.Artifact);

        var (game, alice, bob) = InMainPhase();
        var permanent = game.Create(alice, machine, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);

        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(bob, permanent, "a"));
    }

    [Fact]
    public void A_once_each_turn_trigger_fires_once_and_then_stops_watching()
    {
        var watcher = Card(
            "Once Per Turn Test",
            "Whenever you draw a card, you gain 2 life. This ability triggers only once each turn.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        var first = TestCards.PutInHand(game, alice, Card("First Draw Test", "Draw a card."));
        var second = TestCards.PutInHand(game, alice, Card("Second Draw Test", "Draw a card."));

        game.CastSpell(alice, first, []);
        Settle(game);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);

        // The second draw is the same turn, so the ability has stopped watching.
        game.CastSpell(alice, second, []);
        Settle(game);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);

        // A new turn hands it back its one.
        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PrecombatMain);

        var third = TestCards.PutInHand(game, alice, Card("Third Draw Test", "Draw a card."));
        game.CastSpell(alice, third, []);
        Settle(game);

        // The turn's own draw step already used it, so this is the turn after that one.
        Assert.True(game.State.GetPlayer(alice).Life > 22);
    }

    // ---- Counters of any name (CR 122.1) -------------------------------------

    [Fact]
    public void A_storage_permanent_charges_up_and_spends_what_it_stored()
    {
        // The whole cycle in one card. Counters have always been keyed by name in the engine —
        // a permanent can hold "charge" as readily as "+1/+1" — and only the compiler was pinned
        // to the two that change power and toughness.
        var battery = Card(
            "Storage Test",
            "{T}: Put a charge counter on ~.\n"
                + "Remove three charge counters from ~: You gain 4 life.",
            CardType.Artifact);

        var (game, alice, _) = InMainPhase();
        var permanent = game.Create(alice, battery, Zone.Battlefield);

        // CR 118.3: nothing stored yet, so the second ability is refused.
        var refused = Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, permanent, "a1"));
        Assert.Contains("118.3", refused.Message, StringComparison.Ordinal);

        for (var turn = 0; turn < 3; turn++)
        {
            game.ActivateAbility(alice, permanent, "a");
            Settle(game);
            TestCards.PassToTurn(game, game.State.TurnNumber + 2);
            TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PrecombatMain);
        }

        Assert.Equal(
            3,
            game.State.GetObject(permanent).Permanent!.Counters.GetValueOrDefault("charge"));

        game.ActivateAbility(alice, permanent, "a1");
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);
        Assert.Equal(
            0,
            game.State.GetObject(permanent).Permanent!.Counters.GetValueOrDefault("charge"));
    }

    [Fact]
    public void A_permanent_can_arrive_tapped_and_already_carrying_counters()
    {
        var land = new CardDefinition
        {
            OracleId = "oracle-charged-land-test",
            Name = "Charged Land Test",
            CardTypes = CardType.Land,
            Subtypes = ["Forest"],
            OracleText = "~ enters tapped with two charge counters on it.",
        };

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, land);

        game.PlayLand(alice, card);
        Settle(game);

        var arrived = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Charged Land Test");

        Assert.True(arrived.Permanent!.IsTapped);
        Assert.Equal(2, arrived.Permanent.Counters.GetValueOrDefault("charge"));
    }

    // ---- Where two mechanics meet --------------------------------------------
    //
    // Each mechanic is tested on its own above. These are the pairs — because a template that
    // behaves on a bare board can still be wrong the moment something else is in play, and the
    // layer system exists precisely to make those pairs come out right.

    [Fact]
    public void A_crewed_vehicle_is_a_creature_in_time_for_a_lord_to_pump_it()
    {
        // Layer 4 turns it into a creature; layer 6 and 7 run after and must see what layer 4
        // just made (CR 613.1). If the lord read printed types it would miss the Vehicle
        // entirely, and nothing about either card alone would show it.
        var vehicle = Card(
            "Lorded Vehicle Test", "Crew 2", CardType.Artifact, 3, 3, subtypes: "Vehicle");

        var (game, alice, _) = InMainPhase();
        var truck = game.Create(alice, vehicle, Zone.Battlefield);
        var crew = game.Create(alice, TestCards.Creature("Crew", 2, 2), Zone.Battlefield);

        game.Create(
            alice,
            Card("Vehicle Lord Test", "Other creatures you control get +1/+1.", CardType.Enchantment),
            Zone.Battlefield);

        // Not a creature yet, so the lord does not reach it.
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(truck)).Power);

        game.ActivateAbility(alice, truck, "crew", targets: null, costPayment: [crew]);
        Settle(game);

        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(truck)).Power);
    }

    [Fact]
    public void A_lord_can_save_a_creature_from_a_sweeper_that_would_have_killed_it()
    {
        // The sweeper works out toughness as it resolves, and state-based actions ask again
        // afterwards — so the lord's +1/+1 is the difference between dying and surviving.
        var (game, alice, _) = InMainPhase();

        var small = game.Create(alice, TestCards.Creature("Small", 1, 1), Zone.Battlefield);
        game.Create(
            alice,
            Card("Saving Lord Test", "Other creatures you control get +1/+1.", CardType.Enchantment),
            Zone.Battlefield);

        var sweeper = TestCards.PutInHand(
            game, alice, Card("Small Sweep Test", "All creatures get -1/-1 until end of turn."));

        game.CastSpell(alice, sweeper, []);
        Settle(game);

        // 1/1, plus the lord, minus the sweeper — still alive at 1/1.
        Assert.Contains(small, game.State.Battlefield);
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(small)).Toughness);
    }

    [Fact]
    public void Undying_brings_it_back_from_a_sweeper_too()
    {
        var ghoul = Card(
            "Undying Sweep Test", "Undying", CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, ghoul, Zone.Battlefield);

        var sweeper = TestCards.PutInHand(
            game, alice, Card("Big Sweep Test", "Destroy all creatures."));

        game.CastSpell(alice, sweeper, []);
        Settle(game);

        // It died to the sweeper and came straight back with a counter (CR 702.92a).
        var back = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Undying Sweep Test");

        Assert.Equal(
            1, back.Permanent!.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne));
    }

    [Fact]
    public void Protection_stops_a_block_even_when_a_lord_has_made_the_blocker_bigger()
    {
        // Protection is not about size, and a bigger blocker is still forbidden (CR 702.16e).
        var knight = Card(
            "Protected Test", "Protection from green", CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, knight, Zone.Battlefield);
        var blocker = game.Create(bob, Coloured("Green Blocker", ManaColor.Green), Zone.Battlefield);

        game.Create(
            bob,
            Card("Blocker Lord Test", "Other creatures you control get +3/+3.", CardType.Enchantment),
            Zone.Battlefield);

        Assert.Equal(5, Characteristics.Of(game.State, Pool, game.State.GetObject(blocker)).Power);
        Assert.NotNull(WhyNoBlock(game, blocker, attacker, bob));
    }

    [Fact]
    public void An_equipment_comes_loose_when_its_bearer_dies_and_stops_buffing()
    {
        // CR 704.5n: an Equipment attached to nothing is unattached by a state-based action. The
        // buff has to stop with it, which is the bug the layer system was rebuilt to prevent.
        var sword = Card(
            "Loose Sword Test",
            "Equipped creature gets +3/+3.\nEquip {2}",
            CardType.Artifact, subtypes: "Equipment");

        var (game, alice, _) = InMainPhase();
        var equipment = game.Create(alice, sword, Zone.Battlefield);
        var bearer = game.Create(alice, TestCards.Creature("Bearer", 2, 2), Zone.Battlefield);
        var other = game.Create(alice, TestCards.Creature("Other", 2, 2), Zone.Battlefield);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        game.ActivateAbility(alice, equipment, "equip", [Target.ToPermanent(bearer)]);
        Settle(game);

        Assert.Equal(5, Characteristics.Of(game.State, Pool, game.State.GetObject(bearer)).Power);

        game.MarkDamage(bearer, 5);
        Settle(game);

        // The Equipment is still on the battlefield, attached to nothing, buffing nothing.
        Assert.Contains(equipment, game.State.Battlefield);
        Assert.Null(game.State.GetObject(equipment).Permanent!.AttachedTo);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(other)).Power);
    }

    [Fact]
    public void A_modal_spell_can_be_kicked_too()
    {
        var command = Kicked(
            "Modal Kicker Test", "{1}",
            "Choose one —\n• You gain 2 life.\n• Draw a card.\nKicker {1}\n"
                + "If this spell was kicked, you gain 5 life.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, command);

        foreach (var _ in Enumerable.Range(0, 2))
        {
            var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, forest, "mana");
        }

        game.CastSpell(
            alice, card, targets: null, variableValue: 0, tapToPay: null, modes: [0], kicked: true);

        Settle(game);

        // The chosen mode and the kicked clause both happened; the unchosen mode did not.
        Assert.Equal(27, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_delayed_sacrifice_still_fires_when_the_permanent_changed_hands()
    {
        // CR 603.7c asks only whether the object is still in the zone the ability expects, not
        // who controls it — so a Vehicle that was crewed and then had its delayed exile set up
        // goes away regardless of what else happened to it in between.
        var token = Card(
            "Fleeting Test",
            "When ~ enters, sacrifice it at the beginning of the next end step.",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, token);

        game.CastSpell(alice, card, []);
        Settle(game);

        var creature = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Fleeting Test");

        // A pump in between changes nothing about the delayed ability.
        var pump = TestCards.PutInHand(
            game, alice, Card("Fleeting Pump Test", "Target creature gets +2/+2 until end of turn."));

        game.CastSpell(alice, pump, [Target.ToPermanent(creature.Id)]);
        Settle(game);

        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(creature.Id)).Power);

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.Cleanup);

        Assert.DoesNotContain(creature.Id, game.State.Battlefield);
    }

    // ---- Morph and face-down permanents (CR 702.37, 707) ---------------------

    /// <summary>A morph creature that is obviously not a 2/2, and has a trigger to silence.</summary>
    private static CardDefinition Morphling(string name) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        OracleText = "Flying\nWhenever ~ attacks, you gain 3 life.\nMorph {1}",
        CardTypes = CardType.Creature,
        Subtypes = ["Bird"],
        Power = 5,
        Toughness = 5,
        ManaCostRaw = "{7}",
        Keywords = KeywordAbility.Flying,
    };

    private static ObjectId CastFaceDown(Game game, Guid who, CardDefinition card)
    {
        var inHand = TestCards.PutInHand(game, who, card);

        foreach (var _ in Enumerable.Range(0, 3))
        {
            var land = game.Create(who, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(who, land, "mana");
        }

        game.CastSpell(
            who, inHand, targets: null, variableValue: 0, tapToPay: null, modes: null,
            kicked: false, costPayment: null, faceDown: true);

        return inHand;
    }

    [Fact]
    public void A_face_down_creature_is_a_vanilla_two_two_whatever_the_card_says()
    {
        var (game, alice, _) = InMainPhase();
        CastFaceDown(game, alice, Morphling("Morph Test"));
        Settle(game);

        var hidden = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Morph Test");

        var computed = Characteristics.Of(game.State, new CompiledPool(), game.State.GetObject(hidden));

        // CR 707.2: 2/2, colourless, creature and nothing else, no abilities.
        Assert.Equal(2, computed.Power);
        Assert.Equal(2, computed.Toughness);
        Assert.Equal(CardType.Creature, computed.CardTypes);
        Assert.Empty(computed.Subtypes);
        Assert.Empty(computed.Colors);
        Assert.False(computed.Has(KeywordAbility.Flying));
    }

    [Fact]
    public void Turning_it_face_up_gives_back_everything_the_card_had()
    {
        var (game, alice, _) = InMainPhase();
        CastFaceDown(game, alice, Morphling("Unmorph Test"));
        Settle(game);

        var hidden = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Unmorph Test");

        var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.TurnFaceUp(alice, hidden);

        var computed = Characteristics.Of(game.State, new CompiledPool(), game.State.GetObject(hidden));

        Assert.Equal(5, computed.Power);
        Assert.True(computed.Has(KeywordAbility.Flying));
        Assert.Contains("Bird", computed.Subtypes);
    }

    [Fact]
    public void A_face_down_creatures_triggers_do_not_watch_the_game()
    {
        // The card gains 3 life whenever it attacks. Face down it has no abilities at all, so
        // attacking with it does nothing — this is the half that a 2/2 power check cannot show.
        var (game, alice, bob) = InMainPhase();
        CastFaceDown(game, alice, Morphling("Silent Morph Test"));
        Settle(game);

        var hidden = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Silent Morph Test");

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [hidden] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());
        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.EndOfCombat);

        // Two damage, not five — and no life gained.
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_card_without_morph_cannot_be_cast_face_down()
    {
        var (game, alice, _) = InMainPhase();
        var plain = TestCards.PutInHand(game, alice, TestCards.Creature("No Morph Test"));

        foreach (var _ in Enumerable.Range(0, 3))
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        Assert.Throws<InvalidOperationException>(() => game.CastSpell(
            alice, plain, targets: null, variableValue: 0, tapToPay: null, modes: null,
            kicked: false, costPayment: null, faceDown: true));
    }

    /// <summary>A face-down creature card with the given keyword line.</summary>
    private static CardDefinition Hidden(string name, string keywordLine) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        OracleText = keywordLine,
        CardTypes = CardType.Creature,
        Power = 5,
        Toughness = 5,
        ManaCostRaw = "{7}",
    };

    [Fact]
    public void Megamorph_turns_up_one_bigger_than_morph_would()
    {
        var (game, alice, _) = InMainPhase();
        CastFaceDown(game, alice, Hidden("Megamorph Test", "Megamorph {1}"));
        Settle(game);

        var creature = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Megamorph Test");

        var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.TurnFaceUp(alice, creature);

        // 5/5 printed, plus the +1/+1 counter megamorph puts on as it turns up. Plain morph
        // would leave it a 5/5, which is the one number that separates the two keywords.
        var computed = Characteristics.Of(
            game.State, new CompiledPool(), game.State.GetObject(creature));

        Assert.Equal(6, computed.Power);
        Assert.Equal(6, computed.Toughness);
    }

    [Fact]
    public void Disguise_wards_while_face_down_and_stops_warding_once_it_is_up()
    {
        var (game, alice, bob) = InMainPhase();
        CastFaceDown(game, alice, Hidden("Disguise Test", "Disguise {1}"));
        Settle(game);

        var creature = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Disguise Test");

        // Bob targets it with no mana to spare: ward counters his spell.
        TestCards.PassToTurn(game, 2);
        var bolt = TestCards.PutInHand(
            game, bob, Card("Disguise Bolt Test", "Destroy target creature."));

        game.CastSpell(bob, bolt, [Target.ToPermanent(creature)]);
        SettleDeclining(game);

        Assert.Contains(creature, game.State.Battlefield);

        // Turn it face up. The card itself has no ward, so the next spell gets through.
        TestCards.PassToTurn(game, 3);
        var land = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");
        game.TurnFaceUp(alice, creature);
        Settle(game);

        TestCards.PassToTurn(game, 4);
        var second = TestCards.PutInHand(
            game, bob, Card("Second Bolt Test", "Destroy target creature."));

        game.CastSpell(bob, second, [Target.ToPermanent(creature)]);
        SettleDeclining(game);

        Assert.DoesNotContain(creature, game.State.Battlefield);
    }

    // ---- Counters on a whole group, and targeted discard ---------------------

    [Fact]
    public void Counters_on_each_creature_you_control_skip_the_opponents()
    {
        var anthem = Card(
            "Mass Counter Test",
            "When ~ enters, put a +1/+1 counter on each creature you control.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("My Bear Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Their Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, anthem);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        var pool = new CompiledPool();
        Assert.Equal(3, Characteristics.Of(game.State, pool, game.State.GetObject(mine)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, pool, game.State.GetObject(theirs)).Power);
    }

    [Fact]
    public void Target_player_discards_and_the_caster_keeps_their_hand()
    {
        var spell = Card("Targeted Discard Test", "Target player discards two cards.");

        var (game, alice, bob) = InMainPhase();

        foreach (var i in Enumerable.Range(0, 3))
        {
            TestCards.PutInHand(game, bob, TestCards.Creature($"Bob Card {i} Test"));
            TestCards.PutInHand(game, alice, TestCards.Creature($"Alice Card {i} Test"));
        }

        var card = TestCards.PutInHand(game, alice, spell);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        var aliceBefore = game.State.GetPlayer(alice).Hand.Count;
        var bobBefore = game.State.GetPlayer(bob).Hand.Count;
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        // Two fewer than he held, counting the opening hand he was dealt.
        Assert.Equal(bobBefore - 2, game.State.GetPlayer(bob).Hand.Count);

        // Alice loses only the spell she cast. A discard that fell back to "you" would take two
        // more from her, which is the mistake a scope-shaped implementation makes.
        Assert.Equal(aliceBefore - 1, game.State.GetPlayer(alice).Hand.Count);
    }

    [Fact]
    public void Look_at_the_top_cards_can_bin_the_rest_instead_of_burying_them()
    {
        var spell = Card(
            "Look Bin Test",
            "Look at the top three cards of your library. Put one of them into your hand and "
                + "the rest into your graveyard.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var graveBefore = game.State.GetPlayer(alice).Graveyard.Count;
        var libraryBefore = game.State.GetPlayer(alice).Library.Count;

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        // Three came off the top: one to hand, two to the graveyard — plus the spell itself.
        Assert.Equal(libraryBefore - 3, game.State.GetPlayer(alice).Library.Count);
        Assert.Equal(graveBefore + 3, game.State.GetPlayer(alice).Graveyard.Count);
    }

    // ---- "If it would die this turn, exile it instead" (CR 614.1c) -----------

    [Fact]
    public void A_creature_killed_under_that_replacement_never_reaches_the_graveyard()
    {
        var spell = Card(
            "Puncture Test",
            "~ deals 5 damage to target creature. "
                + "If that creature would die this turn, exile it instead.");

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Punctured Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);

        // The whole point: it is not in the graveyard either. Anything watching for a death saw
        // nothing, and nothing can bring it back from there.
        Assert.DoesNotContain(
            game.State.GetPlayer(bob).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Punctured Bear Test");

        Assert.Contains(
            game.State.Exile,
            id => game.State.GetObject(id).Card.Name == "Punctured Bear Test");
    }

    [Fact]
    public void A_creature_that_survives_the_turn_dies_normally_afterwards()
    {
        // "This turn" is a duration, and the replacement has to end with it — otherwise the card
        // quietly exiles a creature on some later turn that nothing said it should.
        var spell = Card(
            "Weak Puncture Test",
            "~ deals 1 damage to target creature. "
                + "If that creature would die this turn, exile it instead.");

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Survivor Bear Test", 3, 3), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Contains(bear, game.State.Battlefield);

        TestCards.PassToTurn(game, 3);

        var kill = TestCards.PutInHand(
            game, alice, Card("Later Kill Test", "Destroy target creature."));

        var land2 = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, land2, "mana");
        game.CastSpell(alice, kill, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Survivor Bear Test");
    }

    // ---- A choice nested inside an offer (CR 601.2b, 609.4) ------------------

    [Fact]
    public void You_may_sacrifice_a_creature_asks_twice_and_takes_the_one_chosen()
    {
        var spell = Card(
            "Optional Sacrifice Test",
            "You may sacrifice a creature. If you do, draw a card.");

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Offered Bear Test"), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        game.CastSpell(alice, card, targets: null);

        // Two questions in sequence: take the offer, then pick what to sacrifice. The second is
        // the one that could not be found before — a choice nested inside an offer's branch.
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);
        Assert.Equal(handBefore - 1 + 1, game.State.GetPlayer(alice).Hand.Count);
    }

