    // ---- Reanimation, and raking a graveyard ---------------------------------

    [Fact]
    public void Reanimating_puts_the_creature_under_the_casters_control()
    {
        var spell = Card(
            "Control Reanimate Test",
            "Put target creature card from a graveyard onto the battlefield under your control.");

        var (game, alice, bob) = InMainPhase();

        // The card is in the opponent's graveyard: it should arrive on the caster's side, which
        // is the whole reason the card says whose control it enters under.
        game.Create(bob, TestCards.Creature("Raised Bear Test", 2, 2), Zone.Graveyard);

        var card = TestCards.PutInHand(game, alice, spell);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(
            alice,
            card,
            [Target.ToCard(game.State.GetPlayer(bob).Graveyard.Single(
                id => game.State.GetObject(id).Card.Name == "Raised Bear Test"))]);

        Settle(game);

        var raised = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Raised Bear Test");

        Assert.Equal(alice, game.State.GetObject(raised).ControllerId);

        // CR 108.4: ownership never changes, however control does.
        Assert.Equal(bob, game.State.GetObject(raised).OwnerId);
    }

