    // ---- Madness (CR 702.35) -------------------------------------------------

    [Fact]
    public void A_discarded_madness_card_goes_to_exile_and_is_offered_for_its_madness_cost()
    {
        var oracle = Kicked(
            "Madness Test", "{5}", "You gain 3 life.\nMadness {1}", cmc: 5);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, oracle);

        var discarder = TestCards.PutInHand(
            game, alice, Card("Madness Discard Test", "Target player discards a card."));

        foreach (var name in new[] { "Forest", "Plains" })
        {
            var land = game.Create(alice, TestCards.BasicLand(name), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(alice, discarder, [Target.ToPlayer(alice)]);

        // The discard is a real choice and this test is about which card gets discarded, so it
        // answers by name rather than letting a helper take the first option.
        for (var guard = 0; guard < 40; guard++)
        {
            if (game.State.Choice is { } choice)
            {
                var pick = choice.Options!.FirstOrDefault(o => o.Label == "Madness Test")
                    ?? choice.Options![0];

                game.Choose(choice.PlayerId, [pick.Id]);
                continue;
            }

            if (game.State.Exile.Any(id => game.State.GetObject(id).MayCastFree))
                break;

            if (game.State.Priority.Holder is not { } holder)
                break;

            game.PassPriority(holder);
        }

        var offered = game.State.Exile.FirstOrDefault(
            id => game.State.GetObject(id).MayCastFree);

        Assert.NotEqual(default, offered);

        // CR 702.35a: exile, not the graveyard — and the offer charges the madness cost rather
        // than nothing, which is the difference from cascade.
        Assert.Equal("{1}", game.State.GetObject(offered).OfferedCost);
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Madness Test");
    }

    // ---- Rebound (CR 702.88) -------------------------------------------------

    [Fact]
    public void A_rebounding_spell_exiles_itself_and_comes_back_next_upkeep()
    {
        var oracle = Kicked("Rebound Test", "{1}", "You gain 3 life.\nRebound", cmc: 1);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, oracle);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        // It resolved, and went to exile rather than the graveyard.
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Rebound Test");

        var waiting = game.State.Exile.Single(
            id => game.State.GetObject(id).Card.Name == "Rebound Test");

        Assert.False(game.State.GetObject(waiting).MayCastFree);

        // Alice's next upkeep offers it back, and it casts with no mana at all.
        // The delayed ability fires as the step is entered, before anybody has priority — so the
        // wait is for the offer *and* for Alice to be able to act on it.
        TestCards.PassUntil(
            game,
            () => game.State.Priority.Holder == alice
                && game.State.Exile.Any(
                    id => game.State.GetObject(id).Card.Name == "Rebound Test"
                        && game.State.GetObject(id).MayCastFree));

        var offered = game.State.Exile.Single(
            id => game.State.GetObject(id).Card.Name == "Rebound Test");

        game.CastSpell(alice, offered, targets: null);
        Settle(game);

        Assert.Equal(26, game.State.GetPlayer(alice).Life);
    }

    // ---- Sweepers and prevention ---------------------------------------------

    [Fact]
    public void Damage_to_each_creature_and_each_player_reads_both_halves_of_the_sentence()
    {
        var quake = Card("Ember Wave Test", "~ deals 2 damage to each creature and each player.");

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, TestCards.Creature("Sturdy Test", 3, 3), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Frail Test", 1, 1), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, quake);
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        // Both halves, and the caster is not spared either — "each player" includes them.
        Assert.Equal(18, game.State.GetPlayer(alice).Life);
        Assert.Equal(18, game.State.GetPlayer(bob).Life);

        Assert.Contains(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Sturdy Test");
        Assert.DoesNotContain(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Frail Test");
    }

    [Fact]
    public void A_fog_stops_the_whole_combat_damage_step_and_wears_off_after_it()
    {
        var (game, alice, bob) = InMainPhase();

        // Two attackers, because one proves only half of it. The blocked one shows the damage
        // between creatures is prevented; the unblocked one shows the damage to the player is,
        // and a single blocked attacker would have reached neither.
        var blocked = game.Create(
            alice, TestCards.Creature("Fogged Attacker Test", 3, 3), Zone.Battlefield);
        var loose = game.Create(
            alice, TestCards.Creature("Loose Attacker Test", 4, 4), Zone.Battlefield);
        var blocker = game.Create(
            bob, TestCards.Creature("Fogged Blocker Test", 2, 2), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [blocked] = AttackTarget.Player(bob),
                [loose] = AttackTarget.Player(bob),
            });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [blocked] = [blocker] });

        var fog = TestCards.PutInHand(
            game,
            alice,
            Card("Fog Test", "Prevent all combat damage that would be dealt this turn."));

        game.CastSpell(alice, fog, targets: null);

        // Driven all the way past the damage step rather than settled, because settling stops at
        // the priority window inside declare blockers — which would end the combat with no damage
        // dealt whether or not there were a fog, and prove nothing.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        // The 2/2 blocker would have died to a 3/3, and the loose 4/4 would have taken four off
        // the defending player. Neither happened.
        Assert.Equal(20, game.State.GetPlayer(bob).Life);
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Fogged Blocker Test");

        // "This turn" has to mean this turn. The same attack two turns later goes through, which
        // is both the assertion that catches a shield that never expires and the proof that this
        // way of driving a combat does deal damage when nothing is preventing it.
        TestCards.PassToTurn(game, 5);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [loose] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        Assert.Equal(16, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void A_counterspell_can_charge_the_spells_controller_life_for_it()
    {
        var barrier = Card(
            "Psychic Barrier Test",
            "Counter target creature spell. Its controller loses 1 life.");

        var compiled = CardCompiler.Compile(barrier);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirLand = game.Create(bob, TestCards.BasicLand("Forest"), Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2
                && game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.Priority.Holder == bob);

        var answer = TestCards.PutInHand(game, alice, barrier);
        var bear = TestCards.PutInHand(game, bob, TestCards.Creature("Barriered Bear Test"));
        game.ActivateAbility(bob, theirLand, "mana");
        game.CastSpell(bob, bear, targets: null);
        game.PassPriority(bob);

        game.CastSpell(alice, answer, [Target.ToSpell(game.State.Stack.Single())]);
        Settle(game);

        // "Its" is the spell the sentence before countered, and by the time this half runs that
        // spell is a card in a graveyard under a new id (CR 400.7). The controller still has to
        // be found, so the life comes off Bob and not off the player who cast the counter.
        Assert.Equal(19, game.State.GetPlayer(bob).Life);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Barriered Bear Test");
    }

    [Fact]
    public void An_upkeep_tax_takes_the_creature_when_it_is_not_paid()
    {
        var forces = Card(
            "Upkeep Tax Test",
            "At the beginning of your upkeep, sacrifice ~ unless you pay {1}.",
            CardType.Creature, 4, 4);

        var compiled = CardCompiler.Compile(forces);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, forces, Zone.Battlefield);

        // Alice's next upkeep, with no mana available and so no way to pay even if she wanted to.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.Upkeep);
        Settle(game);

        for (var guard = 0; guard < 10 && game.State.Choice is { } choice; guard++)
            game.Choose(choice.PlayerId, [choice.Options[^1].Id]);

        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Upkeep Tax Test");
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Upkeep Tax Test");
    }

    [Fact]
    public void An_upkeep_tax_leaves_the_creature_alone_when_it_is_paid()
    {
        // The other half, and the one that makes the first test mean something: if the offer were
        // never made and the sacrifice simply happened, the unpaid test would pass too.
        var forces = Card(
            "Paid Tax Test",
            "At the beginning of your upkeep, sacrifice ~ unless you pay {1}.",
            CardType.Creature, 4, 4);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, forces, Zone.Battlefield);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.Upkeep);

        // Tapped during the upkeep itself: a mana pool empties as each step ends (CR 500.4), so
        // mana made a step earlier would not be there to pay with.
        game.ActivateAbility(alice, land, "mana");
        Settle(game);

        for (var guard = 0; guard < 10 && game.State.Choice is { } choice; guard++)
            game.Choose(choice.PlayerId, [choice.Options[0].Id]);

        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Paid Tax Test");
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
    }

    [Fact]
    public void A_land_that_reads_any_players_life_counts_its_own_controller_too()
    {
        var campground = Card(
            "Campground Test",
            "~ enters tapped unless a player has 13 or less life.",
            CardType.Land);

        var compiled = CardCompiler.Compile(campground);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        // Everyone at 20: nobody is low, so it arrives tapped.
        game.PlayLand(alice, TestCards.PutInHand(game, alice, campground));
        Settle(game);

        var first = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Campground Test");

        Assert.True(game.State.GetObject(first).Permanent?.IsTapped);

        // "A player" is not "an opponent": the controller's own life total answers it. Alice is
        // taken to 13 and her next copy arrives upright, which is the case that separates this
        // condition from the one it was nearly folded into.
        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, Card("Self Burn Test", "You lose 7 life.")),
            targets: null);
        Settle(game);

        Assert.Equal(13, game.State.GetPlayer(alice).Life);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(
            game,
            () => game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.Priority.Holder == alice);

        game.PlayLand(alice, TestCards.PutInHand(game, alice, campground));
        Settle(game);

        var second = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Campground Test" && id != first);

        Assert.False(game.State.GetObject(second).Permanent?.IsTapped);
    }

    [Fact]
    public void A_negated_type_accepts_everything_that_is_not_that_type()
    {
        var shatter = Card("Noncreature Test", "Destroy target noncreature permanent.");

        var compiled = CardCompiler.Compile(shatter);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var creature = game.Create(bob, TestCards.Creature("Living Test", 2, 2), Zone.Battlefield);
        var relic = game.Create(
            bob, Card("Relic Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, shatter);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [Target.ToPermanent(creature)]));

        game.CastSpell(alice, card, [Target.ToPermanent(relic)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Relic Test");
        Assert.Contains(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Living Test");
    }

    [Fact]
    public void An_unnamed_counter_qualifier_asks_only_whether_there_is_one()
    {
        var snipe = Card("Counter Snipe Test", "Destroy target creature with a counter on it.");
        var grow = Card("Counter Grow Test", "Put a +1/+1 counter on target creature.");

        var compiled = CardCompiler.Compile(snipe);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Countered Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, snipe);

        // Bare, it is not a legal target at all.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [Target.ToPermanent(bear)]));

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, grow), [Target.ToPermanent(bear)]);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        game.CastSpell(alice, card, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Countered Bear Test");
    }

    // ---- Protection when targeting (CR 702.16) -------------------------------

    [Fact]
    public void Protection_stops_the_colour_it_names_and_lets_every_other_colour_through()
    {
        var ward = new CardDefinition
        {
            OracleId = "oracle-white-guard-test",
            Name = "White Guard Test",
            OracleText = "Protection from red",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{W}",
            ColorIdentity = [ManaColor.White],
            Colors = [ManaColor.White],
            Power = 2,
            Toughness = 2,
        };

        // A spell's colour is read from the card's colour identity rather than derived from its
        // mana cost, so a test card has to say what colour it is or it is colourless and nothing
        // is protected from it.
        var redBolt = new CardDefinition
        {
            OracleId = "oracle-red-bolt-test",
            Name = "Red Bolt Test",
            OracleText = "Destroy target creature.",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{R}",
            ColorIdentity = [ManaColor.Red],
            Colors = [ManaColor.Red],
        };

        var blueBolt = new CardDefinition
        {
            OracleId = "oracle-blue-bolt-test",
            Name = "Blue Bolt Test",
            OracleText = "Destroy target creature.",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{U}",
            ColorIdentity = [ManaColor.Blue],
            Colors = [ManaColor.Blue],
        };

        var (game, alice, bob) = InMainPhase();
        var guarded = game.Create(bob, ward, Zone.Battlefield);

        // Both colours available before either cast, so that a refusal can only be about
        // protection. An unpayable cost is refused with the same exception type, and the first
        // draft of this test passed for exactly that reason.
        foreach (var name in new[] { "Mountain", "Island" })
        {
            var land = game.Create(alice, TestCards.BasicLand(name), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        // The red spell may not target it at all (CR 702.16b). Refused as it is cast rather than
        // fizzling later, because the target was never legal (CR 601.2c).
        var red = TestCards.PutInHand(game, alice, redBolt);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, red, [Target.ToPermanent(guarded)]));

        // Protection names one colour, and every other colour goes straight through it. Without
        // this half the test would pass with protection implemented as "cannot be targeted".
        var blue = TestCards.PutInHand(game, alice, blueBolt);
        game.CastSpell(alice, blue, [Target.ToPermanent(guarded)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "White Guard Test");
    }

    // ---- Board conditions ----------------------------------------------------

    [Fact]
    public void A_condition_can_ask_whether_a_creature_has_died_this_turn()
    {
        var ground = Card(
            "Morbid Ground Test",
            "~ enters tapped unless a creature died this turn.",
            CardType.Land);

        var compiled = CardCompiler.Compile(ground);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var doomed = game.Create(bob, TestCards.Creature("Doomed Test", 2, 2), Zone.Battlefield);

        // Nothing has died, so it arrives tapped.
        game.PlayLand(alice, TestCards.PutInHand(game, alice, ground));
        Settle(game);

        var first = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Morbid Ground Test");

        Assert.True(game.State.GetObject(first).Permanent?.IsTapped);

        // Alice's next turn, because a land drop is once a turn (CR 505.6b) and this test needs
        // two of them either side of a death.
        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(
            game,
            () => game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.Priority.Holder == alice
                && game.State.Stack.IsEmpty);

        Assert.False(game.State.CreatureDiedThisTurn);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, Card("Morbid Kill Test", "Destroy target creature.")),
            [Target.ToPermanent(doomed)]);
        Settle(game);

        Assert.True(game.State.CreatureDiedThisTurn);

        TestCards.PassUntil(
            game,
            () => game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.Priority.Holder == alice
                && game.State.Stack.IsEmpty);

        game.PlayLand(alice, TestCards.PutInHand(game, alice, ground));
        Settle(game);

        var second = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Morbid Ground Test" && id != first);

        Assert.False(game.State.GetObject(second).Permanent?.IsTapped);

        // And it is a fact about the turn, not about the game: the next turn forgets. The first
        // assertion above is the same claim made before anything had died at all.
        TestCards.PassToTurn(game, 4);
        Assert.False(game.State.CreatureDiedThisTurn);
    }

    [Fact]
    public void A_condition_can_ask_about_an_opponents_board_rather_than_your_own()
    {
        var ground = Card(
            "Watchful Ground Test",
            "~ enters tapped unless an opponent controls a creature.",
            CardType.Land);

        Assert.True(CardCompiler.Compile(ground).IsComplete);

        var (game, alice, bob) = InMainPhase();

        // Alice has a creature and Bob does not. Read as "you control", this would come in
        // upright — which is the mistake the whose-board group exists to prevent.
        game.Create(alice, TestCards.Creature("Mine Test", 2, 2), Zone.Battlefield);

        game.PlayLand(alice, TestCards.PutInHand(game, alice, ground));
        Settle(game);

        var first = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Watchful Ground Test");

        Assert.True(game.State.GetObject(first).Permanent?.IsTapped);

        game.Create(bob, TestCards.Creature("Theirs Test", 2, 2), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(
            game,
            () => game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.Priority.Holder == alice);

        game.PlayLand(alice, TestCards.PutInHand(game, alice, ground));
        Settle(game);

        var second = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Watchful Ground Test" && id != first);

        Assert.False(game.State.GetObject(second).Permanent?.IsTapped);
    }

    // ---- Target qualifiers ---------------------------------------------------

    [Fact]
    public void A_power_qualifier_reads_the_power_a_creature_has_now()
    {
        var doom = Card("Big Doom Test", "Destroy target creature with power 3 or greater.");
        var pump = Card("Big Pump Test", "Target creature gets +2/+2 until end of turn.");

        var compiled = CardCompiler.Compile(doom);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var small = game.Create(bob, TestCards.Creature("Small Test", 2, 2), Zone.Battlefield);

        var doomCard = TestCards.PutInHand(game, alice, doom);

        // A 2/2 is not a legal target, and it is refused as the spell is cast rather than
        // fizzling later — the target was never legal (CR 601.2c).
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, doomCard, [Target.ToPermanent(small)]));

        // The qualifier reads computed power, not printed power (CR 613.1), so pumping the same
        // creature makes it targetable. Printed power would still say 2 here.
        var pumpCard = TestCards.PutInHand(game, alice, pump);
        game.CastSpell(alice, pumpCard, [Target.ToPermanent(small)]);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        game.CastSpell(alice, doomCard, [Target.ToPermanent(small)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Small Test");
    }

    [Fact]
    public void A_keyword_qualifier_tells_with_from_without()
    {
        var swat = Card("Swat Test", "Destroy target creature with flying.");
        var groundOnly = Card("Ground Only Test", "Destroy target creature without flying.");

        Assert.True(CardCompiler.Compile(swat).IsComplete);
        Assert.True(CardCompiler.Compile(groundOnly).IsComplete);

        var (game, alice, bob) = InMainPhase();

        var flier = game.Create(
            bob,
            Card("Flier Test", string.Empty, CardType.Creature, 2, 2, KeywordAbility.Flying),
            Zone.Battlefield);
        var walker = game.Create(bob, TestCards.Creature("Walker Test", 2, 2), Zone.Battlefield);

        var swatCard = TestCards.PutInHand(game, alice, swat);

        // Each refuses exactly what the other accepts, which is the only way to tell that the
        // negation is being read rather than ignored.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, swatCard, [Target.ToPermanent(walker)]));

        game.CastSpell(alice, swatCard, [Target.ToPermanent(flier)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Flier Test");

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        var groundCard = TestCards.PutInHand(game, alice, groundOnly);
        game.CastSpell(alice, groundCard, [Target.ToPermanent(walker)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Walker Test");
    }

    // ---- Retrace (CR 702.82) -------------------------------------------------

    [Fact]
    public void Retrace_casts_from_the_graveyard_for_a_land_and_leaves_the_card_there()
    {
        var jab = new CardDefinition
        {
            OracleId = "oracle-retrace-jab-test",
            Name = "Retrace Jab Test",
            OracleText = "~ deals 1 damage to any target.\nRetrace",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{0}",
        };

        var compiled = CardCompiler.Compile(jab);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var card = TestCards.PutInHand(game, alice, jab);
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(19, game.State.GetPlayer(bob).Life);

        var inYard = game.State.GetPlayer(alice).Graveyard.Single(
            id => game.State.GetObject(id).Card.Name == "Retrace Jab Test");

        // A land in hand to pay with, and a non-land to prove the cost is choosy about it.
        var land = TestCards.PutInHand(game, alice, TestCards.BasicLand("Forest"));
        var notLand = TestCards.PutInHand(
            game, alice, Card("Retrace Decoy Test", "You gain 1 life."));

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice, inYard, [Target.ToPlayer(bob)], costPayment: [notLand]));

        game.CastSpell(alice, inYard, [Target.ToPlayer(bob)], costPayment: [land]);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.DoesNotContain(game.State.GetPlayer(alice).Hand, id => id == land);

        // And it is back in the graveyard rather than exiled, which is what makes retrace worth
        // having: the lands run out before the card does.
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Retrace Jab Test");
    }

    // ---- Dredge (CR 702.52) --------------------------------------------------

    [Fact]
    public void Dredge_replaces_a_draw_with_a_mill_and_takes_the_card_back()
    {
        var card = Card("Dredge Test", "You gain 1 life.\nDredge 2");

        var compiled = CardCompiler.Compile(card);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, card, Zone.Graveyard);

        var library = game.State.GetPlayer(alice).Library.Count;
        var yard = game.State.GetPlayer(alice).Graveyard.Count;
        var hand = game.State.GetPlayer(alice).Hand.Count + 1;

        // Drawn by a spell rather than in the draw step, which puts the question in the middle of
        // a resolution - the place the engine documents as the one it cannot ask questions from.
        // A replacement is not an effect: the event is held, the answer arrives, and it is
        // re-emitted. That is the whole reason this keyword was on the blocked list.
        var draw = TestCards.PutInHand(game, alice, Card("Dredge Draw Test", "You draw a card."));
        game.CastSpell(alice, draw, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice!;
        Assert.Equal(ChoiceKind.OrderReplacements, choice.Kind);
        Assert.Equal(alice, choice.PlayerId);

        var dredging = choice.Options.Single(o => o.Label.Contains("dredge", StringComparison.Ordinal));
        game.Choose(alice, [dredging.Id]);
        Settle(game);

        // Two milled and the card taken back, and no card drawn: the draw never happened.
        Assert.Equal(library - 2, game.State.GetPlayer(alice).Library.Count);

        // The dredged card arrived and the draw spell left, so the hand is where it started.
        Assert.Equal(hand, game.State.GetPlayer(alice).Hand.Count);
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Dredge Test");

        // Two milled and the spell that tried to draw, less the dredged card that went back to
        // hand.
        Assert.Equal(yard + 2, game.State.GetPlayer(alice).Graveyard.Count);
    }

    [Fact]
    public void Dredge_can_be_declined_and_then_the_draw_happens()
    {
        var card = Card("Dredge Decline Test", "You gain 1 life.\nDredge 2");

        var (game, alice, _) = InMainPhase();
        game.Create(alice, card, Zone.Graveyard);

        var library = game.State.GetPlayer(alice).Library.Count;

        var draw = TestCards.PutInHand(
            game, alice, Card("Dredge Decline Draw Test", "You draw a card."));
        var hand = game.State.GetPlayer(alice).Hand.Count;

        game.CastSpell(alice, draw, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var decline = game.State.Choice!.Options.Single(
            o => o.Label.StartsWith("Let the event", StringComparison.Ordinal));
        game.Choose(alice, [decline.Id]);
        Settle(game);

        // One card off the library and into the hand: an ordinary draw, and the dredge card is
        // still in the graveyard to be offered again next turn.
        Assert.Equal(library - 1, game.State.GetPlayer(alice).Library.Count);

        // One card drawn and one spell cast out of the same hand, so the count is where it was.
        Assert.Equal(hand, game.State.GetPlayer(alice).Hand.Count);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Dredge Decline Test");
    }

    // ---- Assist (CR 702.132) -------------------------------------------------

    [Fact]
    public void Assist_lets_the_other_player_pay_the_generic_half()
    {
        // Built here rather than through Card(), because assist is about the mana cost and the
        // helper does not carry one.
        var spell = new CardDefinition
        {
            OracleId = "oracle-assist-test",
            Name = "Assist Test",
            OracleText = "You gain 3 life.\nAssist",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{3}",
        };

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.Spell!.HasAssist);

        var (game, alice, bob) = InMainPhase();

        // One mana each. Neither could cast a {3} spell alone; between them they can.
        var mine = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, mine, "mana");

        for (var i = 0; i < 2; i++)
        {
            var theirs = game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);
            game.ActivateAbility(bob, theirs, "mana");
        }

        var card = TestCards.PutInHand(game, alice, spell);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null));

        game.CastSpell(alice, card, targets: null, assist: (bob, 2));
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);

        // Both pools are empty: two came out of Bob's and one out of Alice's.
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Assert.True(game.State.GetPlayer(bob).ManaPool.IsEmpty);
    }

    [Fact]
    public void Assist_cannot_pay_a_coloured_symbol()
    {
        var spell = new CardDefinition
        {
            OracleId = "oracle-assist-colour-test",
            Name = "Assist Colour Test",
            OracleText = "You gain 3 life.\nAssist",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{1}{G}",
        };

        var compiled = CardCompiler.Compile(spell);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        for (var i = 0; i < 3; i++)
        {
            var theirs = game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);
            game.ActivateAbility(bob, theirs, "mana");
        }

        var card = TestCards.PutInHand(game, alice, spell);

        // Bob offers three towards {1}{G}. Only the {1} is generic, so the {G} is still Alice's
        // to find - and she has nothing, so the cast is refused with the offer capped, not
        // stretched to cover the colour.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, assist: (bob, 3)));
    }

    // ---- Splice onto Arcane (CR 702.47) --------------------------------------

    [Fact]
    public void Splice_adds_a_cards_text_to_an_arcane_spell_and_leaves_it_in_hand()
    {
        var ray = Card(
            "Splice Ray Test",
            "Splice Ray Test deals 2 damage to any target.\nSplice onto Arcane {1}",
            CardType.Instant, null, null, KeywordAbility.None, "Arcane");

        var arcane = Card(
            "Arcane Draw Test",
            "You gain 1 life.",
            CardType.Instant, null, null, KeywordAbility.None, "Arcane");

        var compiled = CardCompiler.Compile(ray);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.NotNull(compiled.Spell!.SpliceCost);

        var (game, alice, bob) = InMainPhase();
        for (var i = 0; i < 1; i++)
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        var host = TestCards.PutInHand(game, alice, arcane);
        var spliceCard = TestCards.PutInHand(game, alice, ray);

        game.CastSpell(
            alice,
            host,
            targets: [Target.ToPlayer(bob)],
            spliced: [spliceCard]);
        Settle(game);

        // The host's own text and the spliced text both happened, and the spliced half chose its
        // own target - the two effects index into different slices of one target list.
        Assert.Equal(21, game.State.GetPlayer(alice).Life);
        Assert.Equal(18, game.State.GetPlayer(bob).Life);

        // Revealed, not cast: it never left the hand, so it can be spliced again next turn.
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Splice Ray Test");
    }

    [Fact]
    public void Splice_is_refused_onto_a_spell_that_is_not_arcane()
    {
        var ray = Card(
            "Splice Refusal Test",
            "Splice Refusal Test deals 2 damage to any target.\nSplice onto Arcane {1}",
            CardType.Instant, null, null, KeywordAbility.None, "Arcane");

        var plain = Card("Plain Spell Test", "You gain 1 life.");

        var (game, alice, bob) = InMainPhase();
        var host = TestCards.PutInHand(game, alice, plain);
        var spliceCard = TestCards.PutInHand(game, alice, ray);

        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice, host, targets: [Target.ToPlayer(bob)], spliced: [spliceCard]));

        Assert.Contains("702.47a", refused.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void Sacrificing_one_of_your_own_asks_which_when_it_is_not_an_offer()
    {
        var altar = Card(
            "Plain Sacrifice Test",
            "When ~ enters, sacrifice another creature.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(altar);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, TestCards.Creature("Plain Fodder Test", 1, 1), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, altar);
        game.CastSpell(alice, card, targets: null);
