    // ---- Offering to sacrifice one of your own (CR 701.16a) ------------------

    [Fact]
    public void You_may_sacrifice_another_creature_offers_your_others_and_not_itself()
    {
        var altar = Card(
            "Sacrifice Offer Test",
            "When ~ enters, you may sacrifice another creature. If you do, you gain 3 life.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(altar);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var fodder = game.Create(alice, TestCards.Creature("Offered Fodder Test", 1, 1), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, altar);
        game.CastSpell(alice, card, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        // First the offer itself, which names what it is asking rather than a price it has not
        // got: a free "you may" used to put "Pay " on the button with nothing after it.
        var offer = game.State.Choice!;
        Assert.Equal("Sacrifice another creature", offer.Options[0].Label);
        game.Choose(alice, [offer.Options[0].Id]);

        TestCards.PassUntil(game, () => game.State.Choice is not null);
        var which = game.State.Choice!;

        // "Another" is the source excluding itself, so the altar is not on its own menu.
        Assert.Single(which.Options);
        Assert.Equal("Offered Fodder Test", which.Options[0].Label);

        game.Choose(alice, [which.Options[0].Id]);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Offered Fodder Test");
        Assert.False(game.State.TryGetObject(fodder, out _));
    }

    // ---- "When you do" as an offer's consequence (CR 603.11) ------------------

    [Fact]
    public void When_you_do_is_read_as_the_consequence_of_paying()
    {
        // The rules make this a reflexive triggered ability, which would go on the stack between
        // the payment and its effect. Here it happens as the payment does - a deviation worth
        // naming, and the only one between the engine and 43 cards.
        var card = Card(
            "Reflexive Offer Test",
            "You may pay {0}. When you do, you gain 3 life.");

        var compiled = CardCompiler.Compile(card);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var spell = TestCards.PutInHand(game, alice, card);

        game.CastSpell(alice, spell, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var yes = game.State.Choice!.Options[0];
        game.Choose(alice, [yes.Id]);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void Declining_a_when_you_do_offer_buys_nothing()
    {
        var card = Card(
            "Declined Offer Test",
            "You may pay {0}. When you do, you gain 3 life.");

        var (game, alice, _) = InMainPhase();
        var spell = TestCards.PutInHand(game, alice, card);

        game.CastSpell(alice, spell, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice!;
        game.Choose(alice, [choice.Options[^1].Id]);
        Settle(game);

        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    // ---- Looking at the top of the library, with a filter (CR 701.20a) -------

    [Fact]
    public void A_search_that_shuffles_first_leaves_the_card_on_top()
    {
        var tutor = Card(
            "Top Tutor Test",
            "Search your library for a Merfolk card, reveal it, then shuffle and put that card "
                + "on top.");

        var compiled = CardCompiler.Compile(tutor);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(
            alice,
            Card("Tutored Merfolk Test", string.Empty, CardType.Creature, 2, 2,
                KeywordAbility.None, "Merfolk"),
            Zone.Library);

        var card = TestCards.PutInHand(game, alice, tutor);
        game.CastSpell(alice, card, targets: null);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var found = game.State.Choice!.Options.Single(
            o => o.Label == "Tutored Merfolk Test");
        game.Choose(alice, [found.Id]);
        Settle(game);

        // On top of the shuffled library, not shuffled into it: the two steps happen in the
        // order the card prints them, and doing the move first would hide the card at random.
        var top = game.State.GetPlayer(alice).Library[0];
        Assert.Equal("Tutored Merfolk Test", game.State.GetObject(top).Card.Name);
    }

