            CardType.Creature, 0, 1);

        var compiled = CardCompiler.Compile(dryad);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.All(compiled.Activated, a => Assert.Single(a.ChosenCosts));

        var (game, alice, _) = InMainPhase();
        var source = game.Create(alice, dryad, Zone.Battlefield);
        var helper = game.Create(alice, TestCards.Creature("Dryad Helper Test", 1, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.PrecombatMain);
        game.ActivateAbility(alice, source, compiled.Activated[0].Id, costPayment: [helper]);
        Settle(game);

        // Both tapped: the source for {T} and the helper for the chosen cost.
        Assert.True(game.State.GetObject(source).Permanent!.IsTapped);
        Assert.True(game.State.GetObject(helper).Permanent!.IsTapped);
        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool.Total);
    }

    // ---- Vanishing (CR 702.63) -----------------------------------------------

    [Fact]
    public void Vanishing_counts_down_each_upkeep_and_sacrifices_itself_at_zero()
    {
        var ghost = Card("Vanishing Ghost Test", "Vanishing 2", CardType.Creature, 3, 3);

        var compiled = CardCompiler.Compile(ghost);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Cast, because that is the ordinary way one of these reaches the battlefield. It is not
        // the only way it works, and the comment that used to stand here said it was - that
        // "a permanent put straight onto the battlefield never made the move for the replacement
        // to replace". That is not a rule: a permanent arrives either by moving or by being
        // created (CR 111.1, 400.7), the compiler reads both through one helper, and the reason
        // this test could not have been written the other way was a defect rather than CR 614.1c.
        // Vanishing_arrives_on_its_clock_however_the_permanent_got_here takes the other path.
        var card = TestCards.PutInHand(game, alice, ghost);
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        var creature = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Vanishing Ghost Test");
        Assert.Equal(2, game.State.GetObject(creature).Permanent!.Counters[CounterKinds.Time]);

        // Alice's next upkeep takes one off.
        PassTo(game, 3, TurnStep.Upkeep);
        Settle(game);
        Assert.Equal(1, game.State.GetObject(creature).Permanent!.Counters[CounterKinds.Time]);

        // And the one after takes the last, which is what it is sacrificed for.
        PassTo(game, 5, TurnStep.Upkeep);
        Settle(game);

        Assert.False(game.State.TryGetObject(creature, out _));
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Vanishing Ghost Test");
    }

    [Fact]
    public void Vanishing_does_not_tick_on_the_opponents_upkeep()
    {
        var ghost = Card("Vanishing Clock Test", "Vanishing 3", CardType.Creature, 1, 1);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, ghost);
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        var creature = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Vanishing Clock Test");

        // Turn 2 is Bob's. "Your upkeep" is Alice's, so nothing should come off.
        PassTo(game, 2, TurnStep.Upkeep);
        Settle(game);

        Assert.Equal(3, game.State.GetObject(creature).Permanent!.Counters[CounterKinds.Time]);
    }

    /// <summary>A vanishing permanent put straight onto the battlefield still arrives on a clock.</summary>
    /// <remarks>
    /// CR 614.1c is about a permanent <em>entering</em>, and a permanent arrives two ways the card
    /// cannot tell apart: a card moves there and becomes a new object (CR 400.7), or a token is
    /// created there and was never anywhere else (CR 111.1). <c>Arriving</c> exists to read both,
    /// and every entry replacement in the compiler goes through it — except this one, which
    /// matched the move alone.
    /// <para>
    /// So vanishing was right in a real game and silently did nothing whenever a permanent was
    /// placed by <c>Game.Create</c>, which is how the behaviour suite and the corpus soak set up a
    /// board. Nothing failed: the permanent simply arrived with no counters and never left. This
    /// is the path that was blind, which is why the test takes it.
    /// </para>
    /// </remarks>
    [Fact]
    public void Vanishing_arrives_on_its_clock_however_the_permanent_got_here()
    {
        var statue = Card("Vanishing Statue Test", "Vanishing 3", CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(statue);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, statue, Zone.Battlefield);
        Settle(game);

        Assert.Equal(3, game.State.GetObject(creature).Permanent!.Counters[CounterKinds.Time]);

        // And the clock it arrived on is a real one: the next upkeep of its controller's takes
        // one off, which is the half that would look identical if it had entered with none.
        PassTo(game, 3, TurnStep.Upkeep);
        Settle(game);

        Assert.Equal(2, game.State.GetObject(creature).Permanent!.Counters[CounterKinds.Time]);
    }

    // ---- Squad (CR 702.157) --------------------------------------------------

    [Fact]
    public void Squad_brings_one_token_copy_for_every_time_it_was_paid()
    {
        var trooper = Card(
            "Squad Trooper Test", "Squad {0}", CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(trooper);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.NotNull(compiled.Spell!.SquadCost);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, trooper);

        game.CastSpell(alice, card, targets: null, squad: 2);
        Settle(game);

        // The creature itself and two token copies of it.
        var troopers = game.State.Battlefield
            .Select(game.State.GetObject)
            .Where(o => o.Card.Name == "Squad Trooper Test")
            .ToList();

        Assert.Equal(3, troopers.Count);
        Assert.Equal(2, troopers.Count(o => o.Card.CardTypes.HasFlag(CardType.Token)));

        // Copies of the creature, not shrunk versions of it - which is what separates squad from
        // offspring, the mechanism it is built out of.
        foreach (var one in troopers)
        {
            var computed = Characteristics.Of(game.State, Pool, one);
            Assert.Equal(2, computed.Power);
        }
    }

