    // ---- Banding (CR 702.22) -------------------------------------------------

    [Fact]
    public void A_creature_blocked_by_banding_has_its_damage_divided_by_the_defender()
    {
        var wall = Card("Banding Wall Test", "Banding", CardType.Creature, 0, 4);

        var compiled = CardCompiler.Compile(wall);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.GrantedKeywords.HasFlag(KeywordAbility.Banding));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, TestCards.Creature("Banded Attacker Test", 3, 3), Zone.Battlefield);
        var banded = game.Create(bob, wall, Zone.Battlefield);
        var plain = game.Create(bob, TestCards.Creature("Plain Blocker Test", 0, 4), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
        {
            [attacker] = [banded, plain],
        });

        TestCards.PassUntil(game, () => game.State.Choice is not null);
        var choice = game.State.Choice!;
        Assert.Equal(ChoiceKind.DivideCombatDamage, choice.Kind);

        // CR 702.22j: the one exception to CR 510.1c. Alice attacked, and Bob divides - which is
        // the whole point of blocking with a creature that has banding.
        Assert.Equal(bob, choice.PlayerId);

        // And Bob may put it all on the creature that can take it.
        game.Choose(bob, [
            plain.Value.ToString("N"),
            plain.Value.ToString("N"),
            plain.Value.ToString("N"),
        ]);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        Assert.Equal(3, game.State.GetObject(plain).Permanent!.DamageMarked);
        Assert.Equal(0, game.State.GetObject(banded).Permanent!.DamageMarked);
    }

    [Fact]
    public void Without_banding_the_attacker_still_divides()
    {
        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, TestCards.Creature("Unbanded Attacker Test", 3, 3), Zone.Battlefield);
        var first = game.Create(bob, TestCards.Creature("First Wall Test", 0, 4), Zone.Battlefield);
        var second = game.Create(bob, TestCards.Creature("Second Wall Test", 0, 4), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
        {
            [attacker] = [first, second],
        });

        TestCards.PassUntil(game, () => game.State.Choice is not null);

        // The ordinary rule, so that the test above is about banding and not about two blockers.
        Assert.Equal(alice, game.State.Choice!.PlayerId);
    }

    // ---- Recover (CR 702.59) -------------------------------------------------

    [Fact]
    public void Recover_offers_the_card_back_when_a_creature_dies_and_exiles_it_if_declined()
    {
        var card = Card("Recover Test", "You gain 2 life.\nRecover {0}");

        var compiled = CardCompiler.Compile(card);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, card, Zone.Graveyard);
        var doomed = game.Create(alice, TestCards.Creature("Recover Fodder Test", 1, 1), Zone.Battlefield);

        // The creature dies, which is the only thing recover watches.
        game.Move(doomed, Zone.Graveyard, MoveCause.Destroy);
        TestCards.PassUntil(game, () => game.State.Choice is not null);

        var choice = game.State.Choice!;
        Assert.Equal(alice, choice.PlayerId);

        var decline = choice.Options.Single(o => o.Label.Contains("exiled", StringComparison.Ordinal));
        game.Choose(alice, [decline.Id]);
        Settle(game);

        // Declining is not free: the card leaves the graveyard for exile, so it cannot be
        // offered again the next time something dies.
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Recover Test");
        Assert.Contains(
            game.State.Exile, id => game.State.GetObject(id).Card.Name == "Recover Test");
    }

