    // ---- Mentor (CR 702.134) -------------------------------------------------

    [Fact]
    public void Mentor_can_only_pick_an_attacker_smaller_than_itself()
    {
        var mentor = Card("Mentor Test", "Mentor", CardType.Creature, 3, 3);

        var compiled = CardCompiler.Compile(mentor);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var teacher = game.Create(alice, mentor, Zone.Battlefield);
        var student = game.Create(alice, TestCards.Creature("Small Student Test", 1, 1), Zone.Battlefield);
        var equal = game.Create(alice, TestCards.Creature("Equal Peer Test", 3, 3), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [teacher] = AttackTarget.Player(bob),
                [student] = AttackTarget.Player(bob),
                [equal] = AttackTarget.Player(bob),
            });

        for (var guard = 0; guard < 40 && game.State.Choice is null; guard++)
        {
            if (game.State.Priority.Holder is { } holder)
                game.PassPriority(holder);
            else
                break;
        }

        var choice = game.State.Choice;
        Assert.NotNull(choice);

        var offered = choice!.Options.Select(o => o.Label).ToList();

        // Only the smaller attacker. The equal one is out because "lesser" is not "at most", and
        // the mentor is out for the same reason - nothing has power less than its own.
        Assert.Contains(offered, label => label.Contains("Small Student", StringComparison.Ordinal));
        Assert.DoesNotContain(offered, label => label.Contains("Equal Peer", StringComparison.Ordinal));
        Assert.DoesNotContain(offered, label => label.Contains("Mentor Test", StringComparison.Ordinal));

        game.Choose(choice.PlayerId, [choice.Options[0].Id]);
        Settle(game);

        Assert.Equal(
            1, game.State.GetObject(student).Permanent?.Counters.GetValueOrDefault("+1/+1", 0));
    }

