    // ---- Transmute (CR 702.49) -----------------------------------------------

    [Fact]
    public void Transmute_fetches_a_card_of_the_same_mana_value_and_no_other()
    {
        var tutor = new CardDefinition
        {
            OracleId = "oracle-transmute-tutor-test",
            Name = "Transmute Tutor Test",
            OracleText = "Transmute {0}",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{3}",
            Cmc = 3,
        };

        var compiled = CardCompiler.Compile(tutor);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        CardDefinition Costing(string name, int cost) => new()
        {
            OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
            Name = name,
            CardTypes = CardType.Sorcery,
            OracleText = "You gain 1 life.",
            ManaCostRaw = "{" + cost + "}",
            Cmc = cost,
        };

        game.Create(alice, Costing("Exactly Three Test", 3), Zone.Library);
        game.Create(alice, Costing("Only Two Test", 2), Zone.Library);
        game.Create(alice, Costing("Fully Four Test", 4), Zone.Library);

        var inHand = TestCards.PutInHand(game, alice, tutor);
        game.ActivateAbility(alice, inHand, "transmute");

        for (var guard = 0; guard < 40 && game.State.Choice is null; guard++)
        {
            if (game.State.Priority.Holder is { } holder)
                game.PassPriority(holder);
            else
                break;
        }

        var choice = game.State.Choice;
        Assert.NotNull(choice);

        var offered = choice!.Options.Select(o => o.Label).ToList();

        // "The same mana value" is not a cap: the two-drop is as unfetchable as the four-drop.
        Assert.Contains(offered, label => label.Contains("Exactly Three", StringComparison.Ordinal));
        Assert.DoesNotContain(offered, label => label.Contains("Only Two", StringComparison.Ordinal));
        Assert.DoesNotContain(offered, label => label.Contains("Fully Four", StringComparison.Ordinal));

        // And the card paid for it: transmute discards itself.
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Transmute Tutor Test");
    }

    // ---- Protection from a type ----------------------------------------------

    [Fact]
    public void Protection_from_artifacts_stops_an_artifact_and_nothing_else()
    {
        var needlebug = new CardDefinition
        {
            OracleId = "oracle-needlebug-test",
            Name = "Needlebug Test",
            OracleText = "Protection from artifacts",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{1}{G}",
            ColorIdentity = [ManaColor.Green],
            Colors = [ManaColor.Green],
            Power = 1,
            Toughness = 1,
            Keywords = KeywordAbility.ProtectionFromArtifacts,
        };

        var compiled = CardCompiler.Compile(needlebug);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var guarded = game.Create(bob, needlebug, Zone.Battlefield);

        var artifactSpell = new CardDefinition
        {
            OracleId = "oracle-artifact-zap-test",
            Name = "Artifact Zap Test",
            OracleText = "Destroy target creature.",
            CardTypes = CardType.Artifact | CardType.Instant,
            ManaCostRaw = "{2}",
        };

        var plainSpell = new CardDefinition
        {
            OracleId = "oracle-plain-zap-test",
            Name = "Plain Zap Test",
            OracleText = "Destroy target creature.",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{2}",
        };

        foreach (var name in new[] { "Forest", "Plains", "Island", "Swamp" })
        {
            var land = game.Create(alice, TestCards.BasicLand(name), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        // Protection names a quality, and a card type is one as readily as a colour is.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice,
                TestCards.PutInHand(game, alice, artifactSpell),
                [Target.ToPermanent(guarded)]));

        // And only that quality: a spell that is not an artifact goes straight through.
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, plainSpell), [Target.ToPermanent(guarded)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Needlebug Test");
    }

    // ---- Riot (CR 702.135) ---------------------------------------------------

    [Fact]
    public void Riot_offers_a_counter_or_haste_and_gives_only_the_one_chosen()
    {
        var rioter = Card("Riot Test", "Riot", CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(rioter);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var counterPicked = game.Create(alice, rioter, Zone.Battlefield);

        // Settle answers with the first option, which is the counter.
        Settle(game);

        var withCounter = Characteristics.Of(
            game.State, Pool, game.State.GetObject(counterPicked));

        Assert.Equal(3, withCounter.Power);
        Assert.False(withCounter.Has(KeywordAbility.Haste));

        // The other creature takes haste instead, and stays its printed size. Two branches that
        // both do something is what makes this different from an offer you can decline.
        var hastePicked = game.Create(alice, rioter, Zone.Battlefield);

        for (var guard = 0; guard < 40 && game.State.Choice is null; guard++)
        {
            if (game.State.Priority.Holder is { } holder)
                game.PassPriority(holder);
            else
                break;
        }

        var choice = game.State.Choice;
        Assert.NotNull(choice);

        game.Choose(choice!.PlayerId, [choice.Options[^1].Id]);
        Settle(game);

        var withHaste = Characteristics.Of(game.State, Pool, game.State.GetObject(hastePicked));

        Assert.Equal(2, withHaste.Power);
        Assert.True(withHaste.Has(KeywordAbility.Haste));
    }

    [Fact]
    public void Damage_that_gains_you_that_much_life_is_lifelink()
    {
        // The wording lifelink had before the keyword existed, and it means the same rule
        // (CR 702.15b) - so it has to reach the same flag rather than a private imitation.
        var vampire = Card(
            "Longhand Lifelink Test",
            "Whenever ~ deals damage, you gain that much life.",
            CardType.Creature, 3, 3);

        var compiled = CardCompiler.Compile(vampire);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, vampire, Zone.Battlefield);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(attacker))
                .Has(KeywordAbility.Lifelink));

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

