    [Fact]
    public void Unleash_declined_leaves_an_ordinary_creature_that_can_block()
    {
        // The choice is the whole keyword: taken it is a bigger attacker, declined it is a
        // normal creature. An implementation that always took the counter would look right in
        // the test above and quietly remove blocking from every card that prints this.
        var drake = Card("Declined Drake Test", "Unleash", CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var creature = game.Create(alice, drake, Zone.Battlefield);

