                game.PassPriority(holder);
            else
                break;
        }

        var choice = game.State.Choice;
        Assert.NotNull(choice);

        game.Choose(choice!.PlayerId, [choice.Options[^1].Id]);
        Settle(game);

        Assert.Equal(
            0, game.State.GetObject(creature).Permanent?.Counters.GetValueOrDefault("+1/+1", 0));

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(creature));
        Assert.Equal(2, computed.Power);
        Assert.False(computed.Has(KeywordAbility.CantBlock));
    }

    // ---- An Aura pumping on demand -------------------------------------------

    [Fact]
    public void An_aura_can_pump_what_it_is_on_without_naming_a_target()
    {
        var armor = Card(
            "Armor Of Faith Test",
            "Enchant creature\n{0}: Enchanted creature gets +0/+1 until end of turn.",
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var compiled = CardCompiler.Compile(armor);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // No target: "enchanted creature" is whatever it is already on.
        Assert.Empty(compiled.Activated[0].Targets);

        var (game, alice, bob) = InMainPhase();
        var host = game.Create(alice, TestCards.Creature("Armored Bear Test", 2, 2), Zone.Battlefield);
        var other = game.Create(bob, TestCards.Creature("Other Bear Test", 2, 2), Zone.Battlefield);

        var aura = game.State.Battlefield.ToList();
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, armor), [Target.ToPermanent(host)]);
        Settle(game);

        var attached = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Armor Of Faith Test");

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        game.ActivateAbility(alice, attached, compiled.Activated[0].Id);
        Settle(game);

        Assert.Equal(
            3, Characteristics.Of(game.State, Pool, game.State.GetObject(host)).Toughness);

        // Only the host: an effect that pumped its own source, or everything, would be a very
        // different card.
        Assert.Equal(
            2, Characteristics.Of(game.State, Pool, game.State.GetObject(other)).Toughness);

        Assert.NotEmpty(aura);
    }

