    [Fact]
    public void A_permanent_that_returns_itself_comes_back_from_the_graveyard()
    {
        var spine = Card(
            "Spine Test",
            "When ~ is put into a graveyard from the battlefield, return it to its owner's hand.",
            CardType.Artifact);

        var compiled = CardCompiler.Compile(spine);
