    [Fact]
    public void An_ability_that_says_it_cant_be_blocked_this_turn_grants_the_flag()
    {
        var yeti = Card(
            "Yeti Test", "{0}: ~ can't be blocked this turn.", CardType.Creature, 3, 3);

        var compiled = CardCompiler.Compile(yeti);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, yeti, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Yeti Wall Test", 0, 4), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        // Blockable before the ability is used.
        Assert.Null(
            CombatRules.CannotBlock(
                game.State, Pool, game.State.GetObject(blocker),
                game.State.GetObject(attacker), bob));

        game.ActivateAbility(alice, attacker, compiled.Activated[0].Id);
        Settle(game);

        Assert.NotNull(
            CombatRules.CannotBlock(
                game.State, Pool, game.State.GetObject(blocker),
                game.State.GetObject(attacker), bob));
    }

    // ---- Tutors with a mana-value cap ----------------------------------------

    [Fact]
    public void A_tutor_with_a_cap_offers_only_what_it_is_allowed_to_fetch()
    {
        var persuader = Card(
            "Persuader Test",
            "{0}: Search your library for a Mercenary permanent card with mana value 1 or less, "
                + "put it onto the battlefield, then shuffle.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(persuader);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var source = game.Create(alice, persuader, Zone.Battlefield);

        CardDefinition Mercenary(string name, int cost) => new()
        {
            OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
            Name = name,
            CardTypes = CardType.Creature,
            Subtypes = ["Mercenary"],
            ManaCostRaw = "{" + cost + "}",
            Cmc = cost,
            Power = 1,
            Toughness = 1,
        };

        game.Create(alice, Mercenary("Cheap Merc Test", 1), Zone.Library);
        game.Create(alice, Mercenary("Dear Merc Test", 4), Zone.Library);
        game.Create(alice, TestCards.Creature("Not A Merc Test", 1, 1), Zone.Library);

        game.ActivateAbility(alice, source, compiled.Activated[0].Id);

        for (var guard = 0; guard < 40 && game.State.Choice is null; guard++)
        {
            if (game.State.Priority.Holder is { } holder)
                game.PassPriority(holder);
            else
                break;
        }

        var choice = game.State.Choice;
        Assert.NotNull(choice);

        var offered = choice!.Options.Select(o => o.Label).ToList();

        // The cap and the subtype both bite: the four-mana Mercenary is over the limit and the
        // one-mana non-Mercenary is the wrong type. A tutor that ignored either would be a
        // strictly better card than the one printed.
        Assert.Contains(offered, label => label.Contains("Cheap Merc", StringComparison.Ordinal));
        Assert.DoesNotContain(offered, label => label.Contains("Dear Merc", StringComparison.Ordinal));
        Assert.DoesNotContain(offered, label => label.Contains("Not A Merc", StringComparison.Ordinal));
    }

    // ---- Split second (CR 702.18) --------------------------------------------

    [Fact]
    public void Split_second_stops_a_response_but_not_a_mana_ability()
    {
        var possession = Card(
            "Split Second Test", "Split second\nYou gain 3 life.");

        var compiled = CardCompiler.Compile(possession);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.Spell!.HasSplitSecond);

        var (game, alice, bob) = InMainPhase();

        var island = game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, possession), targets: null);
        game.PassPriority(alice);

        var answer = TestCards.PutInHand(game, bob, Card("Blocked Answer Test", "You gain 1 life."));

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(bob, answer, targets: null));

        // A mana ability does not use the stack, so there is nothing for the restriction to hold
        // up (CR 605.3b) - and a rule that stopped it would strand every player with no way to
        // pay for anything once the spell finally resolves.
        game.ActivateAbility(bob, island, "mana");
        Assert.False(game.State.GetPlayer(bob).ManaPool.IsEmpty);

        // Once it resolves the hold is over.
        Settle(game);
        Assert.Equal(23, game.State.GetPlayer(alice).Life);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        game.CastSpell(bob, answer, targets: null);
        Settle(game);

        Assert.Equal(21, game.State.GetPlayer(bob).Life);
    }

    // ---- Extort (CR 702.101) -------------------------------------------------

    [Fact]
    public void Extort_drains_every_opponent_and_gives_back_the_whole_total()
    {
        var drinker = Card("Extort Drinker Test", "Extort", CardType.Creature, 1, 2);

        var compiled = CardCompiler.Compile(drinker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // Three players, because at two "each opponent loses 1" and "you gain that much" are the
        // same number and a card that pays a third of what it should would look correct.
        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");
        var carol = Guid.Parse("33333333-3333-3333-3333-333333333333");

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, TestCards.Deck(40, "Alice")),
                new PlayerSetup(bob, "Bob", 20, TestCards.Deck(40, "Bob")),
                new PlayerSetup(carol, "Carol", 20, TestCards.Deck(40, "Carol")),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        game.Create(alice, drinker, Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.ActivePlayerId == alice
                && game.State.Priority.Holder == alice
                && game.State.Stack.IsEmpty);

        var swamp = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        game.ActivateAbility(alice, swamp, "mana");

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, Card("Extort Trigger Test", "Draw a card.")),
            targets: null);

        Settle(game);

        // Both opponents down one, and Alice up two - not one.
        Assert.Equal(19, game.State.GetPlayer(bob).Life);
        Assert.Equal(19, game.State.GetPlayer(carol).Life);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    // ---- Keyword lines that name several keywords ----------------------------

    [Fact]
    public void A_keyword_line_is_read_whole_or_not_at_all()
    {
        // "Flying, protection from red" is one line naming two keywords, and the check that
        // reads it requires every word on it to be a keyword the card actually has. Protection
        // was missing from that vocabulary, so the second half failed and took the flying with
        // it - the line went unread entire, and the card lost an ability it prints plainly.
        var voice = new CardDefinition
        {
            OracleId = "oracle-voice-of-law-test",
            Name = "Voice Of Law Test",
            OracleText = "Flying, protection from red",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{1}{W}",
            ColorIdentity = [ManaColor.White],
            Colors = [ManaColor.White],
            Power = 2,
            Toughness = 2,
            Keywords = KeywordAbility.Flying | KeywordAbility.ProtectionFromRed,
        };

        var compiled = CardCompiler.Compile(voice);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var guarded = game.Create(bob, voice, Zone.Battlefield);

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(guarded));

        // Both halves, and the engine acting on both.
        Assert.True(computed.Has(KeywordAbility.Flying));
        Assert.True(computed.Has(KeywordAbility.ProtectionFromRed));

        var redBolt = new CardDefinition
        {
            OracleId = "oracle-law-bolt-test",
            Name = "Law Bolt Test",
            OracleText = "Destroy target creature.",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{R}",
            ColorIdentity = [ManaColor.Red],
            Colors = [ManaColor.Red],
        };

        var mountain = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, mountain, "mana");

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice,
                TestCards.PutInHand(game, alice, redBolt),
                [Target.ToPermanent(guarded)]));
    }

    // ---- Umbra armor (CR 702.170) --------------------------------------------

    [Fact]
    public void Umbra_armor_dies_in_place_of_what_it_is_on()
    {
        var umbra = Card(
            "Umbra Test",
            "Enchant creature\nUmbra armor",
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var compiled = CardCompiler.Compile(umbra);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Shielded Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, umbra), [Target.ToPermanent(bear)]);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, Card("Umbra Kill Test", "Destroy target creature.")),
            [Target.ToPermanent(bear)]);
        Settle(game);

        // The creature lives and the Aura is gone in its place.
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Shielded Bear Test");
        Assert.DoesNotContain(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Umbra Test");
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Umbra Test");
    }

    [Fact]
    public void Regenerating_one_creature_leaves_another_creatures_damage_alone()
    {
        // Found while writing umbra armor: regeneration reached for the cleanup step's global
        // damage event, so saving one creature wiped the damage off every other permanent in
        // play - a free save its controller never paid for.
        var (game, alice, bob) = InMainPhase();

        var bystander = game.Create(
            bob, TestCards.Creature("Damaged Onlooker Test", 3, 3), Zone.Battlefield);
        var tough = game.Create(
            alice,
            Card("Shielded Regenerator Test", "{0}: Regenerate ~.", CardType.Creature, 2, 2),
            Zone.Battlefield);

        // Two damage on the bystander, one short of lethal.
        game.CastSpell(
            alice,
            TestCards.PutInHand(
                game, alice, Card("Singe Test", "~ deals 2 damage to target creature.")),
            [Target.ToPermanent(bystander)]);
        Settle(game);

        Assert.Equal(2, game.State.GetObject(bystander).Permanent?.DamageMarked);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        game.ActivateAbility(alice, tough, CardCompiler.Compile(
            Card("Shielded Regenerator Test", "{0}: Regenerate ~.", CardType.Creature, 2, 2))
            .Activated[0].Id);
        Settle(game);

        // The shield is up, and the bystander is still carrying its damage.
        Assert.Equal(2, game.State.GetObject(bystander).Permanent?.DamageMarked);
    }

    // ---- Keywords written out longhand ---------------------------------------

    [Fact]
    public void Cant_be_blocked_by_more_than_one_creature_is_menace()
    {
        // Cards printed before the keyword existed say it in full, and it is the same rule
        // (CR 702.111a) rather than an approximation of it - so it has to reach the same flag
        // the blocking rules already ask for.
        var rider = Card(
            "Longhand Menace Test",
            "~ can't be blocked by more than one creature.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(rider);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, rider, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Lone Wall Test", 0, 4), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        Assert.Throws<InvalidOperationException>(
            () => game.DeclareBlockers(
                bob,
                new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] }));
    }

