    [Fact]
    public void An_aura_that_says_you_control_enchanted_creature_takes_it()
    {
        var mindControl = Card(
            "Spirit Away Test",
            "Enchant creature\nYou control enchanted creature.",
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var compiled = CardCompiler.Compile(mindControl);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.Creature("Stolen Bear Test", 2, 2), Zone.Battlefield);

        Assert.Equal(
            bob, Characteristics.Of(game.State, Pool, game.State.GetObject(theirs)).ControllerId);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, mindControl), [Target.ToPermanent(theirs)]);
        Settle(game);

        // Control is layer 2, ahead of everything about what the creature is - so this is the
        // answer every later question is asked against.
        Assert.Equal(
            alice, Characteristics.Of(game.State, Pool, game.State.GetObject(theirs)).ControllerId);
    }

    [Fact]
    public void A_stolen_creature_can_block_for_its_new_controller()
    {
        // The other side of the same rule. An Aura that says "you control enchanted creature"
        // keeps control for as long as it is attached, so the creature is still yours when its
        // owner attacks into it - and blocking with it is the only reason to have taken it.
        var mindControl = Card(
            "Block Steal Test",
            "Enchant creature\nYou control enchanted creature.",
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var compiled = CardCompiler.Compile(mindControl);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var taken = game.Create(bob, TestCards.Creature("Taken Wall Test", 0, 4), Zone.Battlefield);
        var attacker = game.Create(bob, TestCards.Creature("Owner Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, mindControl), [Target.ToPermanent(taken)]);
        Settle(game);

        // Bob's turn, so Bob attacks and Alice blocks with what used to be Bob's.
        TestCards.PassToTurn(game, 2);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(bob, new Dictionary<ObjectId, AttackTarget>
        {
            [attacker] = AttackTarget.Player(alice),
        });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(alice, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>
        {
            [attacker] = [taken],
        });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        // Blocked, so Alice takes nothing and the wall wears the damage.
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
        Assert.Equal(2, game.State.GetObject(taken).Permanent!.DamageMarked);
    }

    // ---- Bestow (CR 702.103) -------------------------------------------------

    [Fact]
    public void A_bestowed_creature_is_an_aura_until_its_host_leaves_and_then_a_creature_again()
    {
        var dryad = new CardDefinition
        {
            OracleId = "oracle-bestow-dryad-test",
            Name = "Bestow Dryad Test",
            OracleText = "Bestow {0}\nEnchanted creature gets +2/+2.",
            CardTypes = CardType.Creature | CardType.Enchantment,
            ManaCostRaw = "{0}",
            Power = 2,
            Toughness = 2,
        };

        var compiled = CardCompiler.Compile(dryad);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var host = game.Create(alice, TestCards.Creature("Bestow Host Test", 1, 1), Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, dryad),
            [Target.ToPermanent(host)],
            bestowed: true);

        Settle(game);

        var aura = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Bestow Dryad Test");

        // Attached, and not a creature while it is: a bestowed permanent that stayed a creature
        // would be free to attack and block on top of the bonus it is giving.
        Assert.Equal(host, game.State.GetObject(aura).Permanent?.AttachedTo);

        var asAura = Characteristics.Of(game.State, Pool, game.State.GetObject(aura));
        Assert.False(asAura.CardTypes.HasFlag(CardType.Creature));
        Assert.True(asAura.CardTypes.HasFlag(CardType.Enchantment));

        // The host is wearing the bonus.
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(host)).Power);

        // Kill the host: the Aura is left holding nothing and becomes a creature again rather
        // than going to the graveyard, which is the whole reason bestow is worth its cost.
        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, Card("Bestow Kill Test", "Destroy target creature.")),
            [Target.ToPermanent(host)]);
        Settle(game);

        var standing = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Bestow Dryad Test");

        var asCreature = Characteristics.Of(game.State, Pool, game.State.GetObject(standing));
        Assert.True(asCreature.CardTypes.HasFlag(CardType.Creature));
        Assert.Equal(2, asCreature.Power);
    }

    [Fact]
    public void The_same_card_cast_normally_is_a_creature_and_enchants_nothing()
    {
        var dryad = new CardDefinition
        {
            OracleId = "oracle-plain-dryad-test",
            Name = "Plain Dryad Test",
            OracleText = "Bestow {0}\nEnchanted creature gets +2/+2.",
