    // ---- Backup (CR 702.164) -------------------------------------------------

    [Fact]
    public void Backup_puts_counters_on_a_creature_and_lends_it_the_keywords()
    {
        var cleric = Card(
            "Backup Cleric Test", "Backup 1", CardType.Creature, 2, 2, KeywordAbility.Lifelink);

        var compiled = CardCompiler.Compile(cleric);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Backed Bear Test", 2, 2), Zone.Battlefield);

        game.Create(alice, cleric, Zone.Battlefield);

        // Driven by hand up to the target choice, because Settle answers a pending choice with
        // its first option - which here is the cleric itself, and the point of the test is that
        // the counters can go somewhere else.
        for (var guard = 0; guard < 40 && game.State.Choice is null; guard++)
        {
            if (game.State.Priority.Holder is { } holder)
                game.PassPriority(holder);
            else
                break;
        }

        var choice = game.State.Choice;
        Assert.NotNull(choice);

        game.Choose(
            choice!.PlayerId,
            [choice.Options.First(o => o.Label.Contains("Backed Bear", StringComparison.Ordinal)).Id]);

        Settle(game);

        Assert.Equal(
            1, game.State.GetObject(bear).Permanent?.Counters.GetValueOrDefault("+1/+1", 0));

        // The counters are the easy half; lending the keyword is the keyword.
        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(bear))
                .Has(KeywordAbility.Lifelink));
    }

    [Fact]
    public void Backup_is_left_unread_when_the_card_has_more_than_keywords_to_lend()
    {
        // "It gains this creature's other abilities" means copying whatever else the card has.
        // Keywords can be granted; a triggered ability cannot, so the line is left unread rather
        // than handing out half of what the card promises.
        var complicated = Card(
            "Backup Complicated Test",
            "Backup 1\nWhen ~ enters, you gain 2 life.",
            CardType.Creature, 2, 2, KeywordAbility.Lifelink);

        var compiled = CardCompiler.Compile(complicated);

        Assert.False(compiled.IsComplete);
        Assert.Contains(compiled.Unhandled, line => line.StartsWith("Backup", StringComparison.Ordinal));
    }

    // ---- Conspire (CR 702.78) ------------------------------------------------

    [Fact]
    public void Conspire_taps_two_matching_creatures_and_copies_the_spell()
    {
        var discovery = new CardDefinition
        {
            OracleId = "oracle-conspire-discovery-test",
            Name = "Conspire Discovery Test",
            OracleText = "You gain 2 life.\nConspire",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{B}",
            ColorIdentity = [ManaColor.Black],
            Colors = [ManaColor.Black],
        };

        var compiled = CardCompiler.Compile(discovery);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.NotNull(compiled.Spell!.CopyingCost);

        var (game, alice, _) = InMainPhase();

        var black = new CardDefinition
        {
            OracleId = "oracle-black-friend-test",
            Name = "Black Friend Test",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{B}",
            ColorIdentity = [ManaColor.Black],
            Colors = [ManaColor.Black],
            Power = 1,
            Toughness = 1,
        };

        var one = game.Create(alice, black, Zone.Battlefield);
        var two = game.Create(alice, black, Zone.Battlefield);

        var swamp = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        game.ActivateAbility(alice, swamp, "mana");

        game.CastSpell(
            alice,
            TestCards.PutInHand(game, alice, discovery),
            targets: null,
            costPayment: [one, two],
            conspired: true);

        Settle(game);

        // Two resolutions, so four life; and the conspirators are tapped for it.
        Assert.Equal(24, game.State.GetPlayer(alice).Life);
        Assert.True(game.State.GetObject(one).Permanent?.IsTapped);
        Assert.True(game.State.GetObject(two).Permanent?.IsTapped);
    }

    [Fact]
    public void Conspire_refuses_creatures_that_share_no_colour_with_the_spell()
    {
        // "That share a color with it" is the whole restriction, and it is the half a filter
        // that only checked "creature you control" would silently drop.
        var discovery = new CardDefinition
        {
            OracleId = "oracle-conspire-mismatch-test",
            Name = "Conspire Mismatch Test",
            OracleText = "You gain 2 life.\nConspire",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{B}",
            ColorIdentity = [ManaColor.Black],
            Colors = [ManaColor.Black],
        };

        var (game, alice, _) = InMainPhase();

        var green = new CardDefinition
        {
            OracleId = "oracle-green-friend-test",
            Name = "Green Friend Test",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{G}",
            ColorIdentity = [ManaColor.Green],
            Colors = [ManaColor.Green],
            Power = 1,
            Toughness = 1,
        };

        var one = game.Create(alice, green, Zone.Battlefield);
        var two = game.Create(alice, green, Zone.Battlefield);

        // Mana on the table first, so the refusal can only be about the colour of the
        // conspirators - an unpayable cost throws the same exception type.
        var swamp = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);
        game.ActivateAbility(alice, swamp, "mana");

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(
                alice,
                TestCards.PutInHand(game, alice, discovery),
                targets: null,
                costPayment: [one, two],
                conspired: true));
    }

    // ---- Rampage (CR 702.23) -------------------------------------------------

    [Fact]
    public void Rampage_grows_by_each_blocker_beyond_the_first_and_not_for_a_single_one()
    {
        var giant = Card("Rampage Giant Test", "Rampage 2", CardType.Creature, 3, 3);

        var compiled = CardCompiler.Compile(giant);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, giant, Zone.Battlefield);

        var one = game.Create(bob, TestCards.Creature("Gang One Test", 1, 1), Zone.Battlefield);
        var two = game.Create(bob, TestCards.Creature("Gang Two Test", 1, 1), Zone.Battlefield);
        var three = game.Create(bob, TestCards.Creature("Gang Three Test", 1, 1), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [one, two, three] });

        Settle(game);

        // Three blockers is two beyond the first, so +4/+4 on a 3/3.
        Assert.Equal(
            7, Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).Power);
    }

    [Fact]
    public void Rampage_gives_nothing_when_only_one_creature_blocks()
    {
        // "Beyond the first" is the whole arithmetic: one blocker is zero extra, and a reading
        // that counted blockers rather than extras would hand out a bonus here.
        var giant = Card("Lone Block Giant Test", "Rampage 2", CardType.Creature, 3, 3);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, giant, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Lone Blocker Test", 1, 1), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        Settle(game);

        Assert.Equal(
            3, Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).Power);
    }

    // ---- Damage that exiles instead of killing -------------------------------

    [Fact]
    public void A_creature_dealt_damage_this_way_is_exiled_rather_than_buried()
    {
        var flame = Card(
            "Yamabushi Flame Test",
            "~ deals 3 damage to any target. "
                + "If a creature dealt damage this way would die this turn, exile it instead.");

        var compiled = CardCompiler.Compile(flame);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Burned Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, flame), [Target.ToPermanent(bear)]);
        Settle(game);

        // Exile, not the graveyard - which is the whole reason the rider is printed, and the
        // difference every graveyard deck cares about.
        Assert.DoesNotContain(
            game.State.GetPlayer(bob).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Burned Bear Test");
        Assert.Contains(
            game.State.Exile,
            id => game.State.GetObject(id).Card.Name == "Burned Bear Test");
    }

    // ---- Overload (CR 702.96) ------------------------------------------------

    [Fact]
    public void An_overloaded_spell_hits_everything_and_a_normal_one_hits_what_it_targets()
    {
        var mortars = new CardDefinition
        {
            OracleId = "oracle-overload-mortars-test",
            Name = "Overload Mortars Test",
            OracleText = "~ deals 4 damage to target creature you don't control.\nOverload {0}",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{0}",
        };

        var compiled = CardCompiler.Compile(mortars);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.NotEmpty(compiled.Spell!.OverloadEffects);

        var (game, alice, bob) = InMainPhase();

        var one = game.Create(bob, TestCards.Creature("Theirs One Test", 2, 2), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Theirs Two Test", 2, 2), Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Mine Test", 2, 2), Zone.Battlefield);

        // Cast normally: one target, one dead creature.
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, mortars), [Target.ToPermanent(one)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Theirs One Test");
        Assert.Contains(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Theirs Two Test");

        // Overloaded: no targets at all, and everything the description names is hit.
        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, mortars), targets: null, overloaded: true);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Theirs Two Test");

        // "You don't control" survives the rewrite, so Alice's own creature is spared. An
        // overload that dropped the qualifier along with the word "target" would kill it.
        Assert.Contains(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Mine Test");
    }

    [Fact]
    public void An_overload_whose_rewrite_cannot_be_read_leaves_the_line_unread()
    {
        // The failure that matters: accepting the cost with no effects behind it would resolve
        // the card's ordinary targeted text for the overload price, which is a different spell.
        var nonsense = new CardDefinition
        {
            OracleId = "oracle-overload-nonsense-test",
            Name = "Overload Nonsense Test",
            OracleText = "Bamboozle target creature sideways.\nOverload {0}",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{0}",
        };

        var compiled = CardCompiler.Compile(nonsense);

        Assert.False(compiled.IsComplete);
        Assert.Contains(compiled.Unhandled, line => line.StartsWith("Overload", StringComparison.Ordinal));
    }

    // ---- Group effects in the singular ---------------------------------------

    [Fact]
    public void Each_creature_you_control_is_a_group_and_target_creature_is_not()
    {
        // The two sentences differ by one letter of agreement and mean entirely different
        // things. A matcher loose enough to read the first will eat the second, which is what
        // happened the first time this was widened.
        var mass = Card("Mass Pump Test", "Each creature you control gets +1/+1 until end of turn.");
        var single = Card("Single Pump Test", "Target creature gets +2/+2 until end of turn.");

        Assert.True(
            CardCompiler.Compile(mass).IsComplete,
            string.Join(" | ", CardCompiler.Compile(mass).Unhandled));
        Assert.True(CardCompiler.Compile(single).IsComplete);

        // The group form takes no target; the single form takes exactly one.
        Assert.Empty(CardCompiler.Compile(mass).Spell!.Targets);
        Assert.Single(CardCompiler.Compile(single).Spell!.Targets);

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Mine Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Theirs Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, mass), targets: null);
        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(mine)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(theirs)).Power);
    }

    [Fact]
    public void A_group_can_gain_a_keyword_and_not_only_a_size()
    {
        var mass = Card(
            "Mass Grant Test", "Each creature you control gains trample until end of turn.");

        var compiled = CardCompiler.Compile(mass);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var mine = game.Create(alice, TestCards.Creature("Trampler Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Not Mine Test", 2, 2), Zone.Battlefield);

        game.CastSpell(alice, TestCards.PutInHand(game, alice, mass), targets: null);
        Settle(game);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(mine))
                .Has(KeywordAbility.Trample));
        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(theirs))
                .Has(KeywordAbility.Trample));
    }

    // ---- Ninjutsu (CR 702.49) ------------------------------------------------

    [Fact]
    public void Ninjutsu_swaps_an_unblocked_attacker_for_the_ninja_and_keeps_the_attack()
    {
        var ninja = Card(
            "Ninja Test", "Ninjutsu {0}", CardType.Creature, 3, 3);

        var compiled = CardCompiler.Compile(ninja);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var sneak = game.Create(alice, TestCards.Creature("Sneak Test", 1, 1), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [sneak] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());

        var card = TestCards.PutInHand(game, alice, ninja);
        game.ActivateAbility(alice, card, "ninjutsu", costPayment: [sneak]);
        Settle(game);

        // The attacker went home and the ninja took its place, tapped and attacking.
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Sneak Test");

        var arrived = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Ninja Test");

        Assert.True(game.State.GetObject(arrived).Permanent?.IsTapped);
        Assert.True(game.State.Combat.Attackers.ContainsKey(arrived));
        Assert.Equal(bob, game.State.Combat.Attackers[arrived].DefendingPlayer);

        // And it connects for its own size, which is the point of the swap.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    [Fact]
    public void Ninjutsu_refuses_a_creature_that_is_blocked()
    {
        var ninja = Card("Blocked Ninja Test", "Ninjutsu {0}", CardType.Creature, 3, 3);

        var (game, alice, bob) = InMainPhase();
        var sneak = game.Create(alice, TestCards.Creature("Blocked Sneak Test", 1, 1), Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Wall Test", 0, 4), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [sneak] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [sneak] = [blocker] });

        var card = TestCards.PutInHand(game, alice, ninja);

        // "Unblocked" is the whole restriction: a blocked attacker cannot be swapped out, or
        // ninjutsu would undo a block for free.
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, card, "ninjutsu", costPayment: [sneak]));
    }

    // ---- Paying with counters -------------------------------------------------

    [Fact]
    public void A_plus_one_counter_can_be_spent_as_a_cost_and_runs_out()
    {
        var engine = Card(
            "Counter Spender Test",
            "Remove a +1/+1 counter from ~: You gain 1 life.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(engine);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var permanent = game.Create(alice, engine, Zone.Battlefield);

        game.CastSpell(
            alice,
            TestCards.PutInHand(
                game, alice, Card("Grow Test", "Put two +1/+1 counters on target creature.")),
            [Target.ToPermanent(permanent)]);
        Settle(game);

        Assert.Equal(
            2, game.State.GetObject(permanent).Permanent?.Counters.GetValueOrDefault("+1/+1", 0));

        var ability = compiled.Activated[0].Id;

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        game.ActivateAbility(alice, permanent, ability);
        Settle(game);

        // Paid, not merely allowed: the counter has to be gone and the creature smaller for it.
        Assert.Equal(21, game.State.GetPlayer(alice).Life);
        Assert.Equal(
            1, game.State.GetObject(permanent).Permanent?.Counters.GetValueOrDefault("+1/+1", 0));
        Assert.Equal(
            2, Characteristics.Of(game.State, Pool, game.State.GetObject(permanent)).Power);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        game.ActivateAbility(alice, permanent, ability);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);

        // And with none left it cannot be paid at all, which is what makes it a cost rather than
        // a rider on the effect.
        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, permanent, ability));
    }

    // ---- Cost reductions that read the targets --------------------------------

    [Fact]
    public void A_discount_that_depends_on_the_target_is_only_given_when_it_applies()
    {
        var fate = new CardDefinition
        {
            OracleId = "oracle-fate-cryst-test",
            Name = "Fate Cryst Test",
            OracleText = "~ costs {2} less to cast if it targets a tapped creature.\n"
                + "Destroy target creature.",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{3}",
        };

        var compiled = CardCompiler.Compile(fate);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var untapped = game.Create(bob, TestCards.Creature("Awake Test", 2, 2), Zone.Battlefield);
        var tapped = game.Create(bob, TestCards.Creature("Asleep Test", 2, 2), Zone.Battlefield);
        game.Tap(tapped);

        // One mana on the table against a printed {3}: only the discount can make this castable,
        // and only against the tapped creature.
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        var first = TestCards.PutInHand(game, alice, fate);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, first, [Target.ToPermanent(untapped)]));

        game.CastSpell(alice, first, [Target.ToPermanent(tapped)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Asleep Test");
        Assert.Contains(
            game.State.Battlefield, id => game.State.GetObject(id).Card.Name == "Awake Test");
    }

    // ---- Evolve (CR 702.100) -------------------------------------------------
    [Fact]
    public void Evolve_grows_only_for_a_creature_bigger_in_one_dimension()
    {
        var snapjaw = Card("Evolve Snapjaw Test", "Evolve", CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(snapjaw);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var evolver = game.Create(alice, snapjaw, Zone.Battlefield);

        int Counters() => game.State.GetObject(evolver).Permanent?
            .Counters.GetValueOrDefault("+1/+1", 0) ?? 0;

        // Smaller in both: nothing happens.
        game.Create(alice, TestCards.Creature("Small One Test", 1, 1), Zone.Battlefield);
        Settle(game);
        Assert.Equal(0, Counters());

        // Equal in both: still nothing. "Greater than" is not "at least".
        game.Create(alice, TestCards.Creature("Equal One Test", 2, 2), Zone.Battlefield);
        Settle(game);
        Assert.Equal(0, Counters());

        // Bigger in toughness alone is enough - the keyword asks for either dimension, and a
        // reading that wanted both would stop here.
        game.Create(alice, TestCards.Creature("Tall One Test", 1, 3), Zone.Battlefield);
        Settle(game);
        Assert.Equal(1, Counters());

        // And having grown, it now measures from its new size: a 3/3 no longer outsizes it.
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(evolver)).Power);

        game.Create(alice, TestCards.Creature("Same Again Test", 3, 3), Zone.Battlefield);
        Settle(game);
        Assert.Equal(1, Counters());
    }

    // ---- Shuffling (CR 701.24) -----------------------------------------------

    [Fact]
    public void Shuffling_a_graveyard_in_moves_every_card_and_leaves_the_graveyard_empty()
    {
        var recycle = Card("Recycle Test", "Shuffle your graveyard into your library.");

        var compiled = CardCompiler.Compile(recycle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        game.Create(alice, TestCards.Creature("Buried A Test", 2, 2), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Buried B Test", 2, 2), Zone.Graveyard);

        // Bob's graveyard is the control: "your graveyard" is not everybody's.
        game.Create(bob, TestCards.Creature("Their Buried Test", 2, 2), Zone.Graveyard);

        var before = game.State.GetPlayer(alice).Library.Count;

        game.CastSpell(alice, TestCards.PutInHand(game, alice, recycle), targets: null);
        Settle(game);

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name.StartsWith("Buried", StringComparison.Ordinal));

        Assert.Equal(before + 2, game.State.GetPlayer(alice).Library.Count);

        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Their Buried Test");

        // The spell that asked for the shuffle must not be in it. It is still on the stack while
        // it resolves and only reaches the graveyard afterwards (CR 608.2m) - but the shuffle is
        // settled later than that, so gathering the graveyard at settle time swept the sorcery
        // into the library. The first version of this did exactly that, and the count caught it.
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Recycle Test");
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Library,
            id => game.State.GetObject(id).Card.Name == "Recycle Test");
    }

    [Fact]
    public void The_shuffled_order_is_written_into_the_log_so_a_replay_reaches_it()
    {
        // The reason a shuffle is asked for rather than performed by the effect: the order is the
        // game's decision, it comes from the seeded source, and it has to be in the log or a game
        // rebuilt from that log would deal different cards from here on.
        var recycle = Card("Replay Shuffle Test", "Shuffle your library.");

        var (game, alice, _) = InMainPhase();
        game.CastSpell(alice, TestCards.PutInHand(game, alice, recycle), targets: null);
        Settle(game);

        Assert.Contains(game.Log, e => e is LibraryShuffled shuffled && shuffled.PlayerId == alice);
    }

    // ---- Tokens that are more than creatures ---------------------------------

    [Fact]
    public void An_artifact_creature_token_is_an_artifact_as_well()
    {
        var maker = Card(
            "Thopter Maker Test",
            "Create a 1/1 colorless Thopter artifact creature token with flying.");

        var compiled = CardCompiler.Compile(maker);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.CastSpell(alice, TestCards.PutInHand(game, alice, maker), targets: null);
        Settle(game);

        var thopter = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Thopter");

        var computed = Characteristics.Of(game.State, Pool, game.State.GetObject(thopter));

        // Reading only the creature half would put a Thopter on the board that no artifact
        // sweeper could find and no metalcraft would count.
        Assert.True(computed.CardTypes.HasFlag(CardType.Creature));
        Assert.True(computed.CardTypes.HasFlag(CardType.Artifact));
        Assert.True(computed.Has(KeywordAbility.Flying));
        Assert.Equal(1, computed.Power);
    }

    [Fact]
    public void A_counter_can_be_taken_off_the_source_as_well_as_put_on()
    {
        var engine = Card(
            "Counter Engine Test",
            "When ~ enters, put two +1/+1 counters on ~.\n"
                + "At the beginning of your upkeep, remove a +1/+1 counter from ~.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(engine);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var permanent = game.Create(alice, engine, Zone.Battlefield);
        Settle(game);

        Assert.Equal(
            2, game.State.GetObject(permanent).Permanent?.Counters.GetValueOrDefault("+1/+1", 0));
        Assert.Equal(
            3, Characteristics.Of(game.State, Pool, game.State.GetObject(permanent)).Power);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.Upkeep);
        Settle(game);

        // One off, and the power follows it down - which is the half that would go unnoticed if
        // the counter were removed from the dictionary but not from the characteristics.
        Assert.Equal(
            1, game.State.GetObject(permanent).Permanent?.Counters.GetValueOrDefault("+1/+1", 0));
        Assert.Equal(
            2, Characteristics.Of(game.State, Pool, game.State.GetObject(permanent)).Power);
    }

    // ---- Granting keywords the engine already honours -------------------------

    [Fact]
    public void A_granted_landwalk_makes_the_creature_unblockable_against_that_land()
    {
        var trick = Card("Walk Trick Test", "Target creature gains islandwalk until end of turn.");

        var compiled = CardCompiler.Compile(trick);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, TestCards.Creature("Walker Test", 2, 2), Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Blocker Test", 3, 3), Zone.Battlefield);
        game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        // Blockable before the trick.
        Assert.Null(
            CombatRules.CannotBlock(
                game.State, Pool, game.State.GetObject(blocker),
                game.State.GetObject(attacker), bob));

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, trick), [Target.ToPermanent(attacker)]);
        Settle(game);

        // A granted keyword has to be read the same way a printed one is, or granting it looks
        // implemented and changes nothing (CR 613.1f).
        Assert.NotNull(
            CombatRules.CannotBlock(
                game.State, Pool, game.State.GetObject(blocker),
                game.State.GetObject(attacker), bob));
    }

    [Fact]
    public void A_granted_protection_stops_the_colour_it_names()
    {
        var trick = Card(
            "Guard Trick Test", "Target creature gains protection from red until end of turn.");

        Assert.True(CardCompiler.Compile(trick).IsComplete);

        var redBolt = new CardDefinition
        {
            OracleId = "oracle-granted-red-bolt-test",
            Name = "Granted Red Bolt Test",
            OracleText = "Destroy target creature.",
            CardTypes = CardType.Instant,
            ManaCostRaw = "{R}",
            ColorIdentity = [ManaColor.Red],
            Colors = [ManaColor.Red],
        };

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Guarded Bear Test", 2, 2), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);

        // Bob protects his own creature, then Alice cannot target it. Bob has to be holding
        // priority to cast at all, so the pass comes first.
        TestCards.PassUntil(game, () => game.State.Priority.Holder == bob);
        game.CastSpell(
            bob, TestCards.PutInHand(game, bob, trick), [Target.ToPermanent(bear)]);
        Settle(game);

        TestCards.PassUntil(game, () => game.State.Priority.Holder == alice);

        // Tapped only now: a mana pool empties as each step ends (CR 500.4), and mana made
        // earlier would be gone. With it in hand, a refusal can only be about protection.
        game.ActivateAbility(alice, land, "mana");

        // The grant has to survive the round trip through its own id: the keyword flags run past
        // bit 31, and truncating them produced an effect that granted nothing at all.
        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(bear))
                .Has(KeywordAbility.ProtectionFromRed));

        var bolt = TestCards.PutInHand(game, alice, redBolt);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, bolt, [Target.ToPermanent(bear)]));
    }

    // ---- Naming a player the game already picked out --------------------------

    [Fact]
    public void Defending_player_means_whoever_is_being_attacked()
    {
        var raider = Card(
            "Defender Drain Test",
            "Whenever ~ attacks, defending player loses 1 life.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(raider);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, raider, Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });
        Settle(game);

        // One off the trigger, before any combat damage. Read as "you" it would have come off
        // Alice, and read as "each opponent" it would be indistinguishable here - which is why
        // the caster's own total is asserted too.
        Assert.Equal(19, game.State.GetPlayer(bob).Life);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void That_player_means_the_one_the_trigger_was_about()
    {
        var biter = Card(
            "Biter Test",
            "Whenever ~ deals damage to a player, that player discards a card.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(biter);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, biter, Zone.Battlefield);

        var mine = game.State.GetPlayer(alice).Hand.Count;
        var theirs = game.State.GetPlayer(bob).Hand.Count;

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());
        // Driven by hand rather than with PassUntil, because the discard is asked in the middle
        // of the pass and PassUntil refuses to answer a pending choice for a test.
        for (var guard = 0; guard < 50 && game.State.CurrentStep != TurnStep.EndOfCombat; guard++)
        {
            if (game.State.Choice is { } pending)
                game.Choose(pending.PlayerId, [pending.Options[0].Id]);
            else if (game.State.Priority.Holder is { } holder)
                game.PassPriority(holder);
            else
                break;
        }

        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);

        // Bob discarded and Alice did not. Alice draws on her own turn, so her hand is compared
        // against a count taken after that draw rather than against the number it started at.
        Assert.Equal(theirs - 1, game.State.GetPlayer(bob).Hand.Count);
        Assert.True(game.State.GetPlayer(alice).Hand.Count >= mine);
    }

    // ---- Static ability word order -------------------------------------------

    [Fact]
    public void A_condition_that_leads_the_sentence_reads_the_same_as_one_that_trails_it()
    {
        // The same static ability, printed both ways round. The trailing form has been read for
        // a long time; the leading one had not, so a shelf of cards went unread over word order.
        var trailing = Card(
            "Trailing Test", "~ gets +2/+2 as long as you control a Swamp.",
            CardType.Creature, 1, 1);
        var leading = Card(
            "Leading Test", "As long as you control a Swamp, ~ gets +2/+2.",
            CardType.Creature, 1, 1);

        Assert.True(
            CardCompiler.Compile(leading).IsComplete,
            string.Join(" | ", CardCompiler.Compile(leading).Unhandled));

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, trailing, Zone.Battlefield);
        var second = game.Create(alice, leading, Zone.Battlefield);

        // No Swamp: both are their printed size.
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(first)).Power);
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(second)).Power);

        game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(first)).Power);
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(second)).Power);
    }

    [Fact]
    public void A_lord_can_name_its_tribe_instead_of_saying_creatures()
    {
        var lord = Card(
            "Goblin Lord Test", "Other Goblins you control get +1/+0.",
            CardType.Creature, 2, 2, KeywordAbility.None, "Goblin");

        var compiled = CardCompiler.Compile(lord);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, lord, Zone.Battlefield);

        var goblin = game.Create(
            alice,
            Card("Goblin Grunt Test", string.Empty, CardType.Creature, 1, 1,
                KeywordAbility.None, "Goblin"),
            Zone.Battlefield);
        var bear = game.Create(alice, TestCards.Creature("Not A Goblin Test", 2, 2), Zone.Battlefield);

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(goblin)).Power);

        // Two controls: a non-Goblin is untouched, and "Other" means the lord does not pump
        // itself.
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);

        var self = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Goblin Lord Test");
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(self)).Power);
    }

    // ---- Myriad (CR 702.115) -------------------------------------------------

    [Fact]
    public void Myriad_copies_the_attacker_at_every_opponent_it_is_not_already_attacking()
    {
        var raider = Card("Myriad Raider Test", "Myriad", CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(raider);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        // Three players, because myriad does nothing at two: with one opponent, that opponent is
        // the defending player and there is nobody else left to attack.
        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");
        var carol = Guid.Parse("33333333-3333-3333-3333-333333333333");

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 20, TestCards.Deck(40, "Alice")),
                new PlayerSetup(bob, "Bob", 20, TestCards.Deck(40, "Bob")),
                new PlayerSetup(carol, "Carol", 20, TestCards.Deck(40, "Carol")),
            ],
            new GameRandom(1),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);

        var attacker = game.Create(alice, raider, Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 4
                && game.State.ActivePlayerId == alice
                && game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        Settle(game);

        // One copy, aimed at Carol: Bob is already being attacked and Alice is not an opponent.
        var copies = game.State.Combat.Attackers
            .Where(kv => kv.Key != attacker)
            .ToList();

        Assert.Single(copies);
        Assert.Equal(carol, copies[0].Value.DefendingPlayer);
        Assert.True(game.State.GetObject(copies[0].Key).Permanent?.IsTapped);
        Assert.Equal("Myriad Raider Test", game.State.GetObject(copies[0].Key).Card.Name);

        var token = copies[0].Key;

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        // Both were hit, which is the point of the keyword.
        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(18, game.State.GetPlayer(carol).Life);

        // And the copy is gone at end of combat rather than sticking around as a free creature.
        Settle(game);
        Assert.DoesNotContain(game.State.Battlefield, id => id == token);
    }

    // ---- Suspend (CR 702.62) -------------------------------------------------

    [Fact]
    public void A_suspended_card_counts_down_and_is_offered_when_it_runs_out()
    {
        var bloom = new CardDefinition
        {
            OracleId = "oracle-suspend-bloom-test",
            Name = "Suspend Bloom Test",
            OracleText = "Suspend 2—{0}\nYou gain 4 life.",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{9}",
        };

        var compiled = CardCompiler.Compile(bloom);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(2, compiled.Spell!.SuspendCount);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, bloom);

        game.Suspend(alice, card);

        var waiting = game.State.Exile.Single(
            id => game.State.GetObject(id).Card.Name == "Suspend Bloom Test");

        Assert.Equal(2, game.State.GetObject(waiting).TimeCounters);

        // Alice's next upkeep takes one off, and it is still not castable.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.Upkeep);

        Assert.Equal(1, game.State.GetObject(waiting).TimeCounters);
        Assert.False(game.State.GetObject(waiting).MayCastFree);

        // The one after takes the last, and the offer arrives with it.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 5 && game.State.CurrentStep == TurnStep.Upkeep);

        Assert.Equal(0, game.State.GetObject(waiting).TimeCounters);
        Assert.True(game.State.GetObject(waiting).MayCastFree);

        // Cast from exile for nothing, against a printed {9}, with no mana at all.
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        game.CastSpell(alice, waiting, targets: null);
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void Suspending_is_a_sorcery_speed_action_and_needs_the_card_in_hand()
    {
        var bloom = new CardDefinition
        {
            OracleId = "oracle-suspend-timing-test",
            Name = "Suspend Timing Test",
            OracleText = "Suspend 1—{0}\nYou gain 1 life.",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{9}",
        };

        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, bloom);

        // Bob's turn: Alice may hold priority there but not take a sorcery-speed action.
        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 2
                && game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.Priority.Holder == alice);

        Assert.Throws<InvalidOperationException>(() => game.Suspend(alice, card));

        // A card nobody suspended has nothing to suspend with either.
        var plain = TestCards.PutInHand(game, bob, TestCards.Creature("Plain Card Test", 2, 2));
        Assert.Throws<InvalidOperationException>(() => game.Suspend(bob, plain));
    }

    // ---- Activation restrictions (CR 602.5b) ---------------------------------

    [Fact]
    public void A_verge_land_only_taps_for_mana_once_the_right_land_is_out()
    {
        var verge = Card(
            "Verge Test",
            "{T}: Add {W}. Activate only if you control a Plains or a Swamp.",
            CardType.Land);

        var compiled = CardCompiler.Compile(verge);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var land = game.Create(alice, verge, Zone.Battlefield);

        // Nothing else on the board, so the condition is false and the ability is refused.
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, land, compiled.Activated[0].Id));

        // A Swamp is the second half of the alternation. Reading only the first would refuse
        // this too, and the dual lands that print it are exactly the cards that would break.
        game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);

        game.ActivateAbility(alice, land, compiled.Activated[0].Id);

        // CR 605.3b: a mana ability does not use the stack, so the mana is there without anything
        // resolving and nobody could have responded. Lifting the restriction off before the mana
        // grammar reads the line is what keeps that true - left on, the line falls through to the
        // general activated-ability path and the card quietly becomes respondable.
        Assert.NotEmpty(compiled.Activated[0].Produces);
        Assert.Empty(game.State.Stack);
        Assert.False(game.State.GetPlayer(alice).ManaPool.IsEmpty);
    }

    [Fact]
    public void A_basic_land_type_names_a_land_and_not_a_creature()
    {
        // "You control a Plains" asked about creature subtypes before, because a capitalised
        // noun in that position was always read as a creature type. Every card that cares about
        // basic land types said no.
        var spec = EffectPhrase.Specs.Parse("target Plains");

        Assert.NotNull(spec);

        var (game, alice, _) = InMainPhase();
        var plains = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        var bear = game.Create(alice, TestCards.Creature("Not A Plains Test", 2, 2), Zone.Battlefield);

        Assert.True(
            spec!.ObjectFilter!.Invoke(game.State, Pool, game.State.GetObject(plains), alice));
        Assert.False(
            spec.ObjectFilter.Invoke(game.State, Pool, game.State.GetObject(bear), alice));
    }

    // ---- Attack restrictions (CR 506.3) --------------------------------------

    [Fact]
    public void A_creature_that_needs_the_defender_to_have_an_island_waits_until_they_do()
    {
        var armada = Card(
            "Armada Test",
            "~ can't attack unless defending player controls an Island.",
            CardType.Creature, 4, 4);

        var compiled = CardCompiler.Compile(armada);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal("Island", compiled.AttacksOnlyIfDefenderControls);

        var (game, alice, bob) = InMainPhase();
        var ship = game.Create(alice, armada, Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        // Bob controls no Island, so the declaration is refused outright rather than the attack
        // being quietly dropped.
        Assert.Throws<InvalidOperationException>(
            () => game.DeclareAttackers(
                alice,
                new Dictionary<ObjectId, AttackTarget> { [ship] = AttackTarget.Player(bob) }));

        game.Create(bob, TestCards.BasicLand("Island"), Zone.Battlefield);

        // Same creature, same turn, same declaration — and now it is legal, which is the whole
        // point of the restriction reading the defender's board rather than the attacker's.
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [ship] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        Assert.Equal(16, game.State.GetPlayer(bob).Life);
    }

    // ---- Revealing (CR 701.16) -----------------------------------------------

    [Fact]
    public void A_revealed_hand_becomes_visible_to_the_opponent_and_stays_hidden_otherwise()
    {
        var peek = Card("Peek Test", "Target opponent reveals their hand.");

        var compiled = CardCompiler.Compile(peek);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        // Before: Alice sees a count and nothing else.
        var before = game.ViewFor(alice).Players.Single(p => p.PlayerId == bob);
        Assert.Null(before.Hand);
        Assert.Empty(before.RevealedHand);
        Assert.True(before.HandCount > 0);

        var card = TestCards.PutInHand(game, alice, peek);
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        var after = game.ViewFor(alice).Players.Single(p => p.PlayerId == bob);

        // The cards are public now, and the hand itself is still not Alice's to look at: those
        // are different facts, and collapsing them is how a projection starts leaking.
        Assert.Null(after.Hand);
        Assert.Equal(after.HandCount, after.RevealedHand.Count);
        Assert.All(after.RevealedHand, seen => Assert.False(string.IsNullOrEmpty(seen.Name)));
    }

    [Fact]
    public void A_card_drawn_after_the_reveal_is_not_revealed_with_it()
    {
        // A reveal shows what was in the hand when it happened. Anything drawn afterwards was
        // never shown, and a flag that leaked onto it would be a projection bug rather than a
        // rules one.
        var peek = Card("Later Peek Test", "Target opponent reveals their hand.");

        var (game, alice, bob) = InMainPhase();

        var card = TestCards.PutInHand(game, alice, peek);
        game.CastSpell(alice, card, [Target.ToPlayer(bob)]);
        Settle(game);

        var shownCount = game.ViewFor(alice).Players.Single(p => p.PlayerId == bob)
            .RevealedHand.Count;

        game.Draw(bob);

        var after = game.ViewFor(alice).Players.Single(p => p.PlayerId == bob);

        Assert.Equal(shownCount + 1, after.HandCount);
        Assert.Equal(shownCount, after.RevealedHand.Count);
    }

    // ---- Bouncing into the library -------------------------------------------

    [Fact]
    public void A_tuck_puts_the_creature_where_the_card_says_and_not_in_a_hand()
    {
        var onTop = Card("Tuck Top Test", "Put target creature on top of its owner's library.");
        var onBottom = Card(
            "Tuck Bottom Test", "Put target creature on the bottom of its owner's library.");

        Assert.True(
            CardCompiler.Compile(onTop).IsComplete,
            string.Join(" | ", CardCompiler.Compile(onTop).Unhandled));
        Assert.True(CardCompiler.Compile(onBottom).IsComplete);

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Tucked Bear Test", 2, 2), Zone.Battlefield);

        var before = game.State.GetPlayer(bob).Library.Count;

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, onTop), [Target.ToPermanent(bear)]);
        Settle(game);

        // Not the hand, which is what makes this different from an ordinary bounce.
        Assert.DoesNotContain(
            game.State.GetPlayer(bob).Hand,
            id => game.State.GetObject(id).Card.Name == "Tucked Bear Test");

        var library = game.State.GetPlayer(bob).Library;
        Assert.Equal(before + 1, library.Count);
        Assert.Equal("Tucked Bear Test", game.State.GetObject(library[0]).Card.Name);
    }

    [Fact]
    public void The_bottom_of_the_library_is_the_other_end_from_the_top()
    {
        // Which end is the whole reason a card prints one rather than the other, so reading
        // "bottom" as "top" would be a silent and very large difference.
        var onBottom = Card(
            "Deep Tuck Test", "Put target creature on the bottom of its owner's library.");

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Sunk Bear Test", 2, 2), Zone.Battlefield);

        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, onBottom), [Target.ToPermanent(bear)]);
        Settle(game);

        var library = game.State.GetPlayer(bob).Library;
        Assert.Equal("Sunk Bear Test", game.State.GetObject(library[^1]).Card.Name);
        Assert.NotEqual("Sunk Bear Test", game.State.GetObject(library[0]).Card.Name);
    }

    // ---- Graveyard reach -----------------------------------------------------

    [Fact]
    public void A_mass_return_takes_every_matching_card_and_leaves_the_rest()
    {
        var call = Card(
            "Mass Return Test", "Return all creature cards from your graveyard to your hand.");

        var compiled = CardCompiler.Compile(call);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        game.Create(alice, TestCards.Creature("Buried One Test", 2, 2), Zone.Graveyard);
        game.Create(alice, TestCards.Creature("Buried Two Test", 3, 3), Zone.Graveyard);
        game.Create(alice, Card("Buried Spell Test", "Draw a card."), Zone.Graveyard);

        // Bob's graveyard is the control: "your graveyard" is not "a graveyard".
        game.Create(bob, TestCards.Creature("Their Buried Test", 2, 2), Zone.Graveyard);

        var card = TestCards.PutInHand(game, alice, call);
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        var hand = game.State.GetPlayer(alice).Hand
            .Select(id => game.State.GetObject(id).Card.Name)
            .ToList();

        Assert.Contains("Buried One Test", hand);
        Assert.Contains("Buried Two Test", hand);
        Assert.DoesNotContain("Buried Spell Test", hand);

        Assert.Contains(
            game.State.GetPlayer(bob).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Their Buried Test");
    }

    [Fact]
    public void A_graveyard_target_may_name_a_type_that_is_never_a_permanent()
    {
        // The single-type branch asked the permanent type table, which has no answer for
        // "sorcery" - so the pair form "instant or sorcery card" read and the plain one did not,
        // in the one zone where a sorcery card is an ordinary thing to name.
        var recall = Card(
            "Sorcery Recall Test",
            "Return target sorcery card from your graveyard to your hand.");

        var compiled = CardCompiler.Compile(recall);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var buried = game.Create(
            alice,
            Card("Buried Sorcery Test", "Draw a card.", CardType.Sorcery),
            Zone.Graveyard);

        var wrongType = game.Create(alice, TestCards.Creature("Buried Body Test"), Zone.Graveyard);

        var card = TestCards.PutInHand(game, alice, recall);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        // The named type is the whole restriction: a creature card in the same graveyard is not
        // a legal target, which is what tells this apart from the typeless phrasing.
        var wrong = TestCards.PutInHand(game, alice, recall);
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, wrong, [Target.ToCard(wrongType)]));

        game.CastSpell(alice, card, [Target.ToCard(buried)]);
        Settle(game);

        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Buried Sorcery Test");
    }

    [Fact]
    public void A_graveyard_target_that_names_no_type_accepts_any_card_there()
    {
        var hate = Card("Typeless Hate Test", "Exile target card from a graveyard.");

        var compiled = CardCompiler.Compile(hate);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        // An instant, which every typed graveyard phrase in the engine would have refused.
        var buried = game.Create(bob, Card("Buried Instant Test", "Draw a card."), Zone.Graveyard);

        var card = TestCards.PutInHand(game, alice, hate);
        game.CastSpell(alice, card, [Target.ToCard(buried)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.GetPlayer(bob).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Buried Instant Test");
        Assert.Contains(
            game.State.Exile,
            id => game.State.GetObject(id).Card.Name == "Buried Instant Test");
    }

    [Fact]
    public void A_card_from_your_own_graveyard_goes_under_your_own_library()
    {
        // "Your library" was not among the phrasings, though for a card taken out of your own
        // graveyard it names the same deck as "its owner's": a card is only ever in the
        // graveyard of the player who owns it.
        var recycle = Card(
            "Bottom Deck Test",
            "Put target card from your graveyard on the bottom of your library.");

        var compiled = CardCompiler.Compile(recycle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var buried = game.Create(alice, TestCards.Creature("Buried Bear Test"), Zone.Graveyard);
        var before = game.State.GetPlayer(alice).Library.Count;

        var card = TestCards.PutInHand(game, alice, recycle);
        game.CastSpell(alice, card, [Target.ToCard(buried)]);
        Settle(game);

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Buried Bear Test");

        // On the bottom, which is the half of the line that distinguishes it from a tutor.
        var library = game.State.GetPlayer(alice).Library;
        Assert.Equal(before + 1, library.Count);
        Assert.Equal("Buried Bear Test", game.State.GetObject(library[^1]).Card.Name);
    }

    // ---- Group draws ---------------------------------------------------------

    [Fact]
    public void Each_player_draws_reaches_everyone_including_the_caster()
    {
        var wheel = Card("Group Draw Test", "Each player draws two cards.");

        var compiled = CardCompiler.Compile(wheel);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var mine = game.State.GetPlayer(alice).Hand.Count;
        var theirs = game.State.GetPlayer(bob).Hand.Count;

        var card = TestCards.PutInHand(game, alice, wheel);
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        // The caster's hand is counted from before the spell was put into it and after it left,
        // so the only difference is the two cards drawn.
        Assert.Equal(mine + 2, game.State.GetPlayer(alice).Hand.Count);
        Assert.Equal(theirs + 2, game.State.GetPlayer(bob).Hand.Count);
    }

    [Fact]
    public void Each_opponent_draws_leaves_the_caster_out()
    {
        // The scope is the whole difference between the two sentences, and reading it as "each
        // player" would be invisible in a test that only checked the opponent.
        var gift = Card("Opponent Draw Test", "Each opponent draws a card.");

        Assert.True(CardCompiler.Compile(gift).IsComplete);

        var (game, alice, bob) = InMainPhase();

        var mine = game.State.GetPlayer(alice).Hand.Count;
        var theirs = game.State.GetPlayer(bob).Hand.Count;

        var card = TestCards.PutInHand(game, alice, gift);
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        Assert.Equal(mine, game.State.GetPlayer(alice).Hand.Count);
        Assert.Equal(theirs + 1, game.State.GetPlayer(bob).Hand.Count);
    }

    // ---- Cumulative upkeep (CR 702.24) ---------------------------------------

    [Fact]
    public void Cumulative_upkeep_costs_one_more_each_turn_until_it_cannot_be_paid()
    {
        var relic = Card("Ageing Relic Test", "Cumulative upkeep {1}", CardType.Artifact);

        var compiled = CardCompiler.Compile(relic);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, relic, Zone.Battlefield);

        // Exactly one land, for the whole test. That is what makes the two upkeeps differ: the
        // mana available never changes, and only the cost does.
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 3 && game.State.CurrentStep == TurnStep.Upkeep);

        game.ActivateAbility(alice, land, "mana");
        Settle(game);

        for (var guard = 0; guard < 10 && game.State.Choice is { } choice; guard++)
            game.Choose(choice.PlayerId, [choice.Options[0].Id]);

        Settle(game);

        // First age counter, cost {1}, and one mana pays it.
        var alive = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Ageing Relic Test");

        Assert.Equal(1, game.State.GetObject(alive).Permanent?.Counters.GetValueOrDefault("age", 0));

        TestCards.PassUntil(
            game,
            () => game.State.TurnNumber == 5 && game.State.CurrentStep == TurnStep.Upkeep);

        game.ActivateAbility(alice, land, "mana");
        Settle(game);

        for (var guard = 0; guard < 10 && game.State.Choice is { } choice; guard++)
            game.Choose(choice.PlayerId, [choice.Options[^1].Id]);

        Settle(game);

        // Second age counter, cost {1}{1}, and the same one mana no longer covers it. The relic
        // surviving the first upkeep and dying on the second with identical mana is the whole
        // claim: the cost climbed.
        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Ageing Relic Test");
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Ageing Relic Test");
    }

    // ---- Scavenge (CR 702.98) ------------------------------------------------

    [Fact]
    public void Scavenge_exiles_the_card_from_the_graveyard_and_pays_out_its_power()
    {
        var hulk = new CardDefinition
        {
            OracleId = "oracle-scavenge-hulk-test",
            Name = "Scavenge Hulk Test",
            OracleText = "Scavenge {1}",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{3}",
            Power = 3,
            Toughness = 3,
        };

        var compiled = CardCompiler.Compile(hulk);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        var buried = game.Create(alice, hulk, Zone.Graveyard);
        var bear = game.Create(alice, TestCards.Creature("Scavenged Bear Test", 2, 2), Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.ActivateAbility(alice, buried, "scavenge", [Target.ToPermanent(bear)]);
        Settle(game);

        // Three counters, because the card in the graveyard is a 3/3.
        var grown = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Scavenged Bear Test");

        Assert.Equal(
            3, game.State.GetObject(grown).Permanent?.Counters.GetValueOrDefault("+1/+1", 0));
        Assert.Equal(5, Characteristics.Of(game.State, Pool, game.State.GetObject(grown)).Power);

        // And the cost took the card out of the game rather than leaving it in the graveyard to
        // be scavenged again (CR 701.13a).
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Scavenge Hulk Test");
        Assert.Contains(
            game.State.Exile,
            id => game.State.GetObject(id).Card.Name == "Scavenge Hulk Test");
    }

    // ---- Evoke (CR 702.74) ---------------------------------------------------

    [Fact]
    public void An_evoked_creature_dies_at_once_and_its_trigger_happens_anyway()
    {
        var elemental = new CardDefinition
        {
            OracleId = "oracle-evoke-elemental-test",
            Name = "Evoke Elemental Test",
            OracleText = "Evoke {G}\nWhen ~ enters, you gain 4 life.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{4}{G}",
            Power = 3,
            Toughness = 3,
        };

        var compiled = CardCompiler.Compile(elemental);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // One land, against a printed {4}{G}: the cast only works because evoke replaced it.
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        var card = TestCards.PutInHand(game, alice, elemental);
        game.CastSpell(alice, card, targets: null, evoked: true);
        Settle(game);

        // The whole point of paying evoke: the trigger it was cast for still resolves, because a
        // trigger is its own object once it has fired (CR 603.6).
        Assert.Equal(24, game.State.GetPlayer(alice).Life);

        // And the creature itself is gone the moment it arrived.
        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Evoke Elemental Test");
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Evoke Elemental Test");
    }

    [Fact]
    public void The_same_creature_cast_normally_stays_on_the_battlefield()
    {
        // The half that stops the sacrifice being unconditional: evoke is a choice, and a card
        // with evoke cast for its printed cost is an ordinary creature.
        var elemental = new CardDefinition
        {
            OracleId = "oracle-kept-elemental-test",
            Name = "Kept Elemental Test",
            OracleText = "Evoke {G}\nWhen ~ enters, you gain 4 life.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{G}",
            Power = 3,
            Toughness = 3,
        };

        var (game, alice, _) = InMainPhase();
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        var card = TestCards.PutInHand(game, alice, elemental);
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Kept Elemental Test");
    }

    // ---- Dash (CR 702.109) ---------------------------------------------------

    [Fact]
    public void A_dashed_creature_costs_less_attacks_at_once_and_goes_home()
    {
        var raider = new CardDefinition
        {
            OracleId = "oracle-dash-raider-test",
            Name = "Dash Raider Test",
            OracleText = "Dash {1}{R}",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{4}{R}",
            Power = 2,
            Toughness = 2,
        };

        var compiled = CardCompiler.Compile(raider);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        // Two lands: enough for {1}{R} and nowhere near the printed {4}{R}. That the cast works
        // at all is the proof that dash replaced the mana cost rather than being added to it.
        foreach (var name in new[] { "Mountain", "Forest" })
        {
            var land = game.Create(alice, TestCards.BasicLand(name), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        var card = TestCards.PutInHand(game, alice, raider);
        game.CastSpell(alice, card, targets: null, dashed: true);
        Settle(game);

        var raiderId = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Dash Raider Test");

        // Haste, proved the only way it can be proved: it attacks the turn it arrived. A creature
        // without haste is refused here outright (CR 302.6).
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [raiderId] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>>());
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);

        // And then it goes home at the beginning of the end step, still in the same turn — which
        // is what the whole cost discount is paid for.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Dash Raider Test");
        Assert.Contains(
            game.State.GetPlayer(alice).Hand,
            id => game.State.GetObject(id).Card.Name == "Dash Raider Test");
    }

    // ---- Speed (CR 702.179) --------------------------------------------------

    [Fact]
    public void Starting_your_engines_only_helps_a_player_who_has_no_speed()
    {
        var racer = Card(
            "Engine Starter Test", "Start your engines!", CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(racer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        Assert.Equal(0, game.State.GetPlayer(alice).Speed);

        game.Create(alice, racer, Zone.Battlefield);
        Settle(game);

        // No speed becomes speed 1 (CR 702.179a).
        Assert.Equal(1, game.State.GetPlayer(alice).Speed);

        // A second one does nothing at all — the keyword is not "your speed increases".
        game.Create(alice, racer, Zone.Battlefield);
        Settle(game);

        Assert.Equal(1, game.State.GetPlayer(alice).Speed);
    }

    [Fact]
    public void Speed_goes_up_once_a_turn_when_an_opponent_loses_life()
    {
        var racer = Card(
            "Revving Test", "Start your engines!", CardType.Creature, 2, 2);
        var drain = Card("Small Drain Test", "Each opponent loses 1 life.");

        var (game, alice, bob) = InMainPhase();

        game.Create(alice, racer, Zone.Battlefield);
        Settle(game);
        Assert.Equal(1, game.State.GetPlayer(alice).Speed);

        var first = TestCards.PutInHand(game, alice, drain);
        game.CastSpell(alice, first, targets: null);
        Settle(game);

        Assert.Equal(19, game.State.GetPlayer(bob).Life);
        Assert.Equal(2, game.State.GetPlayer(alice).Speed);

        // CR 702.179b: "This happens only once each turn." A second opponent losing life in the
        // same turn is the case the flag exists for, and it is the one that would otherwise let
        // a player reach top speed in a single turn.
        var second = TestCards.PutInHand(game, alice, drain);
        game.CastSpell(alice, second, targets: null);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(2, game.State.GetPlayer(alice).Speed);

        // Bob is not the active player, so nothing about Alice losing life moves Bob — and Bob
        // never started any engines, so he has no speed to increase either way.
        Assert.Equal(0, game.State.GetPlayer(bob).Speed);
    }

    // ---- Cascade (CR 702.85) -------------------------------------------------

    [Fact]
    public void Cascade_digs_past_lands_and_offers_the_first_cheaper_spell()
    {
        var oracle = Kicked("Cascade Test", "{4}", "Cascade\nYou gain 1 life.", cmc: 4);

        var (game, alice, _) = InMainPhase();

        // The library is built top-down: a land first, then something too expensive, then the
        // card cascade should stop on. Digging past all three is what the rule says to do.
        game.Create(alice, Card("Cheap Cascade Hit Test", "You gain 5 life.", CardType.Sorcery),
            Zone.Library);
        var dear = new CardDefinition
        {
            OracleId = "oracle-dear-cascade-test",
            Name = "Dear Cascade Test",
            OracleText = "You gain 9 life.",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{9}",
            Cmc = 9,
        };

        game.Create(alice, dear, Zone.Library);
        game.Create(alice, TestCards.BasicLand("Island"), Zone.Library);

        var card = TestCards.PutInHand(game, alice, oracle);

        foreach (var name in new[] { "Forest", "Plains", "Mountain", "Swamp" })
        {
            var land = game.Create(alice, TestCards.BasicLand(name), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(alice, card, targets: null);
        Settle(game);

        var offered = game.State.Exile.SingleOrDefault(
            id => game.State.GetObject(id).Card.Name == "Cheap Cascade Hit Test");

        Assert.NotEqual(default, offered);

        // The land and the expensive card went back to the bottom; only the hit stayed in exile.
        Assert.DoesNotContain(
            game.State.Exile, id => game.State.GetObject(id).Card.Name == "Island");
        Assert.DoesNotContain(
            game.State.Exile, id => game.State.GetObject(id).Card.Name == "Dear Cascade Test");
    }

    [Fact]
    public void The_offered_card_can_be_cast_for_nothing_and_the_offer_lapses_on_a_pass()
    {
        var oracle = Kicked("Lapse Cascade Test", "{4}", "Cascade\nYou gain 1 life.", cmc: 4);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, Card("Free Hit Test", "You gain 5 life.", CardType.Sorcery), Zone.Library);

        var card = TestCards.PutInHand(game, alice, oracle);

        foreach (var name in new[] { "Forest", "Plains", "Mountain", "Swamp" })
        {
            var land = game.Create(alice, TestCards.BasicLand(name), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.CastSpell(alice, card, targets: null);

        // Settle would pass priority, and passing is what revokes the offer — so this stops the
        // moment the cascade has resolved, which is the window the rules give.
        TestCards.PassUntil(
            game,
            () => game.State.Exile.Any(
                id => game.State.GetObject(id).Card.Name == "Free Hit Test"));

        var offered = game.State.Exile.Single(
            id => game.State.GetObject(id).Card.Name == "Free Hit Test");

        // No mana left at all, and it casts — that is what "without paying its mana cost" means.
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
        Assert.True(game.State.GetObject(offered).MayCastFree);

        game.CastSpell(alice, offered, targets: null);
        Settle(game);

        Assert.Equal(26, game.State.GetPlayer(alice).Life);
    }

    // ---- Foretell (CR 702.143) -----------------------------------------------

    [Fact]
    public void A_foretold_card_is_cast_from_exile_on_a_later_turn_for_less()
    {
        var oracle = Kicked("Foretell Test", "{5}", "Foretell {1}\nYou gain 3 life.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, oracle);

        var first = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var second = game.Create(alice, TestCards.BasicLand("Plains"), Zone.Battlefield);
        game.ActivateAbility(alice, first, "mana");
        game.ActivateAbility(alice, second, "mana");

        // {2} to foretell, and the card leaves the hand for exile.
        game.Foretell(alice, card);
        Assert.DoesNotContain(card, game.State.GetPlayer(alice).Hand);

        var exiled = game.State.Exile.Single(
            id => game.State.GetObject(id).Card.Name == "Foretell Test");

        // A later turn, and one mana pays for a card printed at five.
        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(
            game,
            () => game.State.CurrentStep == TurnStep.PrecombatMain
                && game.State.Priority.Holder == alice);

        var third = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, third, "mana");

        game.CastSpell(alice, exiled, targets: null);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_card_foretold_this_turn_cannot_be_cast_this_turn()
    {
        // "On a later turn" is the whole tension of the mechanic: without it, foretell would just
        // be a discount, paid and spent in one breath.
        var oracle = Kicked("Hasty Foretell Test", "{5}", "Foretell {1}\nYou gain 3 life.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, oracle);

        foreach (var name in new[] { "Forest", "Plains", "Island" })
        {
            var land = game.Create(alice, TestCards.BasicLand(name), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        game.Foretell(alice, card);

        var exiled = game.State.Exile.Single(
            id => game.State.GetObject(id).Card.Name == "Hasty Foretell Test");

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, exiled, targets: null));
    }

    // ---- Conditions that watch a whole board (CR 603.2) ----------------------

    [Fact]
    public void Whenever_a_creature_you_control_attacks_counts_only_yours()
    {
        var watcher = Card(
            "Attack Watcher Test",
            "Whenever a creature you control attacks, you gain 1 life.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        var mine = game.Create(alice, TestCards.Creature("Attacker A Test"), Zone.Battlefield);
        var alsoMine = game.Create(alice, TestCards.Creature("Attacker B Test"), Zone.Battlefield);

        TestCards.PassToTurn(game, 3);
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [mine] = AttackTarget.Player(bob),
                [alsoMine] = AttackTarget.Player(bob),
            });

        Settle(game);

        // The clause is "a creature you control attacks", not "creatures attack" — it fires once
        // per declaration, not once per attacker.
        Assert.Equal(21, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void Whenever_you_sacrifice_a_creature_ignores_the_opponents_sacrifices()
    {
        var watcher = Card(
            "Sacrifice Watcher Test",
            "Whenever you sacrifice a creature, you gain 2 life.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        game.Create(alice, TestCards.Creature("Given Bear Test"), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Their Given Bear Test"), Zone.Battlefield);

