    // ---- Exile until this leaves the battlefield (CR 400.7) ------------------

    [Fact]
    public void The_exiled_card_comes_back_when_the_permanent_that_took_it_goes()
    {
        var ring = Card(
            "Ring Test",
            "When ~ enters, exile target creature an opponent controls until ~ leaves the battlefield.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        var bear = game.Create(bob, TestCards.Creature("Ringed Bear Test", 2, 2), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, ring);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        Assert.DoesNotContain(bear, game.State.Battlefield);
        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Ringed Bear Test");

        // Destroy the enchantment; the creature returns, under its owner's control.
        var ringOnBattlefield = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Ring Test");

        var bolt = TestCards.PutInHand(
            game, alice, Card("Ring Bolt Test", "Destroy target enchantment."));

        var forest2 = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest2, "mana");
        game.CastSpell(alice, bolt, [Target.ToPermanent(ringOnBattlefield)]);
        Settle(game);

        var returned = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Ringed Bear Test");

        // CR 400.7: it comes back as a new object, and it is its owner's — not the exiler's.
        Assert.NotEqual(bear, returned);
        Assert.Equal(bob, game.State.GetObject(returned).ControllerId);
    }

    [Fact]
    public void A_second_ring_gives_back_only_what_it_took()
    {
        var ring = Card(
            "Twin Ring Test",
            "When ~ enters, exile target creature an opponent controls until ~ leaves the battlefield.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(bob, TestCards.Creature("First Bear Test", 2, 2), Zone.Battlefield);
        game.Create(bob, TestCards.Creature("Second Bear Test", 3, 3), Zone.Battlefield);

        for (var i = 0; i < 2; i++)
        {
            var card = TestCards.PutInHand(game, alice, ring);
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
            game.CastSpell(alice, card, targets: null);
            Settle(game);
        }

        // Both bears are gone.
        Assert.DoesNotContain(
            game.State.Battlefield, id => game.State.GetObject(id).ControllerId == bob);

        // Destroy one ring: exactly one bear comes back, not both.
        var oneRing = game.State.Battlefield.First(
            id => game.State.GetObject(id).Card.Name == "Twin Ring Test");

        var bolt = TestCards.PutInHand(
            game, alice, Card("Twin Bolt Test", "Destroy target enchantment."));

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.CastSpell(alice, bolt, [Target.ToPermanent(oneRing)]);
        Settle(game);

        Assert.Single(
            game.State.Battlefield, id => game.State.GetObject(id).ControllerId == bob);
    }

    // ---- Token copies (CR 707.2) ---------------------------------------------

    [Fact]
    public void A_token_copy_takes_the_printed_card_and_not_what_was_done_to_it()
    {
        var mirror = Card(
            "Mirror Test",
            "When ~ enters, create a token that's a copy of target creature you control.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Copied Bear Test", 2, 2), Zone.Battlefield);

        // Counters are not copiable values (CR 707.2), so the copy is a 2/2 and not a 4/4. The
        // bear is the only creature Alice controls, so the trigger has exactly one legal target
        // and the test is not at the mercy of which one gets picked.
        var pump = TestCards.PutInHand(
            game, alice, Card("Counter Pump Test", "Put two +1/+1 counters on target creature."));

        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");
        game.CastSpell(alice, pump, [Target.ToPermanent(bear)]);
        Settle(game);

        Assert.Equal(
            4,
            Characteristics.Of(game.State, new CompiledPool(), game.State.GetObject(bear)).Power);

        var enchantment = TestCards.PutInHand(game, alice, mirror);
        var forest2 = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest2, "mana");
        game.CastSpell(alice, enchantment, targets: null);
        Settle(game);

        var copy = game.State.Battlefield
            .Select(id => game.State.GetObject(id))
            .Single(o => o.Card.Name == "Copied Bear Test"
                && o.Card.CardTypes.HasFlag(CardType.Token));

        Assert.Equal(2, Characteristics.Of(game.State, new CompiledPool(), copy).Power);
    }

    // ---- Copying spells, and storm (CR 707.10, 702.40) -----------------------

    [Fact]
    public void Storm_copies_once_for_each_spell_cast_before_it()
    {
        var bolt = Card("Storm Bolt Test", "~ deals 1 damage to any target.\nStorm");

        var (game, alice, bob) = InMainPhase();

        for (var i = 0; i < 6; i++)
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        // Two cantrips first, so the storm spell is the third of the turn and copies twice.
        for (var i = 0; i < 2; i++)
        {
            var cantrip = TestCards.PutInHand(
                game, alice, Card($"Storm Cantrip {i} Test", "Draw a card."));

            game.CastSpell(alice, cantrip, targets: null);
            Settle(game);
        }

        var storm = TestCards.PutInHand(game, alice, bolt);
        game.CastSpell(alice, storm, [Target.ToPlayer(bob)]);
        Settle(game);

        // Three damage: the spell and its two copies. One copy, or three, would be a different
        // number — and no copies at all would be 1.
        Assert.Equal(17, game.State.GetPlayer(bob).Life);

        // CR 707.10: a copy is not a card, so only the real one is in the graveyard.
        Assert.Single(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Storm Bolt Test");
    }

    [Fact]
    public void Storm_on_the_first_spell_of_the_turn_copies_nothing()
    {
        var bolt = Card("Lonely Storm Test", "~ deals 1 damage to any target.\nStorm");

        var (game, alice, bob) = InMainPhase();
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var storm = TestCards.PutInHand(game, alice, bolt);
        game.CastSpell(alice, storm, [Target.ToPlayer(bob)]);
        Settle(game);

        Assert.Equal(19, game.State.GetPlayer(bob).Life);
    }

    // ---- "Your second spell each turn" (CR 603.2) ----------------------------

    [Fact]
    public void The_second_spell_each_turn_triggers_on_the_second_and_no_other()
    {
        var watcher = Card(
            "Second Spell Test",
            "Whenever you cast your second spell each turn, you gain 3 life.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        for (var i = 0; i < 4; i++)
        {
            var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        var life = new List<int>();

        for (var i = 0; i < 3; i++)
        {
            var spell = TestCards.PutInHand(
                game, alice, Card($"Cantrip {i} Test", "Draw a card."));

            game.CastSpell(alice, spell, targets: null);
            Settle(game);
            life.Add(game.State.GetPlayer(alice).Life);
        }

        // Nothing on the first, three on the second, nothing on the third — a trigger that fired
        // on every spell, or from the first onwards, produces a different sequence.
        Assert.Equal([20, 23, 23], life);
    }

    [Fact]
    public void An_energy_offer_with_a_two_part_consequence_compiles()
    {
        // The line the work queue has been pointing at, written out in full: an energy price,
        // two effects joined by "and", an optional target and a defending-player phrase. Every
        // piece of it was added separately; this is the assertion that they compose.
        var raider = Card(
            "Energy Raider Test",
            "Whenever ~ attacks, you may pay {E}{E}. If you do, put a +1/+1 counter on it and "
                + "tap up to one target creature defending player controls.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(raider);

        // The pieces individually, then the whole. Kept as a list because the composition is
        // what broke: every part of this line compiled on its own while the sentence did not,
        // and the cause was a rewrite claiming any sentence that merely contained "up to one
        // target" and swallowing the conjunction around it.
        foreach (var piece in new[]
        {
            "Whenever ~ attacks, put a +1/+1 counter on it.",
            "Whenever ~ attacks, tap up to one target creature defending player controls.",
            "Whenever ~ attacks, you may pay {E}{E}. If you do, you gain 1 life.",
            "Whenever ~ attacks, put a +1/+1 counter on it and tap up to one target creature "
                + "an opponent controls.",
            "Whenever ~ attacks, ~ deals 2 damage to up to one target creature.",
        })
        {
            var one = CardCompiler.Compile(
                Card("Piece " + piece.GetHashCode() + " Test", piece, CardType.Creature, 2, 2));
            Assert.True(one.IsComplete, piece + " -> " + string.Join(" | ", one.Unhandled));
        }

        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
    }

    /// <summary>
    /// Every shape "up to one target" is printed in, read as the spell it belongs to.
    /// </summary>
    /// <remarks>
    /// Written after a bisect that blamed the compiler for a fault in the test: these lines were
    /// being compiled onto a *creature*, where a bare effect sentence has nowhere to go and is
    /// unhandled for a reason that has nothing to do with the phrase. Compiled as the instants
    /// they are, every one of them reads. The card type is part of the question.
    /// </remarks>
    [Fact]
    public void Up_to_one_target_reads_in_every_shape_it_is_printed_in()
    {
        var failures = new List<string>();

        foreach (var text in new[]
        {
            "Tap up to one target creature.",
            "tap up to one target creature.",
            "Destroy up to one target creature.",
            "~ deals 2 damage to up to one target creature.",
            "Up to one target creature gains flying until end of turn.",
            "Up to one target creature gets +1/+1 until end of turn.",
            "Return up to one target creature to its owner's hand.",
        })
        {
            var one = CardCompiler.Compile(
                Card("Probe " + text.GetHashCode() + " Test", text));

            if (!one.IsComplete)
                failures.Add(text);
        }

        Assert.Empty(failures);
    }

    [Fact]
    public void A_named_type_attacking_alone_checks_both_the_type_and_the_count()
    {
        var banner = Card(
            "Clan Banner Test",
            "Whenever a Samurai or Warrior you control attacks alone, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(banner);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, banner, Zone.Battlefield);

        var samurai = game.Create(
            alice,
            Card("Lone Samurai Test", string.Empty, CardType.Creature, 2, 2,
                KeywordAbility.None, "Samurai"),
            Zone.Battlefield);

        var bear = game.Create(alice, TestCards.Creature("Plain Bear Test", 2, 2), Zone.Battlefield);

        // The wrong type attacking alone is still alone, and still does not answer to the card.
        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [bear] = AttackTarget.Player(bob) });
        Settle(game);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        // The right type, but not alone.
        PassTo(game, 5, TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [samurai] = AttackTarget.Player(bob),
            [bear] = AttackTarget.Player(bob),
        });
        Settle(game);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        // Both conditions at once.
        PassTo(game, 7, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [samurai] = AttackTarget.Player(bob) });
        Settle(game);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void Enters_or_leaves_fires_on_both_halves()
    {
        var revolving = Card(
            "Revolving Door Test",
            "Whenever ~ enters or leaves the battlefield, you gain 1 life.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(revolving);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, revolving, Zone.Battlefield);
        Settle(game);
        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        // "Leaves" is any departure, not a death: this one is exiled and still counts.
        game.Move(creature, Zone.Exile, MoveCause.Exile);
        Settle(game);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    // ---- A static whose size is counted (CR 613.4c) --------------------------

    [Fact]
    public void A_counting_static_grows_as_the_board_does()
    {
        var golem = Card(
            "Counting Golem Test",
            "This creature gets +1/+1 for each artifact you control.",
            CardType.Creature | CardType.Artifact,
            power: 0,
            toughness: 1);

        var compiled = CardCompiler.Compile(golem);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var it = game.Create(alice, golem, Zone.Battlefield);

        // It counts itself, which is what "each artifact you control" says.
        Assert.Equal(1, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(it)));

        game.Create(alice, Card("Counting Rock Test", string.Empty, CardType.Artifact), Zone.Battlefield);
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(it)));

        // The opponent's artifact is not one Alice controls, and the count is taken now rather
        // than when the golem arrived - no event goes back to adjust anything.
        game.Create(bob, Card("Enemy Rock Test", string.Empty, CardType.Artifact), Zone.Battlefield);
        Assert.Equal(2, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(it)));
    }

    [Fact]
    public void A_counting_aura_counts_its_own_controllers_board()
    {
        // The case that separates the two controllers: Alice's Aura on Bob's creature counts
        // Alice's artifacts, because "you" is whoever controls the ability (CR 109.5).
        var aura = Card(
            "Counting Aura Test",
            "Enchant creature\nEnchanted creature gets +1/+0 for each artifact you control.",
            CardType.Enchantment,
            subtypes: "Aura");

        var compiled = CardCompiler.Compile(aura);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var theirs = game.Create(bob, TestCards.Creature("Enchanted Bear Test", 2, 2), Zone.Battlefield);

        game.Create(alice, Card("Alice Rock One Test", string.Empty, CardType.Artifact), Zone.Battlefield);
        game.Create(alice, Card("Alice Rock Two Test", string.Empty, CardType.Artifact), Zone.Battlefield);
        game.Create(bob, Card("Bob Rock Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, aura);
        game.CastSpell(alice, card, [Target.ToPermanent(theirs)]);
        Settle(game);

        // Two, not one and not three: Alice's artifacts, counted for a creature Bob controls.
        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(theirs)));
    }

    [Fact]
    public void A_self_pump_counted_by_the_board_is_counted_when_it_applies()
    {
        var brute = Card(
            "Counting Brute Test",
            "When ~ enters, it gets +1/+1 until end of turn for each artifact you control.",
            CardType.Creature,
            power: 1,
            toughness: 1);

        var compiled = CardCompiler.Compile(brute);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, Card("Brute Rock One Test", string.Empty, CardType.Artifact), Zone.Battlefield);
        game.Create(alice, Card("Brute Rock Two Test", string.Empty, CardType.Artifact), Zone.Battlefield);
        game.Create(bob, Card("Brute Enemy Rock Test", string.Empty, CardType.Artifact), Zone.Battlefield);

        var it = game.Create(alice, brute, Zone.Battlefield);
        Settle(game);

        // 1/1 plus Alice's two artifacts, not Bob's three.
        Assert.Equal(3, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(it)));

        // Counted when the layer applies, not when the trigger resolved: a third artifact makes
        // it bigger with nothing going back to adjust anything.
        game.Create(alice, Card("Brute Rock Three Test", string.Empty, CardType.Artifact), Zone.Battlefield);
        Assert.Equal(4, Characteristics.PowerOf(game.State, Pool, game.State.GetObject(it)));
    }

    // ---- A power threshold on a zone-change trigger (CR 603.2) ---------------

    [Fact]
    public void A_power_threshold_on_an_enters_trigger_is_a_threshold()
    {
        var watcher = Card(
            "Big Arrival Test",
            "Whenever a creature you control with power 3 or greater enters, you gain 2 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
