        // The opponent's big creature is not one Alice controls.
        game.Create(bob, TestCards.Creature("Enemy Arrival Test", 5, 5), Zone.Battlefield);
        Settle(game);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    // ---- Cycling counts as discarding (CR 702.29c) ---------------------------

    [Fact]
    public void Cycle_or_discard_fires_once_for_a_cycle_and_once_for_a_discard()
    {
        var watcher = Card(
            "Discard Watcher Test",
            "Whenever you cycle or discard a card, you gain 1 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);

        var cycler = TestCards.PutInHand(
            game, alice, Card("Watched Cycler Test", "Cycling {0}", CardType.Creature, 2, 2));

        game.ActivateAbility(alice, cycler, "cycling");
        Settle(game);

        // Once, not twice. Cycling discards the card as its cost (CR 702.29c), so a trigger that
        // watched the activation *and* the discard would count one cycle as two.
        Assert.Equal(21, game.State.GetPlayer(alice).Life);

        var spare = TestCards.PutInHand(game, alice, TestCards.Creature("Spare Card Test", 1, 1));
        game.Move(spare, Zone.Graveyard, MoveCause.Discard);
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

