    [Fact]
    public void A_mana_value_threshold_on_a_cast_trigger_is_a_threshold()
    {
        var watcher = Card(
            "Big Spell Watcher Test",
            "Whenever you cast a spell with mana value 3 or greater, you gain 2 life.",
            CardType.Enchantment);

