    // ---- Counting the attack (CR 508.1) --------------------------------------

    [Fact]
    public void Attacking_with_others_counts_the_whole_declaration()
    {
        var captain = Card(
            "Horde Captain Test",
            "Whenever ~ and at least two other creatures attack, you gain 5 life.",
            CardType.Creature, 1, 1);

        var compiled = CardCompiler.Compile(captain);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var leader = game.Create(alice, captain, Zone.Battlefield);
        var first = game.Create(alice, TestCards.Creature("Horde One Test", 1, 1), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Horde Two Test", 1, 1), Zone.Battlefield);

        // Two attackers is one short of what the card asks for.
        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [leader] = AttackTarget.Player(bob),
            [first] = AttackTarget.Player(bob),
        });
        Settle(game);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        // Three is not.
        PassTo(game, 5, TurnStep.DeclareAttackers);
        game.DeclareAttackers(alice, new Dictionary<ObjectId, AttackTarget>
        {
            [leader] = AttackTarget.Player(bob),
            [first] = AttackTarget.Player(bob),
            [second] = AttackTarget.Player(bob),
        });
        Settle(game);
        Assert.Equal(25, game.State.GetPlayer(alice).Life);
    }

