    // ---- An Aura's clock runs on its host's controller (CR 506.2) ------------

    [Fact]
    public void An_aura_upkeep_trigger_follows_the_enchanted_creatures_controller()
    {
        var curse = Card(
            "Aura Clock Test",
            "Enchant creature\nAt the beginning of the upkeep of enchanted creature's "
                + "controller, you gain 1 life.",
            CardType.Enchantment, null, null, KeywordAbility.None, "Aura");

        var compiled = CardCompiler.Compile(curse);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var host = game.Create(bob, TestCards.Creature("Cursed Creature Test", 1, 1), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, curse);
        game.CastSpell(alice, card, targets: [Target.ToPermanent(host)]);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        // Bob's upkeep is turn 2. The Aura is Alice's, and it is Bob's clock that runs it - which
        // is the difference between this and "the beginning of your upkeep", and the reason most
        // of these cards are printed at all.
        PassTo(game, 2, TurnStep.Upkeep);
        Settle(game);
        Assert.Equal(before + 1, game.State.GetPlayer(alice).Life);

        // Alice's own upkeep is not the enchanted creature's controller's, so nothing happens.
        PassTo(game, 3, TurnStep.Upkeep);
        Settle(game);
        Assert.Equal(before + 1, game.State.GetPlayer(alice).Life);
    }

    // ---- "Cast or copy" (CR 707.10) ------------------------------------------

    [Fact]
    public void Cast_or_copy_counts_the_copy_as_well_as_the_cast()
    {
        var watcher = Card(
            "Copy Watcher Test",
            "Whenever you cast or copy an instant or sorcery spell, you gain 1 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var spell = Card("Copied Spell Test", "You gain 3 life.\nCasualty 1");

        var (game, alice, _) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        var fodder = game.Create(alice, TestCards.Creature("Copy Fodder Test", 1, 1), Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, spell);
        game.CastSpell(alice, card, targets: null, costPayment: [fodder], conspired: true);

        // Driven by hand rather than through Settle. Two of the watcher's triggers wait at once -
        // one for the cast, one for the copy - and their controller orders them (CR 603.3b);
        // Settle answers every question with its first option, which an ordering question refuses
        // outright because the same trigger cannot be put first twice.
        for (var guard = 0; guard < 60; guard++)
        {
            if (game.State.Choice is { } pending)
            {
                game.Choose(
                    pending.PlayerId,
                    pending.MaxPicks > 1
                        ? [.. pending.Options.Select(o => o.Id)]
                        : [pending.Options[0].Id]);

                continue;
            }

            if (game.State.Stack.IsEmpty)
                break;

            if (game.State.Priority.Holder is { } holder)
                game.PassPriority(holder);
            else
                break;
        }

        // The spell and its copy each gain 3, and the watcher sees both events: a copy is put on
        // the stack without being cast (CR 707.10), so nothing about the cast event sees it and
        // the trigger has to read both.
        Assert.Equal(28, game.State.GetPlayer(alice).Life);
    }

    // ---- Cycling triggers (CR 702.29a) ---------------------------------------

    [Fact]
    public void A_when_you_cycle_trigger_fires_on_cycling_it()
    {
        var card = Card(
            "Cycle Trigger Test",
            "Cycling {0}\nWhen you cycle ~, you gain 2 life.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(card);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var inHand = TestCards.PutInHand(game, alice, card);
        var handBefore = game.State.GetPlayer(alice).Hand.Count;

        game.ActivateAbility(alice, inHand, "cycling");
        Settle(game);

        // Cycling is the activation, so the trigger fires off it - and the draw the keyword
        // itself gives still happens, which is what keeps the hand count level.
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
        Assert.Equal(handBefore, game.State.GetPlayer(alice).Hand.Count);
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Cycle Trigger Test");
    }

    // ---- A group creature connecting (CR 510.2) ------------------------------

    [Fact]
    public void A_creature_you_control_dealing_combat_damage_triggers_for_your_side_only()
    {
        var watcher = Card(
            "Damage Watcher Test",
            "Whenever a creature you control deals combat damage to a player, you gain 1 life.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, watcher, Zone.Battlefield);
        var mine = game.Create(alice, TestCards.Creature("Connecting Test", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Their Attacker Test", 2, 2), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [mine] = AttackTarget.Player(bob) });
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(21, game.State.GetPlayer(alice).Life);
        Assert.Equal(18, game.State.GetPlayer(bob).Life);

        // Bob's creature connecting is not "a creature you control", so Alice gains nothing from
        // it - the side of the board is part of the trigger, not decoration.
        PassTo(game, 4, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            bob,
            new Dictionary<ObjectId, AttackTarget> { [theirs] = AttackTarget.Player(alice) });
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        // 21 from her own hit, minus the 2 she has just taken, and nothing gained: if Bob's
        // creature had triggered it too she would be on 20.
        Assert.Equal(19, game.State.GetPlayer(alice).Life);
    }

    // ---- "Another target" (CR 115.1) -----------------------------------------

    [Fact]
    public void Another_target_creature_never_means_the_source()
    {
        var captain = Card(
            "Another Target Test",
            "Whenever ~ attacks, another target creature gets +2/+2 until end of turn.",
            CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(captain);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, captain, Zone.Battlefield);
        var ally = game.Create(alice, TestCards.Creature("Pumped Ally Test", 1, 1), Zone.Battlefield);

        PassTo(game, 3, TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });
        Settle(game);

        // The ally grew and the source did not: "another" is the source leaving itself out, and
        // it has to hold when the ability resolves as well as when its target was chosen.
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(ally)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).Power);
    }

