    // ---- Seeing the top of your own library (CR 401.2) ------------------------

    [Fact]
    public void A_permanent_that_shows_the_top_card_shows_it_only_to_its_controller()
    {
        var lens = Card(
            "Top Lens Test",
            "You may look at the top card of your library any time.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(lens);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.ShowsTopOfLibrary);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, lens, Zone.Battlefield);

        var mine = Views.PlayerViewProjector.Project(game.State, alice, Pool)
            .Players.Single(p => p.PlayerId == alice);

        var top = game.State.GetObject(game.State.GetPlayer(alice).Library[0]).Card.Name;
        Assert.Equal(top, mine.TopOfLibrary?.Name);

        // The half that matters: nobody else sees it. A library is hidden from everyone including
        // its owner (CR 401.2), and this line lifts that for exactly one player.
        var theirs = Views.PlayerViewProjector.Project(game.State, bob, Pool)
            .Players.Single(p => p.PlayerId == alice);

        Assert.Null(theirs.TopOfLibrary);
    }

    [Fact]
    public void Playing_with_the_top_card_revealed_shows_it_to_everyone()
    {
        var oracle = Card(
            "Revealed Top Test",
            "Play with the top card of your library revealed.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(oracle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.RevealsTopOfLibrary);
        Assert.False(compiled.ShowsTopOfLibrary);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, oracle, Zone.Battlefield);

        var top = game.State.GetObject(game.State.GetPlayer(alice).Library[0]).Card.Name;

        // Revealed is revealed: the opponent sees the same card, which is the difference between
        // this line and "you may look at the top card of your library any time".
        foreach (var viewer in new[] { alice, bob })
        {
            var seat = Views.PlayerViewProjector.Project(game.State, viewer, Pool)
                .Players.Single(p => p.PlayerId == alice);

            Assert.Equal(top, seat.TopOfLibrary?.Name);
        }
    }

    [Fact]
    public void Without_such_a_permanent_nobody_sees_the_top_card()
    {
        var (game, alice, _) = InMainPhase();

        var mine = Views.PlayerViewProjector.Project(game.State, alice, Pool)
            .Players.Single(p => p.PlayerId == alice);

        Assert.Null(mine.TopOfLibrary);
    }

