    }

    [Fact]
    public void Life_that_cannot_be_paid_is_refused_before_anything_is_spent()
    {
        var pump = Card(
            "Steep Life Test",
            "Pay 25 life: ~ gets +2/+2 until end of turn.",
            CardType.Creature, 1, 1);

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, pump, Zone.Battlefield);

