    [Fact]
    public void A_free_sacrifice_ability_has_a_cost_of_nothing_but_the_sacrifice()
    {
        // The bug this is here for: the remainder of the cost after lifting out the sacrifice is
        // the empty string, and the "one or more mana symbols" check rejected it — so every
        // "Sacrifice this creature: do something" ability in the game read as unimplemented.
        var altar = Card(
            "Free Sacrifice Test",
            "Sacrifice ~: You gain 2 life.",
            CardType.Creature, 1, 1);

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, altar, Zone.Battlefield);

        game.ActivateAbility(alice, creature, "a");
        Settle(game);

        Assert.Equal(22, game.State.GetPlayer(alice).Life);
        Assert.Empty(game.State.Battlefield);
    }

    [Fact]
    public void Sacrificing_a_creature_as_a_cost_takes_the_one_the_player_names()
    {
        var altar = Card(
            "Altar Test",
            "Sacrifice a creature: You gain 3 life.",
            CardType.Artifact);

        var (game, alice, _) = InMainPhase();
        var artifact = game.Create(alice, altar, Zone.Battlefield);
        var goat = game.Create(alice, TestCards.Creature("Goat", 0, 1), Zone.Battlefield);
        var bear = game.Create(alice, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);

        game.ActivateAbility(alice, artifact, "a", targets: null, costPayment: [goat]);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);

        // The one they named went, and the one they did not is still there.
        Assert.Contains(bear, game.State.Battlefield);
        Assert.DoesNotContain(goat, game.State.Battlefield);
    }

    [Fact]
    public void A_sacrifice_cost_refuses_a_permanent_that_does_not_fit_and_charges_nothing()
    {
        var altar = Card(
            "Artifact Altar Test",
            "Sacrifice an artifact: You gain 3 life.",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        var enchantment = game.Create(alice, altar, Zone.Battlefield);
        var bear = game.Create(alice, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);

        var ex = Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, enchantment, "a", targets: null, costPayment: [bear]));

        Assert.Contains("artifact", ex.Message, StringComparison.OrdinalIgnoreCase);

        // CR 601.2h: the whole cost is checked before any of it is paid.
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
        Assert.Contains(bear, game.State.Battlefield);
    }

    [Fact]
    public void Sacrificing_another_creature_will_not_accept_the_source_itself()
    {
        var cannibal = Card(
            "Another Sacrifice Test",
            "Sacrifice another creature: You gain 3 life.",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, cannibal, Zone.Battlefield);

        var ex = Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(
                alice, creature, "a", targets: null, costPayment: [creature]));

        Assert.Contains("another", ex.Message, StringComparison.OrdinalIgnoreCase);
        Assert.Contains(creature, game.State.Battlefield);
    }

    [Fact]
    public void Discarding_as_a_cost_takes_the_card_the_player_names()
    {
        var looter = Card(
            "Discard Cost Test",
            "Discard a card: You gain 2 life.",
