    [Fact]
    public void An_ability_paid_by_exiling_from_the_graveyard_functions_from_the_graveyard()
    {
        var flashy = Card(
            "Graveyard Cost Test",
            "Exile ~ from your graveyard: You gain 4 life.",
            CardType.Creature, 1, 1);

        var (game, alice, _) = InMainPhase();
