    // ---- Evasion keywords (CR 509.1b) ----------------------------------------

    /// <summary>Why the blocker may not block the attacker, or null if it may.</summary>
    private static string? WhyNoBlock(Game game, ObjectId blocker, ObjectId attacker, Guid defender) =>
        CombatRules.CannotBlock(
            game.State, Pool, game.State.GetObject(blocker), game.State.GetObject(attacker),
            defender);

    [Fact]
    public void Fear_admits_only_artifact_and_black_blockers()
    {
        var scary = Card(
            "Fear Test", "Fear", CardType.Creature, 2, 2, keywords: KeywordAbility.Fear);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, scary, Zone.Battlefield);

        var green = game.Create(bob, Coloured("Green Blocker", ManaColor.Green), Zone.Battlefield);
        var black = game.Create(bob, Coloured("Black Blocker", ManaColor.Black), Zone.Battlefield);
        var golem = game.Create(
            bob,
            Card("Golem Test", string.Empty, CardType.Creature | CardType.Artifact, 2, 2),
            Zone.Battlefield);

        Assert.NotNull(WhyNoBlock(game, green, attacker, bob));
        Assert.Null(WhyNoBlock(game, black, attacker, bob));
        Assert.Null(WhyNoBlock(game, golem, attacker, bob));
    }

    [Fact]
    public void A_creature_that_blocks_only_fliers_cannot_stop_anything_else()
    {
        // The mirror of reach, and untested in both directions: the wall stops a flier and lets
        // everything on the ground walk past it.
        // Reach as well as the restriction: a creature that may block only fliers still needs a
        // way to block one, which is why the printed cards with this line all carry flying or
        // reach. Without it the first rule refuses the block and the restriction is never asked.
        var wall = Card(
            "Cloud Wall Test", "Reach\n~ can block only creatures with flying.",
            CardType.Creature, 0, 4,
            keywords: KeywordAbility.BlocksOnlyFlying | KeywordAbility.Reach);

        var (game, alice, bob) = InMainPhase();
        var blocker = game.Create(bob, wall, Zone.Battlefield);

        var footman = game.Create(alice, TestCards.Creature("Ground Footman Test", 2, 2), Zone.Battlefield);
        var drake = game.Create(
            alice,
            Card("Cloud Drake Test", "Flying", CardType.Creature, 2, 2, keywords: KeywordAbility.Flying),
            Zone.Battlefield);

        Assert.NotNull(WhyNoBlock(game, blocker, footman, bob));
        Assert.Null(WhyNoBlock(game, blocker, drake, bob));
    }

    /// <summary>Every landwalk, against its own land type (CR 702.14).</summary>
    /// <remarks>
    /// `Landwalks` is five near-identical arms and only two of them - swampwalk and islandwalk -
    /// were ever reached by a test. Swapping any of the other three for a keyword nothing has
    /// changed no result, which is the same shape as reach against flying: a list of alternatives
    /// where the tested entry stands in for the rest and nothing checks that it can.
    /// </remarks>
    [Theory]
    [InlineData(KeywordAbility.Swampwalk, "Swamp")]
    [InlineData(KeywordAbility.Forestwalk, "Forest")]
    [InlineData(KeywordAbility.Islandwalk, "Island")]
    [InlineData(KeywordAbility.Mountainwalk, "Mountain")]
    [InlineData(KeywordAbility.Plainswalk, "Plains")]
    public void Each_landwalk_is_unblockable_over_its_own_land(KeywordAbility walk, string landType)
    {
        var walker = Card(
            $"{landType} Walker Test", walk.ToString(), CardType.Creature, 2, 2, keywords: walk);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, walker, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature($"{landType} Blocker Test", 2, 2), Zone.Battlefield);

        // Nothing to walk over yet, so the block is fine.
        Assert.Null(WhyNoBlock(game, blocker, attacker, bob));

        game.Create(bob, TestCards.BasicLand(landType), Zone.Battlefield);

        var refused = WhyNoBlock(game, blocker, attacker, bob);
        Assert.NotNull(refused);
        Assert.Contains("702.14", refused, StringComparison.Ordinal);
    }

    [Fact]
    public void Horsemanship_admits_only_other_horsemen()
    {
        // CR 702.5b: flying's older cousin, and the only evasion keyword the suite had never
        // named once. The engine implements it; nothing asked it anything.
        var rider = Card(
            "Horseman Test", "Horsemanship", CardType.Creature, 2, 2,
            keywords: KeywordAbility.Horsemanship);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, rider, Zone.Battlefield);

        var footman = game.Create(bob, TestCards.Creature("Footman Test", 2, 2), Zone.Battlefield);
        var mounted = game.Create(
            bob,
            Card("Other Horseman Test", "Horsemanship", CardType.Creature, 2, 2,
                keywords: KeywordAbility.Horsemanship),
            Zone.Battlefield);

        Assert.NotNull(WhyNoBlock(game, footman, attacker, bob));
        Assert.Null(WhyNoBlock(game, mounted, attacker, bob));
    }

    [Fact]
    public void Intimidate_admits_artifacts_and_creatures_sharing_a_colour()
    {
        // CR 702.13b: fear by colour. The colour half needs a coloured attacker to mean anything,
        // which is why the keyword needs a card built rather than the plain fixture.
        var sneak = new CardDefinition
        {
            OracleId = "oracle-intimidate-test",
            Name = "Intimidate Test",
            CardTypes = CardType.Creature,
            Power = 2,
            Toughness = 2,
            Colors = [ManaColor.Red],
            ColorIdentity = [ManaColor.Red],
            Keywords = KeywordAbility.Intimidate,
        };

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, sneak, Zone.Battlefield);

        var green = game.Create(bob, Coloured("Intimidate Green Test", ManaColor.Green), Zone.Battlefield);
        var red = game.Create(bob, Coloured("Intimidate Red Test", ManaColor.Red), Zone.Battlefield);
        var golem = game.Create(
            bob,
            Card("Intimidate Golem Test", string.Empty, CardType.Creature | CardType.Artifact, 2, 2),
            Zone.Battlefield);

        Assert.NotNull(WhyNoBlock(game, green, attacker, bob));
        Assert.Null(WhyNoBlock(game, red, attacker, bob));
        Assert.Null(WhyNoBlock(game, golem, attacker, bob));
    }

    [Fact]
    public void Shadow_separates_the_two_halves_of_the_board_in_both_directions()
    {
        var ghost = Card(
            "Shadow Test", "Shadow", CardType.Creature, 2, 2, keywords: KeywordAbility.Shadow);

        var (game, alice, bob) = InMainPhase();
        var shadowed = game.Create(alice, ghost, Zone.Battlefield);
        var ordinary = game.Create(bob, TestCards.Creature("Ordinary", 2, 2), Zone.Battlefield);
        var otherGhost = game.Create(
            bob,
            Card("Shadow Blocker Test", "Shadow", CardType.Creature, 2, 2,
                keywords: KeywordAbility.Shadow),
            Zone.Battlefield);

        // A creature without shadow cannot block one with it...
        Assert.NotNull(WhyNoBlock(game, ordinary, shadowed, bob));
        Assert.Null(WhyNoBlock(game, otherGhost, shadowed, bob));

        // ...and a creature with shadow cannot block one without it, which is what makes shadow
        // different from every other evasion keyword.
        var mundane = game.Create(alice, TestCards.Creature("Mundane", 2, 2), Zone.Battlefield);
        Assert.NotNull(WhyNoBlock(game, otherGhost, mundane, bob));
    }

    [Fact]
    public void Skulk_reads_power_as_it_stands_and_not_as_printed()
    {
        var sneak = Card(
            "Skulk Test", "Skulk", CardType.Creature, 2, 2, keywords: KeywordAbility.Skulk);

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, sneak, Zone.Battlefield);
        var small = game.Create(bob, TestCards.Creature("Small", 1, 1), Zone.Battlefield);
        var big = game.Create(bob, TestCards.Creature("Big", 4, 4), Zone.Battlefield);

        Assert.Null(WhyNoBlock(game, small, attacker, bob));
        Assert.NotNull(WhyNoBlock(game, big, attacker, bob));

        // A lord raising the small blocker's power takes the block away, because skulk compares
        // current power (CR 702.17b) rather than what is printed.
        game.Create(
            bob,
            Card("Skulk Lord Test", "Other creatures you control get +2/+2.", CardType.Enchantment),
            Zone.Battlefield);

        Assert.NotNull(WhyNoBlock(game, small, attacker, bob));
    }

    [Fact]
    public void Flashback_casts_it_from_the_graveyard_and_exiles_it_afterwards()
    {
        var bolt = new CardDefinition
        {
            OracleId = "oracle-flashback-test",
            Name = "Flashback Test",
            OracleText = "You gain 3 life.\nFlashback {1}",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{4}",
        };

        var (game, alice, _) = InMainPhase();
        var card = game.Create(alice, bolt, Zone.Graveyard);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        // Cast from the graveyard for {1} rather than from hand for {4}.
        game.CastSpell(alice, card);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);

        // CR 702.34a: exiled instead of going back to the graveyard, so it cannot be cast again.
        Assert.Single(game.State.Exile);
        Assert.Empty(game.State.GetPlayer(alice).Graveyard);
    }

    [Fact]
    public void A_card_without_flashback_still_cannot_be_cast_from_the_graveyard()
    {
        var plain = new CardDefinition
        {
            OracleId = "oracle-no-flashback-test",
            Name = "No Flashback Test",
            OracleText = "You gain 3 life.",
            CardTypes = CardType.Sorcery,
            ManaCostRaw = "{1}",
        };

        var (game, alice, _) = InMainPhase();
        var card = game.Create(alice, plain, Zone.Graveyard);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        var ex = Assert.Throws<InvalidOperationException>(() => game.CastSpell(alice, card));
        Assert.Contains("from hand", ex.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void Unearth_brings_it_back_hasty_and_takes_it_away_at_end_of_turn()
    {
        var ghoul = Card(
            "Unearth Test", "Unearth {1}", CardType.Creature, 3, 3);

        var (game, alice, _) = InMainPhase();
        var card = game.Create(alice, ghoul, Zone.Graveyard);
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, forest, "mana");

        game.ActivateAbility(alice, card, "unearth");
        Settle(game);

        var back = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Unearth Test");

        // CR 702.83a gives it haste, so it can attack the turn it returns.
        Assert.True(Characteristics.Of(game.State, Pool, back).Has(KeywordAbility.Haste));

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.Cleanup);

        // ...and exiles it at the beginning of the next end step, not the graveyard.
        Assert.Single(game.State.Exile);
        Assert.DoesNotContain(back.Id, game.State.Battlefield);
    }

    // ---- Convoke and improvise (CR 702.51a, 702.56a) -------------------------

    /// <summary>A card with a printed mana cost, so a cost reduction has something to reduce.</summary>
    private static CardDefinition Priced(
        string name, string manaCost, string oracleText, CardType types = CardType.Sorcery) => new()
        {
            OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
            Name = name,
            OracleText = oracleText,
            CardTypes = types,
            ManaCostRaw = manaCost,
        };

    [Fact]
    public void Convoking_creatures_pay_part_of_the_cost_and_end_up_tapped()
    {
        var spell = Priced("Convoke Test", "{3}", "Convoke\nYou gain 5 life.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, spell);

        var helpers = Enumerable.Range(0, 3)
            .Select(i => game.Create(alice, TestCards.Creature($"Helper {i}", 1, 1), Zone.Battlefield))
            .ToList();

        // No mana at all: the whole {3} is paid by tapping.
        game.CastSpell(alice, card, targets: null, variableValue: 0, tapToPay: helpers);
        Settle(game);

        Assert.Equal(25, game.State.GetPlayer(alice).Life);
        Assert.All(helpers, id => Assert.True(game.State.GetObject(id).Permanent!.IsTapped));
    }

    [Fact]
    public void A_convoking_creature_pays_its_own_colour_where_the_cost_asks_for_one()
    {
        var spell = Priced("Coloured Convoke Test", "{G}{G}", "Convoke\nYou gain 3 life.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, spell);

        var green = game.Create(alice, Coloured("Green Helper", ManaColor.Green), Zone.Battlefield);
        var alsoGreen = game.Create(alice, Coloured("Second Helper", ManaColor.Green), Zone.Battlefield);

        game.CastSpell(alice, card, targets: null, variableValue: 0, tapToPay: [green, alsoGreen]);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void A_creature_of_the_wrong_colour_cannot_pay_a_coloured_symbol()
    {
        // CR 702.51a: a convoking creature pays {1} or one mana of *its own* colour. A red
        // creature does not pay a {G}, and the cast is refused rather than quietly succeeding.
        var spell = Priced("Wrong Colour Test", "{G}{G}", "Convoke\nYou gain 3 life.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, spell);

        var red = game.Create(alice, Coloured("Red Helper", ManaColor.Red), Zone.Battlefield);
        var alsoRed = game.Create(alice, Coloured("Second Red", ManaColor.Red), Zone.Battlefield);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, variableValue: 0,
                tapToPay: [red, alsoRed]));

        // Nothing was spent: CR 601.2h pays the cost as one act or not at all.
        Assert.False(game.State.GetObject(red).Permanent!.IsTapped);
    }

    [Fact]
    public void Improvise_taps_artifacts_and_never_pays_a_coloured_symbol()
    {
        var spell = Priced("Improvise Test", "{2}{U}", "Improvise\nYou gain 4 life.");

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, spell);

        var artifacts = Enumerable.Range(0, 2)
            .Select(i => game.Create(
                alice,
                Card($"Trinket {i}", string.Empty, CardType.Artifact),
                Zone.Battlefield))
            .ToList();

        var island = game.Create(alice, TestCards.BasicLand("Island"), Zone.Battlefield);
        game.ActivateAbility(alice, island, "mana");

        // The two artifacts cover the {2}; the {U} still has to come from the pool.
        game.CastSpell(alice, card, targets: null, variableValue: 0, tapToPay: artifacts);
        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    // ---- Crew, and tapping as a cost (CR 702.122a, 118.12) -------------------

    [Fact]
    public void Crewing_taps_enough_power_and_turns_the_vehicle_into_a_creature()
    {
        var vehicle = Card(
            "Vehicle Test", "Crew 3", CardType.Artifact, 4, 4, subtypes: "Vehicle");

        var (game, alice, _) = InMainPhase();
        var truck = game.Create(alice, vehicle, Zone.Battlefield);
        var ox = game.Create(alice, TestCards.Creature("Ox", 2, 2), Zone.Battlefield);
        var goat = game.Create(alice, TestCards.Creature("Goat", 1, 1), Zone.Battlefield);

        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(truck)).IsCreature);

        game.ActivateAbility(alice, truck, "crew", targets: null, costPayment: [ox, goat]);
        Settle(game);

        var crewed = Characteristics.Of(game.State, Pool, game.State.GetObject(truck));
        Assert.True(crewed.IsCreature);

        // It keeps every type it already had — a crewed Vehicle is an artifact creature.
        Assert.True(crewed.CardTypes.HasFlag(CardType.Artifact));

        // The crew are tapped, not spent.
        Assert.True(game.State.GetObject(ox).Permanent!.IsTapped);
        Assert.Contains(ox, game.State.Battlefield);
    }

    [Fact]
    public void Crew_refuses_a_crew_that_does_not_add_up()
    {
        var vehicle = Card(
            "Heavy Vehicle Test", "Crew 5", CardType.Artifact, 6, 6, subtypes: "Vehicle");

        var (game, alice, _) = InMainPhase();
        var truck = game.Create(alice, vehicle, Zone.Battlefield);
        var goat = game.Create(alice, TestCards.Creature("Goat", 1, 1), Zone.Battlefield);

        var ex = Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, truck, "crew", targets: null, costPayment: [goat]));

        Assert.Contains("702.122a", ex.Message, StringComparison.Ordinal);

        // CR 601.2h: nothing was spent, so the goat is still upright.
        Assert.False(game.State.GetObject(goat).Permanent!.IsTapped);
    }

    [Fact]
    public void A_creature_that_arrived_this_turn_can_still_crew()
    {
        // CR 302.6 is about a permanent's own {T} ability, not about being tapped to pay for
        // someone else's — so summoning sickness does not stop a fresh creature crewing.
        var vehicle = Card(
            "Fresh Crew Test", "Crew 2", CardType.Artifact, 3, 3, subtypes: "Vehicle");

        var (game, alice, _) = InMainPhase();
        var truck = game.Create(alice, vehicle, Zone.Battlefield);
        var fresh = game.Create(alice, TestCards.Creature("Fresh", 2, 2), Zone.Battlefield);

        Assert.True(game.State.GetObject(fresh).Permanent!.HasSummoningSickness);

        game.ActivateAbility(alice, truck, "crew", targets: null, costPayment: [fresh]);
        Settle(game);

        Assert.True(Characteristics.Of(game.State, Pool, game.State.GetObject(truck)).IsCreature);
    }

    // ---- Delayed triggered abilities (CR 603.7) ------------------------------

    [Fact]
    public void A_delayed_sacrifice_waits_for_the_end_step_and_then_happens_once()
    {
        var hasty = Card(
            "Delayed Sacrifice Test",
            "When ~ enters, sacrifice it at the beginning of the next end step.",
            CardType.Creature, 4, 4);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, hasty);

        game.CastSpell(alice, card, []);
        Settle(game);

        var creature = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Delayed Sacrifice Test");

        // Still here for the rest of the turn — that is the whole point of the delay.
        Assert.Single(game.State.Delayed);
        Assert.Contains(creature.Id, game.State.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.Cleanup);

        Assert.DoesNotContain(creature.Id, game.State.Battlefield);
        Assert.Empty(game.State.Delayed);
    }

    [Fact]
    public void A_delayed_ability_whose_subject_has_gone_does_nothing_at_all()
    {
        // CR 603.7c: if the object is no longer in the zone the ability expected, the ability
        // does nothing — including to the new object that took its place.
        var hasty = Card(
            "Vanishing Test",
            "When ~ enters, exile it at the beginning of the next end step.",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, hasty);

        game.CastSpell(alice, card, []);
        Settle(game);

        var creature = game.State.Battlefield
            .Select(game.State.GetObject)
            .Single(o => o.Card.Name == "Vanishing Test");

        game.MarkDamage(creature.Id, 2);
        Settle(game);
        Assert.Single(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Vanishing Test");

        TestCards.PassUntil(game, () => game.State.CurrentStep >= TurnStep.Cleanup);

        // It died before the end step, so it is in the graveyard and not in exile.
        Assert.Empty(game.State.Exile);
        Assert.Empty(game.State.Delayed);
    }

    // ---- Abilities granted by another permanent (CR 613.1f) ------------------

    [Fact]
    public void An_aura_can_grant_a_whole_ability_and_the_land_can_use_it()
    {
        // Layer 6 adds abilities, not only keywords. Asking the *card* what it can do reports no
        // such ability and refuses the activation, which is why the engine and the board both ask
        // the computed characteristics instead.
        var aura = Card(
            "Granting Aura Test",
            "Enchant land\nEnchanted land has \"{T}: Add {B}\".",
            CardType.Enchantment, subtypes: "Aura");

        var (game, alice, _) = InMainPhase();
        var forest = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, aura);

        game.CastSpell(alice, card, [Target.ToPermanent(forest)]);
        Settle(game);

        var granted = Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(forest))
            .Single(a => a.Id.StartsWith("granted:", StringComparison.Ordinal));

        game.ActivateAbility(alice, forest, granted.Id);

        Assert.Equal(1, game.State.GetPlayer(alice).ManaPool.Colored
            .GetValueOrDefault(ManaColor.Black));

        // The land keeps its own ability too — two abilities, and the player says which.
        Assert.Equal(
            2, Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(forest)).Count);
    }

    [Fact]
    public void A_granted_ability_goes_away_with_the_permanent_that_granted_it()
    {
        var lord = Card(
            "Granting Lord Test",
            "Other creatures you control have \"{T}: You gain 1 life\".",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();
        var granter = game.Create(alice, lord, Zone.Battlefield);
        var bear = game.Create(alice, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.Single(Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(bear)));

        // The bug the layer system exists to prevent, in its ability-granting form.
        game.MarkDamage(granter, 2);
        Settle(game);

        Assert.Empty(Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(bear)));
    }

    // ---- Static abilities over a group (CR 613) ------------------------------

    [Fact]
    public void A_lord_pumps_your_creatures_and_stops_when_it_leaves()
    {
        var lord = Card(
            "Lord Test",
            "Other creatures you control get +1/+1.",
            CardType.Creature, 2, 2);

        var (game, alice, bob) = InMainPhase();
        var anthem = game.Create(alice, lord, Zone.Battlefield);
        var mine = game.Create(alice, TestCards.Creature("Mine", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Theirs", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(mine)).Power);

        // "Other" excludes the lord itself, and "you control" excludes the opponent's.
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(anthem)).Power);
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(theirs)).Power);

        // The bug the layer system exists to prevent: the lord dies and the buff stays on.
        game.MarkDamage(anthem, 2);
        Settle(game);

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(mine)).Power);
    }

    [Fact]
    public void A_tribal_lord_only_pumps_its_tribe()
    {
        var lord = Card(
            "Tribal Test",
            "Other Goblin creatures you control get +1/+1 and have haste.",
            CardType.Creature, 2, 2, subtypes: "Goblin");

        var (game, alice, _) = InMainPhase();
        game.Create(alice, lord, Zone.Battlefield);

        var goblin = game.Create(
            alice,
            Card("Goblin Test", string.Empty, CardType.Creature, 1, 1, subtypes: "Goblin"),
            Zone.Battlefield);

        var bear = game.Create(alice, TestCards.Creature("Bear", 2, 2), Zone.Battlefield);
        Settle(game);

        var pumped = Characteristics.Of(game.State, Pool, game.State.GetObject(goblin));
        Assert.Equal(2, pumped.Power);
        Assert.True(pumped.Has(KeywordAbility.Haste));

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }

    [Fact]
    public void A_static_aimed_at_opponents_leaves_your_own_creatures_alone()
    {
        var curse = Card(
            "Curse Test",
            "Creatures your opponents control get -1/-1.",
            CardType.Enchantment);

        var (game, alice, bob) = InMainPhase();
        game.Create(alice, curse, Zone.Battlefield);
        var mine = game.Create(alice, TestCards.Creature("Mine", 2, 2), Zone.Battlefield);
        var theirs = game.Create(bob, TestCards.Creature("Theirs", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(mine)).Power);
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(theirs)).Power);
    }

    // ---- Effects naming a group of players rather than a target --------------

    [Fact]
    public void Each_opponent_loses_life_and_you_gain_it_is_two_effects_in_one_sentence()
    {
        var drain = Card("Drain Test", "Each opponent loses 2 life and you gain 2 life.");
        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, drain);

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);
        Assert.Equal(22, game.State.GetPlayer(alice).Life);
    }

    [Fact]
    public void Damage_to_each_opponent_is_damage_and_not_life_loss()
    {
        var pyroclasm = Card("Sweep Test", "~ deals 3 damage to each opponent.");
        var (game, alice, bob) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, pyroclasm);

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);

        // It is damage, so it went through the damage event and not a bare life change.
        Assert.Contains(game.Log, e => e is PlayerDamaged { IsCombat: false, Amount: 3 });
    }

    [Fact]
    public void Milling_stops_at_the_end_of_the_library_rather_than_losing_the_game()
    {
        var mill = Card("Mill Test", "Each opponent mills three cards.");
        var (game, alice, bob) = InMainPhase();
        var before = game.State.GetPlayer(bob).Graveyard.Count;
        var card = TestCards.PutInHand(game, alice, mill);

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(before + 3, game.State.GetPlayer(bob).Graveyard.Count);
        Assert.False(game.State.GetPlayer(bob).HasLost);
    }

    [Fact]
    public void Exiling_the_top_card_puts_it_in_exile_and_not_the_graveyard()
    {
        var exile = Card("Exile Top Test", "You exile the top card of your library.");
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, exile);

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Single(game.State.Exile);
    }

    [Fact]
    public void Each_opponent_discarding_asks_that_opponent_which_card()
    {
        var duress = Card("Discard Test", "Each opponent discards a card.");
        var (game, alice, bob) = InMainPhase();
        var handBefore = game.State.GetPlayer(bob).Hand.Count;
        var card = TestCards.PutInHand(game, alice, duress);

        game.CastSpell(alice, card, []);

        // The game stops and asks *them*, because which card to discard is their choice
        // (CR 701.9a) — not the caster's, and not the engine's.
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.DiscardToEffect });
        var choice = game.State.Choice!;
        Assert.Equal(bob, choice.PlayerId);

        game.Choose(bob, [choice.Options[0].Id]);
        Settle(game);

        Assert.Equal(handBefore - 1, game.State.GetPlayer(bob).Hand.Count);
        Assert.Single(game.State.GetPlayer(bob).Graveyard);
    }

    [Fact]
    public void Draw_then_discard_is_read_as_the_two_instructions_it_is()
    {
        var looter = Card("Loot Test", "Draw a card, then discard a card.");
        var (game, alice, _) = InMainPhase();
        var handBefore = game.State.GetPlayer(alice).Hand.Count;
        var card = TestCards.PutInHand(game, alice, looter);

        game.CastSpell(alice, card, []);
        TestCards.PassUntil(game, () => game.State.Choice is { Kind: ChoiceKind.DiscardToEffect });

        var choice = game.State.Choice!;
        game.Choose(alice, [choice.Options[0].Id]);
        Settle(game);

        // Held N, was dealt the looter (N+1), cast it (N), drew (N+1), discarded (N).
        Assert.Equal(handBefore, game.State.GetPlayer(alice).Hand.Count);
        Assert.Equal(2, game.State.GetPlayer(alice).Graveyard.Count);
    }

    [Fact]
    public void Returning_the_source_from_the_graveyard_is_read_from_the_graveyard()
    {
        var oracle = Card(
            "Recursion Test",
            "{2}: Return ~ from your graveyard to your hand.",
            CardType.Creature, 2, 2);

        var (game, alice, _) = InMainPhase();

        // Compiled from the graveyard, which is where the ability functions — so the card has to
        // be there and the ability has to be reachable from there.
        var compiled = CardCompiler.Compile(oracle);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Single(compiled.Activated);
        Assert.NotEqual(alice, Guid.Empty);
    }

    [Fact]
    public void Being_dealt_damage_triggers_on_the_source_itself()
    {
        var thorn = Card(
            "Damage Watch Test",
            "Whenever ~ is dealt damage, you gain 3 life.",
            CardType.Creature, 4, 4);

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, thorn, Zone.Battlefield);

        game.MarkDamage(creature, 1);
        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    // ---- Surge and spectacle: an alternative cost with a condition (CR 601.2f) ----

    private static CardDefinition Blessing(string name, string cost, string keywordLine, int life) =>
        new()
        {
            OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
            Name = name,
            OracleText = keywordLine + "\nYou gain " + life + " life.",
            CardTypes = CardType.Instant,
            ManaCostRaw = cost,
        };

    /// <summary>
    /// Two Mountains against a printed {4}{R}: the cast can only work if surge replaced the
    /// cost rather than discounting it.
    /// </summary>
    [Fact]
    public void A_surge_spell_costs_its_surge_cost_once_another_spell_has_been_cast()
    {
        var first = Blessing("Surge Opener Test", "{R}", "Flash", 1);
        var surged = Blessing("Surge Blessing Test", "{4}{R}", "Surge {R}", 3);

        var compiled = CardCompiler.Compile(surged);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        foreach (var name in new[] { "Mountain", "Mountain" })
        {
            var land = game.Create(alice, TestCards.BasicLand(name), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        // Cast in response to the first spell rather than after it resolves. Surge asks whether
        // another spell has been cast, not whether one has resolved, and casting into the same
        // stack is both the truer reading and the one that cannot accidentally end the step.
        game.CastSpell(alice, TestCards.PutInHand(game, alice, first), targets: null);
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, surged), targets: null, alternativeCost: true);

        Settle(game);

        Assert.Equal(24, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// The same card, reached for first: the offer is not on the table and saying so is the
    /// whole point of the condition.
    /// </summary>
    [Fact]
    public void A_surge_spell_is_refused_when_it_is_the_first_spell_of_the_turn()
    {
        var surged = Blessing("Surge Refusal Test", "{4}{R}", "Surge {R}", 3);
        var (game, alice, _) = InMainPhase();

        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var card = TestCards.PutInHand(game, alice, surged);

        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, alternativeCost: true));

        Assert.Contains("surge", refused.Message, StringComparison.Ordinal);
        Assert.Equal(20, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// Spectacle after combat damage, which is the case the flag it reads used to miss.
    /// </summary>
    [Fact]
    public void Spectacle_is_available_once_combat_damage_has_reached_an_opponent()
    {
        var shown = Blessing("Spectacle Blessing Test", "{4}{B}", "Spectacle {B}", 3);

        var compiled = CardCompiler.Compile(shown);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var bear = game.Create(
            alice,
            new CardDefinition
            {
                OracleId = "oracle-spectacle-bear",
                Name = "Spectacle Bear Test",
                CardTypes = CardType.Creature,
                Power = 2,
                Toughness = 2,

                // Haste rather than an aged creature, so the test can attack on the turn it
                // sets up. Summoning sickness is not what is under test here.
                Keywords = KeywordAbility.Haste,
            },
            Zone.Battlefield);

        var land = game.Create(alice, TestCards.BasicLand("Swamp"), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [bear] = AttackTarget.Player(bob) });

        // On to the postcombat main phase rather than settling in end of combat: settling with
        // an empty stack passes the step out from under the caster, and the cast below needs
        // Alice to still hold priority.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.PostcombatMain);

        Assert.Equal(18, game.State.GetPlayer(bob).Life);

        // The fact the whole condition rests on, asserted on its own so that a regression here
        // is not mistaken for a broken cost. Combat damage is life lost (CR 120.3c), and this
        // flag did not say so until the rule above was fixed.
        Assert.True(game.State.GetPlayer(bob).LostLifeThisTurn);

        game.ActivateAbility(alice, land, "mana");
        game.CastSpell(
            alice, TestCards.PutInHand(game, alice, shown), targets: null, alternativeCost: true);

        Settle(game);

        Assert.Equal(23, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// A card with no such offer at all, which is a different mistake from one whose condition
    /// is false and comes back saying so.
    /// </summary>
    [Fact]
    public void A_card_without_a_conditional_cost_refuses_the_offer()
    {
        var plain = Blessing("Plain Blessing Test", "{R}", "Flash", 1);
        var (game, alice, _) = InMainPhase();

        var land = game.Create(alice, TestCards.BasicLand("Mountain"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        var card = TestCards.PutInHand(game, alice, plain);

        var refused = Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, targets: null, alternativeCost: true));

        Assert.Contains("no alternative cost", refused.Message, StringComparison.Ordinal);
    }

    // ---- Training (CR 702.149) and annihilator (CR 702.86) -------------------

    private static CardDefinition Fighter(string name, string text, int power) => new()
    {
        OracleId = "oracle-" + name.ToLowerInvariant().Replace(' ', '-'),
        Name = name,
        OracleText = text,
        CardTypes = CardType.Creature,
        ManaCostRaw = "{2}",
        Power = power,
        Toughness = 3,
        Keywords = KeywordAbility.Haste,
    };

    /// <summary>
    /// Greater power, not merely another attacker: the same board with a smaller partner has to
    /// leave the counter off, or the test passes for a card that reads "whenever ~ attacks".
    /// </summary>
    [Theory]
    [InlineData(4, 1)]
    [InlineData(2, 0)]
    public void Training_pays_only_when_a_bigger_creature_attacks_alongside(
        int partnerPower, int expected)
    {
        var student = Fighter("Training Student Test", "Training", 2);
        var partner = Fighter("Training Partner Test", string.Empty, partnerPower);

        var compiled = CardCompiler.Compile(student);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var trained = game.Create(alice, student, Zone.Battlefield);
        var beside = game.Create(alice, partner, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [trained] = AttackTarget.Player(bob),
                [beside] = AttackTarget.Player(bob),
            });

        Settle(game);

        var counters = game.State.GetObject(trained).Permanent?.Counters;
        Assert.Equal(
            expected,
            counters?.GetValueOrDefault(CounterKinds.PlusOnePlusOne) ?? 0);
    }

    /// <summary>
    /// Two sacrifices, and the defender chooses both. Asserting only the count would pass for a
    /// card that made the attacker choose, which is a different and much stronger card.
    /// </summary>
    [Fact]
    public void Annihilator_makes_the_defending_player_sacrifice_that_many_permanents()
    {
        var eldrazi = Fighter("Annihilator Horror Test", "Annihilator 2", 4);

        var compiled = CardCompiler.Compile(eldrazi);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var horror = game.Create(alice, eldrazi, Zone.Battlefield);

        // Three, so that a sacrifice of "everything" and a sacrifice of two look different.
        foreach (var name in new[] { "Island", "Island", "Island" })
            game.Create(bob, TestCards.BasicLand(name), Zone.Battlefield);

        var mine = game.State.Battlefield.Count(
            id => game.State.GetObject(id).ControllerId == alice);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [horror] = AttackTarget.Player(bob) });

        Settle(game);

        Assert.Equal(
            1,
            game.State.Battlefield.Count(id => game.State.GetObject(id).ControllerId == bob));

        // Nothing of Alice's went anywhere: the question was addressed to Bob, and a scope that
        // fell back to the controller would have taken the attacker's board instead.
        Assert.Equal(
            mine,
            game.State.Battlefield.Count(id => game.State.GetObject(id).ControllerId == alice));
    }

    /// <summary>
    /// Outlast is the expansion and nothing else, so the test is that the expanded ability is
    /// the one the engine ends up playing: it taps, it costs, and it will not run at instant
    /// speed (CR 702.104a).
    /// </summary>
    [Fact]
    public void Outlast_taps_for_a_counter_and_only_at_sorcery_speed()
    {
        var elder = Fighter("Outlast Elder Test", "Outlast {1}", 2);

        var compiled = CardCompiler.Compile(elder);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var ability = Assert.Single(compiled.Activated);
        Assert.Equal(ActivationTiming.SorceryOnly, ability.Timing);

        var (game, alice, _) = InMainPhase();

        var creature = game.Create(alice, elder, Zone.Battlefield);
        var land = game.Create(alice, TestCards.BasicLand("Forest"), Zone.Battlefield);
        game.ActivateAbility(alice, land, "mana");

        game.ActivateAbility(alice, creature, ability.Id);
        Settle(game);

        var permanent = game.State.GetObject(creature).Permanent;

        Assert.Equal(1, permanent?.Counters.GetValueOrDefault(CounterKinds.PlusOnePlusOne) ?? 0);

        // The tap is part of the cost, not a side effect, so it is paid whether or not anything
        // else about the activation worked.
        Assert.True(permanent?.IsTapped);
    }

    /// <summary>
    /// The tokens have to arrive <em>in the combat</em>, not merely on the board: a 1/1 created
    /// beside the attack deals no damage and never gets sacrificed.
    /// </summary>
    [Fact]
    public void Mobilize_brings_warriors_in_attacking_and_takes_them_away_at_end_of_turn()
    {
        var captain = Fighter("Mobilize Captain Test", "Mobilize 2", 1);

        var compiled = CardCompiler.Compile(captain);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var leader = game.Create(alice, captain, Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [leader] = AttackTarget.Player(bob) });

        Settle(game);

        var warriors = game.State.Battlefield
            .Where(id => game.State.GetObject(id).Card.Name == "Warrior")
            .ToList();

        Assert.Equal(2, warriors.Count);

        // In the combat and pointed at the same player, which is the whole difference between
        // this and two tokens created beside the attack.
        foreach (var warrior in warriors)
        {
            Assert.True(game.State.GetObject(warrior).Permanent?.IsTapped);
            Assert.True(game.State.Combat.Attackers.ContainsKey(warrior));
            Assert.Equal(bob, game.State.Combat.Attackers[warrior].DefendingPlayer);
        }

        // Three damage rather than one: the captain's 1 and a Warrior each.
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Assert.Equal(17, game.State.GetPlayer(bob).Life);

        // Gone by the time the turn is over, and gone because they were sacrificed rather than
        // because a token stopped existing on its own.
        TestCards.PassUntil(game, () => game.State.TurnNumber > 1);

        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Warrior");
    }

    /// <summary>
    /// One opponent means +1/+1, and it has to come from the count rather than from a flat
    /// bonus - so the same creature attacking nobody gets nothing.
    /// </summary>
    [Fact]
    public void Melee_counts_the_opponents_attacked_rather_than_paying_a_flat_bonus()
    {
        var raider = Fighter("Melee Raider Test", "Melee", 2);

        var compiled = CardCompiler.Compile(raider);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var attacker = game.Create(alice, raider, Zone.Battlefield);

        // Before any attack the effect exists nowhere and the creature is its printed size.
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).Power);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        Settle(game);

        // +1/+1 for the one opponent attacked. In a two-player game that is the whole range the
        // count has, which is exactly why the assertion below matters more than this one.
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).Power);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);

        Assert.Equal(17, game.State.GetPlayer(bob).Life);
    }

    // ---- Blitz (CR 702.152) -------------------------------------------------

    private static CardDefinition Blitzer() => new()
    {
        OracleId = "oracle-blitz-runner-test",
        Name = "Blitz Runner Test",
        OracleText = "Blitz {1}{R}",
        CardTypes = CardType.Creature,
        ManaCostRaw = "{4}{R}",
        Power = 2,
        Toughness = 2,
    };

    /// <summary>
    /// Blitz is three abilities in one word, and this walks all three: the cost that replaces the
    /// printed one, the haste that lets it attack at once, and the card drawn when the clock runs
    /// out and sacrifices it.
    /// </summary>
    [Fact]
    public void A_blitzed_creature_attacks_at_once_then_dies_for_a_card()
    {
        var runner = Blitzer();

        var compiled = CardCompiler.Compile(runner);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        // Two lands against a printed {4}{R}: the cast only works if blitz replaced the cost.
        foreach (var name in new[] { "Mountain", "Forest" })
        {
            var land = game.Create(alice, TestCards.BasicLand(name), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        var card = TestCards.PutInHand(game, alice, runner);
        game.CastSpell(alice, card, targets: null, blitzed: true);
        Settle(game);

        var runnerId = game.State.Battlefield.Single(
            id => game.State.GetObject(id).Card.Name == "Blitz Runner Test");

        // Haste, proved the only way it can be: it attacks the turn it arrived (CR 302.6).
        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [runnerId] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Assert.Equal(18, game.State.GetPlayer(bob).Life);

        // Counted off the library rather than the hand. The sacrifice happens in the end step
        // and cleanup follows it immediately, so a hand at seven cards draws one and discards one
        // and finishes the turn exactly where it started - which is a passing assertion for a
        // trigger that never fired. The library only goes one way.
        var left = game.State.GetPlayer(alice).Library.Count;

        // The end step takes it, and the death trigger pays for it.
        TestCards.PassUntil(game, () => game.State.TurnNumber > 1);

        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Blitz Runner Test");

        Assert.Equal(left - 1, game.State.GetPlayer(alice).Library.Count);
    }

    /// <summary>
    /// The same card cast for what it says on it: the word is still printed, and none of the
    /// consequences apply. A trigger that fired here would draw a card off every copy that ever
    /// died, blitzed or not.
    /// </summary>
    [Fact]
    public void A_card_with_blitz_cast_for_its_printed_cost_draws_nothing_when_it_dies()
    {
        var runner = Blitzer();
        var (game, alice, _) = InMainPhase();

        var creature = game.Create(alice, runner, Zone.Battlefield);
        var left = game.State.GetPlayer(alice).Library.Count;

        // Killed by damage rather than by a helper, so it is put into the graveyard from the
        // battlefield the same way the blitzed one was (CR 704.5g).
        game.MarkDamage(creature, 2);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Blitz Runner Test");

        Assert.Equal(left, game.State.GetPlayer(alice).Library.Count);
    }

    // ---- The guard that used to drop costs ----------------------------------

    /// <summary>
    /// Every field of a spell definition has to count as "this card says something about how it
    /// is cast". The check that decides that used to be a hand-written list, and a field left off
    /// it was silently thrown away - which is how blitz was written, read, assigned and lost.
    /// </summary>
    /// <remarks>
    /// Driven off the type rather than off a list of names, so a field added tomorrow is covered
    /// today. Only the property kinds a value can be invented for are exercised; the rest are
    /// counted so that a shrinking pool of checks is visible rather than silent.
    /// </remarks>
    [Fact]
    public void No_field_of_a_spell_definition_can_be_set_and_still_count_as_nothing()
    {
        Assert.True(SpellDefinition.CarriesNothing(new SpellDefinition()));

        var checkedFields = 0;

        foreach (var field in typeof(SpellDefinition).GetProperties())
        {
            if (!field.CanWrite)
                continue;

            object? value = field.PropertyType switch
            {
                var t when t == typeof(bool) => true,
                var t when t == typeof(int) => 7,
                var t when t == typeof(int?) => 7,
                var t when t == typeof(string) => "x",
                var t when t == typeof(Mana.ManaCostSpec) => Mana.ManaCostSpec.Parse("{1}"),
                _ => null,
            };

            if (value is null)
                continue;

            var carrying = new SpellDefinition();
            field.SetValue(carrying, value);
            checkedFields++;

            Assert.False(
                SpellDefinition.CarriesNothing(carrying),
                $"{field.Name} was set and the definition still counted as empty.");
        }

        // Well below the field count, and deliberately: this is a floor that notices the checks
        // being removed, not a count of the record.
        Assert.True(checkedFields >= 25, $"only {checkedFields} fields were exercised");
    }

    /// <summary>
    /// Undaunted with one opponent is {1} off, and the test proves it by giving Alice exactly
    /// the reduced cost and nothing more (CR 702.125a).
    /// </summary>
    [Fact]
    public void Undaunted_takes_one_generic_off_for_each_opponent()
    {
        var soldier = new CardDefinition
        {
            OracleId = "oracle-undaunted-soldier-test",
            Name = "Undaunted Soldier Test",
            OracleText = "Undaunted",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{3}{W}",
            Power = 2,
            Toughness = 2,
        };

        var compiled = CardCompiler.Compile(soldier);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        // Three mana against a printed {3}{W}: enough only if the one opponent took {1} off.
        foreach (var name in new[] { "Plains", "Plains", "Plains" })
        {
            var land = game.Create(alice, TestCards.BasicLand(name), Zone.Battlefield);
            game.ActivateAbility(alice, land, "mana");
        }

        var card = TestCards.PutInHand(game, alice, soldier);
        game.CastSpell(alice, card, targets: null);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Undaunted Soldier Test");

        // The coloured half is untouched, which is the rule rather than a detail: a reduction
        // never removes a coloured requirement (CR 601.2f). Three Plains paid {2}{W}.
        Assert.True(game.State.GetPlayer(alice).ManaPool.IsEmpty);
    }

    // ---- Partner abilities (CR 702.124) -------------------------------------

    /// <summary>
    /// The inert partner abilities are read and written down, because they genuinely do nothing
    /// during a game - they "function before the game begins" (CR 702.124a).
    /// </summary>
    [Theory]
    [InlineData("Partner")]
    [InlineData("Partner—Friends forever")]
    [InlineData("Choose a Background")]
    [InlineData("Doctor's companion")]
    public void A_deck_construction_partner_ability_is_recorded_and_does_nothing(string printed)
    {
        var legend = new CardDefinition
        {
            OracleId = "oracle-partner-" + printed.GetHashCode(StringComparison.Ordinal),
            Name = "Partner Legend Test",
            OracleText = printed,
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}{W}",
            Power = 2,
            Toughness = 2,
        };

        var compiled = CardCompiler.Compile(legend);

        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.Equal(printed, compiled.PartnerRule);

        // Nothing to play. A partner ability that produced a trigger or a static would be an
        // ability the card does not have.
        Assert.Empty(compiled.Triggers);
        Assert.Empty(compiled.Statics);
        Assert.Empty(compiled.Activated);
    }

    /// <summary>
    /// "Partner with [name]" is two abilities, and the second one searches a library
    /// (CR 702.124j). Sweeping it in with the inert ones would compile a card that silently lost
    /// its tutor, so it stays unread until that trigger is written.
    /// </summary>
    [Fact]
    public void Partner_with_a_name_is_not_treated_as_the_inert_kind()
    {
        var paired = new CardDefinition
        {
            OracleId = "oracle-partner-with-test",
            Name = "Partner With Test",
            OracleText = "Partner with Some Other Legend",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}{W}",
            Power = 2,
            Toughness = 2,
        };

        var compiled = CardCompiler.Compile(paired);

        Assert.Null(compiled.PartnerRule);
        Assert.Contains("Partner with Some Other Legend", compiled.Unhandled);
    }

    /// <summary>
    /// A lord whose filter is a counter rather than a keyword. The counter is asked of the
    /// permanent, so the grant appears and disappears as counters come and go.
    /// </summary>
    [Fact]
    public void A_lord_can_ask_for_a_counter_instead_of_a_keyword()
    {
        var overseer = Card(
            "Counter Overseer Test",
            "Each creature you control with a +1/+1 counter on it has trample.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(overseer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();

        game.Create(alice, overseer, Zone.Battlefield);

        var bear = game.Create(alice, Fighter("Counter Bear Test", string.Empty, 2), Zone.Battlefield);

        // No counter, no trample: a lord that granted it to everything would pass a test that
        // only looked after the counter arrived.
        Assert.False(
            Characteristics.Of(game.State, Pool, game.State.GetObject(bear))
                .Has(KeywordAbility.Trample));

        game.AddCounters(bear, CounterKinds.PlusOnePlusOne, 1);

        Assert.True(
            Characteristics.Of(game.State, Pool, game.State.GetObject(bear))
                .Has(KeywordAbility.Trample));

        // And a creature of the opponent's with a counter is still not theirs to buff.
        Assert.Equal(
            3,
            Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }

    /// <summary>
    /// No compiled pattern may contain a control character. A pattern that does still compiles,
    /// still runs, and silently matches nothing.
    /// </summary>
    /// <remarks>
    /// This has now happened twice. A regex written through a tool that treats backslash escapes
    /// as its own turns "\b" into a literal backspace, so the pattern reads "&lt;BS&gt;enters the
    /// battlefield&lt;BS&gt;" - which is valid, compiles clean, and never matches a card. The first
    /// time cost a matcher that looked correct in every review; the second was caught only
    /// because the bytes were checked by hand.
    /// <para>
    /// Driven off the attributes rather than off a list of patterns, so every regex in the card
    /// compiler is covered the moment it is written. It reads the source generator's own input,
    /// which is the string the engine actually runs.
    /// </para>
    /// </remarks>
    [Fact]
    public void No_compiled_card_pattern_contains_a_control_character()
    {
        var types = new[]
        {
            typeof(CardCompiler),
            typeof(EffectPhrase),
            typeof(BoardConditions),
            typeof(GenerativeEffects),
        };

        var patterns = 0;

        foreach (var type in types)
        {
            var methods = type.GetMethods(
                System.Reflection.BindingFlags.Public
                | System.Reflection.BindingFlags.NonPublic
                | System.Reflection.BindingFlags.Static
                | System.Reflection.BindingFlags.Instance
                | System.Reflection.BindingFlags.DeclaredOnly);

            foreach (var method in methods)
            {
                var attribute = method
                    .GetCustomAttributes(typeof(System.Text.RegularExpressions.GeneratedRegexAttribute), inherit: false)
                    .Cast<System.Text.RegularExpressions.GeneratedRegexAttribute>()
                    .FirstOrDefault();

                if (attribute is null)
                    continue;

                patterns++;

                var offending = attribute.Pattern.FirstOrDefault(char.IsControl);

                Assert.True(
                    offending == default,
                    $"{type.Name}.{method.Name} has U+{(int)offending:X4} in its pattern: "
                        + attribute.Pattern.Replace("", "<BS>", StringComparison.Ordinal));
            }
        }

        // A floor rather than a count, so the check going quiet is a failure. The four types
        // between them carry every pattern the card compiler runs.
        Assert.True(patterns >= 300, $"only {patterns} patterns were scanned");
    }

    /// <summary>
    /// "Deals <em>combat</em> damage to a creature" must not fire on damage that was not combat
    /// damage. The word was read off the card and then asked only of the arms that damage a
    /// player, so every creature-damage trigger of this shape went off on any damage at all.
    /// </summary>
    [Theory]
    [InlineData("Whenever ~ deals combat damage to a creature, draw a card.", false)]
    [InlineData("Whenever ~ deals damage to a creature, draw a card.", true)]
    public void A_combat_damage_trigger_ignores_damage_that_was_not_combat(
        string printed, bool shouldFire)
    {
        var watcher = new CardDefinition
        {
            OracleId = "oracle-combat-watch-" + printed.GetHashCode(StringComparison.Ordinal),
            Name = "Combat Watcher Test",
            OracleText = printed,
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}{R}",
            Power = 2,
            Toughness = 2,
        };

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var source = game.Create(alice, watcher, Zone.Battlefield);
        var victim = game.Create(bob, Fighter("Combat Victim Test", string.Empty, 1), Zone.Battlefield);

        var held = game.State.GetPlayer(alice).Library.Count;

        // Damage marked outside combat, by this permanent. Nothing about it is combat damage.
        game.MarkDamage(victim, 1, sourceId: source);
        Settle(game);

        Assert.Equal(
            shouldFire ? held - 1 : held,
            game.State.GetPlayer(alice).Library.Count);
    }

    /// <summary>
    /// The other half of the check above: real combat damage still fires it. Without this, an arm
    /// that had been made permanently false would pass every assertion in the theory.
    /// </summary>
    [Fact]
    public void A_combat_damage_trigger_still_fires_on_actual_combat_damage()
    {
        var watcher = new CardDefinition
        {
            OracleId = "oracle-combat-watch-positive",
            Name = "Combat Watcher Positive Test",
            OracleText = "Whenever ~ deals combat damage to a creature, draw a card.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}{R}",
            Power = 2,
            Toughness = 2,
            Keywords = KeywordAbility.Haste,
        };

        var compiled = CardCompiler.Compile(watcher);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var attacker = game.Create(alice, watcher, Zone.Battlefield);
        var blocker = game.Create(bob, Fighter("Combat Blocker Test", string.Empty, 1), Zone.Battlefield);

        var held = game.State.GetPlayer(alice).Library.Count;

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.Equal(held - 1, game.State.GetPlayer(alice).Library.Count);
    }

    // ---- "That creature" after a damage trigger (CR 603.2) ------------------

    /// <summary>
    /// The damaged creature, not the one that dealt the damage. Both are on the battlefield and
    /// both are creatures, so an implementation that picked the source would look right until you
    /// checked which one died.
    /// </summary>
    [Fact]
    public void That_creature_after_a_damage_trigger_means_the_creature_that_was_damaged()
    {
        var slayer = new CardDefinition
        {
            OracleId = "oracle-slayer-test",
            Name = "Damage Slayer Test",
            OracleText = "Whenever ~ deals combat damage to a creature, destroy that creature.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}{B}",
            Power = 1,
            Toughness = 4,
            Keywords = KeywordAbility.Haste,
        };

        var compiled = CardCompiler.Compile(slayer);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        var attacker = game.Create(alice, slayer, Zone.Battlefield);

        // A 2/3, so one point of combat damage is nowhere near lethal. Only the trigger can
        // kill it, which is what makes the assertion mean something.
        var blocker = game.Create(bob, Fighter("Damage Survivor Test", string.Empty, 2), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);
        game.DeclareAttackers(
            alice, new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);
        game.DeclareBlockers(
            bob, new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.EndOfCombat);
        Settle(game);

        Assert.DoesNotContain(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Damage Survivor Test");

        // And the source survives. A subject that resolved to the permanent with the ability
        // would have destroyed this instead, which is the bug the strict subject exists to stop.
        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Damage Slayer Test");
    }

    /// <summary>
    /// A trigger whose event carries no object leaves the line unread rather than compiling a
    /// sentence that means nothing. This is the case that reverted the first attempt.
    /// </summary>
    [Fact]
    public void That_creature_stays_unread_when_the_trigger_names_no_object()
    {
        var blockerKiller = new CardDefinition
        {
            OracleId = "oracle-block-slayer-test",
            Name = "Block Slayer Test",
            OracleText = "Whenever ~ blocks a creature, destroy that creature.",
            CardTypes = CardType.Creature,
            ManaCostRaw = "{2}{B}",
            Power = 1,
            Toughness = 4,
        };

        var compiled = CardCompiler.Compile(blockerKiller);

        Assert.False(compiled.IsComplete);
        Assert.Contains(
            "Whenever ~ blocks a creature, destroy that creature.",
            compiled.Unhandled);
    }

    /// <summary>
    /// A dies trigger's "that creature" is the card now in the graveyard, not the permanent that
    /// watched it die (CR 400.7). Both are creatures the enchantment can see.
    /// </summary>
    [Fact]
    public void That_creature_after_a_dies_trigger_means_the_card_in_the_graveyard()
    {
        var reaper = Card(
            "Graveyard Reaper Test",
            "Whenever a creature an opponent controls dies, exile that creature.",
            CardType.Enchantment);

        var compiled = CardCompiler.Compile(reaper);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();

        game.Create(alice, reaper, Zone.Battlefield);

        var doomed = game.Create(bob, Fighter("Doomed Bear Test", string.Empty, 2), Zone.Battlefield);

        game.MarkDamage(doomed, 3);
        Settle(game);

        // Not in the graveyard: the trigger took it out of there. A trigger that resolved to
        // nothing would leave it sitting in Bob's graveyard, which looks identical to a card
        // that simply died.
        Assert.DoesNotContain(
            game.State.GetPlayer(bob).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Doomed Bear Test");

        Assert.Contains(
            game.State.Exile,
            id => game.State.GetObject(id).Card.Name == "Doomed Bear Test");
    }

    /// <summary>
    /// The verbs are admitted one at a time, so a family member that names no object stays
    /// refused. This is the same card that reverted the first attempt, asserted twice over.
    /// </summary>
    [Theory]
    [InlineData("Whenever ~ blocks a creature, destroy that creature.")]
    [InlineData("Whenever ~ becomes blocked by a creature, destroy that creature.")]
    public void A_trigger_verb_that_names_no_object_still_leaves_the_line_unread(string printed)
