    /// <summary>A card with two castable halves, printed the way the real ones are.</summary>
    private static CardDefinition Adventurer() => new()
    {
        OracleId = "oracle-test-guidemother",
        Name = "Test Guidemother",
        ManaCostRaw = "{1}{W}",
        OracleText = "Flying",
        CardTypes = CardType.Creature,
        Subtypes = ["Faerie"],
        Power = 1,
        Toughness = 1,
        Keywords = KeywordAbility.Flying,
        Faces =
        [
            new CardFace
            {
                Name = "Test Guidemother",
                ManaCostRaw = "{1}{W}",
                TypeLine = "Creature \u2014 Faerie",
                CardTypes = CardType.Creature,
                Subtypes = ["Faerie"],
                OracleText = "Flying",
                Power = 1,
                Toughness = 1,
                Keywords = KeywordAbility.Flying,
            },
            new CardFace
            {
                Name = "Test Gift of the Fae",
                ManaCostRaw = "{W}",
                TypeLine = "Sorcery \u2014 Adventure",
                CardTypes = CardType.Sorcery,
                Subtypes = ["Adventure"],
                OracleText = "You gain 3 life.",
            },
        ],
    };

    /// <summary>
    /// An Adventure resolves as itself, is exiled rather than binned, and the creature can then
    /// be cast from exile (CR 715.3b, 715.3d).
    /// </summary>
    /// <remarks>
    /// This is the shape of card the coverage number is least honest about. Both halves of an
    /// adventurer card read cleanly - they are an ordinary sorcery and an ordinary creature - so
    /// all 170 of them counted as understood while the engine had no way to cast the Adventure at
    /// all. Reading a card and being able to play it are different claims, and only one of them
    /// was being made.
    /// <para>
    /// The life total is what says the <em>Adventure</em> resolved rather than the creature: the
    /// card underneath is a 1/1 Faerie with flying and nothing else, so a resolution that
    /// consulted the card would have put a creature on the battlefield and gained nobody
    /// anything.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_Adventure_resolves_as_itself_and_leaves_the_creature_castable()
    {
        var faerie = Adventurer();

        var compiled = CardCompiler.Compile(faerie);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.NotNull(compiled.Adventure);

        var (game, alice, _) = InMainPhase();
        var before = game.State.GetPlayer(alice).Life;
        var card = TestCards.PutInHand(game, alice, faerie);

        for (var i = 0; i < 4; i++)
            game.AddMana(alice, ManaColor.White);

        game.CastSpell(alice, card, [], asAdventure: true);
        Settle(game);

        // The Adventure did what the Adventure says.
        Assert.Equal(before + 3, game.State.GetPlayer(alice).Life);

        // And it is in exile rather than in the graveyard (CR 715.3d).
        var exiled = Assert.Single(
            game.State.Exile,
            id => game.State.GetObject(id).Card.Name == "Test Guidemother");

        Assert.True(game.State.GetObject(exiled).OnAdventure);
        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Test Guidemother");

        // The creature can be cast from there, and only as the creature.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, exiled, [], asAdventure: true));

        game.CastSpell(alice, exiled, []);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Test Guidemother");
    }
