    /// <summary>Two spells on one card, printed the way the real ones are.</summary>
    private static CardDefinition SplitCard() => new()
    {
        OracleId = "oracle-test-fire-ice",
        Name = "Test Blaze // Test Chill",
        ManaCostRaw = "{1}{R}",
        OracleText = "Test Blaze deals 2 damage to any target.",
        CardTypes = CardType.Instant,
        Faces =
        [
            new CardFace
            {
                Name = "Test Blaze",
                ManaCostRaw = "{1}{R}",
                TypeLine = "Instant",
                CardTypes = CardType.Instant,
                OracleText = "Test Blaze deals 2 damage to any target.",
            },
            new CardFace
            {
                Name = "Test Chill",
                ManaCostRaw = "{1}{U}",
                TypeLine = "Instant",
                CardTypes = CardType.Instant,
                OracleText = "You gain 4 life.",
            },
        ],
    };

    /// <summary>
    /// Casting a split card's second half runs that half, not the one printed first (CR 709.4).
    /// </summary>
    /// <remarks>
    /// The whole card is one object with two spells on it, and everything that resolves a spell
    /// looks its effects up from the card - so without recording which half was chosen, the
    /// second half resolves as the first. The life total and the untouched life total of the
    /// opponent are what tell the two apart: one deals damage and the other does not.
    /// </remarks>
    [Fact]
    public void Casting_the_second_half_of_a_split_card_runs_that_half()
    {
        var split = SplitCard();

        var compiled = CardCompiler.Compile(split);
        Assert.Equal(2, compiled.Halves.Count);

        var (game, alice, bob) = InMainPhase();
        var mine = game.State.GetPlayer(alice).Life;
        var theirs = game.State.GetPlayer(bob).Life;
        var card = TestCards.PutInHand(game, alice, split);

        for (var i = 0; i < 4; i++)
            game.AddMana(alice, ManaColor.Blue);

        game.CastSpell(alice, card, [], half: 1);
        Settle(game);

        Assert.Equal(mine + 4, game.State.GetPlayer(alice).Life);

        // Nobody was burned: the other half never ran.
        Assert.Equal(theirs, game.State.GetPlayer(bob).Life);

        // And it is a spell, so it is in the graveyard rather than on the battlefield.
        Assert.Contains(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Test Blaze // Test Chill");
    }

    /// <summary>
    /// A half that is a permanent resolves into one, and a half that is not does not.
    /// </summary>
    /// <remarks>
    /// Where a resolving spell goes was decided by asking whether the <em>card</em> is a
    /// permanent card. A card with two halves is whichever half is on the stack, and asking the
    /// card put an Adventure's creature onto the battlefield the moment its sorcery resolved.
    /// This is the same question asked of a split card, where the two halves can differ.
    /// </remarks>
    [Fact]
    public void A_permanent_half_resolves_into_a_permanent()
    {
        var split = new CardDefinition
        {
            OracleId = "oracle-test-split-permanent",
            Name = "Test Bolt // Test Bear",
            ManaCostRaw = "{R}",
            OracleText = "Test Bolt deals 2 damage to any target.",
            CardTypes = CardType.Instant,
            Faces =
            [
                new CardFace
                {
                    Name = "Test Bolt",
                    ManaCostRaw = "{R}",
                    TypeLine = "Instant",
                    CardTypes = CardType.Instant,
                    OracleText = "Test Bolt deals 2 damage to any target.",
                },
                new CardFace
                {
                    Name = "Test Bear",
                    ManaCostRaw = "{1}{G}",
                    TypeLine = "Creature \u2014 Bear",
                    CardTypes = CardType.Creature,
                    Subtypes = ["Bear"],
                    OracleText = string.Empty,
                    Power = 2,
                    Toughness = 2,
                },
            ],
        };

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, split);

        for (var i = 0; i < 4; i++)
            game.AddMana(alice, ManaColor.Green);

        game.CastSpell(alice, card, [], half: 1);
        Settle(game);

        Assert.Contains(
            game.State.Battlefield,
            id => game.State.GetObject(id).Card.Name == "Test Bolt // Test Bear");
    }
