                CardTypes = CardType.Enchantment,
                Subtypes = ["Room"],
                OracleText = "Creatures you control get +0/+2.",
            },
        ],
    };

    /// <summary>
    /// Only the door that was paid for is open, and paying the other one opens it
    /// (CR 709.5d, 709.5e).
    /// </summary>
    /// <remarks>
    /// Both halves of a Room are on the same permanent at the same time, so the whole mechanic is
    /// the gate: a locked half "doesn't have the name, mana cost, or rules text" of that half
    /// (CR 709.5). Without it a player pays for one door and gets both, which is the card doing
    /// twice what it says while looking entirely normal.
    /// <para>
    /// The two doors give different bonuses on purpose - one power, one toughness - because a
    /// gate that leaked would be invisible if both halves did the same thing.
    /// </para>
    /// </remarks>
    [Fact]
    public void A_Room_opens_only_the_door_that_was_paid_for()
    {
        var room = Room();

        var compiled = CardCompiler.Compile(room);
        Assert.Equal(2, compiled.Halves.Count);

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Test Room Bear", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, room);

        for (var i = 0; i < 6; i++)
            game.AddMana(alice, ManaColor.Red);

        game.CastSpell(alice, card, [], half: 0);
        Settle(game);

        var permanent = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Vents // Test Maze");

        Assert.Equal([0], game.State.GetObject(permanent).Permanent!.UnlockedHalves);

        var open = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(3, open.Power);

        // The other door is shut: its bonus is not there.
        Assert.Equal(2, open.Toughness);

        game.UnlockDoor(alice, permanent, 1);
        Settle(game);

        var both = Characteristics.Of(game.State, Pool, game.State.GetObject(bear));
        Assert.Equal(3, both.Power);
        Assert.Equal(4, both.Toughness);
    }

    /// <summary>A door that is already open cannot be paid for again (CR 709.5c).</summary>
    [Fact]
    public void An_open_door_cannot_be_unlocked_twice()
    {
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, Room());

        for (var i = 0; i < 6; i++)
            game.AddMana(alice, ManaColor.Red);

        game.CastSpell(alice, card, [], half: 0);
        Settle(game);

        var permanent = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Vents // Test Maze");

        Assert.Throws<InvalidOperationException>(() => game.UnlockDoor(alice, permanent, 0));
    }
    /// <summary>
    /// "When you unlock this door" fires as its own door opens, and only then (CR 709.5f).
    /// </summary>
    /// <remarks>
    /// Third time this shape has appeared: an ability printed behind the switch it fires on. A
    /// Saga's chapter, a Class's level, and now a Room's door - each of them is checked against
    /// a state that has not changed yet, so each needs its gate lifted for its own event and no
    /// other.
    /// <para>
    /// The other door is what carries the test. A trigger that fired on any unlock would look
    /// right until the second door opened and the first one's trigger went off again.
    /// </para>
    /// </remarks>
    [Fact]
    public void An_unlock_trigger_fires_for_its_own_door_only()
    {
        var room = new CardDefinition
        {
            OracleId = "oracle-test-door-room",
            Name = "Test Hall // Test Cellar",
            ManaCostRaw = "{R}",
            OracleText = "When you unlock this door, you gain 2 life.",
            CardTypes = CardType.Enchantment,
            Subtypes = ["Room"],
            Faces =
            [
                new CardFace
                {
                    Name = "Test Hall",
                    ManaCostRaw = "{R}",
                    TypeLine = "Enchantment \u2014 Room",
                    CardTypes = CardType.Enchantment,
                    Subtypes = ["Room"],
                    OracleText = "When you unlock this door, you gain 2 life.",
                },
                new CardFace
                {
                    Name = "Test Cellar",
                    ManaCostRaw = "{2}{R}",
                    TypeLine = "Enchantment \u2014 Room",
                    CardTypes = CardType.Enchantment,
                    Subtypes = ["Room"],
                    OracleText = "Creatures you control get +1/+0.",
                },
            ],
        };

        var compiled = CardCompiler.Compile(room);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var start = game.State.GetPlayer(alice).Life;
        var card = TestCards.PutInHand(game, alice, room);

        for (var i = 0; i < 6; i++)
            game.AddMana(alice, ManaColor.Red);

        // Open the *other* door first. The trigger belongs to the hall, not the cellar.
        game.CastSpell(alice, card, [], half: 1);
        Settle(game);

        Assert.Equal(start, game.State.GetPlayer(alice).Life);

        var permanent = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Hall // Test Cellar");

        game.UnlockDoor(alice, permanent, 0);
        Settle(game);

        Assert.Equal(start + 2, game.State.GetPlayer(alice).Life);
    }
