    /// <summary>A split card whose second half is cast from the graveyard.</summary>
    private static CardDefinition AftermathCard() => new()
    {
        OracleId = "oracle-test-aftermath",
        Name = "Test Strike // Test Echo",
        ManaCostRaw = "{R}",
        OracleText = "You gain 1 life.",
        CardTypes = CardType.Sorcery,
        Faces =
        [
            new CardFace
            {
                Name = "Test Strike",
                ManaCostRaw = "{R}",
                TypeLine = "Sorcery",
                CardTypes = CardType.Sorcery,
                OracleText = "You gain 1 life.",
            },
            new CardFace
            {
                Name = "Test Echo",
                ManaCostRaw = "{2}{R}",
                TypeLine = "Sorcery",
                CardTypes = CardType.Sorcery,
                OracleText = "You gain 5 life.\nAftermath",
            },
        ],
    };

    /// <summary>
    /// An aftermath half is cast from the graveyard, from nowhere else, and is exiled afterwards
    /// (CR 702.127a).
    /// </summary>
    /// <remarks>
    /// One word, three static abilities, and the two easy to skip are the ones that make it a
    /// two-part card rather than simply a better one: it cannot be cast from hand, and it is
    /// exiled rather than put back where it came from. Without the second, the card returns to
    /// the graveyard it was just cast from and can be cast again every turn.
    /// </remarks>
    [Fact]
    public void An_aftermath_half_is_cast_from_the_graveyard_and_then_exiled()
    {
        var split = AftermathCard();

        var compiled = CardCompiler.Compile(split);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.Halves[1].HasAftermath);

        var (game, alice, _) = InMainPhase();
        var start = game.State.GetPlayer(alice).Life;
        var card = TestCards.PutInHand(game, alice, split);

        for (var i = 0; i < 8; i++)
            game.AddMana(alice, ManaColor.Red);

        // From hand it is only the first half. The second refuses.
        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [], half: 1));

        game.CastSpell(alice, card, [], half: 0);
        Settle(game);

        Assert.Equal(start + 1, game.State.GetPlayer(alice).Life);

        var inGraveyard = Assert.Single(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Test Strike // Test Echo");

        game.CastSpell(alice, inGraveyard, [], half: 1);
        Settle(game);

        Assert.Equal(start + 6, game.State.GetPlayer(alice).Life);

        // Exiled, not returned - so it cannot be cast a third time.
        Assert.Contains(
            game.State.Exile,
            id => game.State.GetObject(id).Card.Name == "Test Strike // Test Echo");

        Assert.DoesNotContain(
            game.State.GetPlayer(alice).Graveyard,
            id => game.State.GetObject(id).Card.Name == "Test Strike // Test Echo");
    }
    // ---- Fuse (CR 702.102) ---------------------------------------------------

    /// <summary>
    /// A fused split spell runs both halves, each at its own target (CR 702.102b).
    /// </summary>
    /// <remarks>
    /// The second half was compiled on its own and numbers its targets from zero. Left alone,
    /// both halves point at whatever the player chose first - one creature taking two spells'
    /// worth of attention while the other stands untouched, which is why this test pumps two
    /// different creatures by two different amounts and checks both.
    /// </remarks>
    [Fact]
    public void A_fused_split_spell_runs_both_halves_at_their_own_targets()
    {
        var split = new CardDefinition
        {
            OracleId = "oracle-test-fused",
            Name = "Test Push // Test Pull",
            ManaCostRaw = "{G}",
            OracleText = "Target creature gets +1/+1 until end of turn.",
            CardTypes = CardType.Instant,
            Faces =
            [
                new CardFace
                {
                    Name = "Test Push",
                    ManaCostRaw = "{G}",
                    TypeLine = "Instant",
                    CardTypes = CardType.Instant,
                    OracleText = "Target creature gets +1/+1 until end of turn.\nFuse",
                },
                new CardFace
                {
                    Name = "Test Pull",
                    ManaCostRaw = "{G}",
                    TypeLine = "Instant",
                    CardTypes = CardType.Instant,
                    OracleText = "Target creature gets +3/+3 until end of turn.\nFuse",
                },
            ],
        };

        var compiled = CardCompiler.Compile(split);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));
        Assert.True(compiled.HasFuse);

        var (game, alice, _) = InMainPhase();
        var first = game.Create(alice, TestCards.Creature("Test Fuse One", 2, 2), Zone.Battlefield);
        var second = game.Create(alice, TestCards.Creature("Test Fuse Two", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, split);

        for (var i = 0; i < 4; i++)
            game.AddMana(alice, ManaColor.Green);

        game.CastSpell(
            alice,
            card,
            [Target.ToPermanent(first), Target.ToPermanent(second)],
            fused: true);

        Settle(game);

        // Each half found its own target rather than both landing on the first.
        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(first)).Power);
        Assert.Equal(5, Characteristics.Of(game.State, Pool, game.State.GetObject(second)).Power);
    }

    /// <summary>Fuse works from hand and nowhere else (CR 702.102a).</summary>
    [Fact]
    public void A_split_card_cannot_be_fused_without_fuse()
    {
        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, SplitCard());

        for (var i = 0; i < 6; i++)
            game.AddMana(alice, ManaColor.Blue);

        Assert.Throws<InvalidOperationException>(
            () => game.CastSpell(alice, card, [], fused: true));
    }
