    /// <summary>
    /// Station is a sorcery-speed action, and needs a creature other than the ship
    /// (CR 702.184a).
    /// </summary>
    /// <remarks>
    /// The first test of station proved it charges. Neither half of its restriction was checked,
    /// and both are the kind that make a card correct rather than merely functional: a Spacecraft
    /// that could station at instant speed is a combat trick, and one that could tap itself
    /// charges for free.
    /// </remarks>
    [Fact]
    public void Station_refuses_without_another_creature()
    {
        var (game, alice, _) = InMainPhase();
        var ship = game.Create(alice, Spacecraft(), Zone.Battlefield);

        // No creature on the battlefield at all: there is nothing to tap.
        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, ship, "station", [], [ship]));
    }

    /// <summary>Station is sorcery speed, so not while a spell is waiting (CR 702.184a).</summary>
    [Fact]
    public void Station_refuses_while_something_is_on_the_stack()
    {
        var (game, alice, _) = InMainPhase();
        var ship = game.Create(alice, Spacecraft(), Zone.Battlefield);

        var crew = game.Create(
            alice,
