    /// <summary>
    /// A granted trigger stops watching when the thing that granted it leaves (CR 613.1f).
    /// </summary>
    /// <remarks>
    /// A granted ability is a continuous effect, so it lasts exactly as long as its source does.
    /// The definition is written into a side table when the trigger is found, and a table is
    /// precisely the sort of thing that keeps answering after the world has moved on - so this
    /// asks whether the creature is still carrying an ability nothing is giving it.
    /// </remarks>
    [Fact]
    public void A_granted_trigger_stops_when_its_source_leaves()
    {
        var chant = Card(
            "Test Fading Chant",
            "Creatures you control have \"When this creature dies, you gain 3 life.\"",
            CardType.Enchantment);

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Test Fading Bear", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, chant);

        game.CastSpell(alice, card, []);
        Settle(game);

        var enchantment = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Fading Chant");

        // The chant goes first.
        game.Move(enchantment, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        game.Move(bear, Zone.Graveyard, MoveCause.Destroy);
        Settle(game);

        Assert.Equal(before, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// An activated ability under a level bar cannot be activated below that level (CR 716.2a).
    /// </summary>
    /// <remarks>
    /// The Class tests covered a static and a trigger. An activated ability is the third kind and
    /// takes a different gate - <c>ActivateOnlyIf</c> rather than a predicate - so it is the one
    /// that could have been wired to nothing without any other test noticing.
    /// </remarks>
    [Fact]
    public void An_activated_ability_under_a_level_bar_waits_for_its_level()
    {
        var talent = Card(
            "Test Ability Talent",
            "{1}: Level 2\n{T}: You gain 2 life.",
            CardType.Enchantment,
            null,
            null,
            KeywordAbility.None,
            "Class");

        var compiled = CardCompiler.Compile(talent);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, talent);

        game.CastSpell(alice, card, []);
        Settle(game);

        var klass = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Ability Talent");

        // The level bar's own ability is "level2"; the one behind it is prefixed "l2".
        var gated = Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(klass))
            .Single(a => a.Id.StartsWith("l2", StringComparison.Ordinal));

        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, klass, gated.Id, []));

        TapLands(game, alice, 2);
        game.ActivateAbility(alice, klass, "level2", []);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;
        game.ActivateAbility(alice, klass, gated.Id, []);
        Settle(game);

        Assert.Equal(before + 2, game.State.GetPlayer(alice).Life);
    }

    /// <summary>
    /// A Background follows the card's owner, not whoever controls it now (CR 903.3).
    /// </summary>
    /// <remarks>
    /// "Commander creatures you own" is written that way on purpose: a commander stolen by an
    /// opponent is still its owner's commander. A filter reading control instead of ownership
    /// would look identical in every ordinary game and be wrong in exactly the game where it
    /// matters.
    /// </remarks>
    [Fact]
    public void A_Background_follows_ownership_rather_than_control()
    {
        var background = Card(
            "Test Owner Background",
            "Commander creatures you own have \"{T}: Draw a card.\"",
            CardType.Enchantment,
            null,
            null,
            KeywordAbility.None,
            "Background");

        var alice = Guid.Parse("11111111-1111-1111-1111-111111111111");
        var bob = Guid.Parse("22222222-2222-2222-2222-222222222222");

        var boss = Card(
            "Test Owner Commander",
            string.Empty,
            CardType.Creature,
            3,
            3,
            KeywordAbility.Haste);

        var game = Game.Start(
            Guid.NewGuid(),
            [
                new PlayerSetup(alice, "Alice", 40, [.. TestCards.Deck(40, "Alice"), boss])
                {
                    CommanderOracleId = boss.OracleId,
                },
                new PlayerSetup(bob, "Bob", 40, TestCards.Deck(40, "Bob")),
            ],
            new GameRandom(3),
            startingPlayerId: alice,
            abilities: Pool);

        game.BeginPlay(withMulligans: false);
        TestCards.PassToStep(game, TurnStep.PrecombatMain);

        // Bob's commander, which Alice's Background must not reach.
        var theirs = game.Create(bob, boss, Zone.Battlefield);

        var card = TestCards.PutInHand(game, alice, background);
        game.CastSpell(alice, card, []);
        Settle(game);

        var granted = Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(theirs))
            .Where(a => a.Id.StartsWith("granted:", StringComparison.Ordinal))
            .ToList();

        Assert.Empty(granted);
    }

    /// <summary>
    /// A charged Spacecraft's printed power is a base, so a counter counts on top (CR 613.4b).
    /// </summary>
    /// <remarks>
    /// CR 721.2b says the threshold makes it "a creature with base power and toughness [P/T]",
    /// and base means layer 7b - set rather than modified. Written into layer 7c instead it would
    /// still look right on an untouched ship and would quietly swallow every counter put on one.
    /// </remarks>
    [Fact]
    public void A_charged_Spacecrafts_power_is_a_base_that_counters_add_to()
    {
        var (game, alice, _) = InMainPhase();
        var ship = game.Create(alice, Spacecraft(), Zone.Battlefield);

        var crew = game.Create(
            alice,
            Card("Test Base Hand", string.Empty, CardType.Creature, 4, 4, KeywordAbility.Haste),
            Zone.Battlefield);

        game.ActivateAbility(alice, ship, "station", [], [crew]);
        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(ship)).Power);

        var pump = TestCards.PutInHand(
            game,
            alice,
            Card("Test Base Counter", "Put a +1/+1 counter on target creature."));

        game.AddMana(alice, ManaColor.Green);
        game.CastSpell(alice, pump, [Target.ToPermanent(ship)]);
        Settle(game);

        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(ship)).Power);
    }
    /// <summary>
    /// A Saga chapter that targets chooses its target as the chapter goes on the stack
    /// (CR 603.3d, 714.2b).
    /// </summary>
    /// <remarks>
    /// Every Saga test so far used chapters that target nothing, which meant the whole targeting
    /// path was untried for them: a chapter is an ordinary triggered ability and gets its targets
    /// the ordinary way, but "ordinary" is a claim rather than a fact until something exercises
    /// it. Roughly a third of the chapter lines in the corpus target something.
    /// </remarks>
    [Fact]
    public void A_Saga_chapter_that_targets_picks_a_target_when_it_fires()
    {
        var saga = Card(
            "Test Aiming Saga",
            "I \u2014 Put a +1/+1 counter on target creature.\nII \u2014 You gain 1 life.",
            CardType.Enchantment,
            null,
            null,
            KeywordAbility.None,
            "Saga");

        var compiled = CardCompiler.Compile(saga);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var chapter = compiled.Triggers.Single(t => t.Chapter == 1);
        Assert.Single(chapter.Targets);

        var (game, alice, _) = InMainPhase();
        var bear = game.Create(alice, TestCards.Creature("Test Aiming Bear", 2, 2), Zone.Battlefield);
        var card = TestCards.PutInHand(game, alice, saga);

        game.CastSpell(alice, card, []);
        Settle(game);

        Assert.Equal(3, Characteristics.Of(game.State, Pool, game.State.GetObject(bear)).Power);
    }

    /// <summary>
    /// A Case's solved section gates a trigger and an activated ability, not only a static
    /// (CR 719.3c).
    /// </summary>
    /// <remarks>
    /// The first Case test used a static, which is one of three kinds and the only one whose gate
    /// had been exercised. CR 719.3c is explicit that a solved ability "may affect the game if
    /// it's a static ability, it may trigger if it's a triggered ability, and it can be activated
    /// if it's an activated ability" - three separate gates, and two of them were claims.
    /// </remarks>
    [Fact]
    public void A_Cases_solved_trigger_waits_until_it_is_solved()
    {
        var investigation = Card(
            "Test Trigger Case",
            "To solve \u2014 You control three or more artifacts.\n"
                + "Solved \u2014 Whenever a creature you control enters, you gain 2 life.",
            CardType.Enchantment,
            null,
            null,
            KeywordAbility.None,
            "Case");

        var compiled = CardCompiler.Compile(investigation);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, investigation);

        game.CastSpell(alice, card, []);
        Settle(game);

        var before = game.State.GetPlayer(alice).Life;

        // Unsolved: a creature arrives and nothing happens.
        game.Create(alice, TestCards.Creature("Test Case Early", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.Equal(before, game.State.GetPlayer(alice).Life);

        for (var i = 0; i < 3; i++)
        {
            game.Create(
                alice,
                Card(
                    "Test Trigger Relic " + i.ToString(System.Globalization.CultureInfo.InvariantCulture),
                    string.Empty,
                    CardType.Artifact),
                Zone.Battlefield);
        }

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.End);
        Settle(game);

        var file = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Trigger Case");

        Assert.True(game.State.GetObject(file).Permanent!.IsSolved);

        // Once, and once only (CR 719.3a: "and this Case is not solved"). The designation is
        // already true after the first time, so nothing about the board says whether it solved
        // again - only the log does, and a Case that re-solves re-fires anything watching for it.
        //
        // A *second* end step is what makes this a test: with only one, the count is 1 whether
        // the clause is there or not, which is how the first version of this assertion passed
        // against a Case with the clause taken out.
        TestCards.PassUntil(
            game,
            () => game.State.ActivePlayerId == alice
                && game.State.CurrentStep == TurnStep.End
                && game.State.TurnNumber > 1);

        Settle(game);

        Assert.Equal(1, game.Log.Count(e => e is CaseSolved));

        var solved = game.State.GetPlayer(alice).Life;

        game.Create(alice, TestCards.Creature("Test Case Late", 2, 2), Zone.Battlefield);
        Settle(game);

        Assert.Equal(solved + 2, game.State.GetPlayer(alice).Life);
    }

    /// <summary>A Case's solved activated ability cannot be used before it is solved.</summary>
    [Fact]
    public void A_Cases_solved_activated_ability_waits_until_it_is_solved()
    {
        var investigation = Card(
            "Test Ability Case",
            "To solve \u2014 You control three or more artifacts.\n"
                + "Solved \u2014 {T}: You gain 2 life.",
            CardType.Enchantment,
            null,
            null,
            KeywordAbility.None,
            "Case");

        var compiled = CardCompiler.Compile(investigation);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, investigation);

        game.CastSpell(alice, card, []);
        Settle(game);

        var file = game.State.Battlefield
            .Single(id => game.State.GetObject(id).Card.Name == "Test Ability Case");

        var ability = Game.ActivatedAbilitiesOf(game.State, Pool, game.State.GetObject(file))
            .Single(a => a.Id.StartsWith("solved", StringComparison.Ordinal));

        Assert.Throws<InvalidOperationException>(
            () => game.ActivateAbility(alice, file, ability.Id, []));
    }
    /// <summary>
    /// Two lore counters arriving together cross two chapters at once (CR 714.2b).
    /// </summary>
    /// <remarks>
    /// The rule says "when <em>one or more</em> lore counters are put onto this Saga, if the
    /// number of lore counters on it was less than N and became at least N". Every other Saga
    /// test advances one counter at a time, which is the only thing the turn-based action ever
    /// does - so the "or more" half had never been exercised by anything.
    /// <para>
    /// No card in the corpus puts two lore counters on at once; it happens when something doubles
    /// the counters going on. Rather than invent engine surface to reach it, the chapter
    /// predicates are asked directly, which is what the rule is about: given a Saga on one
    /// counter and two more arriving, chapters II and III both fire and chapter I does not.
    /// </para>
    /// <para>
    /// Read as "there are now N counters" instead, chapter II would fire and chapter III would be
    /// skipped for the rest of the game - the Saga would reach its final chapter number without
    /// ever running its final chapter, and then be sacrificed for it (CR 714.4).
    /// </para>
    /// </remarks>
    [Fact]
    public void Two_lore_counters_at_once_cross_both_chapters()
    {
        var saga = ThreeChapterSaga();
        var compiled = CardCompiler.Compile(saga);

        var (game, alice, _) = InMainPhase();
        var card = TestCards.PutInHand(game, alice, saga);

        game.CastSpell(alice, card, []);
        Settle(game);

        var id = game.State.Battlefield
            .Single(o => game.State.GetObject(o).Card.Name == "Test Chronicle");

        var chronicle = game.State.GetObject(id);
        Assert.Equal(1, chronicle.Permanent!.Counters.GetValueOrDefault(CounterKinds.Lore));

        var arriving = new CountersChanged(id, CounterKinds.Lore, 2);
        var source = new TriggerSource(chronicle, Pool);

        TriggeredAbilityDefinition Chapter(int at) =>
            compiled.Triggers.Single(t => t.Chapter == at);

        // Already past: one counter was on it before these two arrived.
        Assert.False(Chapter(1).Triggers(arriving, game.State, source));

        // Both crossed by the same event.
        Assert.True(Chapter(2).Triggers(arriving, game.State, source));
        Assert.True(Chapter(3).Triggers(arriving, game.State, source));
    }
    // ---- The three keywords nothing had played ------------------------------

    /// <summary>
    /// Prowess triggers on a noncreature spell and not on a creature one (CR 702.108a).
    /// </summary>
    /// <remarks>
    /// The word "noncreature" is the whole of the restriction, and a version without it is a
    /// creature that grows on every spell - stronger, never wrong-looking, and impossible to
    /// notice from the card. So the creature spell is cast first and the power checked before
    /// anything else happens.
    /// </remarks>
    [Fact]
    public void Prowess_grows_on_a_noncreature_spell_only()
    {
        var monk = Card(
            "Test Prowess Monk",
            "Prowess",
            CardType.Creature,
            1,
            2);

        var compiled = CardCompiler.Compile(monk);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        var creature = game.Create(alice, monk, Zone.Battlefield);

        // A creature spell: prowess must not notice.
        var bear = TestCards.PutInHand(game, alice, TestCards.Creature("Test Prowess Bear", 2, 2));
        game.AddMana(alice, ManaColor.Green);
        game.CastSpell(alice, bear, []);
        Settle(game);

        // The premise first: a test that never casts a creature spell proves nothing about what
        // prowess does when one is cast, and would pass against any implementation at all.
        Assert.Equal(1, game.Log.Count(e => e is SpellCastEvent));

        // Asked of the log rather than of the power. Prowess lasts until end of turn, and the
        // power is back to 1 by the time anything settles - so "still 1" is true whether the
        // ability triggered or not, and mutation testing caught this assertion passing against a
        // prowess with the word "noncreature" taken out of it.
        Assert.DoesNotContain(
            game.Log,
            e => e is AbilityTriggered { AbilityId: "prowess" });

        // A noncreature spell: it does.
        var bolt = TestCards.PutInHand(
            game,
            alice,
            Card("Test Prowess Bolt", "Test Prowess Bolt deals 2 damage to any target."));

        game.AddMana(alice, ManaColor.Red);
        game.CastSpell(alice, bolt, [Target.ToPlayer(alice)]);

        Assert.Contains(
            game.Log,
            e => e is AbilityTriggered { AbilityId: "prowess" });
    }

    /// <summary>
    /// Exalted pumps the creature that attacked alone, and only when it attacked alone
    /// (CR 702.83a).
    /// </summary>
    /// <remarks>
    /// Two things are easy to get wrong here and neither shows on the card. The bonus goes to
    /// <em>the attacking creature</em>, which need not be the creature with exalted - so a lord
    /// that pumped itself would look right in every game where the exalted creature is the one
    /// attacking. And "alone" means exactly one attacker: two creatures attacking is no trigger
    /// at all, not a smaller one.
    /// </remarks>
    [Fact]
    public void Exalted_pumps_the_lone_attacker_and_not_a_crowd()
    {
        var lord = Card("Test Exalted Lord", "Exalted", CardType.Creature, 2, 2);

        var compiled = CardCompiler.Compile(lord);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, _) = InMainPhase();
        game.Create(alice, lord, Zone.Battlefield);

        var soldier = game.Create(
            alice,
            Card("Test Exalted Soldier", string.Empty, CardType.Creature, 1, 1, KeywordAbility.Haste),
            Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget>
            {
                [soldier] = AttackTarget.Player(game.State.TurnOrder.First(id => id != alice)),
            });

        Settle(game);

        // The soldier attacked alone, so the soldier is the one that grew.
        Assert.Equal(2, Characteristics.Of(game.State, Pool, game.State.GetObject(soldier)).Power);
    }

    /// <summary>Two attackers is not attacking alone, so exalted says nothing (CR 702.83a).</summary>
    [Fact]
    public void Exalted_says_nothing_when_two_creatures_attack()
    {
        var (game, alice, _) = InMainPhase();
        game.Create(alice, Card("Test Crowd Lord", "Exalted", CardType.Creature, 2, 2), Zone.Battlefield);

        var one = game.Create(
            alice,
            Card("Test Crowd One", string.Empty, CardType.Creature, 1, 1, KeywordAbility.Haste),
            Zone.Battlefield);

        var two = game.Create(
            alice,
            Card("Test Crowd Two", string.Empty, CardType.Creature, 1, 1, KeywordAbility.Haste),
            Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        var defender = AttackTarget.Player(game.State.TurnOrder.First(id => id != alice));

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [one] = defender, [two] = defender });

        Settle(game);

        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(one)).Power);
        Assert.Equal(1, Characteristics.Of(game.State, Pool, game.State.GetObject(two)).Power);
    }

    /// <summary>
    /// Bushido triggers when the creature becomes blocked (CR 702.45a).
    /// </summary>
    /// <remarks>
    /// "Blocks or becomes blocked" is two triggers in one line and the second is the one an
    /// attacker uses. A bushido creature that only noticed blocking would be a card that works
    /// on defence and does nothing on offence - half a card, and half a card is not obviously
    /// broken.
    /// </remarks>
    [Fact]
    public void Bushido_grows_when_it_becomes_blocked()
    {
        var samurai = Card(
            "Test Bushido Samurai",
            "Bushido 2",
            CardType.Creature,
            2,
            2,
            KeywordAbility.Haste);

        var compiled = CardCompiler.Compile(samurai);
        Assert.True(compiled.IsComplete, string.Join(" | ", compiled.Unhandled));

        var (game, alice, bob) = InMainPhase();
        var attacker = game.Create(alice, samurai, Zone.Battlefield);
        var blocker = game.Create(bob, TestCards.Creature("Test Bushido Wall", 0, 4), Zone.Battlefield);

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareAttackers);

        game.DeclareAttackers(
            alice,
            new Dictionary<ObjectId, AttackTarget> { [attacker] = AttackTarget.Player(bob) });

        TestCards.PassUntil(game, () => game.State.CurrentStep == TurnStep.DeclareBlockers);

        game.DeclareBlockers(
            bob,
            new Dictionary<ObjectId, IReadOnlyList<ObjectId>> { [attacker] = [blocker] });
        Settle(game);

        Assert.Equal(4, Characteristics.Of(game.State, Pool, game.State.GetObject(attacker)).Power);
    }
